// ══════════════════════════════════════════════════════════════════════
//  § 26 · v53 — ⌨️ GAME 30: COMMAND LINE — type the command, kill the process
// ══════════════════════════════════════════════════════════════════════
// Viruses fall toward your shell, each one carrying a command. Type a word's
// first letter to lock onto the virus nearest the shell that starts with it,
// then type the rest; every letter fires a bolt and the last one deletes the
// process. A typo breaks the combo but not the lock. Let a virus reach the
// shell and it costs a point of integrity — three and the session is gone.
//
// It is the one verb the arcade had none of. Every other mission is steered,
// aimed, timed or deduced; this one is SPELLED. On a phone the keys are an
// on-screen keypad under the board (#g-type-keys), because the system keyboard
// covers half the screen and autocorrects commands into English.
//
// ONE SIMULATION, TWO RENDERERS (§ 16's pattern): cmdSim() is the game in
// board space; the 2D build draws it as a terminal, the 3D build as a deck the
// viruses run down, with the words as DOM labels over them. Words are drawn
// through dailyRand(), so the Daily Hack and a party both deal every player the
// same stream of commands.
//
// ⚠️ LOAD ORDER — META/SOLO_START and the other tables name startCommandLine
// (a hoisted function); everything the tables or other sections reach here is
// a function declaration or a `var`.
var CMD = {
  CAP: 1200,
  TIME: 90,                    // seconds at Stable, times the tier's clock
  INTEGRITY: 3,
  SPAWN0: 2.5, SPAWN1: 1.25,   // seconds between viruses, start → end of the round
  FALL0: 13.5, FALL1: 8.2,     // seconds a virus takes to reach the shell, start → end
  BOSS_EVERY: 24, BOSS_FALL: 19,
  MAX_LIVE: 8,
  LETTER: 1, WORD: 2, BOSS_BONUS: 40,
  COMBO_STEP: 4, MULT_STEP: 0.25, MULT_MAX: 2,
  SURVIVE: 30                  // per point of integrity left at the buzzer
};
// Four tiers by length. Lower-case a–z only, so every word can be typed on the
// keypad and read at a glance — commands, protocols and the grid's own words.
var CMD_WORDS = [
  ['bit', 'bot', 'bug', 'byte', 'cpu', 'dns', 'git', 'hex', 'hub', 'key', 'lag', 'lan', 'log', 'net', 'node',
   'null', 'ping', 'port', 'ram', 'root', 'rom', 'run', 'ssh', 'sudo', 'sys', 'tcp', 'udp', 'url', 'usb', 'vpn',
   'web', 'wifi', 'zip', 'code', 'core', 'data', 'disk', 'grid', 'hack', 'host', 'link', 'loop', 'mesh', 'neon',
   'pipe', 'scan', 'sync', 'void', 'wire', 'worm', 'zero', 'echo', 'fork', 'flag', 'kill', 'grep', 'exit', 'jump'],
  ['admin', 'alias', 'array', 'cache', 'chmod', 'cloud', 'crash', 'crypt', 'debug', 'delta', 'drone', 'error',
   'flood', 'input', 'laser', 'login', 'macro', 'patch', 'pixel', 'proxy', 'query', 'queue', 'relay', 'reset',
   'route', 'shell', 'stack', 'token', 'trace', 'virus', 'binary', 'bitmap', 'buffer', 'cipher', 'cookie',
   'cursor', 'daemon', 'domain', 'driver', 'encode', 'filter', 'glitch', 'hacker', 'hijack', 'kernel', 'packet',
   'plasma', 'portal', 'reboot', 'render', 'router', 'script', 'server', 'signal', 'socket', 'spider', 'syntax',
   'thread', 'tunnel', 'update', 'uplink', 'vector'],
  ['adware', 'backdoor', 'botnet', 'browser', 'compile', 'console', 'cyborg', 'decrypt', 'default', 'deflect',
   'desktop', 'digital', 'dropper', 'encrypt', 'exploit', 'firewall', 'firmware', 'gateway', 'hardware',
   'keylogger', 'mainframe', 'malware', 'network', 'overflow', 'overload', 'password', 'payload', 'phishing',
   'protocol', 'quantum', 'ransom', 'rootkit', 'sandbox', 'scanner', 'spoofer', 'spyware', 'terminal', 'trojan',
   'upgrade', 'variable', 'virtual', 'wireless', 'software', 'hotspot', 'datalink'],
  ['ransomware', 'encryption', 'cyberattack', 'overclocked', 'polymorphic', 'datastream', 'blockchain',
   'quarantine', 'singularity', 'motherboard', 'microchip', 'algorithm', 'supercomputer', 'cryptojacker',
   'decompiler', 'bootloader']
];

function cmdPickWord(t, boss, taken, firsts){
  const R = typeof dailyRand === 'function' ? dailyRand : Math.random;
  let tier;
  if(boss) tier = 3;
  else{
    const u = R();
    tier = t < 20 ? (u < 0.72 ? 0 : 1)
         : t < 48 ? (u < 0.3 ? 0 : u < 0.8 ? 1 : 2)
         :          (u < 0.1 ? 0 : u < 0.5 ? 1 : 2);
  }
  // 🧱 A BRICK LAB word list (§ 25), sorted into the same four tiers.
  const lists = (typeof labCmdWords === 'function' && labCmdWords()) || CMD_WORDS;
  const list = lists[tier];
  // Prefer a word whose first letter nothing on screen already starts with —
  // the first keystroke picks the target, so two live words sharing a letter
  // make that keystroke a guess.
  let pick = null;
  for(let k = 0; k < 10; k++){
    const w = list[Math.floor(R() * list.length)];
    if(taken.has(w)) continue;
    pick = w;
    if(!firsts.has(w[0])) break;
  }
  return pick || list[Math.floor(R() * list.length)];
}

function cmdSim(opts){
  opts = opts || {};
  const W = opts.W || BOARD_W, H = opts.H || BOARD_H;
  const diff = Math.max(0.5, opts.diff || 1);
  const coreX = W / 2, coreY = H - 40;
  const S = {
    W, H, coreX, coreY,
    viruses: [], lock: null, t: 0, spawnIn: 0.6, bossIn: CMD.BOSS_EVERY,
    score: 0, combo: 0, bestCombo: 0, kills: 0, letters: 0, typos: 0, strays: 0, keys: 0,
    integrity: CMD.INTEGRITY, over: false, nextId: 1, duration: opts.duration || CMD.TIME
  };
  const mult = () => Math.min(CMD.MULT_MAX, 1 + Math.floor(S.combo / CMD.COMBO_STEP) * CMD.MULT_STEP);

  function spawn(boss){
    const R = typeof dailyRand === 'function' ? dailyRand : Math.random;
    const taken = new Set(S.viruses.map(v => v.word));
    const firsts = new Set(S.viruses.filter(v => !v.typed).map(v => v.word[0]));
    const word = cmdPickWord(S.t, boss, taken, firsts);
    const k = Math.min(1, S.t / Math.max(1, S.duration));
    const fall = (boss ? CMD.BOSS_FALL : CMD.FALL0 + (CMD.FALL1 - CMD.FALL0) * k) / diff;
    const x0 = W * (0.12 + R() * 0.76);
    // Converging on the shell, but only part of the way: straight at it and
    // every word would pile into one unreadable stack by the bottom third.
    const x1 = x0 + (coreX - x0) * 0.62;
    S.viruses.push({ id: S.nextId++, word, typed: 0, boss: !!boss, age: 0, fall,
                     x0, y0: -14, x1, y1: coreY - 22, x: x0, y: -14, hitAt: -9, wob: R() * 6.28 });
    return word;
  }

  function nearestFor(ch){
    let best = null;
    for(const v of S.viruses){
      if(v.word[0] !== ch) continue;
      if(!best || v.y > best.y) best = v;
    }
    return best;
  }

  // One keystroke. Returns what it did, for the round's sounds and the
  // renderers' bolts.
  function key(ch){
    if(S.over) return null;
    ch = String(ch || '').toLowerCase();
    if(!/^[a-z]$/.test(ch)) return null;
    S.keys++;
    let v = S.lock ? S.viruses.find(x => x.id === S.lock) : null;
    if(!v){
      v = nearestFor(ch);
      if(!v){ S.strays++; return { type: 'stray' }; }
      S.lock = v.id;
    }
    if(v.word[v.typed] !== ch){
      S.typos++;
      S.combo = 0;
      return { type: 'typo', v };
    }
    v.typed++;
    v.hitAt = S.t;
    S.letters++;
    S.score += CMD.LETTER * mult();
    if(v.typed >= v.word.length){
      S.kills++;
      S.combo++;
      S.bestCombo = Math.max(S.bestCombo, S.combo);
      S.score += v.word.length * CMD.WORD * mult() + (v.boss ? CMD.BOSS_BONUS : 0);
      S.viruses = S.viruses.filter(x => x !== v);
      S.lock = null;
      return { type: 'kill', v, combo: S.combo, mult: mult() };
    }
    return { type: v.typed === 1 ? 'lock' : 'hit', v };
  }

  // Backspace / Escape: let go of a half-typed word. Its letters stay typed —
  // a word you walk away from is still half-deleted.
  function release(){
    if(!S.lock) return false;
    S.lock = null;
    return true;
  }

  // Advances the round. `breach(v)` is asked when a virus reaches the shell and
  // answers whether a shield absorbed it; returns the events of this step.
  function update(dt, breach){
    const ev = [];
    if(S.over || dt <= 0) return ev;
    S.t += dt;
    for(const v of S.viruses){
      v.age += dt;
      const k = Math.min(1, v.age / v.fall);
      // Slightly eased so a virus seems to speed up as it closes in.
      const e = k * (0.7 + 0.3 * k);
      v.x = v.x0 + (v.x1 - v.x0) * e + Math.sin(v.age * 1.6 + v.wob) * 6 * (1 - k);
      v.y = v.y0 + (v.y1 - v.y0) * e;
    }
    for(const v of S.viruses.filter(x => x.age >= x.fall)){
      S.viruses = S.viruses.filter(x => x !== v);
      if(S.lock === v.id) S.lock = null;
      const saved = breach ? breach(v) : false;
      if(!saved){
        S.integrity -= v.boss ? 2 : 1;
        S.combo = 0;
      }
      ev.push({ type: saved ? 'saved' : 'breach', v });
      if(S.integrity <= 0){ S.integrity = 0; S.over = true; ev.push({ type: 'dead' }); return ev; }
    }
    S.spawnIn -= dt;
    S.bossIn -= dt;
    if(S.bossIn <= 0){
      S.bossIn = CMD.BOSS_EVERY;
      ev.push({ type: 'boss', word: spawn(true) });
    }else if(S.spawnIn <= 0 && S.viruses.length < CMD.MAX_LIVE){
      const k = Math.min(1, S.t / Math.max(1, S.duration));
      S.spawnIn = (CMD.SPAWN0 + (CMD.SPAWN1 - CMD.SPAWN0) * k) / Math.sqrt(diff);
      spawn(false);
    }
    return ev;
  }

  return { S, key, release, update, mult };
}

// ── THE ROUND ──────────────────────────────────────────────────────────
var cmdLast = null;
function cmdRound(o){
  o = o || {};
  const diff = getDifficultyModifier();
  const total = Math.max(20, Math.round(CMD.TIME * getTimeModifier()));
  const sim = cmdSim({ W: BOARD_W, H: BOARD_H, diff, duration: total });
  const S = sim.S;
  let time = total, ended = false;

  setControls(null);
  setControlHint('TAP THE KEYS UNDER THE BOARD', 'TYPE THE WORD ON A VIRUS · BACKSPACE LETS GO');
  document.getElementById('g-time').textContent = time;
  document.getElementById('prog-fill').style.background = 'linear-gradient(90deg,var(--lime),var(--cyan))';
  cmdShowKeys(true);
  showTouchHint('TYPE THE FIRST LETTER OF A WORD TO LOCK ON');

  const live = () => {
    setLive(Math.min(CMD.CAP, Math.round(S.score)));
  };
  const press = ch => {
    if(ended) return;
    hideTouchHint();
    const r = sim.key(ch);
    if(!r) return;
    if(r.type === 'stray'){ snd('deny'); }
    else if(r.type === 'typo'){ snd('wrong'); }
    else if(r.type === 'kill'){ snd(r.v.boss ? 'bigExplode' : 'explode'); if(r.combo > 1 && r.combo % CMD.COMBO_STEP === 0) snd('combo', { semi: Math.min(12, r.combo) }); }
    else{ snd('node', { semi: Math.min(14, r.v.typed) }); }
    live();
    if(o.onKey) o.onKey(r);
  };
  const letGo = () => { if(!ended && sim.release()){ snd('uiBack'); if(o.onKey) o.onKey({ type: 'release' }); } };

  window.onkeydown = e => {
    if(e.ctrlKey || e.metaKey || e.altKey) return;
    if(e.key === 'Backspace' || e.key === 'Escape'){ e.preventDefault(); letGo(); return; }
    if(e.key && e.key.length === 1 && /[a-z]/i.test(e.key)){
      e.preventDefault();
      if(!e.repeat) press(e.key);
    }
  };
  cmdKeysBind(press, letGo);

  gTimer = setInterval(() => {
    if(ended) return;
    time--;
    document.getElementById('g-time').textContent = time;
    document.getElementById('prog-fill').style.width = `${Math.max(0, time / total * 100)}%`;
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0) end('timeout');
  }, 1000);

  function step(dt){
    if(ended) return;
    const ev = sim.update(dt, () => survivedFatal());
    for(const e of ev){
      if(e.type === 'breach'){ snd('hurt'); }
      else if(e.type === 'saved'){ snd('shield'); }
      else if(e.type === 'boss'){ snd('alarm'); }
      else if(e.type === 'dead'){ snd('gameOver'); end('breached'); }
      if(o.onEvent) o.onEvent(e);
    }
    if(ev.length) live();
  }

  function end(reason){
    if(ended) return;
    ended = true;
    S.over = true;
    cmdShowKeys(false);
    const acc = S.keys ? S.letters / S.keys : 0;
    const survive = S.integrity * CMD.SURVIVE;
    const earned = capRaw(CMD.CAP, Math.round(S.score + survive));
    gLater(() => showResults('cmdline', earned, {
      '📡 Session': reason === 'timeout' ? 'CLOCK EXPIRED' : 'SHELL BREACHED',
      '💀 Processes Killed': S.kills,
      '⌨️ Accuracy': `${Math.round(acc * 100)}% · ${S.letters} of ${S.keys} keys`,
      '🔗 Best Clean Run': `${S.bestCombo} words`,
      '🛡️ Integrity Left': `${S.integrity} (+${survive})`,
      '🏆 Final Score': `${earned} PTS`
    }), 900);
  }
  snd('go');
  return cmdLast = { sim, S, step, press, letGo, mult: sim.mult, get ended(){ return ended; }, get time(){ return time; }, total };
}

// ── THE KEYPAD — built once, shown on touch devices ─────────────────────
var CMD_ROWS = ['qwertyuiop', 'asdfghjkl', 'zxcvbnm'];
var cmdKeysHandlers = null;
function cmdBuildKeys(){
  const el = document.getElementById('g-type-keys');
  if(!el || el.dataset.built) return el;
  el.dataset.built = '1';
  el.innerHTML = CMD_ROWS.map((row, i) =>
    `<div class="tk-row">` + [...row].map(ch => `<button class="tk-key" type="button" data-k="${ch}" aria-label="${ch}">${ch}</button>`).join('') +
    (i === 2 ? `<button class="tk-key tk-back" type="button" data-k="back" aria-label="Let go of the word">⌫</button>` : '') +
    `</div>`).join('');
  // pointerdown, not click: a click waits for the finger to lift, and a typist
  // on glass is already on the next key by then.
  el.addEventListener('pointerdown', e => {
    const b = e.target.closest && e.target.closest('.tk-key');
    if(!b || !cmdKeysHandlers) return;
    e.preventDefault();
    b.classList.add('down');
    setTimeout(() => b.classList.remove('down'), 110);
    if(b.dataset.k === 'back') cmdKeysHandlers.back();
    else cmdKeysHandlers.press(b.dataset.k);
  });
  return el;
}
function cmdKeysBind(press, back){ cmdKeysHandlers = { press, back }; }
function cmdShowKeys(on){
  const el = document.getElementById('g-type-keys');
  if(!el) return;
  // Touch only: a keyboard's own keys are faster than any on-screen copy of
  // them, and the keypad would cost the board height it does not need to lose.
  const want = !!on && (typeof isTouchDevice !== 'undefined' ? isTouchDevice : false);
  if(want) cmdBuildKeys();
  el.style.display = want ? '' : 'none';
  if(!on) cmdKeysHandlers = null;
}

// ── THE 2D BUILD — a terminal the viruses fall down ─────────────────────
function startCommandLine(){
  document.getElementById('g-canvas-holder').style.display = 'block';
  const W = BOARD_W, H = BOARD_H;
  let shake = 0, flash = 0, flashText = '', typoFlash = 0;
  const bolts = [], parts = [], rings = [];
  const round = cmdRound({
    onKey(r){
      if(r.type === 'typo'){ typoFlash = 1; shake = 5; }
      if(r.type === 'lock' || r.type === 'hit' || r.type === 'kill'){
        bolts.push({ x: S.coreX, y: S.coreY - 14, tx: r.v.x, ty: r.v.y, t: 0 });
      }
      if(r.type === 'kill'){
        for(let i = 0; i < (r.v.boss ? 34 : 16); i++){
          const a = Math.random() * 6.283, v = 40 + Math.random() * 140;
          parts.push({ x: r.v.x, y: r.v.y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life: 0.7, c: r.v.boss ? '#ffd700' : '#ff4df0' });
        }
        rings.push({ x: r.v.x, y: r.v.y, t: 0, boss: r.v.boss });
        if(r.combo > 1 && r.combo % CMD.COMBO_STEP === 0){ flash = 1; flashText = `CLEAN RUN ×${r.mult.toFixed(2)}`; }
      }
    },
    onEvent(e){
      if(e.type === 'breach'){ shake = 12; flash = 1; flashText = e.v.boss ? 'SHELL BREACHED ×2' : 'SHELL BREACHED'; }
      if(e.type === 'saved'){ flash = 1; flashText = '🛡️ SHIELD CATCH'; }
      if(e.type === 'boss'){ flash = 1; flashText = '⚠ HEAVY PROCESS INCOMING'; }
    }
  });
  fitCanvas();
  const S = round.S;
  let last = gNow();

  function wordLabel(v){
    const locked = S.lock === v.id;
    const done = v.word.slice(0, v.typed), rest = v.word.slice(v.typed);
    aCtx.save();
    aCtx.font = `700 ${v.boss ? 17 : 14}px Consolas, Menlo, "DejaVu Sans Mono", monospace`;
    aCtx.textBaseline = 'middle';
    const wDone = aCtx.measureText(done).width, wAll = aCtx.measureText(v.word).width;
    let x = v.x - wAll / 2;
    x = Math.max(6, Math.min(W - wAll - 6, x));
    const y = v.y - (v.boss ? 30 : 22);
    aCtx.fillStyle = locked ? 'rgba(0,30,40,0.85)' : 'rgba(4,4,14,0.72)';
    aCtx.strokeStyle = locked ? '#00f5ff' : 'rgba(255,255,255,0.14)';
    aCtx.lineWidth = locked ? 1.5 : 1;
    aCtx.beginPath(); aCtx.roundRect(x - 6, y - 11, wAll + 12, 22, 5); aCtx.fill(); aCtx.stroke();
    aCtx.fillStyle = '#00f5ff'; aCtx.shadowBlur = locked ? 10 : 0; aCtx.shadowColor = '#00f5ff';
    aCtx.fillText(done, x, y + 1);
    aCtx.shadowBlur = 0;
    aCtx.fillStyle = locked ? '#ffffff' : 'rgba(234,246,255,0.92)';
    aCtx.fillText(rest, x + wDone, y + 1);
    aCtx.restore();
  }

  function loop(){
    gameLoopId = requestAnimationFrame(loop);
    const now = gNow();
    const dt = Math.max(0, Math.min(0.05, (now - last) / 1000)); last = now;
    round.step(dt);

    aCtx.clearRect(0, 0, W, H);
    aCtx.save();
    if(shake > 0){ aCtx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake); if(dt > 0){ shake *= 0.86; if(shake < 0.3) shake = 0; } }
    // The terminal: a dark screen, a faint grid, scanlines.
    const g = aCtx.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, '#030712'); g.addColorStop(1, '#06121a');
    aCtx.fillStyle = g; aCtx.fillRect(0, 0, W, H);
    aCtx.strokeStyle = 'rgba(57,255,20,0.05)'; aCtx.lineWidth = 1;
    for(let x = 0; x <= W; x += 28){ aCtx.beginPath(); aCtx.moveTo(x, 0); aCtx.lineTo(x, H); aCtx.stroke(); }
    for(let y = 0; y <= H; y += 28){ aCtx.beginPath(); aCtx.moveTo(0, y); aCtx.lineTo(W, y); aCtx.stroke(); }
    aCtx.fillStyle = 'rgba(0,0,0,0.12)';
    for(let y = 0; y < H; y += 3) aCtx.fillRect(0, y, W, 1);

    // The lock: a beam from the shell to the target.
    const lk = S.lock ? S.viruses.find(v => v.id === S.lock) : null;
    if(lk){
      aCtx.save();
      aCtx.strokeStyle = 'rgba(0,245,255,0.35)'; aCtx.lineWidth = 2; aCtx.setLineDash([6, 6]);
      aCtx.lineDashOffset = -S.t * 40;
      aCtx.beginPath(); aCtx.moveTo(S.coreX, S.coreY - 16); aCtx.lineTo(lk.x, lk.y); aCtx.stroke();
      aCtx.restore();
    }

    // Viruses: a spiked core that pulses, bigger and gold-rimmed for a boss.
    for(const v of S.viruses){
      const r = v.boss ? 17 : 11;
      const hit = S.t - v.hitAt < 0.12;
      const danger = v.age / v.fall;
      const col = v.boss ? '#ffb000' : danger > 0.75 ? '#ff2442' : '#ff2bd6';
      aCtx.save();
      aCtx.translate(v.x, v.y);
      aCtx.rotate(v.age * (v.boss ? 0.8 : 1.6));
      aCtx.shadowBlur = hit ? 26 : 16; aCtx.shadowColor = col;
      aCtx.strokeStyle = col; aCtx.lineWidth = 2;
      const spikes = v.boss ? 10 : 7;
      aCtx.beginPath();
      for(let i = 0; i < spikes; i++){
        const a = i / spikes * 6.283;
        aCtx.moveTo(Math.cos(a) * r * 0.7, Math.sin(a) * r * 0.7);
        aCtx.lineTo(Math.cos(a) * r * 1.35, Math.sin(a) * r * 1.35);
      }
      aCtx.stroke();
      aCtx.fillStyle = hit ? '#ffffff' : col;
      aCtx.beginPath(); aCtx.arc(0, 0, r * 0.72, 0, 6.283); aCtx.fill();
      aCtx.fillStyle = 'rgba(0,0,0,0.45)';
      aCtx.beginPath(); aCtx.arc(0, 0, r * 0.34, 0, 6.283); aCtx.fill();
      aCtx.restore();
      if(S.lock === v.id){
        aCtx.save();
        aCtx.strokeStyle = '#00f5ff'; aCtx.lineWidth = 1.5;
        aCtx.beginPath(); aCtx.arc(v.x, v.y, r * 1.8 + Math.sin(S.t * 8) * 2, 0, 6.283); aCtx.stroke();
        aCtx.restore();
      }
    }
    for(const v of S.viruses) wordLabel(v);

    // Bolts and bursts.
    for(let i = bolts.length - 1; i >= 0; i--){
      const b = bolts[i];
      if(dt > 0) b.t += dt / 0.1;
      if(b.t >= 1){ bolts.splice(i, 1); continue; }
      const x = b.x + (b.tx - b.x) * b.t, y = b.y + (b.ty - b.y) * b.t;
      aCtx.save(); aCtx.fillStyle = '#b8ffff'; aCtx.shadowBlur = 12; aCtx.shadowColor = '#00f5ff';
      aCtx.beginPath(); aCtx.arc(x, y, 3.2, 0, 6.283); aCtx.fill(); aCtx.restore();
    }
    for(let i = parts.length - 1; i >= 0; i--){
      const p = parts[i];
      if(dt > 0){ p.life -= dt; p.x += p.vx * dt; p.y += p.vy * dt; p.vx *= 0.94; p.vy *= 0.94; }
      if(p.life <= 0){ parts.splice(i, 1); continue; }
      aCtx.save(); aCtx.globalAlpha = Math.min(1, p.life / 0.5); aCtx.fillStyle = p.c;
      aCtx.fillRect(p.x - 1.5, p.y - 1.5, 3, 3); aCtx.restore();
    }
    for(let i = rings.length - 1; i >= 0; i--){
      const q = rings[i];
      if(dt > 0) q.t += dt * 2.6;
      if(q.t >= 1){ rings.splice(i, 1); continue; }
      aCtx.save(); aCtx.globalAlpha = 1 - q.t; aCtx.strokeStyle = q.boss ? '#ffd700' : '#ff4df0'; aCtx.lineWidth = 2;
      aCtx.beginPath(); aCtx.arc(q.x, q.y, 10 + q.t * (q.boss ? 60 : 36), 0, 6.283); aCtx.stroke(); aCtx.restore();
    }

    // The shell: a prompt block, the half-typed word, the integrity pips.
    if(dt > 0) typoFlash = Math.max(0, typoFlash - dt * 3);
    const px = S.coreX - 92, py = S.coreY - 16;
    aCtx.save();
    aCtx.fillStyle = typoFlash > 0 ? `rgba(255,36,66,${0.25 + typoFlash * 0.4})` : 'rgba(0,20,12,0.9)';
    aCtx.strokeStyle = typoFlash > 0 ? '#ff2442' : '#39ff14'; aCtx.lineWidth = 1.5;
    aCtx.shadowBlur = 14; aCtx.shadowColor = aCtx.strokeStyle;
    aCtx.beginPath(); aCtx.roundRect(px, py, 184, 34, 6); aCtx.fill(); aCtx.stroke();
    aCtx.shadowBlur = 0;
    aCtx.font = '700 15px Consolas, Menlo, "DejaVu Sans Mono", monospace'; aCtx.textBaseline = 'middle';
    const shown = lk ? lk.word.slice(0, lk.typed) : '';
    const caret = Math.floor(S.t * 2) % 2 ? '_' : ' ';
    aCtx.fillStyle = '#39ff14';
    aCtx.fillText('> ' + shown + caret, px + 10, py + 17);
    for(let i = 0; i < CMD.INTEGRITY; i++){
      aCtx.fillStyle = i < S.integrity ? '#39ff14' : 'rgba(255,255,255,0.12)';
      aCtx.fillRect(px + 184 - 14 - i * 12, py + 12, 8, 10);
    }
    aCtx.restore();

    // Top-left: the multiplier and the clean-run count.
    const m = round.mult();
    aCtx.font = '700 12px Orbitron, sans-serif'; aCtx.textAlign = 'left'; aCtx.textBaseline = 'alphabetic';
    aCtx.fillStyle = m > 1 ? '#ffd700' : 'rgba(234,246,255,0.7)';
    aCtx.fillText(`×${m.toFixed(2)}` + (S.combo ? ` · CLEAN ${S.combo}` : ''), 12, 22);

    if(flash > 0){
      if(dt > 0) flash -= dt * 1.2;
      aCtx.save();
      aCtx.globalAlpha = Math.max(0, flash);
      aCtx.font = '900 22px Orbitron, sans-serif'; aCtx.textAlign = 'center';
      aCtx.fillStyle = '#eaffff'; aCtx.shadowBlur = 18; aCtx.shadowColor = '#00f5ff';
      aCtx.fillText(flashText, W / 2, H * 0.42);
      aCtx.restore();
    }
    aCtx.restore();
  }
  gameLoopId = requestAnimationFrame(loop);
}

// ══════════════════════════════════════════════════════════════════════
//  🚀 3D MISSIONS, PART VII · ⌨️ COMMAND LINE 3D — processes on the deck
// ══════════════════════════════════════════════════════════════════════
// The board rotated onto the floor: viruses come down a long deck toward the
// shell's turret, which turns to face whatever you are typing at — the
// turret turns, the camera never does (§ 3's never-yaw rule is about input,
// and here the input is letters). The words ride over the viruses as DOM
// labels in the world's text layer, projected every frame, so they stay the
// crisp webfont a player has to read at speed; unmount() clears the layer.
(function(){
'use strict';

const P = window.PI3D;
if(!P) return;
const K = P.kit;
const { begin3d, runLoop } = K;

const TERM = {
  env:  { zenith:'#02040f', horizon:'#0a3a2c', ground:'#03070a', intensity: 1.2 },
  fog:  { color:'#03100c', density: 0.0072 },
  sun:  { dir:[-0.3, -1, -0.5], color:'#4fffb0', intensity: 0.5 },
  grade:{ exposure: 0.95, bloom: 0.45, threshold: 1.6, knee: 0.5, radius: 0.9,
          vignette: 0.46, aberration: 0.35, grain: 0.03, scanline: 0.02, saturation: 1.1 }
};

P.games.cmdline = function(){
  const w = begin3d(Object.assign({ ease: 0.1 }, TERM));
  if(!w) return;
  const r = w.r;
  w.buildCity({ seed: 20261001, count: 70, spread: 120, hole: 18, y: -6 });
  w.buildStars(140);
  const layer = document.getElementById('gl-fx');
  const labels = new Map();                 // virus id → { el, key }
  let aim = 0, recoil = 0, typo = 0, barrelK = 0;

  // Board space → the deck. The shell sits at z = 3; a virus spawns 40 back.
  let S = null;
  const X = x => (x / S.W - 0.5) * 22;
  const Z = y => -40 + (y / S.coreY) * 43;
  const at = v => [X(v.x), v.boss ? 1.9 : 1.35, Z(v.y)];
  const SHELL = [0, 0.9, 4.2];

  const round = cmdRound({
    onKey(res){
      if(res.type === 'typo'){ typo = 1; w.kick(0.35); return; }
      if(!res.v) return;
      const p = at(res.v);
      // A bolt: one fast spark from the barrel toward the target. ✨ v59 · out of
      // a barrel tip (the turret's muzzleR/L in turn, drawn at y 1.25, scale 1.1)
      barrelK++;
      const ya = Math.atan2(-(p[0] - SHELL[0]), -(p[2] - SHELL[2])), yc = Math.cos(ya), ys = Math.sin(ya);
      const bq = [barrelK % 2 ? 0.16 : -0.16, 0, -0.86];
      const o = [SHELL[0] + (bq[0] * yc + bq[2] * ys) * 1.1, 1.25, SHELL[2] + (-bq[0] * ys + bq[2] * yc) * 1.1];
      const dx = p[0] - o[0], dz = p[2] - o[2], dy = p[1] - o[1], L = Math.hypot(dx, dy, dz) || 1;
      w.spark(o, '#b8ffff', 0.42, L / 90, [dx / L * 90, dy / L * 90, dz / L * 90]);
      recoil = 1;
      if(res.type === 'kill'){
        w.burst(p, res.v.boss ? '#ffd700' : '#ff4df0', res.v.boss ? 46 : 24, { speed: res.v.boss ? 14 : 10, life: 0.7, size: 0.36 });
        w.kick(res.v.boss ? 1.2 : 0.35);
        if(res.combo > 1 && res.combo % CMD.COMBO_STEP === 0) w.pop([p[0], p[1] + 2.4, p[2]], `CLEAN ×${res.mult.toFixed(2)}`, '#ffd700', { size: 16 });
      }
    },
    onEvent(e){
      if(e.type === 'breach'){ w.kick(2); w.burst([SHELL[0], 1.2, SHELL[2]], '#ff2442', 34, { speed: 12, life: 0.8 }); }
      if(e.type === 'saved'){ w.pop([SHELL[0], 3, SHELL[2]], 'SHIELD CATCH', '#a855f7'); w.kick(0.8); }
      if(e.type === 'boss'){ w.pop([0, 4, -30], 'HEAVY PROCESS', '#ffb000', { size: 18, life: 1.6 }); }
    }
  });
  S = round.S;

  function label(v, sp){
    let L = labels.get(v.id);
    if(!L){
      const el = document.createElement('div');
      el.className = 'cmd-lbl' + (v.boss ? ' boss' : '');
      layer.appendChild(el);
      L = { el, key: '' };
      labels.set(v.id, L);
    }
    const lock = S.lock === v.id;
    const key = v.typed + (lock ? 'L' : '');
    if(L.key !== key){
      L.key = key;
      L.el.innerHTML = `<b>${v.word.slice(0, v.typed)}</b>${v.word.slice(v.typed)}`;
      L.el.classList.toggle('lock', lock);
    }
    if(!sp){ L.el.style.opacity = '0'; return; }
    L.el.style.opacity = '1';
    L.el.style.transform = `translate(-50%,-100%) translate(${sp.x.toFixed(1)}px,${sp.y.toFixed(1)}px)`;
  }

  runLoop(dt => {
    round.step(dt);
    if(dt > 0){ recoil = Math.max(0, recoil - dt * 6); typo = Math.max(0, typo - dt * 3); }
    const lk = S.lock ? S.viruses.find(v => v.id === S.lock) : null;
    // ✨ v59 · the turret noses −Z: yaw = atan2(−dx, −dz) (the sign was mirrored)
    const want = lk ? Math.atan2(-(X(lk.x) - SHELL[0]), -(Z(lk.y) - SHELL[2])) : 0;
    if(dt > 0) aim += (want - aim) * Math.min(1, dt * 14);

    w.goal.eye[0] = 0; w.goal.eye[1] = 10.5; w.goal.eye[2] = 16;
    w.goal.target[0] = 0; w.goal.target[1] = 0; w.goal.target[2] = -12;
    w.goal.fov = 56;
    w.step(dt);

    w.begin();
    w.drawStars();
    // Roughness 0.4, not a mirror: a glossy deck under a point light returns a
    // hard specular blob that reads as an object sitting in the lane.
    r.draw('ground', { pos:[0, 0, -18], scale:[26, 1, 52], color:'#03080a', metallic: 0.8, roughness: 0.4, rim: 0.4 });
    w.drawGrid({ y: 0.02, halfX: 12, halfZ: 26, step: 3, color:'#1b7a4a', emissive: 0.9, width: 0.05 });
    w.drawCity(0);
    for(const s of [-1, 1]){
      r.beam([s * 11.6, 0.08, -44], [s * 11.6, 0.08, 6], 0.12, { color:'#39ff88', emissive:'#39ff88', emissiveStrength: 2, height: 0.1 });
    }
    // The line a virus must not cross.
    r.beam([-11.6, 0.09, SHELL[2] - 1.6], [11.6, 0.09, SHELL[2] - 1.6], 0.14,
           { color:'#ff2442', emissive:'#ff2442', emissiveStrength: 2.2 + typo * 3, height: 0.12 });

    // The shell: a turret that turns to face what you are typing at.
    r.draw('core', { pos:[SHELL[0], 0.45, SHELL[2]], scale: 1.3, color:'#0c1a14', metallic: 0.8, roughness: 0.3, rim: 1.2,
                     emissive: typo > 0 ? '#ff2442' : '#39ff14', emissiveStrength: 0.8 + typo * 2 });
    r.draw('turret', { pos:[SHELL[0], 1.25, SHELL[2] + recoil * 0.25], rot:[0, aim, 0], scale: 1.1,
                       color:'#bfe9d0', metallic: 1, roughness: 0.2, rim: 1.4, emissive: '#39ff14', emissiveStrength: 0.6 });
    for(let i = 0; i < CMD.INTEGRITY; i++){
      const on = i < S.integrity;
      r.draw('thintorus', { pos:[SHELL[0] - 1.6 + i * 1.6, 0.2, SHELL[2] + 1.8], rot:[Math.PI / 2, 0, w.t], scale: 0.6,
                            color: on ? '#39ff14' : '#2a3a30', emissive: on ? '#39ff14' : '#2a3a30', emissiveStrength: on ? 2.2 : 0.2 });
    }
    if(lk){
      const p = at(lk);
      r.beam([SHELL[0], 1.5, SHELL[2] - 0.6], p, 0.05, { color:'#00f5ff', emissive:'#00f5ff', emissiveStrength: 2.4, height: 0.05 });
    }

    // The processes.
    for(const v of S.viruses){
      const p = at(v);
      const danger = v.age / v.fall;
      const col = v.boss ? '#ffb000' : danger > 0.75 ? '#ff2442' : '#ff2bd6';
      const hit = S.t - v.hitAt < 0.12;
      const sc = v.boss ? 1.5 : 0.95;
      // ✨ v60 · PAINTED, NOT LIT (see ENEMY_PAINT): a glossy painted shell in
      // its threat colour inside two chrome-and-paint orbit rings — no hull lit
      // from inside, no neon rings, no halo. White for the instant a key lands.
      r.draw('lowsphere', { pos: p, rot:[v.age * 1.3, v.age * 0.9, 0], scale: sc, ...P.kit.foeLook(col, hit) });
      r.draw('torus', { pos: p, rot:[v.age * 2, 0, 0.6], scale: sc * 1.45, ...P.kit.foeLook(col, hit, { metallic: 0.7, roughness: 0.3 }) });
      r.draw('torus', { pos: p, rot:[0.5, v.age * 2.4, Math.PI / 2], scale: sc * 1.3, color: '#c9ced8', metallic: 0.9, roughness: 0.22, rim: 0.4 });
      if(S.lock === v.id){
        r.draw('thintorus', { pos:[p[0], 0.1, p[2]], rot:[Math.PI / 2, 0, w.t * 3], scale: sc * 2.4,
                              color:'#00f5ff', emissive:'#00f5ff', emissiveStrength: 2.6 });
      }
    }
    r.light({ pos:[SHELL[0], 4, SHELL[2]], color: typo > 0 ? '#ff2442' : '#39ff88', intensity: 180, range: 20 });
    r.light({ pos:[0, 15, -34], color:'#ff2bd6', intensity: 220, range: 50 });
    w.end();

    // Labels last, after the frame is drawn: every projection first, then
    // every write, so no read in the loop has to wait on a style change.
    const shown = new Set();
    const pos = S.viruses.map(v => { const p = at(v); return r.project([p[0], p[1] + (v.boss ? 1.9 : 1.4), p[2]]); });
    S.viruses.forEach((v, i) => { shown.add(v.id); label(v, pos[i]); });
    for(const [id, L] of labels){ if(!shown.has(id)){ L.el.remove(); labels.delete(id); } }
  });
};

})();

// ══════════════════════════════════════════════════════════════════════
//  § 27 · v53 — 🎬 CLIP RECORDER
// ══════════════════════════════════════════════════════════════════════
// Every round on a canvas board is recorded as it is played, and the last
// ~twelve seconds of it — plus a one-second end card — can be saved from the
// results card as a video: MP4 (H.264) where the browser can encode it, WebM
// otherwise. On a phone it goes straight to the share sheet with the round's
// challenge link; on a desktop it downloads. Nothing is uploaded, anywhere.
//
// Every clip carries its own advert: the mission, the live score and the
// site's address are burned into the picture, so a clip posted anywhere says
// where to play.
//
// HOW (WebCodecs, no library):
//   · a 2D board is sampled from #arcade-canvas on a frame loop of its own; a
//     3D round is grabbed inside runLoop() in the SAME turn as the render,
//     because the GL canvas has no preserveDrawingBuffer (a separate callback
//     would copy a blank buffer);
//   · each grab is drawn onto a small compositing canvas with the overlay and
//     handed to a VideoEncoder with a keyframe every second, at most 30 fps,
//     timestamped on ROUND time (gNow) so a pause or a photo leaves no hole;
//   · encoded chunks go into a rolling buffer trimmed at a keyframe to the
//     last CLIP_SECS, so memory stays at a few megabytes however long you play;
//   · on save, the chunks are wrapped in a container written here (mp4Mux /
//     webmMux): the chunks ARE the video, so the container is only an index.
//
// Missions whose 2D build is DOM rather than canvas (Click Frenzy's button,
// Memory Match's grid, Math Blitz…) have nothing to record in 2D and offer no
// clip; in 3D every mission has a canvas. A duel, a party turn and a lab run
// start without prepGame() and are not recorded. Off switch: ⚙️ SETTINGS.
//
// ⚠️ LOAD ORDER: hooks reach this from prepGame, showResults, stopGame,
// runLoop (§ 2) and showResultsCard — every name they touch is a `var` or a
// function declaration.
var CLIP_KEY = 'pi_clips';
var CLIP_SECS = 12, CLIP_FPS = 30, CLIP_KF = 30, CLIP_END = 36;
var clip = null;            // the round being recorded
var clipDone = null;        // the last round's clip, ready to save
var clipSeq = 0;            // bumps every start, so a late flush can tell it is stale
var clipCodec = null;       // the encoder config this device supports, or null
var clipProbed = false;

function clipSupported(){ return typeof VideoEncoder === 'function' && typeof VideoFrame === 'function'; }
function clipsEnabled(){ try{ return localStorage.getItem(CLIP_KEY) !== '0'; }catch(e){ return true; } }
function clipSize(){
  // Multiples of 16 (encoders are happiest on whole macroblocks), at the
  // board's own 560:500 aspect. Smaller on a touch device: the encoder shares
  // a phone's budget with the round.
  return (typeof isTouchDevice !== 'undefined' && isTouchDevice) ? [640, 576] : [896, 800];
}
async function clipProbe(){
  if(clipProbed || !clipSupported()) return clipCodec;
  clipProbed = true;
  const [w, h] = clipSize();
  const base = { width: w, height: h, bitrate: 2500000, framerate: CLIP_FPS, latencyMode: 'realtime' };
  const tries = [
    { kind: 'mp4',  config: Object.assign({ codec: 'avc1.42001f', avc: { format: 'avc' } }, base) },
    { kind: 'mp4',  config: Object.assign({ codec: 'avc1.4d001f', avc: { format: 'avc' } }, base) },
    { kind: 'webm', config: Object.assign({ codec: 'vp09.00.10.08' }, base) },
    { kind: 'webm', config: Object.assign({ codec: 'vp8' }, base) }
  ];
  for(const t of tries){
    try{
      const s = await VideoEncoder.isConfigSupported(t.config);
      if(s && s.supported){ clipCodec = t; break; }
    }catch(e){ /* this codec is not on this device — try the next */ }
  }
  paintClipToggle();
  return clipCodec;
}
function clipHost(){
  const href = document.querySelector('link[rel="canonical"]')?.href || location.href;
  try{ const u = new URL(href); return (u.host + u.pathname).replace(/\/+$/, ''); }catch(e){ return 'Point Invaders'; }
}

// From prepGame's countdown callback, right after the mission has started.
function clipStart(gid){
  clipStop({ discard: true });
  clipDone = null;
  clipSeq++;
  if(!clipsEnabled() || !clipSupported() || !clipCodec || !META[gid]) return;
  if(mp || (typeof partyRunActive === 'function' && partyRunActive()) || (typeof labActive === 'function' && labActive())) return;
  const gl = document.getElementById('gl-canvas');
  const is3d = !!(gl && gl.style.display !== 'none' && getComputedStyle(gl).display !== 'none' &&
                  document.body.classList.contains('mode-3d'));
  const holder = document.getElementById('g-canvas-holder');
  const src = is3d ? gl : document.getElementById('arcade-canvas');
  // A DOM mission in 2D: its board is not a canvas, so there is nothing to film.
  if(!src || (!is3d && (!holder || holder.style.display === 'none' || !document.getElementById('game-screen').classList.contains('canvas-game')))) return;
  const [W, H] = clipSize();
  const cv = document.createElement('canvas');
  cv.width = W; cv.height = H;
  const c = { seq: clipSeq, gid, is3d, src, cv, ctx: cv.getContext('2d'), chunks: [], meta: null, W, H,
              g0: gNow(), last: -1e9, lastTs: 0, n: 0, raf: 0, broken: false,
              host: clipHost(), title: META[gid].emoji + '  ' + META[gid].name };
  try{
    c.enc = new VideoEncoder({
      output: (chunk, md) => {
        const data = new Uint8Array(chunk.byteLength);
        chunk.copyTo(data);
        c.chunks.push({ key: chunk.type === 'key', ts: chunk.timestamp, data });
        const desc = md && md.decoderConfig && md.decoderConfig.description;
        if(desc && !c.meta) c.meta = new Uint8Array(desc.buffer ? desc.buffer.slice(desc.byteOffset || 0, (desc.byteOffset || 0) + desc.byteLength) : desc);
        clipTrim(c);
      },
      error: e => { console.warn('🎬 Clip encoder stopped:', e && e.message); c.broken = true; }
    });
    c.enc.configure(Object.assign({}, clipCodec.config, { width: W, height: H }));
  }catch(e){ console.warn('🎬 Clip recorder unavailable:', e && e.message); return; }
  clip = c;
  if(!is3d){
    const tick = () => { if(clip !== c) return; clipGrab(c); c.raf = requestAnimationFrame(tick); };
    c.raf = requestAnimationFrame(tick);
  }
}

// From resetGameStage(): every round starts without the last one's clip —
// including the rounds that are never recorded (a duel, a party turn, a lab
// run), whose cards must not offer a clip of something else. Bumping the
// sequence also drops a flush still in flight for the round before.
function clipReset(){
  clipDone = null;
  clipSeq++;
  clipPaintButton();
}

// Called by runLoop() (§ 2) straight after a 3D frame is rendered.
function clipGrab3D(){ if(clip && clip.is3d) clipGrab(clip); }

function clipOverlay(c){
  const x = c.ctx, W = c.W, H = c.H, s = W / 896;
  const g = x.createLinearGradient(0, 0, 0, 74 * s);
  g.addColorStop(0, 'rgba(2,3,12,0.8)'); g.addColorStop(1, 'rgba(2,3,12,0)');
  x.fillStyle = g; x.fillRect(0, 0, W, 74 * s);
  x.textBaseline = 'top';
  x.font = `900 ${Math.round(22 * s)}px Orbitron, sans-serif`;
  x.fillStyle = '#00f5ff'; x.textAlign = 'left';
  x.fillText(c.title, 18 * s, 14 * s);
  const pts = (document.getElementById('g-pts') || {}).textContent || '0';
  x.fillStyle = '#ffd700'; x.textAlign = 'right';
  x.fillText(pts + ' PTS', W - 18 * s, 14 * s);
  const bh = 42 * s;
  x.fillStyle = 'rgba(2,3,12,0.74)'; x.fillRect(0, H - bh, W, bh);
  x.textBaseline = 'middle'; x.textAlign = 'left';
  x.font = `700 ${Math.round(16 * s)}px Rajdhani, sans-serif`;
  x.fillStyle = 'rgba(234,246,255,0.92)';
  x.fillText('▶ PLAY FREE · ' + c.host, 18 * s, H - bh / 2);
  x.textAlign = 'right'; x.fillStyle = '#ff2bd6';
  x.font = `900 ${Math.round(14 * s)}px Orbitron, sans-serif`;
  x.fillText('POINT INVADERS', W - 18 * s, H - bh / 2);
  x.textAlign = 'left';
}

function clipGrab(c){
  if(c.broken || !c.enc || c.enc.state !== 'configured') return;
  if(typeof photoActive === 'function' && photoActive()) return;
  const now = gNow();
  if(now - c.last < 1000 / CLIP_FPS - 2) return;
  // An encoder that has fallen behind drops a frame rather than queueing more
  // work into the round it is sharing the device with.
  if(c.enc.encodeQueueSize > 3) return;
  c.last = now;
  try{
    c.ctx.drawImage(c.src, 0, 0, c.W, c.H);
    clipOverlay(c);
    const ts = Math.round((now - c.g0) * 1000);
    const vf = new VideoFrame(c.cv, { timestamp: ts });
    c.enc.encode(vf, { keyFrame: c.n % CLIP_KF === 0 });
    vf.close();
    c.lastTs = ts; c.n++;
  }catch(e){ c.broken = true; }
}

// Keeps the buffer to the last CLIP_SECS, cut at a keyframe so it still starts
// on a picture a player can decode.
function clipTrim(c){
  const ch = c.chunks;
  if(ch.length < 2) return;
  const last = ch[ch.length - 1].ts;
  let cut = 0;
  for(let i = 0; i < ch.length; i++){ if(ch[i].key && last - ch[i].ts >= CLIP_SECS * 1e6) cut = i; }
  if(cut > 0) ch.splice(0, cut);
}

function clipEndCard(c, pts, i){
  const x = c.ctx, W = c.W, H = c.H, s = W / 896;
  const k = Math.min(1, i / 8);
  x.fillStyle = `rgba(3,4,14,${0.55 + 0.35 * k})`;
  x.fillRect(0, 0, W, H);
  x.textAlign = 'center'; x.textBaseline = 'middle';
  x.font = `900 ${Math.round(24 * s)}px Orbitron, sans-serif`;
  x.fillStyle = '#00f5ff';
  x.fillText(c.title, W / 2, H * 0.34);
  x.font = `900 ${Math.round(74 * s)}px Orbitron, sans-serif`;
  x.fillStyle = '#ffd700';
  x.fillText(Math.max(0, Math.round(+pts || 0)).toLocaleString(), W / 2, H * 0.5);
  x.font = `700 ${Math.round(20 * s)}px Rajdhani, sans-serif`;
  x.fillStyle = 'rgba(234,246,255,0.95)';
  x.fillText('THINK YOU CAN BEAT IT?  ·  PLAY FREE AT ' + c.host, W / 2, H * 0.66);
  x.font = `900 ${Math.round(16 * s)}px Orbitron, sans-serif`;
  x.fillStyle = '#ff2bd6';
  x.fillText('POINT INVADERS', W / 2, H * 0.76);
  x.textAlign = 'left';
}

// From showResults (with the round's score) or stopGame (a quit: discarded).
async function clipStop(o){
  o = o || {};
  const c = clip;
  if(!c) return;
  clip = null;
  if(c.raf) cancelAnimationFrame(c.raf);
  if(o.discard || c.broken){ try{ c.enc.close(); }catch(e){} return; }
  try{
    // Out of the moment the round ends: the end card is 36 frames of drawing
    // and encoding, and that moment belongs to the death sting.
    await new Promise(r => setTimeout(r, 0));
    // The end card: the final number and where to play, held for a second.
    if(c.n > 0 && c.enc.state === 'configured'){
      for(let i = 0; i < CLIP_END; i++){
        clipEndCard(c, o.pts, i);
        const vf = new VideoFrame(c.cv, { timestamp: c.lastTs + Math.round((i + 1) * 1e6 / CLIP_FPS) });
        c.enc.encode(vf, { keyFrame: i === 0 });
        vf.close();
      }
    }
    await c.enc.flush();
    c.enc.close();
  }catch(e){ return; }
  clipTrim(c);
  // Stale: another round started while this one flushed.
  if(c.seq !== clipSeq) return;
  if(c.chunks.length < CLIP_FPS || !c.chunks[0].key || (clipCodec.kind === 'mp4' && !c.meta)) return;
  clipDone = { chunks: c.chunks, meta: c.meta, W: c.W, H: c.H, kind: clipCodec.kind, codec: clipCodec.config.codec,
               gid: c.gid, pts: Math.max(0, Math.round(+o.pts || 0)) };
  clipPaintButton();
}

// ── THE CONTAINERS ──
function clipBytes(parts){
  let n = 0;
  for(const p of parts) n += p.length;
  const out = new Uint8Array(n);
  let o = 0;
  for(const p of parts){ out.set(p, o); o += p.length; }
  return out;
}
function mp4Mux(d){
  const u32 = v => new Uint8Array([(v >>> 24) & 255, (v >>> 16) & 255, (v >>> 8) & 255, v & 255]);
  const u16 = v => new Uint8Array([(v >>> 8) & 255, v & 255]);
  const str = t => new Uint8Array([...t].map(ch => ch.charCodeAt(0)));
  const zeros = n => new Uint8Array(n);
  const box = (type, ...parts) => { const body = clipBytes(parts); return clipBytes([u32(body.length + 8), str(type), body]); };
  const full = (type, ver, flags, ...parts) => box(type, new Uint8Array([ver, (flags >> 16) & 255, (flags >> 8) & 255, flags & 255]), ...parts);
  const matrix = clipBytes([u32(0x00010000), u32(0), u32(0), u32(0), u32(0x00010000), u32(0), u32(0), u32(0), u32(0x40000000)]);

  const TS = 90000;
  const t0 = d.chunks[0].ts;
  const times = d.chunks.map(c => Math.round((c.ts - t0) * TS / 1e6));
  const frame = Math.round(TS / CLIP_FPS);
  const durs = times.map((t, i) => i < times.length - 1 ? Math.max(1, times[i + 1] - t) : frame);
  const total = durs.reduce((a, b) => a + b, 0);
  const ms = Math.round(total * 1000 / TS);

  const sttsE = [];
  for(const v of durs){ const l = sttsE[sttsE.length - 1]; if(l && l[1] === v) l[0]++; else sttsE.push([1, v]); }
  const keys = [];
  d.chunks.forEach((c, i) => { if(c.key) keys.push(i + 1); });

  const ftyp = box('ftyp', str('isom'), u32(512), str('isom'), str('iso2'), str('avc1'), str('mp41'));
  const dataLen = d.chunks.reduce((a, c) => a + c.data.length, 0);
  const mdatHead = clipBytes([u32(dataLen + 8), str('mdat')]);
  const firstOffset = ftyp.length + mdatHead.length;

  const name = new Uint8Array(32); const nm = 'Point Invaders'; name[0] = nm.length; name.set(str(nm), 1);
  const avc1 = box('avc1', zeros(6), u16(1), u16(0), u16(0), zeros(12), u16(d.W), u16(d.H),
                   u32(0x00480000), u32(0x00480000), u32(0), u16(1), name, u16(0x0018), u16(0xffff),
                   box('avcC', d.meta));
  const stbl = box('stbl',
    full('stsd', 0, 0, u32(1), avc1),
    full('stts', 0, 0, u32(sttsE.length), ...sttsE.map(e => clipBytes([u32(e[0]), u32(e[1])]))),
    full('stss', 0, 0, u32(keys.length), ...keys.map(k => u32(k))),
    full('stsc', 0, 0, u32(1), u32(1), u32(d.chunks.length), u32(1)),
    full('stsz', 0, 0, u32(0), u32(d.chunks.length), ...d.chunks.map(c => u32(c.data.length))),
    full('stco', 0, 0, u32(1), u32(firstOffset)));
  const minf = box('minf', full('vmhd', 0, 1, u16(0), u16(0), u16(0), u16(0)),
                   box('dinf', full('dref', 0, 0, u32(1), full('url ', 0, 1))), stbl);
  const mdia = box('mdia',
    full('mdhd', 0, 0, u32(0), u32(0), u32(TS), u32(total), u16(0x55c4), u16(0)),
    full('hdlr', 0, 0, u32(0), str('vide'), zeros(12), str('VideoHandler'), zeros(1)),
    minf);
  const trak = box('trak',
    full('tkhd', 0, 3, u32(0), u32(0), u32(1), u32(0), u32(ms), zeros(8), u16(0), u16(0), u16(0), u16(0),
         matrix, u32(d.W << 16), u32(d.H << 16)),
    mdia);
  const moov = box('moov',
    full('mvhd', 0, 0, u32(0), u32(0), u32(1000), u32(ms), u32(0x00010000), u16(0x0100), zeros(10), matrix, zeros(24), u32(2)),
    trak);
  return new Blob([ftyp, mdatHead, ...d.chunks.map(c => c.data), moov], { type: 'video/mp4' });
}
function webmMux(d){
  const id = hex => new Uint8Array(hex.match(/../g).map(h => parseInt(h, 16)));
  const size8 = n => { const b = new Uint8Array(8); b[0] = 0x01; let v = n; for(let i = 7; i >= 1; i--){ b[i] = v & 255; v = Math.floor(v / 256); } return b; };
  const el = (hex, ...parts) => { const body = clipBytes(parts.map(p => p instanceof Uint8Array ? p : new Uint8Array(p))); return clipBytes([id(hex), size8(body.length), body]); };
  const uint = (hex, v) => { const b = []; do{ b.unshift(v & 255); v = Math.floor(v / 256); }while(v > 0); return el(hex, new Uint8Array(b)); };
  const text = (hex, t) => el(hex, new Uint8Array([...t].map(ch => ch.charCodeAt(0))));
  const f64 = (hex, v) => { const b = new Uint8Array(8); new DataView(b.buffer).setFloat64(0, v); return el(hex, b); };
  const t0 = d.chunks[0].ts;
  const dur = (d.chunks[d.chunks.length - 1].ts - t0) / 1000 + 1000 / CLIP_FPS;
  const blocks = d.chunks.map(c => {
    const rel = Math.round((c.ts - t0) / 1000);
    const head = new Uint8Array([0x81, (rel >> 8) & 255, rel & 255, c.key ? 0x80 : 0x00]);
    return el('A3', clipBytes([head, c.data]));
  });
  const header = el('1A45DFA3', uint('4286', 1), uint('42F7', 1), uint('42F2', 4), uint('42F3', 8),
                    text('4282', 'webm'), uint('4287', 4), uint('4285', 2));
  const info = el('1549A966', uint('2AD7B1', 1000000), text('4D80', 'PointInvaders'), text('5741', 'PointInvaders'), f64('4489', dur));
  const tracks = el('1654AE6B', el('AE', uint('D7', 1), uint('73C5', 1), uint('83', 1),
                    text('86', /^vp09/.test(d.codec) ? 'V_VP9' : 'V_VP8'), el('E0', uint('B0', d.W), uint('BA', d.H))));
  const cluster = el('1F43B675', uint('E7', 0), ...blocks);
  const segment = el('18538067', info, tracks, cluster);
  return new Blob([header, segment], { type: 'video/webm' });
}

// ── THE RESULTS CARD'S BUTTON ──
function clipPaintButton(){
  const b = document.getElementById('btn-clip');
  if(!b) return;
  const gname = document.getElementById('results-screen')?.classList.contains('active');
  const ready = !!clipDone && gname;
  b.style.display = ready ? '' : 'none';
  b.disabled = !ready;
  b.textContent = '🎬 Save Clip';
}
async function saveClip(){
  const d = clipDone, b = document.getElementById('btn-clip');
  if(!d){ snd('deny'); return; }
  let blob;
  try{ blob = d.kind === 'mp4' ? mp4Mux(d) : webmMux(d); }
  catch(e){ console.warn('🎬 Clip could not be written:', e); snd('error'); toast('🎬 That clip could not be written.', 2800); return; }
  try{ if(typeof statsEvent === 'function') statsEvent('_clip'); }catch(e){}
  const name = `point-invaders-${d.gid}-${d.pts}.${d.kind}`;
  const type = d.kind === 'mp4' ? 'video/mp4' : 'video/webm';
  const phone = !!(window.matchMedia && matchMedia('(pointer: coarse)').matches);
  if(phone && typeof File === 'function' && navigator.canShare){
    const file = new File([blob], name, { type });
    if(navigator.canShare({ files: [file] })){
      const run = (typeof clLastRun === 'object' && clLastRun) ? clLastRun : null;
      const text = run ? `⚔️ Beat my ${run.pts.toLocaleString()} in ${META[run.gid].name} on Point Invaders: ${clUrl(run)}`
                       : `👾 ${META[d.gid].name} on Point Invaders — play free: ${document.querySelector('link[rel="canonical"]')?.href || location.href}`;
      try{ await navigator.share({ files: [file], title: 'Point Invaders', text }); snd('coin'); return; }
      catch(e){ if(e && e.name === 'AbortError') return; }
    }
  }
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 60000);
  snd('coin');
  if(b){ b.textContent = '✔ Clip saved'; setTimeout(() => { b.textContent = '🎬 Save Clip'; }, 2400); }
}

// ── ⚙️ SETTINGS ──
function paintClipToggle(){
  const b = document.getElementById('btn-clips');
  const note = document.getElementById('clips-note');
  if(!b) return;
  const ok = clipSupported() && (!clipProbed || !!clipCodec);
  const on = ok && clipsEnabled();
  b.disabled = !ok;
  b.classList.toggle('on', on);
  b.setAttribute('aria-pressed', String(on));
  b.textContent = !ok ? '🎬 CLIPS: NOT SUPPORTED HERE' : on ? '🎬 CLIPS: ON' : '🎬 CLIPS: OFF';
  if(note && !ok) note.textContent = 'This browser cannot encode video, so there is nothing to record — every round still plays exactly the same.';
}

try{
  document.getElementById('btn-clip')?.addEventListener('click', () => saveClip());
  document.getElementById('btn-clips')?.addEventListener('click', () => {
    try{ localStorage.setItem(CLIP_KEY, clipsEnabled() ? '0' : '1'); }catch(e){}
    if(!clipsEnabled()) clipStop({ discard: true });
    paintClipToggle();
    snd('toggle');
    toast(clipsEnabled() ? '🎬 Clips on — the last twelve seconds of each round can be saved from the results card.' : '🎬 Clips off.', 2800);
  });
  paintClipToggle();
  // Probed once, shortly after load, so the first round already knows.
  setTimeout(() => { clipProbe().catch(() => {}); }, 1500);
}catch(e){ console.warn('Clip recorder failed to wire:', e); }

// ══════════════════════════════════════════════════════════════════════
//  § 28 · v55 — 📲 INSTALL · 💾 SAVE WITH GOOGLE
// ══════════════════════════════════════════════════════════════════════
// Two ways to bring a player back, from the 2026-09-30 look at the live
// profiles: of the real sign-ups, only three had ever played two days running
// and only three guests had ever saved their progress to an account.
//
// 📲 INSTALL. The arcade has always been installable (manifest + service
// worker, see index.html), but nothing ever OFFERED it — Chrome shows a
// mini-bar once, early, and then nothing. The browser's own prompt is caught
// here (beforeinstallprompt) and held for a better moment: the ⚙️ Settings
// panel always, and one line on the results card after the third round on
// this device. iPhone and iPad have no prompt at all, so there the same
// button opens a two-step "Share → Add to Home Screen" card instead.
//
// 💾 SAVE WITH GOOGLE. The Save Account modal asked for an email AND a
// password; a guest now picks a username and taps Google. linkWithPopup keeps
// the SAME uid, exactly like the email link, so every point stays where it
// is. A Google account that is already a player is offered as a switch (the
// guest cannot be merged into it — said so before anything is deleted). The
// sign-in screen gets the matching "Continue with Google", and a Google
// account signing in for the first time names itself in a small callsign
// dialog before the hub opens.
//
// Popups, not redirects: the site lives on github.io and signs in through
// neal-with-roblox.firebaseapp.com, and browsers that partition third-party
// storage break signInWithRedirect across those two origins. A popup opened
// straight from the click is not blocked. In-app browsers (Instagram,
// Facebook, TikTok…) are refused by Google itself, so they are told to open
// the page in a real browser instead of watching a popup fail.
//
// Two Console steps before Google works at all — the error text names both:
// Authentication → Sign-in method → Google → Enable, and Authentication →
// Settings → Authorized domains → add cat9748912-cpu.github.io.
//
// ⚠️ LOAD ORDER: hooked from showResultsCard, loadUser and paintSettings, all
// earlier in the file — everything they reach is a var or a function
// declaration (see § 21).

var instEvt = null;                 // the browser's held install prompt (Chrome, Edge, Samsung)
var INST_KEY = 'pi_inst';           // { n: times dismissed, until: ms, done: 1 }
var ROUNDS_KEY = 'pi_rounds';       // results cards seen on this device
var SAVE_NUDGE_KEY = 'pi_save_nudge';

function instStandalone(){
  try{
    if(navigator.standalone === true) return true;
    if(matchMedia('(display-mode: standalone)').matches) return true;
    // The manifest asks for fullscreen; a page the PLAYER sent fullscreen with
    // the ⛶ button matches that query too, so it only counts outside one.
    return matchMedia('(display-mode: fullscreen)').matches && !document.fullscreenElement && !document.webkitFullscreenElement;
  }catch(e){ return false; }
}
function instIOS(){
  const ua = navigator.userAgent || '';
  return /iPad|iPhone|iPod/.test(ua) || (navigator.platform === 'MacIntel' && (navigator.maxTouchPoints || 0) > 1);
}
// Browsers built into other apps: no install, and Google refuses to sign in there.
function gInApp(){
  return /FBAN|FBAV|FB_IAB|Instagram|Line\/|Snapchat|TikTok|musical_ly|BytedanceWebview|GSA\/|MicroMessenger|; wv\)/i.test(navigator.userAgent || '');
}
function instOfferable(){
  if(instStandalone()) return false;
  return !!instEvt || (instIOS() && !gInApp());
}
function instState(){ const o = lsGet(INST_KEY, null); return (o && typeof o === 'object') ? o : { n: 0, until: 0 }; }

// ── ⚙️ SETTINGS ──
function instPaint(){
  const sec = document.getElementById('set-app');
  if(!sec) return;
  const btn = document.getElementById('btn-install');
  const note = document.getElementById('set-app-note');
  const badge = document.getElementById('set-app-state');
  const app = instStandalone();
  sec.hidden = !(app || instOfferable());
  if(sec.hidden) return;
  if(app){
    badge.className = 'set-state ok'; badge.textContent = 'INSTALLED';
    note.textContent = 'You are playing the installed app — it opens from your home screen, full screen, and keeps working offline.';
    btn.hidden = true;
    return;
  }
  badge.className = 'set-state'; badge.textContent = '';
  btn.hidden = false;
  btn.textContent = instEvt ? '📲 Install Point Invaders' : '📲 Add to Home Screen';
  note.textContent = instEvt
    ? 'Put Point Invaders on your home screen or desktop — it opens full screen like an app, starts faster and keeps working offline.'
    : 'Put Point Invaders on your home screen — it opens full screen like an app, starts faster and keeps working offline. Safari does it in two taps.';
}

// The one door both offers use. Resolves true when the player said yes.
async function instGo(src){
  try{ statsEvent('_inst_tap'); }catch(e){}
  if(instEvt){
    const ev = instEvt;
    instEvt = null;              // a prompt can be shown once; the browser deals a fresh one later if still installable
    try{
      await ev.prompt();
      const ch = await ev.userChoice;
      const yes = !!(ch && ch.outcome === 'accepted');
      if(yes){ lsSet(INST_KEY, Object.assign(instState(), { done: 1 })); snd('success'); }
      else snd('uiBack');
      instPaint();
      return yes;
    }catch(e){
      console.warn('Install prompt failed:', e);
      instPaint();
      return false;
    }
  }
  if(instIOS()){ instOpenHowTo(); return false; }
  toast('📲 This browser cannot install web apps — open the arcade in Chrome, Edge or Safari.', 4200);
  return false;
}

// iPhone / iPad: where Safari keeps "Add to Home Screen".
var INST_SHARE_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12"/><path d="M8 7l4-4 4 4"/><path d="M6 11H5a1 1 0 0 0-1 1v8a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-8a1 1 0 0 0-1-1h-1"/></svg>';
var INST_ADD_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M12 8v8M8 12h8"/></svg>';
function instOpenHowTo(){
  const ov = document.getElementById('inst-overlay'), body = document.getElementById('inst-body');
  if(!ov || !body) return;
  try{ statsEvent('_inst_ios'); }catch(e){}
  const safari = /Safari/.test(navigator.userAgent || '') && !/CriOS|FxiOS|EdgiOS/.test(navigator.userAgent || '');
  body.innerHTML =
    `<ol class="inst-steps">` +
      `<li><span>Tap <span class="inst-glyph">${INST_SHARE_SVG}</span> <b>Share</b> — ${safari ? 'in Safari’s toolbar, at the bottom of the screen (at the top on iPad)' : 'in the browser’s address bar or menu'}.</span></li>` +
      `<li><span>Scroll the list and tap <span class="inst-glyph">${INST_ADD_SVG}</span> <b>Add to Home Screen</b>.</span></li>` +
      `<li><span>Tap <b>Add</b>. Point Invaders is now an icon on your home screen.</span></li>` +
    `</ol>` +
    `<div class="inst-note">It opens full screen with no browser bars, and your progress comes with it — same browser storage, same account.</div>` +
    `<button class="btn btn-primary btn-full" id="inst-ok" type="button">Got it</button>`;
  document.getElementById('inst-ok').onclick = () => closeOverlay('inst-overlay');
  ov.classList.add('show');
  ov.setAttribute('aria-hidden', 'false');
  snd('tab');
}

// ── 💬 THE RESULTS CARD'S ONE LINE ──
// Save first (a guest with real points stands to LOSE something), install
// second (after the third card on this device). Never both, never on a duel.
function saveNudgeDue(pts){
  if(!user || !user.isGuest || isLocalSession() || offlineMode || !auth || !db) return false;
  if(!auth.currentUser || !auth.currentUser.isAnonymous) return false;
  const total = (user.totalPoints || 0) + Math.max(0, +pts || 0);
  if(total < 250 || (user.gamesPlayed || 0) < 1) return false;
  const st = lsGet(SAVE_NUDGE_KEY, null) || {};
  return Date.now() >= (+st.until || 0);
}
function instNudgeDue(rounds){
  if(rounds < 3 || !instOfferable()) return false;
  const st = instState();
  if(st.done || (st.n | 0) >= 3) return false;
  return Date.now() >= (+st.until || 0);
}
function resNudgePaint(gid, pts, opts){
  const el = document.getElementById('res-nudge');
  if(!el) return;
  el.hidden = true; el.className = 'res-nudge'; el.textContent = '';
  const rounds = (lsGet(ROUNDS_KEY, 0) | 0) + 1;
  lsSet(ROUNDS_KEY, rounds);
  if(mp || (opts && opts.internal)) return;
  const x = label => {
    const b = document.createElement('button');
    b.className = 'btn rn-x'; b.type = 'button'; b.textContent = '✕'; b.setAttribute('aria-label', label);
    return b;
  };
  const txt = html => { const s = document.createElement('span'); s.className = 'rn-txt'; s.innerHTML = html; return s; };
  const ico = e => { const s = document.createElement('span'); s.className = 'rn-ico'; s.textContent = e; s.setAttribute('aria-hidden', 'true'); return s; };

  if(saveNudgeDue(pts)){
    const total = (user.totalPoints || 0) + Math.max(0, Math.round(+pts || 0));
    el.classList.add('save');
    const go = document.createElement('button');
    go.className = 'btn btn-google rn-go'; go.type = 'button';
    go.innerHTML = (document.querySelector('#up-google .g-logo')?.outerHTML || '') + '<span>Save with Google</span>';
    const no = x('Not now');
    el.append(ico('💾'), txt(`<b>${total.toLocaleString()} PTS</b> live only in this browser. Keep them — pick a name and tap Google.`), go, no);
    go.onclick = () => { try{ statsEvent('_save_tap'); }catch(e){} if(typeof window.openSaveAccount === 'function') window.openSaveAccount(); };
    no.onclick = () => {
      const st = lsGet(SAVE_NUDGE_KEY, null) || {};
      const n = (st.n | 0) + 1;
      lsSet(SAVE_NUDGE_KEY, { n, until: Date.now() + [2, 5, 14][Math.min(2, n - 1)] * DAY_MS });
      el.hidden = true; snd('uiBack');
    };
    el.hidden = false;
    try{ statsEvent('_save_offer'); }catch(e){}
    return;
  }
  if(instNudgeDue(rounds)){
    const go = document.createElement('button');
    go.className = 'btn btn-primary rn-go'; go.type = 'button';
    go.textContent = instEvt ? '📲 Install' : '📲 How?';
    const no = x('Not now');
    el.append(ico('📲'), txt(instEvt ? '<b>Play it like an app</b> — full screen, one tap from your home screen, works offline.'
                                      : '<b>Put it on your home screen</b> — full screen, one tap away, works offline.'), go, no);
    go.onclick = async () => { const yes = await instGo('card'); if(yes) el.hidden = true; };
    no.onclick = () => {
      const st = instState();
      const n = (st.n | 0) + 1;
      lsSet(INST_KEY, Object.assign(st, { n, until: Date.now() + [4, 10, 30][Math.min(2, n - 1)] * DAY_MS }));
      el.hidden = true; snd('uiBack');
    };
    el.hidden = false;
    try{ statsEvent('_inst_offer'); }catch(e){}
  }
}

// ── 🔑 GOOGLE ──────────────────────────────────────────────────────────
var G_INAPP_MSG = 'Google sign-in does not work inside another app’s built-in browser — open this page in Chrome or Safari (⋮ or ⋯ → Open in browser).';
function gProvider(){
  const p = new firebase.auth.GoogleAuthProvider();
  // Always show the account chooser, so a shared computer never signs the
  // next person straight into the last person's arcade.
  try{ p.setCustomParameters({ prompt: 'select_account' }); }catch(e){}
  return p;
}
function gErrText(e){
  const c = e && e.code;
  if(e && e.isOffline) return '📴 No connection to the mainframe.';
  switch(c){
    case 'auth/popup-closed-by-user':
    case 'auth/cancelled-popup-request':
    case 'auth/user-cancelled':
      return '';
    case 'auth/popup-blocked':
      return 'The browser blocked Google’s window — allow pop-ups for this site, then tap the button again.';
    case 'auth/operation-not-allowed':
    case 'auth/admin-restricted-operation':
      return 'Google sign-in is switched off — enable it in the Firebase Console (Authentication → Sign-in method → Google).';
    case 'auth/unauthorized-domain':
      return 'This address is not on the sign-in allowlist — add it in the Firebase Console (Authentication → Settings → Authorized domains).';
    case 'auth/operation-not-supported-in-this-environment':
    case 'auth/web-storage-unsupported':
      return G_INAPP_MSG;
    case 'auth/network-request-failed':
      return '📴 Could not reach Google — check the connection and try again.';
    case 'auth/account-exists-with-different-credential':
    case 'auth/email-already-in-use':
      return 'That Google address already belongs to a Point Invaders account with a password — sign in with email instead.';
    case 'auth/provider-already-linked':
      return 'This profile is already saved with Google.';
    case 'auth/too-many-requests':
      return 'Too many tries — wait a minute, then try again.';
  }
  return (typeof fErr === 'function') ? fErr(e, 'google') : 'Matrix validation anomaly.';
}
// The same shape as showAuthErr(): the friendly line, then the raw code under it.
function gShowErr(el, e){
  const t = gErrText(e);
  if(!el || !t) return;
  snd('error');
  el.textContent = t;
  if(e && e.code){
    const tag = document.createElement('div');
    tag.textContent = e.code;
    tag.style.cssText = 'margin-top:6px;font-family:var(--fd),monospace;font-size:.52rem;letter-spacing:.1em;color:var(--dimmer);text-transform:none';
    el.appendChild(tag);
  }
}
function gIsGoogleUser(u){
  return !!(u && !u.isAnonymous && (u.providerData || []).some(p => p && p.providerId === 'google.com'));
}
// A Google account with no profile yet names itself first (loadUser asks this).
function gNeedsCallsign(){ return !!(auth && gIsGoogleUser(auth.currentUser)); }

// The sign-in screen's button.
async function signInGoogle(){
  const btn = document.getElementById('btn-google');
  const errEl = document.getElementById('auth-err');
  if(!auth || !db){ showAuthOfflineNotice(); return; }
  if(gInApp()){ setErr(G_INAPP_MSG); return; }
  setErr('');
  // Held until this function has decided where the account goes, so the
  // session-restore listener cannot open a half-made profile underneath it.
  authPending = true;
  if(btn) btn.disabled = true;
  let cred;
  try{
    cred = await auth.signInWithPopup(gProvider());      // straight from the click, or it is blocked
  }catch(e){
    authPending = false;
    if(btn) btn.disabled = false;
    console.warn('Google sign-in failed:', e);
    gShowErr(errEl, e);
    return;
  }
  try{
    const uid = cred.user.uid;
    const snap = await withTimeout(db.ref('players/' + uid).once('value'), NET_WAIT);
    if(snap.exists()){
      authPending = false;
      await loadUser(uid);
      try{ statsEvent('_login_g'); }catch(e){}
    }else{
      gOpenCallsign(uid);                                  // keeps authPending until it is done
    }
  }catch(e){
    authPending = false;
    console.warn('Google sign-in: profile read failed:', e);
    if(e && e.isOffline) showAuthOfflineNotice(); else gShowErr(errEl, e);
  }finally{
    if(btn) btn.disabled = false;
  }
}

// ── 🆔 CALLSIGN ──
var csUid = null, csBusy = false;
function gOpenCallsign(uid){
  const ov = document.getElementById('cs-overlay');
  if(!ov) return;
  csUid = uid;
  authPending = true;
  const inp = document.getElementById('cs-name'), err = document.getElementById('cs-err');
  const cu = auth && auth.currentUser;
  const sub = document.getElementById('cs-sub');
  if(sub) sub.textContent = cu && cu.email ? `New account · ${cu.email}` : 'New Google account · one last step';
  if(err) err.textContent = '';
  // Never prefilled from the Google profile: a real name is not a callsign,
  // and this one goes on a public leaderboard.
  if(inp){ inp.value = ''; setTimeout(() => inp.focus(), 260); }
  ov.classList.add('show');
  ov.setAttribute('aria-hidden', 'false');
  snd('tab');
}
function gCloseCallsign(){
  const ov = document.getElementById('cs-overlay');
  if(!ov) return;
  ov.classList.remove('show');
  ov.setAttribute('aria-hidden', 'true');
}
async function gCallsignGo(){
  if(csBusy || !csUid) return;
  const inp = document.getElementById('cs-name'), err = document.getElementById('cs-err'), go = document.getElementById('cs-go');
  const name = (inp && inp.value || '').trim();
  if(!/^[a-zA-Z0-9_-]{2,20}$/.test(name)){ snd('error'); if(err) err.textContent = name ? 'Format error inside username syntax.' : 'Pick a username first.'; return; }
  if(!db){ showAuthOfflineNotice(); return; }
  csBusy = true;
  if(go){ go.disabled = true; go.textContent = '⏳ Registering…'; }
  const uid = csUid;
  try{
    await withTimeout(db.ref('players/' + uid).set({
      username: name, totalPoints: 0, gamesPlayed: 0, credits: 0, isGuest: false,
      createdAt: firebase.database.ServerValue.TIMESTAMP
    }), NET_WAIT);
    gCloseCallsign();
    csUid = null;
    authPending = false;
    await loadUser(uid);
    try{ statsEvent('_new_g'); }catch(e){}
    toast(`🔒 Welcome to the grid, ${name} — your progress is saved to Google.`, 4200);
  }catch(e){
    console.warn('Callsign write failed:', e);
    if(err){ if(e && e.isOffline){ err.textContent = '📴 No connection to the mainframe.'; } else showAuthErr(err, e, 'google'); }
  }finally{
    csBusy = false;
    if(go){ go.disabled = false; go.textContent = 'Enter the Grid →'; }
  }
}
async function gCallsignCancel(){
  if(csBusy) return;
  csUid = null;
  gCloseCallsign();
  try{ if(auth) await auth.signOut(); }catch(e){}
  authPending = false;
  snd('uiBack');
}

// ── 💾 SAVE: THE SWITCH ──
// linkWithPopup refused because this Google account already HAS a profile.
// The guest cannot be merged into it; switching deletes the guest (as Exit
// would) and signs in to the saved account. The order matters: the guest's
// node can only be removed while signed in AS the guest, and User.delete()
// signs out whoever is current — so both happen before the switch, never after.
async function gSwitchAccounts(e){
  const old = auth && auth.currentUser;
  if(!old || !old.isAnonymous) return false;
  const pts = ((user && user.totalPoints) || 0).toLocaleString();
  if(!confirm(`That Google account already has its own Point Invaders profile.\n\nSwitching signs this browser in to it. This guest profile and its ${pts} PTS are deleted — they cannot be merged.\n\nSwitch accounts?`)) return false;
  let cred = e && e.credential;
  try{ if(!cred && firebase.auth.GoogleAuthProvider.credentialFromError) cred = firebase.auth.GoogleAuthProvider.credentialFromError(e); }catch(x){}
  authPending = true;
  try{
    if(typeof mpLeaveRoom === 'function') await mpLeaveRoom();
    try{ if(db) await withTimeout(db.ref('players/' + old.uid).remove(), NET_WAIT); }catch(x){ console.warn('Guest purge before switch failed:', x); }
    try{ await old.delete(); }catch(x){ try{ await auth.signOut(); }catch(y){} }
    if(cred) await auth.signInWithCredential(cred);
    else await auth.signInWithPopup(gProvider());
    try{ statsEvent('_login_g'); }catch(x){}
    toast('🔓 Switched to your saved account…', 2000);
    // A clean boot, not a patched-up session: every hub system restarts
    // against the account it now belongs to.
    setTimeout(() => location.reload(), 500);
    return true;
  }catch(x){
    authPending = false;
    console.warn('Account switch failed:', x);
    toast('⚠️ Could not switch accounts — sign in with Google from the start screen.', 4200);
    setTimeout(() => location.reload(), 1600);
    return false;
  }
}

// ── WIRING ──
try{
  if(typeof fErrProviderOff === 'object' && fErrProviderOff){
    fErrProviderOff.google = 'Google sign-in is switched off — enable it in the Firebase Console (Authentication → Sign-in method → Google).';
  }
}catch(e){}
try{
  window.addEventListener('beforeinstallprompt', e => {
    // Held for a moment the player chooses, instead of Chrome's mini-bar
    // turning up over the first round.
    e.preventDefault();
    instEvt = e;
    instPaint();
  });
  window.addEventListener('appinstalled', () => {
    instEvt = null;
    lsSet(INST_KEY, Object.assign(instState(), { done: 1 }));
    try{ statsEvent('_inst_ok'); }catch(e){}
    toast('📲 Installed — Point Invaders is on your home screen now.', 3600);
    instPaint();
    const el = document.getElementById('res-nudge');
    if(el && !el.classList.contains('save')) el.hidden = true;
  });
  document.getElementById('btn-install')?.addEventListener('click', () => instGo('settings'));
  document.getElementById('inst-close')?.addEventListener('click', () => closeOverlay('inst-overlay'));
  document.getElementById('inst-overlay')?.addEventListener('click', e => { if(e.target.id === 'inst-overlay') closeOverlay('inst-overlay'); });
  document.addEventListener('keydown', e => {
    if(e.key === 'Escape' && document.getElementById('inst-overlay')?.classList.contains('show')) closeOverlay('inst-overlay');
  });
  document.getElementById('btn-google')?.addEventListener('click', signInGoogle);
  document.getElementById('cs-go')?.addEventListener('click', gCallsignGo);
  document.getElementById('cs-cancel')?.addEventListener('click', gCallsignCancel);
  document.getElementById('cs-name')?.addEventListener('keydown', e => { if(e.key === 'Enter'){ e.preventDefault(); gCallsignGo(); } });
  document.addEventListener('keydown', e => {
    if(e.key === 'Escape' && document.getElementById('cs-overlay')?.classList.contains('show')){ e.stopPropagation(); gCallsignCancel(); }
  }, true);
  registerOverlayCloser('cs-overlay', () => gCallsignCancel());
  // In another app's browser the button stays, but says what will happen.
  if(gInApp()){
    const b = document.getElementById('btn-google');
    if(b) b.title = 'Opens in Chrome or Safari only';
  }
  instPaint();
}catch(e){ console.warn('Install / Google sign-in failed to wire:', e); }

// ══════════════════════════════════════════════════════════════════════
//  § 29 · v55 — 🌐 LAB GALLERY · publish · play · like · Level of the Day
// ══════════════════════════════════════════════════════════════════════
// Brick Lab levels used to travel only as links. The gallery is a shared
// shelf: 📤 PUBLISH from the editor, and anyone can browse it by mission,
// sort it by 🔥 TOP or 🆕 NEW, play a level (still a practice run — § 25's
// side door, nothing banked), ♥ like it, 🔗 pass it on or ⚑ report it.
// Every day one level is the ⭐ LEVEL OF THE DAY, shown here and on the hub's
// lab banner.
//
// RULES FOR PUBLISHING — the gallery should be worth opening:
//   · a network profile (a guest counts; a local session or offline, no),
//   · a name, and nothing in it the name filter refuses,
//   · the level passes its own lab check,
//   · YOU have scored on it at least once (a TEST RUN), so every level on the
//     shelf has been played by the person who made it,
//   · not already on the shelf (same mission, same layout — names aside),
//   · one publish a minute (the database enforces it: the `lab` rule's w/<uid>).
//
// DATA (all under the NEW top-level node `lab`, readable by anyone):
//   lab/d/<id>     { g: mission, c: PIL1 code, n: name, b: author, u: uid, t: time }
//   lab/l/<id>/<uid>   true — a like (removable)
//   lab/p/<id>         plays, +1 at a time
//   lab/f/<id>/<uid>   true — a report; three hide a level for everyone
//   lab/day/<date>     the Level of the Day's id — written once, by whoever
//                      opens the gallery first that UTC day
//   lab/w/<uid>        the last publish time (the one-a-minute brake)
//
// ⚠️ A NEW TOP-LEVEL NODE: the database refuses it unless the Console rules
// carry the `lab` block (a copy of the whole rules file is in
// _firebase/database.rules.json beside the project, not deployed). Without it
// the gallery says it is not open yet and publishing is refused; nothing else
// is affected.
//
// ⚠️ LOAD ORDER: § 25 (renderLab, the editor, labFinish) and enterHub call in
// here, so every name they reach is a var or a function declaration.

var GAL = { state: 'idle', items: [], byId: Object.create(null), days: {}, lotd: null, at: 0, err: null,
            sort: 'top', gid: '', busy: null, shown: 40, hubAt: 0, hub: null, flash: null };
var GAL_TTL = 60000, GAL_PAGE = 40, GAL_HIDE_AT = 3;
var GAL_PLAYED_KEY = 'pi_gal_played', GAL_PUB_KEY = 'pi_gal_pub', GAL_HIDE_KEY = 'pi_gal_hidden';
var GAL_BAD_SUB = null, GAL_BAD_WORD = null;
// ── THE NAME FILTER ──
// Names are public. Two lists, stored encoded so the source does not carry
// them in plain text: stems refused anywhere in the name (leetspeak folded,
// spacing ignored), and short words refused only as whole words — "GRAPE",
// "PASS" and "COCKPIT" are fine.
function galBadLists(){
  if(GAL_BAD_SUB) return;
  try{
    GAL_BAD_SUB = atob('ZnVjayxzaGl0LGN1bnQsYml0Y2gsd2hvcmUsc2x1dCxuaWdnLGZhZ2dvdCxyZXRhcmQscG9ybixwZW5pcyx2YWdpbmEsZGlsZG8saml6eix3YW5rLHR3YXQsYXNzaG9sZSxoaXRsZXIsbmF6aSxwdXNzeSxib29icyxwdWtpbWFrLGtpbWFrLGxhbmNhdSxwYW50YXQsYnV0b2gscGVwZWssY2liYWksa2FuaW5hLGxhbmppYW8sbW90aGVyZg==').split(',');
    GAL_BAD_WORD = atob('cmFwZSxyYXBlZCxjb2NrLGRpY2ssY3VtLHNleCxreXMsZmFnLGFzcyx0aXRzLGtpa2Usc3BpYyxjaGluayx0cmFubnkscHVraSxuYWJlaCxrbm4sYmFiaSxzaWFsLGtvdGUsaG9lLGhvZXMsYW5hbCxudWRlLG51ZGVz').split(',');
  }catch(e){ GAL_BAD_SUB = []; GAL_BAD_WORD = []; }
}
function galClean(text){
  galBadLists();
  const map = { '0': 'o', '1': 'i', '3': 'e', '4': 'a', '5': 's', '7': 't', '8': 'b', '@': 'a', '$': 's', '!': 'i', '|': 'i' };
  const low = String(text || '').toLowerCase().replace(/[0134578@$!|]/g, c => map[c] || c);
  const flat = low.replace(/[^a-z]/g, '');
  if(GAL_BAD_SUB.some(w => w && flat.includes(w))) return false;
  const words = low.split(/[^a-z]+/).filter(Boolean);
  if(words.some(w => GAL_BAD_WORD.includes(w)) || GAL_BAD_WORD.includes(flat)) return false;
  return true;
}

function galOnline(){ return !!db && !!user && !isLocalSession() && !offlineMode; }
function galCanWrite(){ return galOnline() && !!(auth && auth.currentUser); }
function galDenied(e){ return /PERMISSION|permission/.test(String((e && (e.code || e.message)) || '')); }
function galHiddenIds(){ const a = lsGet(GAL_HIDE_KEY, []); return new Set(Array.isArray(a) ? a : []); }

// ── READING THE SHELF ──
function galLoad(force){
  if(!galOnline()){ GAL.state = 'offline'; return Promise.resolve(); }
  if(GAL.busy) return GAL.busy;
  if(!force && GAL.state === 'ok' && Date.now() - GAL.at < GAL_TTL) return Promise.resolve();
  GAL.busy = (async () => {
    try{
      const [d, l, p, f, days] = await Promise.all([
        withTimeout(db.ref('lab/d').orderByChild('t').limitToLast(300).once('value'), NET_WAIT),
        withTimeout(db.ref('lab/l').once('value'), NET_WAIT),
        withTimeout(db.ref('lab/p').once('value'), NET_WAIT),
        withTimeout(db.ref('lab/f').once('value'), NET_WAIT),
        withTimeout(db.ref('lab/day').orderByKey().limitToLast(40).once('value'), NET_WAIT)
      ]);
      galIngest(d.val() || {}, l.val() || {}, p.val() || {}, f.val() || {}, days.val() || {});
      GAL.state = 'ok'; GAL.at = Date.now(); GAL.err = null;
      await galEnsureLotd();
    }catch(e){
      GAL.state = galDenied(e) ? 'off' : 'error';
      GAL.err = (e && (e.code || e.message)) || String(e);
      console.info('🌐 Lab gallery:', GAL.state, GAL.err);
    }finally{
      GAL.busy = null;
    }
  })();
  return GAL.busy;
}
function galIngest(D, L, P, F, Dy){
  const me = user && user.uid;
  const hidden = galHiddenIds();
  const items = [];
  for(const [id, r] of Object.entries(D)){
    if(!r || typeof r !== 'object' || typeof r.c !== 'string' || !r.g) continue;
    // A level for a mission this build does not have (an older cached page)
    // or a code that does not decode is simply not shown.
    const design = labDecode(r.c);
    if(!design || design.gid !== r.g || !LAB_DEFS[design.gid] || !META[design.gid] || !SOLO_START[design.gid]) continue;
    const lk = (L[id] && typeof L[id] === 'object') ? L[id] : {};
    const flags = (F[id] && typeof F[id] === 'object') ? Object.keys(F[id]).length : 0;
    items.push({
      id, g: r.g, c: r.c, n: String(r.n || '').slice(0, 32), b: String(r.b || '').slice(0, 24), u: r.u, t: +r.t || 0, design,
      likes: Object.keys(lk).length, liked: !!(me && lk[me]), plays: +P[id] || 0, flags,
      mine: !!(me && r.u === me), hidden: flags >= GAL_HIDE_AT || hidden.has(id)
    });
  }
  GAL.items = items;
  GAL.byId = Object.create(null);
  items.forEach(i => { GAL.byId[i.id] = i; });
  GAL.days = (Dy && typeof Dy === 'object') ? Dy : {};
}

// ── ⭐ LEVEL OF THE DAY ──
// The most-liked level that has not been featured in the last month (plays
// and freshness break ties). Chosen by the first player to open the gallery
// that UTC day and written ONCE — everybody else reads the same answer.
function galPickLotd(today){
  const recent = new Set(Object.entries(GAL.days).filter(([k]) => k < today && daysBetween(k, today) <= 30).map(([, v]) => v));
  const cands = GAL.items.filter(i => !i.hidden && i.flags === 0 && !recent.has(i.id));
  if(!cands.length) return null;
  const now = Date.now();
  const score = i => i.likes * 4 + Math.min(i.plays, 60) * 0.5 + Math.max(0, 14 - (now - i.t) / DAY_MS) * 0.2;
  cands.sort((a, b) => score(b) - score(a) || b.t - a.t);
  return cands[0];
}
async function galEnsureLotd(){
  const today = dayKey();
  let id = GAL.days[today];
  if(!id || !GAL.byId[id]){
    const pick = galPickLotd(today);
    if(pick && galCanWrite() && !id){
      try{
        await withTimeout(db.ref('lab/day/' + today).set(pick.id), NET_WAIT);
        GAL.days[today] = pick.id;
      }catch(e){
        // Written first by someone else (the day is write-once): theirs stands.
        try{ const s = await withTimeout(db.ref('lab/day/' + today).once('value'), NET_WAIT); if(s.exists()) GAL.days[today] = s.val(); }catch(x){}
      }
    }
    id = GAL.days[today];
  }
  const it = id ? GAL.byId[id] : null;
  GAL.lotd = it && !it.hidden ? it : null;
}

// ── THE VIEW ───────────────────────────────────────────────────────────
function galAge(t){
  const s = Math.max(0, (Date.now() - t) / 1000);
  if(s < 3600) return 'just now';
  if(s < 86400) return Math.floor(s / 3600) + 'h ago';
  if(s < 86400 * 45) return Math.floor(s / 86400) + 'd ago';
  return new Date(t).toISOString().slice(0, 10);
}
function galMsg(title, body, retry){
  return `<div class="gal-msg"><div class="gal-msg-h">${title}</div><p>${body}</p>` +
         (retry ? `<button class="btn btn-secondary btn-sm" id="gal-retry" type="button">↻ Try again</button>` : '') + `</div>`;
}
function galList(){
  let list = GAL.items.filter(i => !i.hidden || i.mine);
  if(GAL.gid) list = list.filter(i => i.g === GAL.gid);
  if(GAL.sort === 'new') list.sort((a, b) => b.t - a.t);
  else list.sort((a, b) => b.likes - a.likes || b.plays - a.plays || b.t - a.t);
  return list;
}
function galRowHTML(i){
  const m = META[i.g];
  const name = esc(i.n || i.design.name || 'CUSTOM ' + (LAB_DEFS[i.g].what || 'LEVEL'));
  return `<div class="gal-row${i.id === GAL.flash ? ' flash' : ''}" role="listitem" data-id="${esc(i.id)}">` +
      `<span class="gal-em" aria-hidden="true">${m.emoji}</span>` +
      `<div class="gal-main"><b>${name}</b><em>${esc(m.name)} · by ${esc(i.b || 'someone')} · ${galAge(i.t)}</em>` +
        (i.mine && i.hidden ? `<span class="gal-chip">⚑ HIDDEN — REPORTED</span>` : '') + `</div>` +
      `<span class="gal-st" title="${i.likes} likes · ${i.plays} plays"><span class="gal-lk${i.liked ? ' on' : ''}">♥ ${i.likes}</span> <span>▶ ${i.plays}</span></span>` +
      `<div class="gal-acts">` +
        `<button class="btn btn-primary btn-sm" type="button" data-a="play" aria-label="Play ${name}">▶ PLAY</button>` +
        (i.mine ? '' : `<button class="btn btn-secondary btn-sm gal-like${i.liked ? ' on' : ''}" type="button" data-a="like" aria-pressed="${i.liked}" aria-label="${i.liked ? 'Unlike' : 'Like'} ${name}">♥</button>`) +
        `<button class="btn btn-secondary btn-sm" type="button" data-a="share" aria-label="Copy a link to ${name}" title="Copy link">🔗</button>` +
        (i.mine ? `<button class="btn btn-secondary btn-sm" type="button" data-a="del" aria-label="Delete ${name}" title="Delete your level">🗑</button>`
                : `<button class="btn btn-secondary btn-sm" type="button" data-a="report" aria-label="Report ${name}" title="Report">⚑</button>`) +
      `</div>` +
    `</div>`;
}
function galLotdHTML(i){
  const m = META[i.g];
  const name = esc(i.n || i.design.name || 'CUSTOM ' + (LAB_DEFS[i.g].what || 'LEVEL'));
  return `<div class="gal-lotd" data-id="${esc(i.id)}">` +
      `<div class="gal-lotd-h">⭐ LEVEL OF THE DAY <span>${dayKey()}</span></div>` +
      `<div class="gal-lotd-in">` +
        `<div class="gal-lotd-prev">${labPreviewHTML(i.design)}</div>` +
        `<div class="gal-lotd-txt">` +
          `<div class="gal-lotd-m">${m.emoji} ${esc(m.name)}</div>` +
          `<b>${name}</b><em>by ${esc(i.b || 'someone')}</em>` +
          `<div class="gal-lotd-s">♥ ${i.likes} · ▶ ${i.plays} plays</div>` +
          `<div class="gal-lotd-b"><button class="btn btn-primary btn-sm" type="button" data-a="play">▶ PLAY IT</button>` +
          (i.mine ? '' : `<button class="btn btn-secondary btn-sm gal-like${i.liked ? ' on' : ''}" type="button" data-a="like" aria-pressed="${i.liked}" aria-label="Like">♥</button>`) +
          `</div>` +
        `</div>` +
      `</div>` +
    `</div>`;
}

function labRenderGallery(body, sub){
  if(sub) sub.textContent = 'Levels built by players · play them, like the good ones';
  galSwitchPaint();
  if(!galOnline()){
    body.innerHTML = galMsg('📡 The gallery needs a connection',
      isLocalSession() ? 'This profile lives on this device only. Save it online from ⚙️ Settings, then the whole gallery opens up.'
                       : 'Reconnect, then open it again. Levels sent to you by link still play offline.');
    return;
  }
  if(GAL.state === 'off'){
    body.innerHTML = galMsg('🌐 The gallery is not open yet', 'Share your levels by link meanwhile — 🔗 SHARE in the editor. They play the same way.', true);
    galWireMsg();
    return;
  }
  if(GAL.state === 'error'){
    body.innerHTML = galMsg('📡 Could not reach the gallery', 'The connection dropped on the way. Try again in a moment.', true);
    galWireMsg();
    return;
  }
  if(GAL.state !== 'ok'){
    body.innerHTML = `<div class="lb-empty">Loading the gallery…</div>`;
    galLoad().then(() => { if(labView === 'gallery' && document.getElementById('lab-overlay')?.classList.contains('show')) renderLab(); });
    return;
  }
  // Stale: show what we have, refresh underneath.
  if(Date.now() - GAL.at > GAL_TTL && !GAL.busy){
    galLoad(true).then(() => { if(labView === 'gallery' && document.getElementById('lab-overlay')?.classList.contains('show')) renderLab(); });
  }
  const list = galList();
  const counts = Object.create(null);
  GAL.items.forEach(i => { if(!i.hidden || i.mine) counts[i.g] = (counts[i.g] || 0) + 1; });
  const total = Object.values(counts).reduce((a, b) => a + b, 0);
  const gids = Object.keys(SOLO_START).filter(g => LAB_DEFS[g] && META[g]);
  const shown = list.slice(0, GAL.shown);
  body.innerHTML =
    `<div class="gal">` +
      (GAL.lotd && !GAL.gid ? galLotdHTML(GAL.lotd) : '') +
      `<div class="gal-ctl">` +
        `<select class="input gal-sel" id="gal-mission" aria-label="Show levels for">` +
          `<option value="">ALL MISSIONS · ${total}</option>` +
          gids.map(g => `<option value="${g}"${g === GAL.gid ? ' selected' : ''}>${META[g].emoji} ${esc(META[g].name)} · ${counts[g] || 0}</option>`).join('') +
        `</select>` +
        `<div class="gal-sort" role="group" aria-label="Sort">` +
          `<button class="gal-srt${GAL.sort === 'top' ? ' on' : ''}" type="button" data-s="top" aria-pressed="${GAL.sort === 'top'}">🔥 TOP</button>` +
          `<button class="gal-srt${GAL.sort === 'new' ? ' on' : ''}" type="button" data-s="new" aria-pressed="${GAL.sort === 'new'}">🆕 NEW</button>` +
        `</div>` +
      `</div>` +
      (shown.length
        ? `<div class="gal-list" role="list">${shown.map(galRowHTML).join('')}</div>`
        : `<div class="gal-empty">${GAL.gid ? 'No ' + esc(META[GAL.gid].name) + ' levels yet.' : 'No levels yet.'} Build one, score on it with ▶ TEST RUN, then press <b>📤 PUBLISH</b>.</div>`) +
      (list.length > shown.length ? `<button class="btn btn-secondary btn-full btn-sm gal-more" id="gal-more" type="button">Show more · ${list.length - shown.length} left</button>` : '') +
      `<div class="lab-out" id="lab-out"></div>` +
      `<div class="lab-note">Levels are built by players and play as practice runs — nothing is banked. Tap ⚑ to report one that should not be here; it disappears for you at once.</div>` +
    `</div>`;
  galWire(body);
}
function galWireMsg(){
  const b = document.getElementById('gal-retry');
  if(b) b.onclick = () => { GAL.state = 'idle'; snd('tab'); renderLab(); };
}
function galWire(body){
  const sel = document.getElementById('gal-mission');
  if(sel) sel.onchange = () => { GAL.gid = sel.value; GAL.shown = GAL_PAGE; snd('tab'); renderLab(); };
  body.querySelectorAll('.gal-srt').forEach(b => b.onclick = () => { GAL.sort = b.dataset.s; GAL.shown = GAL_PAGE; snd('tab'); renderLab(); });
  const more = document.getElementById('gal-more');
  if(more) more.onclick = () => { GAL.shown += GAL_PAGE; snd('tab'); renderLab(); };
  body.querySelectorAll('[data-a]').forEach(b => b.onclick = e => {
    const host = b.closest('[data-id]');
    const it = host && GAL.byId[host.dataset.id];
    if(!it) return;
    const a = b.dataset.a;
    if(a === 'play') galPlay(it);
    else if(a === 'like') galLike(it, b);
    else if(a === 'share') galShare(it, b);
    else if(a === 'report') galReport(it);
    else if(a === 'del') galDelete(it);
  });
}

// The switch at the top of the lab: 🧱 BUILD | 🌐 GALLERY.
function galSwitchPaint(){
  const g = labView === 'gallery';
  const b = document.getElementById('lab-sw-build'), gl = document.getElementById('lab-sw-gallery');
  if(b){ b.classList.toggle('on', !g); b.setAttribute('aria-selected', String(!g)); }
  if(gl){ gl.classList.toggle('on', g); gl.setAttribute('aria-selected', String(g)); }
}
function galOpen(){
  labView = 'gallery';
  try{ statsEvent('_gal_open'); }catch(e){}
  if(!document.getElementById('lab-overlay')?.classList.contains('show')) openLab();
  else renderLab();
}

// ── ACTIONS ────────────────────────────────────────────────────────────
function galPlay(it, src){
  if(!it || !it.design) return;
  // One play a level a device a day — a practice loop is not ten plays.
  const played = lsGet(GAL_PLAYED_KEY, {}) || {};
  const today = dayKey();
  if(played[it.id] !== today && galCanWrite()){
    played[it.id] = today;
    const keys = Object.keys(played);
    if(keys.length > 200) delete played[keys[0]];
    lsSet(GAL_PLAYED_KEY, played);
    it.plays++;
    try{ db.ref('lab/p/' + it.id).set(firebase.database.ServerValue.increment(1)).catch(() => {}); }catch(e){}
  }
  try{ statsEvent(src === 'hub' ? '_gal_lotd' : '_gal_play'); }catch(e){}
  labPlay(it.design, { gal: it.id });
}
async function galLike(it, btn){
  if(!galCanWrite()){ snd('deny'); toast('🌐 Liking needs a connection.', 2400); return; }
  if(it.mine) return;
  const uid = auth.currentUser.uid;
  const was = it.liked;
  it.liked = !was; it.likes += was ? -1 : 1;
  snd(was ? 'uiBack' : 'coin');
  galRepaintLikes(it);
  try{
    const r = db.ref('lab/l/' + it.id + '/' + uid);
    await withTimeout(was ? r.remove() : r.set(true), NET_WAIT);
    if(!was){ try{ statsEvent('_gal_like'); }catch(e){} }
  }catch(e){
    it.liked = was; it.likes += was ? 1 : -1;
    galRepaintLikes(it);
    toast(galDenied(e) ? '🌐 The gallery refused that — it may not be open yet.' : '📡 Could not save the like.', 2800);
  }
}
function galRepaintLikes(it){
  document.querySelectorAll(`[data-id="${CSS.escape(it.id)}"]`).forEach(host => {
    host.querySelectorAll('.gal-like').forEach(b => { b.classList.toggle('on', it.liked); b.setAttribute('aria-pressed', String(it.liked)); });
    const lk = host.querySelector('.gal-lk');
    if(lk){ lk.textContent = '♥ ' + it.likes; lk.classList.toggle('on', it.liked); }
    const s = host.querySelector('.gal-lotd-s');
    if(s) s.textContent = `♥ ${it.likes} · ▶ ${it.plays} plays`;
  });
  const rl = document.getElementById('lab-res-like');
  if(rl && labResult && labResult.gal === it.id){ rl.classList.toggle('on', it.liked); rl.textContent = it.liked ? '♥ LIKED' : '♥ LIKE THIS LEVEL'; }
}
async function galShare(it, btn){
  // The author's name stays on it — this is their level being passed on.
  const d = Object.assign({}, it.design, { name: it.n || it.design.name, by: it.b || it.design.by });
  const url = labUrl(d);
  const m = META[it.g], def = LAB_DEFS[it.g];
  const text = `🧱 Try “${d.name || 'this level'}” — a ${m.name} ${String(def.what || 'level').toLowerCase()} by ${d.by || 'a player'} on Point Invaders.`;
  try{ statsEvent('_share_wall'); }catch(e){}
  const phone = !!(window.matchMedia && matchMedia('(pointer: coarse)').matches);
  if(navigator.share && phone){
    try{ await navigator.share({ title: 'Point Invaders · Brick Lab', text, url }); snd('coin'); return; }
    catch(e){ if(e && e.name === 'AbortError') return; }
  }
  try{
    await navigator.clipboard.writeText(text + ' ' + url);
    snd('coin');
    if(btn){ const was = btn.textContent; btn.textContent = '✔'; setTimeout(() => { btn.textContent = was; }, 1600); }
    toast('🔗 Link copied.', 1800);
  }catch(e){
    const out = document.getElementById('lab-out');
    if(out) out.innerHTML = `<div class="replay-code">${esc(text + ' ' + url)}</div><div class="replay-hint">Copy this and paste it anywhere.</div>`;
  }
}
async function galReport(it){
  if(!confirm(`Report “${it.n || 'this level'}”?\n\nIt disappears for you now, and three reports hide it for everyone.`)) return;
  const hidden = galHiddenIds(); hidden.add(it.id);
  lsSet(GAL_HIDE_KEY, [...hidden].slice(-300));
  it.hidden = true;
  snd('uiBack');
  toast('⚑ Reported — thanks. It is hidden for you.', 2600);
  renderLab();
  if(galCanWrite()){
    try{ await withTimeout(db.ref('lab/f/' + it.id + '/' + auth.currentUser.uid).set(true), NET_WAIT); }catch(e){}
  }
}
async function galDelete(it){
  if(!it.mine || !galCanWrite()) return;
  if(!confirm(`Delete “${it.n || 'your level'}” from the gallery?\n\nIts likes go with it. Your draft in the editor stays.`)) return;
  try{
    await withTimeout(db.ref('lab/d/' + it.id).remove(), NET_WAIT);
    GAL.items = GAL.items.filter(x => x.id !== it.id);
    delete GAL.byId[it.id];
    if(GAL.lotd && GAL.lotd.id === it.id) GAL.lotd = null;
    snd('uiBack');
    toast('🗑 Removed from the gallery.', 2200);
    renderLab();
  }catch(e){
    toast(galDenied(e) ? '🌐 The gallery refused that.' : '📡 Could not reach the gallery.', 2800);
  }
}

// 📤 From the editor (and from a lab result that just scored).
async function galPublish(d, btn){
  const def = d && LAB_DEFS[d.gid];
  const out = document.getElementById('lab-out');
  const say = (msg, good) => {
    if(!good) snd('deny');
    if(out) out.innerHTML = `<div class="${good ? 'replay-hint' : 'replay-err'}">${msg}</div>`;
    else toast(msg.replace(/<[^>]+>/g, ''), 3200);
  };
  if(!def) return;
  if(!galCanWrite()) return say(isLocalSession() ? '📤 Publishing needs a profile online — save this one from ⚙️ Settings first.' : '📡 Publishing needs a connection.');
  const chk = labCheck(d);
  if(chk && chk.block) return say('⚠️ ' + esc(chk.block));
  const name = String(d.name || '').trim();
  if(!name) return say('📤 Give your level a name first.');
  if(!galClean(name)) return say('📤 That name will not go on a public shelf — pick another.');
  const design = labNorm(Object.assign({}, d, { name, by: String(user.username || '').slice(0, 14) }));
  if(!galClean(design.by)) return say('📤 Your username will not go on a public shelf — publishing is off for this profile.');
  if(labBestOf(labKey(design)) <= 0) return say('📤 Play it first — score on it with <b>▶ TEST RUN</b>, then publish. Every level on the shelf has been played by the one who made it.');
  const last = +lsGet(GAL_PUB_KEY, 0) || 0;
  if(Date.now() - last < 60000) return say('📤 One level a minute — try again in ' + Math.ceil((60000 - (Date.now() - last)) / 1000) + 's.');
  if(btn){ btn.disabled = true; btn.textContent = '⏳ Publishing…'; }
  try{
    await galLoad(true);
    if(GAL.state === 'off') return say('🌐 The gallery is not open yet — share it with 🔗 SHARE meanwhile.');
    if(GAL.state !== 'ok') return say('📡 Could not reach the gallery — try again in a moment.');
    const data = labPackData(def, design);
    const twin = GAL.items.find(i => i.g === design.gid && labPackData(def, i.design) === data);
    if(twin) return say(twin.mine ? '📤 This level is already in the gallery — it is yours.' : '📤 This exact layout is already in the gallery (“' + esc(twin.n || 'untitled') + '”).');
    const uid = auth.currentUser.uid;
    const id = db.ref('lab/d').push().key;
    const TS = firebase.database.ServerValue.TIMESTAMP;
    await withTimeout(db.ref('lab').update({
      ['d/' + id]: { g: design.gid, c: labEncode(design), n: design.name, b: design.by, u: uid, t: TS },
      ['w/' + uid]: TS
    }), NET_WAIT);
    lsSet(GAL_PUB_KEY, Date.now());
    try{ statsEvent('_gal_pub'); }catch(e){}
    snd('victory');
    toast(`📤 “${design.name}” is in the gallery.`, 3200);
    GAL.at = 0; GAL.sort = 'new'; GAL.gid = ''; GAL.flash = id; GAL.shown = GAL_PAGE;
    await galLoad(true);
    labView = 'gallery';
    renderLab();
  }catch(e){
    console.warn('Publish failed:', e);
    if(galDenied(e)){
      const recent = Date.now() - last < 70000;
      say(recent ? '📤 One level a minute — try again shortly.' : '🌐 The gallery refused it — it may not be open yet. Share it with 🔗 SHARE meanwhile.');
    }else say('📡 Could not reach the gallery — try again in a moment.');
  }finally{
    if(btn){ btn.disabled = false; btn.textContent = '📤 PUBLISH'; }
  }
}

// ── ⭐ ON THE HUB ──
// The lab banner carries today's featured level: one small read, at most
// every ten minutes, and nothing at all while the gallery is closed.
async function galHubPaint(){
  const el = document.getElementById('lab-lotd');
  if(!el) return;
  if(!galOnline() || GAL.state === 'off'){ el.hidden = true; return; }
  if(!GAL.hub || Date.now() - GAL.hubAt > 600000){
    GAL.hubAt = Date.now();
    try{
      const s = await withTimeout(db.ref('lab/day').orderByKey().limitToLast(1).once('value'), NET_WAIT);
      let day = null, id = null;
      s.forEach(c => { day = c.key; id = c.val(); });
      if(!id){ GAL.hub = null; el.hidden = true; return; }
      const r = await withTimeout(db.ref('lab/d/' + id).once('value'), NET_WAIT);
      const v = r.val();
      const design = v && v.c ? labDecode(v.c) : null;
      GAL.hub = design && META[design.gid] ? { id, day, n: String(v.n || design.name || ''), b: String(v.b || ''), g: design.gid, design, c: v.c } : null;
    }catch(e){
      if(galDenied(e)) GAL.state = 'off';
      GAL.hub = null;
    }
  }
  const h = GAL.hub;
  if(!h || !document.getElementById('hub-screen')?.classList.contains('active')){ el.hidden = !h; if(!h) return; }
  const today = h.day === dayKey();
  el.innerHTML = `<span class="lab-lotd-k">${today ? '⭐ LEVEL OF THE DAY' : '⭐ FEATURED LEVEL'}</span>` +
                 `<span class="lab-lotd-n">${META[h.g].emoji} ${esc(h.n || 'UNTITLED')}</span>` +
                 `<span class="lab-lotd-b">by ${esc(h.b || 'a player')} · ${esc(META[h.g].name)} · ▶ PLAY</span>`;
  el.hidden = false;
  el.onclick = () => {
    const it = GAL.byId[h.id] || { id: h.id, g: h.g, design: h.design, n: h.n, b: h.b, plays: 0 };
    galPlay(it, 'hub');
  };
}

// ── WIRING ──
try{
  document.getElementById('lab-sw-build')?.addEventListener('click', () => {
    if(labView === 'gallery'){ labView = 'edit'; snd('tab'); renderLab(); }
  });
  document.getElementById('lab-sw-gallery')?.addEventListener('click', () => {
    if(labView !== 'gallery'){ snd('tab'); galOpen(); }
  });
}catch(e){ console.warn('Lab gallery failed to wire:', e); }

// ══════════════════════════════════════════════════════════════════════
//  § 30 · v55 — 🎱 GAME 31: NEON PINBALL — three balls, two flippers, one clock
// ══════════════════════════════════════════════════════════════════════
// The arcade staple the grid did not have. Pull the plunger, keep the ball
// alive with the flippers, light the N·E·O·N lanes for the multiplier, clear
// the drop targets to relight the kickbacks, and put five shots into the
// reactor core for MULTIBALL. Three balls and a two-minute clock.
//
// ONE SIMULATION, TWO RENDERERS (the Light Cycle pattern, § 16): pbSim() is
// the whole table — geometry, physics, rules, scoring — and pbRound() the
// whole round (controls, clock, sounds, the ending). The 2D build below and
// the 3D build in 3D MISSIONS PART VIII only draw it and feed it time.
//
// PHYSICS: circles and segments, sub-stepped so no step moves a ball more
// than ~3.5 units (a ball is 8 in radius, so a thin wall can never be
// skipped); flippers are capsules whose surface speed is added to the
// bounce. A ball that sits still somewhere it cannot leave is nudged free
// after a couple of seconds — never one resting on a raised flipper.
// Tiers speed the whole table up rather than changing its geometry
// (Safe 0.88×, Overclock 1.15×, Meltdown 1.27×).
//
// Balanced with a headless bot (scratchpad pb_bot.mjs, 40 rounds a tier): a
// steady flipper banks ~600 at Stable, the top tenth ~1,000–1,150 — hence
// the 1,200 cap. Without flipping at all a round lasts ~30 s for ~35 points.
// No layout, stock or lab, ever let a ball out of the table.
//
// Pause/photo rules (§ 13): every wall-clock read is gNow(), the only timer
// is the shimmed 1 s clock, and the table only moves when the frame loop
// hands it time (dt 0 while held).
// ── THE TABLE ──────────────────────────────────────────────────────────
// World units: 360 × 720, y DOWN (toward the flippers). The 2D build draws
// it squashed vertically (a tilted-table look); the 3D build lays it flat
// on the deck. Everything that moves or scores lives here, so a 3D score is
// a 2D score by construction.
var PB = {
  W: 360, H: 720, BALL_R: 8,
  G: 1150,                    // gravity down the table at Stable, units/s²
  VMAX: 2100,                 // a speed clamp, so nothing tunnels
  CLOCK: 120, BALLS: 3, BALLS_MAX: 5,
  SAVE: 6,                    // ball-save seconds after a launch
  CAP: 1200,
  // Points before the playfield multiplier.
  PTS: { bumper: 1, sling: 0, lane: 3, neon: 20, target: 4, bank: 15, labTarget: 3, labBank: 15,
         core: 3, multiball: 20, jackpot: 15, skill: 25, star: 2, kickback: 0 },
  MULT_MAX: 4, CORE_HITS: 5,
  KICK: { bumper: 560, sling: 480, back: 1250 },
  // The Brick Lab grid over the middle of the table (§ 25): 9 × 7 squares.
  GRID: { cols: 9, rows: 7, x0: 40, x1: 290, y0: 150, y1: 470 },
  LANE_X: [105, 145, 185, 225], LANE_Y0: 92, LANE_Y1: 128,
  FLIP: { len: 58, r0: 9, r1: 5, rest: 0.49, up: -0.52, wUp: 22, wDown: 13, e: 0.28 },
  PLUNGE: { x: 333, y: 691, vMin: 1160, vMax: 1830, chargeSecs: 0.9 },
  COLORS: { bumper: '#ff2bd6', post: '#00f5ff', target: '#ffd700', core: '#39ff14', star: '#b35cff', sling: '#00f5ff', wall: '#3d7bff' }
};
// The stock table is a lab design like any other: . empty · B bumper ·
// P post · T target · C core · S star. A lab level replaces it square for square.
var PB_CHARS = '.BPTCS';
var PB_CLASSIC = ['..S...S..', '...B.B...', '....B....', '.........', 'T.......T', '..P.C.P..', '.........'];

function pbCell(c, r){
  const g = PB.GRID, cw = (g.x1 - g.x0) / g.cols, ch = (g.y1 - g.y0) / g.rows;
  return { x: g.x0 + (c + 0.5) * cw, y: g.y0 + (r + 0.5) * ch, cw, ch };
}
function pbCellsFromPic(rows){
  const g = PB.GRID, cells = new Array(g.cols * g.rows).fill(0);
  rows.forEach((row, r) => { for(let c = 0; c < g.cols; c++){ const v = PB_CHARS.indexOf(row[c] || '.'); cells[r * g.cols + c] = v > 0 ? v : 0; } });
  return cells;
}

// Segments are {ax, ay, bx, by}; `one` makes one side solid only (its front
// is the LEFT of A→B, i.e. normal (dy, -dx)/len for a y-down world).
function pbSeg(ax, ay, bx, by, o){ return Object.assign({ ax, ay, bx, by, e: 0.45 }, o || {}); }

function pbTable(cells){
  const W = PB.W, H = PB.H;
  const walls = [], posts = [], bumpers = [], slings = [], targets = [], stars = [];
  let core = null;
  const add = (ax, ay, bx, by, o) => { const s = pbSeg(ax, ay, bx, by, o); walls.push(s); return s; };
  // ── THE FRAME ──
  add(12, H + 40, 12, 170);                                   // left wall
  // The top arch: an ellipse from the left wall over to the right wall.
  const cx = 180, cy = 170, rx = 168, ry = 150, N = 26;
  let px = 12, py = 170;
  for(let i = 1; i <= N; i++){
    const a = Math.PI - Math.PI * i / N;
    const x = cx + rx * Math.cos(a), y = cy - ry * Math.sin(a);
    add(px, py, x, y, { arc: true });
    px = x; py = y;
  }
  add(348, 170, 348, H + 40);                                 // right wall (the plunger lane's outer wall)
  add(318, H + 40, 318, 258);                                 // the lane's inner wall
  // One-way gate at the top of the lane, sloped so a ball that lands on it
  // rolls off into the playfield instead of back down the lane.
  add(318, 258, 346, 238, { one: true, gate: true });
  // The plunger's face: the ball rests on it.
  add(318, 700, 348, 700, { plunger: true, e: 0.1 });
  // ── THE BOTTOM: outlanes, inlanes, slingshots (mirrored about x = 165) ──
  const M = x => 330 - x;
  for(const s of [1, -1]){
    const X = x => s > 0 ? x : M(x);
    // Inlane guide: the post line between the outlane and the inlane, then the bend onto the flipper.
    add(X(32), 506, X(32), 596, { side: s });
    add(X(32), 596, X(91), 629, { side: s });
    posts.push({ x: X(32), y: 506, r: 5, kind: 'lanepost' });
    // Slingshot: the kicking face looks up and in, toward the middle.
    const a = [X(62), 506], b = [X(62), 574], c = [X(94), 594];
    add(a[0], a[1], b[0], b[1], { side: s, sling: true });
    add(b[0], b[1], c[0], c[1], { side: s, sling: true });
    const face = pbSeg(a[0], a[1], c[0], c[1], { side: s, e: 0.5, flash: 0 });
    const dx = face.bx - face.ax, dy = face.by - face.ay, L = Math.hypot(dx, dy);
    // The inward normal: points away from the sling body toward the playfield centre.
    let nx = dy / L, ny = -dx / L;
    if((165 - (face.ax + face.bx) / 2) * nx < 0){ nx = -nx; ny = -ny; }
    face.nx = nx; face.ny = ny;
    slings.push(face);
    posts.push({ x: a[0], y: a[1], r: 4, kind: 'slingpost' });
    posts.push({ x: c[0], y: c[1], r: 4, kind: 'slingpost' });
    // The apron under the flipper, into the drain.
    add(X(12), 660, X(88), 700, { side: s, apron: true });
  }
  // ── THE TOP LANES: five posts make four rollover lanes ──
  for(const x of [85, 125, 165, 205, 245]){
    walls.push(pbSeg(x, PB.LANE_Y0, x, PB.LANE_Y1, { r: 4, lane: true }));
    posts.push({ x, y: PB.LANE_Y0, r: 4, kind: 'lanepost' });
    posts.push({ x, y: PB.LANE_Y1, r: 4, kind: 'lanepost' });
  }
  // ── THE DROP-TARGET BANK on the right, against the lane wall ──
  // A launch comes round the arch and down the LEFT side, so a bank there was
  // hit by nearly every plunge. Over here it has to be aimed at.
  for(let i = 0; i < 3; i++){
    const y = 330 + i * 30;
    const t = pbSeg(316, y - 13, 316, y + 13, { bank: true, i, down: false, flash: 0, e: 0.35 });
    t.nx = -1; t.ny = 0;
    targets.push(t);
  }
  // ── THE MIDDLE: a lab design, or the stock one ──
  const g = PB.GRID;
  const list = Array.isArray(cells) && cells.length === g.cols * g.rows ? cells : pbCellsFromPic(PB_CLASSIC);
  let li = 0;
  list.forEach((v, i) => {
    if(!v) return;
    const { x, y } = pbCell(i % g.cols, Math.floor(i / g.cols));
    if(v === 1) bumpers.push({ x, y, r: 14, flash: 0, i: bumpers.length });
    else if(v === 2) posts.push({ x, y, r: 6, kind: 'post' });
    else if(v === 3){
      const t = pbSeg(x - 11, y, x + 11, y, { lab: true, i: li++, lit: false, flash: 0, two: true, e: 0.4 });
      t.nx = 0; t.ny = 1;
      targets.push(t);
    }
    else if(v === 4 && !core) core = { x, y, r: 13, flash: 0 };
    else if(v === 5) stars.push({ x, y, r: 11, flash: 0, cool: 0 });
  });
  // Posts that are also wall ends are drawn once but collide as circles too.
  const flippers = [-1, 1].map(s => {
    const F = PB.FLIP;
    const px = s < 0 ? 98 : 232, py = 640;
    // Angles measured from +x in the y-down world. The left flipper points
    // right; the right one is its mirror (π − θ).
    const rest = s < 0 ? F.rest : Math.PI - F.rest, up = s < 0 ? F.up : Math.PI - F.up;
    return { side: s < 0 ? 'L' : 'R', s, px, py, len: F.len, r0: F.r0, r1: F.r1, rest, up, ang: rest, w: 0, held: false };
  });
  // Kickbacks: a lit outlane throws the ball back up once (lit at every new
  // ball, relit by clearing the drop-target bank).
  const kickbacks = [{ side: 'L', x0: 12, x1: 32, lit: true, flash: 0 }, { side: 'R', x0: 298, x1: 318, lit: true, flash: 0 }];
  return { W, H, walls, posts, bumpers, slings, targets, stars, core, flippers, kickbacks, lanes: PB.LANE_X.map(x => ({ x, lit: false, flash: 0 })) };
}

// Closest point on a segment.
function pbClosest(s, x, y){
  const dx = s.bx - s.ax, dy = s.by - s.ay, L2 = dx * dx + dy * dy || 1;
  let t = ((x - s.ax) * dx + (y - s.ay) * dy) / L2;
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  return { x: s.ax + dx * t, y: s.ay + dy * t, t };
}

// ── THE SIMULATION ─────────────────────────────────────────────────────
// opts: { diff, cells (a lab layout or null), absorb() (the shield), rng }
function pbSim(opts){
  opts = opts || {};
  const rng = opts.rng || Math.random;
  const T = pbTable(opts.cells || null);
  // A tier runs the WHOLE table faster (every shot keeps its shape, there is
  // just less time to answer it): Safe 0.88×, Overclock 1.15×, Meltdown 1.27×.
  const PACE = Math.pow(Math.min(3, Math.max(0.5, opts.diff || 1)), 0.35);
  const G = PB.G;
  const S = {
    score: 0, mult: 1, ballsLeft: PB.BALLS - 1, ballNo: 1, over: false, reason: '',
    save: 0, saveUsed: false, skill: -1, skillOpen: false, neonSets: 0, extra: 0,
    bankUp: 3, coreHits: 0, multiball: false, charge: 0, charging: false,
    labHit: 0, labTargets: T.targets.filter(t => t.lab).length,
    stats: { bumpers: 0, slings: 0, targets: 0, banks: 0, lanes: 0, neon: 0, jackpots: 0, multiballs: 0, drains: 0, stars: 0, saves: 0 },
    t: 0, bankReset: 0, autoLaunch: 0, flipEvt: null, pace: PACE, jpCool: 0
  };
  const pend = [];              // events raised by input between frames
  const balls = [];
  let nextId = 1;
  const R = PB.BALL_R;

  function newBall(inLane){
    const b = { id: nextId++, x: PB.PLUNGE.x, y: 700 - R - 0.5, vx: 0, vy: 0, lane: !!inLane, still: 0, stuckT: 0, lastX: 0, lastY: 0 };
    balls.push(b);
    return b;
  }
  function award(ev, kind, pts, x, y){
    const p = Math.round(pts * S.mult);
    S.score += p;
    ev.push({ type: kind, pts: p, x, y });
    return p;
  }
  function pickSkill(){ S.skill = Math.floor(rng() * 4); S.skillOpen = true; }

  // Serves a ball into the plunger lane.
  function serve(){
    const b = newBall(true);
    pickSkill();
    return b;
  }

  // ── COLLISION RESPONSE ──
  function bounce(b, nx, ny, e, kick, fr){
    const vn = b.vx * nx + b.vy * ny;
    if(vn < 0){
      b.vx -= (1 + e) * vn * nx; b.vy -= (1 + e) * vn * ny;
      if(fr){ const tx = -ny, ty = nx, vt = b.vx * tx + b.vy * ty; b.vx -= vt * fr * tx; b.vy -= vt * fr * ty; }
    }
    if(kick){
      const v2 = b.vx * nx + b.vy * ny;
      if(v2 < kick){ b.vx += (kick - v2) * nx; b.vy += (kick - v2) * ny; }
    }
    return -vn;                       // impact speed
  }
  function hitSeg(b, s){
    const c = pbClosest(s, b.x, b.y);
    let dx = b.x - c.x, dy = b.y - c.y;
    let d = Math.hypot(dx, dy);
    const rad = R + (s.r || 0);
    if(d >= rad) return null;
    if(s.one){
      // Solid from the front only: the front is where (dy, -dx) points.
      const sx = s.bx - s.ax, sy = s.by - s.ay, L = Math.hypot(sx, sy);
      const fx = sy / L, fy = -sx / L;
      if((b.x - s.ax) * fx + (b.y - s.ay) * fy < 0) return null;
      if(d < 1e-6){ dx = fx; dy = fy; d = 1; }
    }
    if(d < 1e-6){ dx = 0; dy = -1; d = 1; }
    const nx = dx / d, ny = dy / d;
    b.x += nx * (rad - d); b.y += ny * (rad - d);
    return { nx, ny };
  }
  function hitCircle(b, cx, cy, r){
    let dx = b.x - cx, dy = b.y - cy;
    const d = Math.hypot(dx, dy), rad = R + r;
    if(d >= rad) return null;
    if(d < 1e-6){ dx = 0; dy = -1; }
    const nx = d < 1e-6 ? 0 : dx / d, ny = d < 1e-6 ? -1 : dy / d;
    b.x = cx + nx * rad; b.y = cy + ny * rad;
    return { nx, ny };
  }
  function flipperPts(f){
    const c = Math.cos(f.ang), s = Math.sin(f.ang);
    return { tx: f.px + c * f.len, ty: f.py + s * f.len };
  }
  function hitFlipper(b, f){
    const { tx, ty } = flipperPts(f);
    const dx = tx - f.px, dy = ty - f.py, L2 = dx * dx + dy * dy;
    let t = ((b.x - f.px) * dx + (b.y - f.py) * dy) / L2;
    t = t < 0 ? 0 : t > 1 ? 1 : t;
    const cx = f.px + dx * t, cy = f.py + dy * t, rr = f.r0 + (f.r1 - f.r0) * t;
    let ox = b.x - cx, oy = b.y - cy;
    const d = Math.hypot(ox, oy), rad = R + rr;
    if(d >= rad) return false;
    const nx = d < 1e-6 ? 0 : ox / d, ny = d < 1e-6 ? -1 : oy / d;
    b.x = cx + nx * rad; b.y = cy + ny * rad;
    // The flipper's own surface speed where the ball touches it.
    const rx = cx + nx * rr - f.px, ry = cy + ny * rr - f.py;
    const svx = -f.w * ry, svy = f.w * rx;
    const rvx = b.vx - svx, rvy = b.vy - svy;
    const vn = rvx * nx + rvy * ny;
    if(vn < 0){
      b.vx -= (1 + PB.FLIP.e) * vn * nx; b.vy -= (1 + PB.FLIP.e) * vn * ny;
      // A little grip along the rubber, so a flip carries the ball with it.
      const tx2 = -ny, ty2 = nx, vt = rvx * tx2 + rvy * ty2;
      b.vx -= vt * 0.08 * tx2; b.vy -= vt * 0.08 * ty2;
    }
    return true;
  }

  // ── ONE SUBSTEP ──
  function step(b, h, ev){
    if(b.lane){
      // Resting on the plunger: nothing moves until it is launched.
      b.x = PB.PLUNGE.x; b.y = 700 - R - 0.5 + S.charge * 14; b.vx = 0; b.vy = 0;
      return;
    }
    b.vy += G * h;
    b.vx *= 1 - 0.25 * h; b.vy *= 1 - 0.25 * h;
    const sp = Math.hypot(b.vx, b.vy);
    if(sp > PB.VMAX){ b.vx *= PB.VMAX / sp; b.vy *= PB.VMAX / sp; }
    b.x += b.vx * h; b.y += b.vy * h;

    for(const s of T.walls){
      const n = hitSeg(b, s);
      if(n) bounce(b, n.nx, n.ny, s.e != null ? s.e : 0.45, 0, 0.02);
    }
    for(const p of T.posts){
      if(p.kind !== 'post') continue;          // lane and sling posts are drawn; their walls collide
      const n = hitCircle(b, p.x, p.y, p.r);
      if(n) bounce(b, n.nx, n.ny, 0.5, 0, 0.02);
    }
    for(const sl of T.slings){
      const n = hitSeg(b, sl);
      if(!n) continue;
      // Only a real hit fires the kicker; a ball rolling along it just rolls.
      const imp = -(b.vx * n.nx + b.vy * n.ny);
      if(imp > 70 && n.nx * sl.nx + n.ny * sl.ny > 0.5){
        bounce(b, sl.nx, sl.ny, 0.5, PB.KICK.sling, 0);
        if(sl.flash <= 0){ S.stats.slings++; award(ev, 'sling', PB.PTS.sling, b.x, b.y); }
        sl.flash = 0.18;
      }else bounce(b, n.nx, n.ny, 0.45, 0, 0.02);
    }
    for(const bp of T.bumpers){
      const n = hitCircle(b, bp.x, bp.y, bp.r);
      if(!n) continue;
      bounce(b, n.nx, n.ny, 0.9, PB.KICK.bumper, 0);
      if(bp.flash <= 0.05){ S.stats.bumpers++; award(ev, 'bumper', PB.PTS.bumper, bp.x, bp.y); ev.push({ type: 'bumperhit', i: bp.i, x: bp.x, y: bp.y }); }
      bp.flash = 0.2;
    }
    for(const t of T.targets){
      if(t.down) continue;
      const n = hitSeg(b, t);
      if(!n) continue;
      const imp = bounce(b, n.nx, n.ny, t.e, 0, 0.02);
      if(imp < 60 || t.flash > 0.05) continue;
      t.flash = 0.3;
      if(t.bank){
        t.down = true;
        S.bankUp--;
        S.stats.targets++;
        award(ev, 'target', PB.PTS.target, t.ax, (t.ay + t.by) / 2);
        if(S.bankUp <= 0){
          S.stats.banks++;
          award(ev, 'bank', PB.PTS.bank, 300, 360);
          S.bankReset = 3;
          if(T.kickbacks.some(k => !k.lit)){ T.kickbacks.forEach(k => { k.lit = true; }); ev.push({ type: 'kbon' }); }
        }
      }else if(t.lab){
        if(!t.lit){ t.lit = true; S.labHit++; }
        S.stats.targets++;
        award(ev, 'target', PB.PTS.labTarget, (t.ax + t.bx) / 2, t.ay);
        if(S.labHit >= S.labTargets){
          award(ev, 'bank', PB.PTS.labBank, (t.ax + t.bx) / 2, t.ay);
          S.stats.banks++;
          T.targets.forEach(x => { if(x.lab) x.lit = false; });
          S.labHit = 0;
        }
      }
    }
    if(T.core){
      const c = T.core, n = hitCircle(b, c.x, c.y, c.r);
      if(n){
        const imp = bounce(b, n.nx, n.ny, 0.6, 0, 0);
        // Only a real SHOT counts — a ball dribbling off the core is not one.
        if(imp > 220 && c.flash <= 0.05){
          c.flash = 0.35;
          if(S.multiball){
            if(S.jpCool <= 0){ S.jpCool = 1.2; S.stats.jackpots++; award(ev, 'jackpot', PB.PTS.jackpot, c.x, c.y); }
          }else{
            S.coreHits++;
            award(ev, 'core', PB.PTS.core, c.x, c.y);
            ev.push({ type: 'corecharge', n: S.coreHits });
            if(S.coreHits >= PB.CORE_HITS) startMultiball(ev);
          }
        }
      }
    }
    for(const f of T.flippers) hitFlipper(b, f);
    // Other balls (multiball): equal masses, a soft elastic swap along the normal.
    for(const o of balls){
      if(o === b || o.lane || o.id < b.id) continue;
      const dx = b.x - o.x, dy = b.y - o.y, d = Math.hypot(dx, dy);
      if(d >= 2 * R || d < 1e-6) continue;
      const nx = dx / d, ny = dy / d, pen = (2 * R - d) / 2;
      b.x += nx * pen; b.y += ny * pen; o.x -= nx * pen; o.y -= ny * pen;
      const rv = (b.vx - o.vx) * nx + (b.vy - o.vy) * ny;
      if(rv < 0){ const j = -rv * 0.95; b.vx += j * nx; b.vy += j * ny; o.vx -= j * nx; o.vy -= j * ny; }
    }
  }

  // Rollovers: the lanes and the lab's stars are sensors, crossed not hit.
  function sensors(b, ev){
    if(b.y > PB.LANE_Y0 && b.y < PB.LANE_Y1){
      for(let i = 0; i < 4; i++){
        const ln = T.lanes[i];
        if(Math.abs(b.x - ln.x) < 14 && !b.inLane){
          b.inLane = true;
          ln.flash = 0.4;
          S.stats.lanes++;
          award(ev, 'lane', PB.PTS.lane, ln.x, 110);
          if(S.skillOpen){
            S.skillOpen = false;
            if(i === S.skill){ award(ev, 'skill', PB.PTS.skill, ln.x, 110); }
          }
          if(!ln.lit){
            ln.lit = true;
            if(T.lanes.every(l => l.lit)){
              S.neonSets++; S.stats.neon++;
              award(ev, 'neon', PB.PTS.neon, 165, 110);
              T.lanes.forEach(l => { l.lit = false; });
              if(S.mult < PB.MULT_MAX){ S.mult++; ev.push({ type: 'mult', mult: S.mult }); }
              // Every third N·E·O·N earns an extra ball.
              if(S.neonSets % 3 === 0 && S.ballsLeft + balls.length < PB.BALLS_MAX){ S.ballsLeft++; S.extra++; ev.push({ type: 'extra' }); }
            }
          }
        }
      }
    }
    if(b.y > PB.LANE_Y1 + 6 || b.y < PB.LANE_Y0 - 6) b.inLane = false;
    for(const k of T.kickbacks){
      if(!k.lit || b.vy <= 0 || b.y < 600 || b.y > 650 || b.x < k.x0 || b.x > k.x1) continue;
      k.lit = false; k.flash = 0.6;
      b.vy = -PB.KICK.back; b.vx = k.side === 'L' ? 30 : -30;
      award(ev, 'kickback', PB.PTS.kickback, b.x, 630);
    }
    for(const st of T.stars){
      if(st.cool > 0) continue;
      if(Math.hypot(b.x - st.x, b.y - st.y) < st.r + R * 0.4){
        st.cool = 0.4; st.flash = 0.3; S.stats.stars++;
        award(ev, 'star', PB.PTS.star, st.x, st.y);
      }
    }
  }

  function startMultiball(ev){
    S.multiball = true; S.coreHits = 0; S.stats.multiballs++;
    award(ev, 'multiball', PB.PTS.multiball, T.core ? T.core.x : 165, T.core ? T.core.y : 400);
    const nb = newBall(false);
    nb.x = PB.PLUNGE.x; nb.y = 640; nb.vx = 0; nb.vy = -1500;
    S.save = Math.max(S.save, 8);
  }

  // A ball resting somewhere it can never leave (a pocket of posts in a lab
  // level, a dead spot on the stock one) gets nudged after a few seconds.
  // Not a ball the player is holding up on a flipper — that is a trap, a skill.
  function unstick(b, dt, ev){
    const moved = Math.hypot(b.x - b.lastX, b.y - b.lastY);
    b.lastX = b.x; b.lastY = b.y;
    const onFlipper = T.flippers.some(f => f.held && Math.hypot(b.x - f.px, b.y - f.py) < f.len + 20);
    if(!b.lane && !onFlipper && moved < 25 * dt) b.stuckT += dt; else b.stuckT = 0;
    if(b.stuckT > 2.6){
      b.stuckT = 0;
      b.vx = (rng() - 0.5) * 500; b.vy = -380 - rng() * 220;
      ev.push({ type: 'nudge', x: b.x, y: b.y });
    }
  }

  // ── DRAINS ──
  function drain(b, ev){
    balls.splice(balls.indexOf(b), 1);
    S.stats.drains++;
    ev.push({ type: 'drain', x: b.x });
    if(balls.length) {                       // multiball carries on while one is left
      if(balls.filter(x => !x.lane).length === 1 && S.multiball){ S.multiball = false; ev.push({ type: 'mbend' }); }
      return;
    }
    S.multiball = false;
    if(S.save > 0){ S.stats.saves++; ev.push({ type: 'saved' }); serve(); S.skillOpen = false; S.autoLaunch = 0.7; S.save = 0; S.saveUsed = true; return; }
    if(S.ballsLeft > 0){
      S.ballsLeft--; S.ballNo++;
      T.kickbacks.forEach(k => { k.lit = true; });
      ev.push({ type: 'nextball', n: S.ballNo });
      serve();
      return;
    }
    // The last ball: the round asks the shield first.
    if(opts.absorb && opts.absorb()){ ev.push({ type: 'absorb', x: b.x, y: 680 }); serve(); S.skillOpen = false; S.autoLaunch = 0.7; S.saveUsed = true; return; }
    S.over = true; S.reason = 'drain';
    ev.push({ type: 'over' });
  }

  // ── INPUT ──
  function flip(side, down){
    for(const f of T.flippers){
      if(f.side !== side) continue;
      if(down && !f.held) pend.push({ type: 'flip', side });
      f.held = !!down;
    }
    // A flip is also a LANE CHANGE: the lit N·E·O·N letters shift with it.
    if(down){
      const lit = T.lanes.map(l => l.lit);
      if(lit.some(Boolean) && !lit.every(Boolean)){
        const n = lit.length;
        T.lanes.forEach((l, i) => { l.lit = side === 'L' ? lit[(i + 1) % n] : lit[(i - 1 + n) % n]; });
      }
    }
  }
  function launch(ev, power){
    const b = balls.find(x => x.lane);
    if(!b) return false;
    const P = PB.PLUNGE;
    b.lane = false;
    b.x = P.x; b.y = 700 - R - 1;
    b.vx = 0; b.vy = -(P.vMin + (P.vMax - P.vMin) * Math.max(0, Math.min(1, power)));
    S.save = Math.max(S.save, S.saveUsed ? 0 : PB.SAVE);
    S.saveUsed = false;
    ev.push({ type: 'launch', power });
    return true;
  }

  function update(dtReal){
    const ev = pend.splice(0);
    if(S.over || dtReal <= 0) return ev;
    const dt = dtReal * PACE;
    S.t += dt;
    if(S.save > 0) S.save = Math.max(0, S.save - dt);
    if(S.jpCool > 0) S.jpCool = Math.max(0, S.jpCool - dt);
    if(S.charging) S.charge = Math.min(1, S.charge + dt / PB.PLUNGE.chargeSecs);
    if(S.autoLaunch > 0){ S.autoLaunch -= dt; if(S.autoLaunch <= 0){ S.autoLaunch = 0; launch(ev, 0.55); } }
    if(S.bankReset > 0){ S.bankReset -= dt; if(S.bankReset <= 0){ T.targets.forEach(t => { if(t.bank) t.down = false; }); S.bankUp = 3; ev.push({ type: 'bankup' }); } }
    // Flippers move at their own speed, whatever the frame rate.
    for(const f of T.flippers){
      const target = f.held ? f.up : f.rest;
      const w = f.held ? PB.FLIP.wUp : PB.FLIP.wDown;
      const d = target - f.ang;
      const stepA = Math.sign(d) * Math.min(Math.abs(d), w * dt);
      f.w = dt > 0 ? stepA / dt : 0;
      f.dAng = stepA;
    }
    // Substeps: each moves a ball at most ~4 units, so a thin wall cannot be skipped.
    let vmax = 0;
    for(const b of balls) vmax = Math.max(vmax, Math.hypot(b.vx, b.vy));
    const fmax = Math.max(...T.flippers.map(f => Math.abs(f.w) * f.len));
    const n = Math.min(40, Math.max(3, Math.ceil(Math.max(vmax, fmax) * dt / 3.5)));
    const h = dt / n;
    for(let k = 0; k < n; k++){
      for(const f of T.flippers) f.ang += f.dAng / n;
      for(const b of balls.slice()) step(b, h, ev);
      for(const b of balls) sensors(b, ev);
    }
    for(const f of T.flippers) if(Math.abs(f.ang - (f.held ? f.up : f.rest)) < 1e-4) f.w = 0;
    for(const b of balls.slice()){
      // A plunge too weak to clear the lane rolls back onto the plunger: it is
      // served again rather than counted as stuck.
      if(!b.lane && b.x > 318 && b.y > 650 && Math.abs(b.vy) < 60 && Math.abs(b.vx) < 60){ b.lane = true; b.stuckT = 0; }
      unstick(b, dt, ev);
      if(b.y > PB.H + R * 2 || b.x < -30 || b.x > PB.W + 30) drain(b, ev);
    }
    const fade = x => x > 0 ? Math.max(0, x - dt) : 0;
    T.bumpers.forEach(o => { o.flash = fade(o.flash); });
    T.slings.forEach(o => { o.flash = fade(o.flash); });
    T.targets.forEach(o => { o.flash = fade(o.flash); });
    T.lanes.forEach(o => { o.flash = fade(o.flash); });
    T.stars.forEach(o => { o.flash = fade(o.flash); o.cool = fade(o.cool); });
    T.kickbacks.forEach(o => { o.flash = fade(o.flash); });
    if(T.core) T.core.flash = fade(T.core.flash);
    return ev;
  }

  serve();
  return {
    S, T, balls, update, flip,
    // Hold to charge, let go to fire. A tap is a soft plunge.
    chargeDown(){ if(balls.some(b => b.lane)){ S.charging = true; } },
    chargeUp(){
      if(!S.charging) return false;
      S.charging = false;
      const p = S.charge;
      S.charge = 0;
      return launch(pend, p);
    },
    endClock(){ if(!S.over){ S.over = true; S.reason = 'timeout'; } },
    flipperTip(f){ return flipperPts(f); }
  };
}

// ── THE ROUND ──────────────────────────────────────────────────────────
// Controls, clock, scoring and the ending, shared by both builds. The frame
// loop is the renderer's: it calls round.frame(dt) and draws what comes back.
var pbLast = null;   // the last round, for the console: pbLast.S is the whole state
var PB_LKEYS = ['ArrowLeft', 'KeyZ', 'KeyA', 'ShiftLeft'];
var PB_RKEYS = ['ArrowRight', 'Slash', 'KeyM', 'KeyD', 'ShiftRight'];
// Up AND down both plunge, so INVERSE CONTROLS (which swaps them) cannot strand a ball.
var PB_PKEYS = ['Space', 'ArrowDown', 'ArrowUp', 'Enter', 'KeyS', 'KeyW'];

function pbRound(){
  const diff = getDifficultyModifier();
  const sim = pbSim({
    diff,
    cells: (typeof labTable === 'function') ? labTable() : null,    // 🧱 a Brick Lab table, or the stock one
    absorb: () => survivedFatal(),
    rng: () => dailyRand()
  });
  const S = sim.S;
  S.multMax = 1;
  const time0 = Math.round(PB.CLOCK * getTimeModifier());
  let time = time0, ended = false;

  setControls({ left: '◀', action: 'LAUNCH', right: '▶' });
  setControlHint('HOLD ◀ ▶ (OR EITHER HALF OF THE TABLE) TO FLIP · LAUNCH FIRES THE BALL',
                 '← / Z FLIPS LEFT · → / M FLIPS RIGHT · HOLD SPACE OR ↓ TO PULL THE PLUNGER');
  showTouchHint('TAP TO LAUNCH · HOLD EITHER SIDE TO FLIP');
  document.getElementById('g-time').textContent = time;
  document.getElementById('prog-fill').style.background = 'linear-gradient(90deg,#ff2bd6,var(--cyan))';

  // Every source that can hold a flipper (a key, the pad, a finger) is
  // counted, so letting go of ONE of them never drops a flipper another is
  // still holding.
  const held = { L: new Set(), R: new Set() };
  const frozen = () => ((typeof photoActive === 'function') && photoActive()) || ((typeof pauseActive === 'function') && pauseActive());
  const press = (side, src) => {
    if(ended || frozen()) return;
    hideTouchHint();
    const set = held[side];
    const was = set.size > 0;
    set.add(src);
    if(!was) sim.flip(side, true);
  };
  const release = (side, src) => {
    const set = held[side];
    if(!set.delete(src)) return;
    if(!set.size) sim.flip(side, false);
  };
  let plungeSrc = null;
  const laneBall = () => sim.balls.some(b => b.lane) && !S.autoLaunch;
  const plungeDown = src => {
    if(ended || frozen() || plungeSrc || !laneBall()) return false;
    hideTouchHint();
    plungeSrc = src;
    sim.chargeDown();
    return true;
  };
  const plungeUp = src => {
    if(plungeSrc !== src) return;
    plungeSrc = null;
    sim.chargeUp();
  };

  window.onkeydown = e => {
    const k = e.code;
    if(PB_LKEYS.includes(k)){ e.preventDefault(); if(!e.repeat) press('L', 'k' + k); }
    else if(PB_RKEYS.includes(k)){ e.preventDefault(); if(!e.repeat) press('R', 'k' + k); }
    else if(PB_PKEYS.includes(k)){
      e.preventDefault();
      // The gamepad's A arrives as a Space press with no release (it plunges
      // through the LAUNCH pad instead), so an untrusted one is ignored here.
      if(e.isTrusted === false && (k === 'Space' || k === 'Enter')) return;
      if(!e.repeat) plungeDown('k' + k);
    }
  };
  window.onkeyup = e => {
    const k = e.code;
    if(PB_LKEYS.includes(k)) release('L', 'k' + k);
    else if(PB_RKEYS.includes(k)) release('R', 'k' + k);
    else if(PB_PKEYS.includes(k)) plungeUp('k' + k);
  };
  bindHold(document.getElementById('ctrl-left'),  () => press('L', 'pad'), () => release('L', 'pad'));
  bindHold(document.getElementById('ctrl-right'), () => press('R', 'pad'), () => release('R', 'pad'));
  bindHold(document.getElementById('ctrl-action'), () => plungeDown('padA'), () => plungeUp('padA'));

  // The table itself: EVERY finger is its own flipper (bindCanvasDrag drives
  // one finger only, and pinball is played with two). A touch while a ball
  // waits on the plunger launches it; after that, the side it lands on flips.
  // Registered in _drag so clearCanvasDrag() takes it down with the round.
  const touches = new Map();
  const on = (target, type, fn, bucket) => { target.addEventListener(type, fn, { passive: false }); _drag[bucket].push([target, type, fn]); };
  const sideAt = (cx, cy) => boardPos(cx, cy).x < BOARD_W / 2 ? 'L' : 'R';
  if(aCanvas){
    if('ontouchstart' in window){
      on(aCanvas, 'touchstart', e => {
        e.preventDefault();
        for(const t of e.changedTouches){
          const id = 't' + t.identifier;
          if(sim.balls.every(b => b.lane) && plungeDown(id)){ touches.set(id, 'P'); continue; }
          const side = sideAt(t.clientX, t.clientY);
          touches.set(id, side);
          press(side, id);
        }
      }, 'touch');
      const up = e => {
        e.preventDefault();
        for(const t of e.changedTouches){
          const id = 't' + t.identifier, what = touches.get(id);
          touches.delete(id);
          if(what === 'P') plungeUp(id); else if(what) release(what, id);
        }
      };
      on(aCanvas, 'touchend', up, 'touch');
      on(aCanvas, 'touchcancel', up, 'touch');
    }
    // A mouse on the table works like one finger (the controller's A button
    // synthesises mouse presses at its cursor — those are left to the pad).
    let mouseSide = null;
    on(aCanvas, 'mousedown', e => {
      if(e.isTrusted === false) return;
      e.preventDefault();
      if(sim.balls.every(b => b.lane) && plungeDown('m')){ mouseSide = 'P'; return; }
      mouseSide = sideAt(e.clientX, e.clientY);
      press(mouseSide, 'm');
    }, 'mouse');
    on(window, 'mouseup', e => {
      if(!mouseSide) return;
      if(mouseSide === 'P') plungeUp('m'); else release(mouseSide, 'm');
      mouseSide = null;
    }, 'mouse');
  }

  gTimer = setInterval(() => {
    if(ended) return;
    time--;
    document.getElementById('g-time').textContent = Math.max(0, time);
    document.getElementById('prog-fill').style.width = `${Math.max(0, time / time0 * 100)}%`;
    if(time <= 5 && time > 0) snd('tick');
    if(time <= 0){ sim.endClock(); end('timeout'); }
  }, 1000);

  function end(reason){
    if(ended) return;
    ended = true;
    clearCanvasDrag();
    held.L.clear(); held.R.clear();
    sim.flip('L', false); sim.flip('R', false);
    if(reason !== 'timeout') snd('gameOver');
    const earned = capRaw(PB.CAP, Math.round(S.score));
    const st = S.stats;
    gLater(() => showResults('pinball', earned, {
      '🎯 Bumper Hits': st.bumpers,
      '🔤 N·E·O·N Sets': st.neon,
      '✖️ Best Multiplier': '×' + S.multMax,
      '💥 Multiballs': st.multiballs + (st.jackpots ? ` · ${st.jackpots} jackpot${st.jackpots === 1 ? '' : 's'}` : ''),
      '🎱 Balls Played': S.ballNo + (S.extra ? ` (+${S.extra} extra)` : ''),
      ...(reason === 'timeout' ? { '✅ Status': 'TABLE POWERED DOWN' } : { '💥 Status': 'LAST BALL DRAINED' }),
      '🏆 Final Score': `${earned} PTS`
    }), reason === 'timeout' ? 300 : 900);
  }

  let lastScore = -1;
  snd('go');
  return pbLast = {
    sim, S,
    // One frame: advance, sound, publish — and hand the events to the renderer.
    frame(dt){
      if(ended) return [];
      const ev = sim.update(dt);
      for(const e of ev){
        switch(e.type){
          case 'flip': snd('flip'); break;
          case 'launch': snd('shoot'); break;
          case 'bumper': snd('bounce'); break;
          case 'sling': snd('bounceWall'); break;
          case 'target': snd('hit'); break;
          case 'bank': snd('combo'); toastPb('🎯 BANK CLEARED'); break;
          case 'bankup': break;
          case 'kbon': toastPb('⬆ KICKBACKS LIT'); break;
          case 'lane': snd('pickup'); break;
          case 'skill': snd('success'); toastPb('🎯 SKILL SHOT +' + e.pts); break;
          case 'neon': snd('levelUp'); break;
          case 'mult': S.multMax = Math.max(S.multMax, e.mult); toastPb(`🔤 N·E·O·N · MULTIPLIER ×${e.mult}`); break;
          case 'extra': snd('levelUp'); toastPb('🎱 EXTRA BALL'); break;
          case 'core': snd('charge'); break;
          case 'multiball': snd('alarm'); toastPb('💥 MULTIBALL'); break;
          case 'jackpot': snd('coin'); toastPb('💰 JACKPOT +' + e.pts); break;
          case 'star': snd('score'); break;
          case 'kickback': snd('dash'); break;
          case 'nudge': snd('land'); break;
          case 'drain': snd('hurt'); break;
          case 'saved': snd('shield'); toastPb('🛡️ BALL SAVED'); break;
          case 'absorb': snd('shieldHit'); toastPb('🛡️ SHIELD — ONE MORE BALL'); break;
          case 'nextball': snd('go'); break;
          case 'over': break;
        }
      }
      if(S.score !== lastScore){ lastScore = S.score; setLive(Math.min(PB.CAP, S.score)); }
      if(S.over && S.reason === 'drain') end('drain');
      return ev;
    },
    get ended(){ return ended; }
  };
}
// A one-line banner under the board for the table's big moments — the
// renderers draw their own flourish; this one says it in words.
function toastPb(msg){ try{ toast(msg, 1500); }catch(e){} }

// ── THE 2D BUILD ───────────────────────────────────────────────────────
// The table is drawn in its own units and squashed to fit the 560 × 500
// board: 360 wide in the middle, 720 tall shown as 500 — a table seen at a
// tilt, so every circle is an ellipse and the flippers read as flat on it.
// The two side panels carry the table's state; the header carries the score.
function startPinball(){
  document.getElementById('g-canvas-holder').style.display = 'block';
  const round = pbRound();
  fitCanvas();
  const W = BOARD_W, H = BOARD_H;
  const OX = (W - PB.W) / 2, K = H / PB.H;
  const S = round.S, sim = round.sim, T = sim.T;
  const trails = new Map(), pops = [], sparks = [];
  let banner = { text: 'BALL 1', t: 1.4 }, last = gNow(), glowT = 0;
  const col = PB.COLORS;
  const sx = x => OX + x, sy = y => y * K;

  // Draw in table units: everything between begin() and done() is squashed,
  // so a circle comes out an ellipse and the flippers keep their true shape.
  function begin(){ aCtx.save(); aCtx.translate(OX, 0); aCtx.scale(1, K); }
  function done(){ aCtx.restore(); }

  function glowLine(ax, ay, bx, by, c, w, blur){
    aCtx.save();
    aCtx.strokeStyle = c; aCtx.lineWidth = w; aCtx.lineCap = 'round';
    aCtx.shadowBlur = blur || 0; aCtx.shadowColor = c;
    aCtx.beginPath(); aCtx.moveTo(ax, ay); aCtx.lineTo(bx, by); aCtx.stroke();
    aCtx.restore();
  }
  function disc(x, y, r, fill, stroke, lw){
    aCtx.beginPath(); aCtx.arc(x, y, r, 0, Math.PI * 2);
    if(fill){ aCtx.fillStyle = fill; aCtx.fill(); }
    if(stroke){ aCtx.strokeStyle = stroke; aCtx.lineWidth = lw || 2; aCtx.stroke(); }
  }
  function starPath(x, y, r){
    aCtx.beginPath();
    for(let i = 0; i < 10; i++){
      const a = -Math.PI / 2 + i * Math.PI / 5, rr = i % 2 ? r * 0.45 : r;
      const px = x + Math.cos(a) * rr, py = y + Math.sin(a) * rr;
      i ? aCtx.lineTo(px, py) : aCtx.moveTo(px, py);
    }
    aCtx.closePath();
  }

  // The playfield's outline, for the table surface.
  function fieldPath(){
    aCtx.beginPath();
    aCtx.moveTo(12, PB.H);
    for(const w of T.walls) if(w.arc) aCtx.lineTo(w.bx, w.by);
    aCtx.lineTo(348, PB.H); aCtx.closePath();
  }

  function drawTable(dt){
    // ── SURFACE ──
    begin();
    fieldPath();
    const g = aCtx.createLinearGradient(0, 0, 0, PB.H);
    g.addColorStop(0, '#0b0a26'); g.addColorStop(0.55, '#07081a'); g.addColorStop(1, '#0d0618');
    aCtx.fillStyle = g; aCtx.fill();
    aCtx.save(); aCtx.clip();
    aCtx.strokeStyle = 'rgba(80,120,255,0.07)'; aCtx.lineWidth = 1;
    for(let x = 12; x < 348; x += 24){ aCtx.beginPath(); aCtx.moveTo(x, 0); aCtx.lineTo(x, PB.H); aCtx.stroke(); }
    for(let y = 0; y < PB.H; y += 24){ aCtx.beginPath(); aCtx.moveTo(0, y); aCtx.lineTo(PB.W, y); aCtx.stroke(); }
    // Lane glow under the plunger lane and a soft pool of light where the bumpers are.
    const pool = aCtx.createRadialGradient(165, 250, 10, 165, 250, 170);
    pool.addColorStop(0, 'rgba(255,43,214,0.10)'); pool.addColorStop(1, 'rgba(255,43,214,0)');
    aCtx.fillStyle = pool; aCtx.fillRect(0, 60, PB.W, 400);
    aCtx.restore();
    // The plunger lane.
    aCtx.fillStyle = 'rgba(0,245,255,0.05)';
    aCtx.fillRect(318, 250, 30, 450);

    // ── WALLS ──
    for(const w of T.walls){
      if(w.plunger) continue;
      const c = w.arc ? '#ff2bd6' : w.gate ? '#ffd700' : w.lane ? '#00f5ff' : w.sling ? '#1fb7ff' : w.apron ? '#3d7bff' : col.wall;
      glowLine(w.ax, w.ay, w.bx, w.by, c, w.lane ? 5 : 3, w.arc ? 10 : 6);
    }
    // Slingshot faces: they light when they kick.
    for(const s of T.slings){
      const f = Math.min(1, s.flash / 0.18);
      glowLine(s.ax, s.ay, s.bx, s.by, f > 0 ? '#ffffff' : '#00f5ff', 4 + f * 3, 8 + f * 16);
    }
    // Posts.
    for(const p of T.posts){
      disc(p.x, p.y, p.r, p.kind === 'post' ? '#0b1a3a' : '#0a1024', p.kind === 'post' ? col.post : 'rgba(0,245,255,0.7)', 2);
    }
    // ── TOP LANES ──
    const letters = ['N', 'E', 'O', 'N'];
    T.lanes.forEach((ln, i) => {
      const lit = ln.lit, fl = ln.flash > 0, skill = S.skillOpen && S.skill === i && sim.balls.some(b => b.lane || b.y > 250);
      aCtx.fillStyle = lit ? 'rgba(255,43,214,0.55)' : fl ? 'rgba(255,255,255,0.35)' : skill && (glowT % 0.5 < 0.25) ? 'rgba(255,215,0,0.45)' : 'rgba(255,43,214,0.08)';
      aCtx.fillRect(ln.x - 12, PB.LANE_Y0 + 4, 24, PB.LANE_Y1 - PB.LANE_Y0 - 8);
    });
    // Kickback arrows in the outlanes.
    for(const k of T.kickbacks){
      const x = (k.x0 + k.x1) / 2;
      aCtx.fillStyle = k.lit ? (k.flash > 0 ? '#ffffff' : '#39ff14') : 'rgba(57,255,20,0.12)';
      aCtx.beginPath(); aCtx.moveTo(x, 606); aCtx.lineTo(x + 7, 622); aCtx.lineTo(x - 7, 622); aCtx.closePath(); aCtx.fill();
    }
    // ── STARS ──
    for(const st of T.stars){
      starPath(st.x, st.y, st.r);
      aCtx.fillStyle = st.flash > 0 ? '#ffffff' : 'rgba(179,92,255,0.35)';
      aCtx.fill();
      aCtx.strokeStyle = col.star; aCtx.lineWidth = 1.5; aCtx.stroke();
    }
    // ── TARGETS ──
    for(const t of T.targets){
      if(t.bank){
        if(t.down){ glowLine(t.ax, t.ay, t.bx, t.by, 'rgba(255,215,0,0.15)', 3, 0); continue; }
        glowLine(t.ax, t.ay, t.bx, t.by, t.flash > 0 ? '#ffffff' : col.target, 6, 10);
      }else{
        glowLine(t.ax, t.ay, t.bx, t.by, t.flash > 0 ? '#ffffff' : t.lit ? col.target : 'rgba(255,215,0,0.35)', 6, t.lit ? 10 : 0);
      }
    }
    // ── THE CORE ──
    if(T.core){
      const c = T.core, fl = c.flash > 0;
      const pulse = 0.6 + 0.4 * Math.sin(glowT * (S.multiball ? 14 : 4));
      const rg = aCtx.createRadialGradient(c.x, c.y, 2, c.x, c.y, c.r + 10);
      rg.addColorStop(0, fl ? '#ffffff' : '#b6ffa0'); rg.addColorStop(0.5, S.multiball ? '#ffd700' : col.core); rg.addColorStop(1, 'rgba(57,255,20,0)');
      aCtx.fillStyle = rg; aCtx.globalAlpha = 0.5 + 0.5 * pulse;
      disc(c.x, c.y, c.r + 10, rg);
      aCtx.globalAlpha = 1;
      disc(c.x, c.y, c.r, '#052a10', S.multiball ? '#ffd700' : col.core, 2.5);
      // Charge pips: how many hits until multiball.
      for(let i = 0; i < PB.CORE_HITS; i++){
        const a = -Math.PI / 2 + i * Math.PI * 2 / PB.CORE_HITS;
        disc(c.x + Math.cos(a) * (c.r - 5), c.y + Math.sin(a) * (c.r - 5), 2.2, i < S.coreHits || S.multiball ? '#39ff14' : 'rgba(57,255,20,0.2)');
      }
    }
    // ── BUMPERS ──
    for(const bp of T.bumpers){
      const f = Math.min(1, bp.flash / 0.2);
      aCtx.save();
      aCtx.shadowBlur = 8 + f * 22; aCtx.shadowColor = col.bumper;
      disc(bp.x, bp.y, bp.r + f * 3, '#2a0628', f > 0 ? '#ffffff' : col.bumper, 3);
      aCtx.restore();
      const cap = aCtx.createRadialGradient(bp.x - 4, bp.y - 5, 1, bp.x, bp.y, bp.r - 3);
      cap.addColorStop(0, f > 0 ? '#ffffff' : '#ff9df0'); cap.addColorStop(1, '#8a0f7a');
      disc(bp.x, bp.y, bp.r - 4, cap);
    }
    // ── FLIPPERS ──
    for(const fl of T.flippers){
      const tip = sim.flipperTip(fl);
      const ang = Math.atan2(tip.ty - fl.py, tip.tx - fl.px);
      aCtx.save();
      aCtx.translate(fl.px, fl.py); aCtx.rotate(ang);
      aCtx.beginPath();
      aCtx.arc(0, 0, fl.r0, Math.PI / 2, Math.PI * 1.5);
      aCtx.lineTo(fl.len, -fl.r1);
      aCtx.arc(fl.len, 0, fl.r1, -Math.PI / 2, Math.PI / 2);
      aCtx.closePath();
      const fg = aCtx.createLinearGradient(0, -fl.r0, 0, fl.r0);
      fg.addColorStop(0, '#e8f6ff'); fg.addColorStop(1, '#6a86b8');
      aCtx.fillStyle = fg; aCtx.fill();
      aCtx.shadowBlur = fl.held ? 16 : 8; aCtx.shadowColor = '#00f5ff';
      aCtx.strokeStyle = fl.held ? '#ffffff' : '#00f5ff'; aCtx.lineWidth = 2.5; aCtx.stroke();
      aCtx.restore();
      disc(fl.px, fl.py, 3, '#0a1230');
    }
    // ── THE PLUNGER ──
    const py0 = 700 + S.charge * 14;
    aCtx.strokeStyle = S.charging ? '#ffd700' : 'rgba(0,245,255,0.6)'; aCtx.lineWidth = 2;
    aCtx.beginPath();
    for(let i = 0; i <= 8; i++){ const y = py0 + i * (PB.H + 10 - py0) / 8; aCtx.lineTo(i % 2 ? 326 : 340, y); }
    aCtx.stroke();
    aCtx.fillStyle = S.charging ? '#ffd700' : '#9fe6ff';
    aCtx.fillRect(320, py0 - 2, 26, 5);

    // ── BALLS (and their trails) ──
    for(const b of sim.balls){
      let tr = trails.get(b.id);
      if(!tr){ tr = []; trails.set(b.id, tr); }
      if(dt > 0){ tr.push([b.x, b.y]); if(tr.length > 7) tr.shift(); }
      for(let i = 0; i < tr.length - 1; i++){
        aCtx.globalAlpha = (i + 1) / tr.length * 0.28;
        disc(tr[i][0], tr[i][1], PB.BALL_R * (0.5 + 0.5 * i / tr.length), '#9fe6ff');
      }
      aCtx.globalAlpha = 1;
      const bg = aCtx.createRadialGradient(b.x - 3, b.y - 3, 1, b.x, b.y, PB.BALL_R);
      bg.addColorStop(0, '#ffffff'); bg.addColorStop(0.35, '#d6e2f2'); bg.addColorStop(0.8, '#7f8fb0'); bg.addColorStop(1, '#3a4460');
      aCtx.save(); aCtx.shadowBlur = 10; aCtx.shadowColor = '#9fe6ff';
      disc(b.x, b.y, PB.BALL_R, bg);
      aCtx.restore();
    }
    for(const id of [...trails.keys()]) if(!sim.balls.some(b => b.id === id)) trails.delete(id);
    done();

    // ── IN SCREEN SPACE: words (never squashed) ──
    aCtx.textAlign = 'center';
    aCtx.font = '900 13px Orbitron, sans-serif';
    T.lanes.forEach((ln, i) => {
      aCtx.fillStyle = ln.lit ? '#ff2bd6' : 'rgba(255,255,255,0.28)';
      aCtx.fillText(letters[i], sx(ln.x), sy(PB.LANE_Y0) - 4);
    });
    if(S.save > 0){
      const blink = S.save > 2 || (glowT % 0.3 < 0.18);
      aCtx.font = '700 10px Orbitron, sans-serif';
      aCtx.fillStyle = blink ? '#39ff14' : 'rgba(57,255,20,0.25)';
      aCtx.fillText('SHOOT AGAIN', sx(165), sy(706));
    }
  }

  function drawPanels(){
    aCtx.textAlign = 'center';
    // LEFT: the ball, the multiplier, N·E·O·N.
    const L = OX / 2;
    aCtx.font = '700 9px Orbitron, sans-serif'; aCtx.fillStyle = 'rgba(234,246,255,0.55)';
    aCtx.fillText('BALL', L, 40);
    aCtx.font = '900 22px Orbitron, sans-serif'; aCtx.fillStyle = '#eaf6ff';
    aCtx.fillText(String(S.ballNo), L, 66);
    const left = S.ballsLeft;
    for(let i = 0; i < Math.min(5, left); i++) disc(L - (Math.min(5, left) - 1) * 7 + i * 14, 84, 4.5, '#cfd9ea');
    aCtx.font = '700 9px Orbitron, sans-serif'; aCtx.fillStyle = 'rgba(234,246,255,0.55)';
    aCtx.fillText('MULTIPLIER', L, 124);
    aCtx.font = '900 30px Orbitron, sans-serif'; aCtx.fillStyle = S.mult > 1 ? '#ff2bd6' : '#eaf6ff';
    aCtx.fillText('×' + S.mult, L, 158);
    aCtx.font = '700 9px Orbitron, sans-serif'; aCtx.fillStyle = 'rgba(234,246,255,0.55)';
    aCtx.fillText('LIGHT N·E·O·N', L, 196);
    aCtx.fillText('FOR ×' + Math.min(PB.MULT_MAX, S.mult + 1), L, 210);
    // RIGHT: the core and the kickbacks.
    const R = W - OX / 2;
    aCtx.fillStyle = 'rgba(234,246,255,0.55)';
    aCtx.fillText(S.multiball ? 'JACKPOT' : 'CORE', R, 40);
    aCtx.font = '900 20px Orbitron, sans-serif';
    aCtx.fillStyle = S.multiball ? '#ffd700' : '#39ff14';
    aCtx.fillText(S.multiball ? 'LIVE' : `${S.coreHits}/${PB.CORE_HITS}`, R, 66);
    aCtx.font = '700 9px Orbitron, sans-serif'; aCtx.fillStyle = 'rgba(234,246,255,0.55)';
    aCtx.fillText('KICKBACK', R, 110);
    T.kickbacks.forEach((k, i) => {
      aCtx.fillStyle = k.lit ? '#39ff14' : 'rgba(57,255,20,0.18)';
      aCtx.font = '900 14px Orbitron, sans-serif';
      aCtx.fillText(k.side, R - 12 + i * 24, 132);
    });
    aCtx.font = '700 9px Orbitron, sans-serif'; aCtx.fillStyle = 'rgba(234,246,255,0.55)';
    aCtx.fillText('TARGETS', R, 176);
    for(let i = 0; i < 3; i++) disc(R - 14 + i * 14, 192, 4.5, i < 3 - S.bankUp ? '#ffd700' : 'rgba(255,215,0,0.2)');
    if(S.charging){
      aCtx.fillStyle = 'rgba(234,246,255,0.55)'; aCtx.fillText('PLUNGER', R, 236);
      aCtx.fillStyle = 'rgba(255,215,0,0.2)'; aCtx.fillRect(R - 30, 244, 60, 8);
      aCtx.fillStyle = '#ffd700'; aCtx.fillRect(R - 30, 244, 60 * S.charge, 8);
    }
  }

  function loop(){
    if(round.ended && !pops.length && !sparks.length) return;
    gameLoopId = requestAnimationFrame(loop);
    const now = gNow();
    const dt = Math.max(0, Math.min(0.05, (now - last) / 1000)); last = now;
    if(dt > 0) glowT += dt;
    const ev = round.frame(dt);
    for(const e of ev){
      if(e.pts > 0 && e.x != null) pops.push({ x: sx(e.x), y: sy(e.y), text: '+' + e.pts, t: 0.9, big: e.pts >= 15 });
      if(e.type === 'bumperhit' || e.type === 'jackpot' || e.type === 'multiball'){
        const n = e.type === 'bumperhit' ? 8 : 26;
        for(let i = 0; i < n; i++){ const a = Math.random() * Math.PI * 2, v = 1 + Math.random() * 3; sparks.push({ x: sx(e.x), y: sy(e.y), vx: Math.cos(a) * v, vy: Math.sin(a) * v * K, t: 1, c: e.type === 'jackpot' ? '#ffd700' : '#ff2bd6' }); }
      }
      if(e.type === 'multiball') banner = { text: 'MULTIBALL', t: 1.6 };
      else if(e.type === 'jackpot') banner = { text: 'JACKPOT', t: 1.1 };
      else if(e.type === 'neon') banner = { text: 'N·E·O·N', t: 1.2 };
      else if(e.type === 'skill') banner = { text: 'SKILL SHOT', t: 1.3 };
      else if(e.type === 'saved') banner = { text: 'BALL SAVED', t: 1.2 };
      else if(e.type === 'absorb') banner = { text: 'SHIELD SAVE', t: 1.3 };
      else if(e.type === 'extra') banner = { text: 'EXTRA BALL', t: 1.4 };
      else if(e.type === 'nextball') banner = { text: 'BALL ' + e.n, t: 1.3 };
      else if(e.type === 'kickback') banner = { text: 'KICKBACK', t: 0.9 };
    }

    aCtx.clearRect(0, 0, W, H);
    aCtx.fillStyle = '#04050d'; aCtx.fillRect(0, 0, W, H);
    // The side panels' frames.
    aCtx.fillStyle = 'rgba(255,255,255,0.025)';
    aCtx.fillRect(0, 0, OX - 6, H); aCtx.fillRect(W - OX + 6, 0, OX - 6, H);
    drawTable(dt);
    drawPanels();

    for(let i = sparks.length - 1; i >= 0; i--){
      const p = sparks[i];
      if(dt > 0){ p.x += p.vx; p.y += p.vy; p.vx *= 0.93; p.vy *= 0.93; p.t -= dt * 2; }
      if(p.t <= 0){ sparks.splice(i, 1); continue; }
      aCtx.globalAlpha = p.t; aCtx.fillStyle = p.c; aCtx.fillRect(p.x - 1.5, p.y - 1.5, 3, 3);
    }
    aCtx.globalAlpha = 1;
    aCtx.textAlign = 'center';
    for(let i = pops.length - 1; i >= 0; i--){
      const p = pops[i];
      if(dt > 0){ p.t -= dt; p.y -= dt * 22; }
      if(p.t <= 0){ pops.splice(i, 1); continue; }
      aCtx.globalAlpha = Math.min(1, p.t * 2);
      aCtx.font = (p.big ? '900 15px' : '700 11px') + ' Orbitron, sans-serif';
      aCtx.fillStyle = p.big ? '#ffd700' : '#eaf6ff';
      aCtx.fillText(p.text, p.x, p.y);
    }
    aCtx.globalAlpha = 1;
    if(banner.t > 0){
      if(dt > 0) banner.t -= dt;
      aCtx.save();
      aCtx.globalAlpha = Math.min(1, banner.t * 1.6);
      aCtx.font = '900 28px Orbitron, sans-serif';
      aCtx.fillStyle = '#eaf6ff';
      aCtx.shadowBlur = 18; aCtx.shadowColor = '#ff2bd6';
      aCtx.fillText(banner.text, W / 2, H * 0.52);
      aCtx.restore();
    }
  }
  gameLoopId = requestAnimationFrame(loop);
}

// ══════════════════════════════════════════════════════════════════════
//  🚀 3D MISSIONS, PART VIII · 🎱 NEON PINBALL 3D — a table in the city
// ══════════════════════════════════════════════════════════════════════
// The same pbRound() as the 2D build (§ 30), drawn as a real table: walls
// that stand up, bumpers with lit caps, a chrome ball, a spinning reactor
// core and a backbox that carries the ball, the multiplier and the core in
// the arcade's block type. The camera is FIXED behind the flippers (the
// never-yaw rule, § 3) — nothing but the flippers and the ball ever turns.
(function(){
'use strict';

const P = window.PI3D;
if(!P) return;
const K = P.kit;
const { begin3d, runLoop, mine } = K;
const drawText3D = K.drawText3D;

P.games.pinball = function(){
  const w = begin3d({
    ease: 0.1,
    env:  { zenith:'#05031a', horizon:'#3a0a4a', ground:'#05040f', intensity: 1.25 },
    fog:  { color:'#0c0620', density: 0.0048 },
    sun:  { dir:[-0.35, -0.9, -0.45], color:'#8f7dff', intensity: 0.65 },
    grade:{ exposure: 0.95, bloom: 0.46, threshold: 1.6, knee: 0.5, radius: 0.9,
            vignette: 0.46, aberration: 0.4, grain: 0.026, scanline: 0.012, saturation: 1.14 }
  });
  if(!w) return;
  const r = w.r;
  const round = pbRound();
  const S = round.S, sim = round.sim, T = sim.T;
  const U = 1 / 20;                                   // table units → world
  const X = x => (x - 180) * U, Z = y => (y - 360) * U;
  const WALL_H = 0.62, me = mine();
  let spin = 0, glowT = 0;

  w.buildCity({ seed: 31031, count: 64, spread: 112, hole: 26, y: -11 });

  const EM = { arc: '#ff2bd6', wall: '#3d7bff', lane: '#00f5ff', gate: '#ffd700', sling: '#1fb7ff', apron: '#3d7bff' };
  function wall(s){
    const c = s.arc ? EM.arc : s.gate ? EM.gate : s.lane ? EM.lane : s.sling ? EM.sling : s.apron ? EM.apron : EM.wall;
    const h = s.lane ? 0.5 : WALL_H;
    const a = [X(s.ax), h / 2, Z(s.ay)], b = [X(s.bx), h / 2, Z(s.by)];
    const wd = s.lane ? 0.34 : 0.2;
    r.beam(a, b, wd, { height: h, color: '#0a0f24', metallic: 0.7, roughness: 0.32, rim: 1.1, emissive: c, emissiveStrength: 0.35, detail: 0 });
    // A hot rim along the top of every wall: the table's neon.
    r.beam([a[0], h + 0.02, a[2]], [b[0], h + 0.02, b[2]], wd * 1.1, { height: 0.05, color: '#ffffff', emissive: c, emissiveStrength: s.arc ? 1.9 : 1.4, detail: 0 });
  }

  runLoop(dt => {
    const ev = round.frame(dt);
    if(dt > 0){ spin += dt * 1.6; glowT += dt; }
    for(const e of ev){
      if(e.type === 'bumperhit'){ w.burst([X(e.x), 0.9, Z(e.y)], '#ff2bd6', 12, { speed: 6, life: 0.45 }); }
      else if(e.type === 'jackpot'){ w.burst([X(e.x), 1, Z(e.y)], '#ffd700', 40, { speed: 11, life: 0.8 }); w.pop([X(e.x), 2.6, Z(e.y)], 'JACKPOT +' + e.pts, '#ffd700'); w.kick(1.3); }
      else if(e.type === 'multiball'){ w.burst([X(e.x), 1, Z(e.y)], '#39ff14', 50, { speed: 12, life: 0.9 }); w.pop([0, 3, Z(300)], 'MULTIBALL', '#39ff14'); w.kick(1.8); }
      else if(e.type === 'neon'){ w.pop([0, 2.4, Z(90)], 'NEON', '#ff2bd6'); }
      else if(e.type === 'mult'){ w.pop([0, 3.2, Z(200)], 'MULTIPLIER X' + e.mult, '#ff2bd6'); }
      else if(e.type === 'skill'){ w.pop([X(e.x), 2.4, Z(110)], 'SKILL SHOT', '#ffd700'); }
      else if(e.type === 'bank'){ w.pop([X(300), 2.2, Z(360)], 'TARGETS +' + e.pts, '#ffd700'); }
      else if(e.type === 'saved' || e.type === 'absorb'){ w.pop([0, 2.4, Z(640)], e.type === 'saved' ? 'BALL SAVED' : 'SHIELD', '#39ff14'); }
      else if(e.type === 'extra'){ w.pop([0, 2.8, Z(400)], 'EXTRA BALL', '#00f5ff'); }
      else if(e.type === 'drain'){ w.burst([X(e.x), 0.6, Z(712)], '#ff4d6d', 22, { speed: 7, life: 0.6 }); w.kick(0.8); }
      else if(e.type === 'kickback'){ w.burst([X(e.x), 0.6, Z(630)], '#39ff14', 18, { speed: 8, life: 0.5 }); }
      else if(e.type === 'nextball'){ w.pop([0, 2.6, Z(560)], 'BALL ' + e.n, '#eaf6ff'); }
    }

    // A FIXED camera behind the flippers, high enough to see the top lanes
    // and the backbox over the whole length of the table.
    w.goal.eye[0] = 0; w.goal.eye[1] = 25; w.goal.eye[2] = 27.5;
    w.goal.target[0] = 0; w.goal.target[1] = -1; w.goal.target[2] = 0.4;
    w.goal.fov = 55;
    w.step(dt);

    w.begin();
    w.drawStars();
    w.drawCity(0);

    // ── THE CABINET AND THE PLAYFIELD ──
    r.draw('slab', { pos:[0, -0.9, 0.2], scale:[18.6, 1.4, 37.6], color:'#120a26', metallic: 0.6, roughness: 0.34, rim: 0.9, emissive:'#6b2bd6', emissiveStrength: 0.12 });
    r.draw('box', { pos:[0, -0.19, 0], scale:[17.0, 0.04, 36.2], color:'#070818', metallic: 0.35, roughness: 0.42, rim: 0.3 });
    for(let x = 36; x < 348; x += 48){
      r.beam([X(x), -0.16, Z(20)], [X(x), -0.16, Z(718)], 0.03, { height: 0.02, color:'#101a40', emissive:'#2a4dff', emissiveStrength: 0.35, detail: 0 });
    }
    for(let y = 48; y < 720; y += 48){
      r.beam([X(14), -0.16, Z(y)], [X(346), -0.16, Z(y)], 0.03, { height: 0.02, color:'#101a40', emissive:'#2a4dff', emissiveStrength: 0.35, detail: 0 });
    }
    // The plunger lane glows faintly.
    r.draw('box', { pos:[X(333), -0.15, Z(480)], scale:[1.4, 0.02, 22.4], color:'#04151c', emissive:'#00f5ff', emissiveStrength: 0.14 });

    // ── THE BACKBOX ──
    r.draw('slab', { pos:[0, 2.3, Z(-26)], scale:[18.6, 4.8, 0.6], color:'#0d0820', metallic: 0.65, roughness: 0.3, rim: 1.2, emissive:'#ff2bd6', emissiveStrength: 0.1 });
    r.beam([X(0), 4.75, Z(-26) + 0.32], [X(360), 4.75, Z(-26) + 0.32], 0.12, { height: 0.08, color:'#ffffff', emissive:'#ff2bd6', emissiveStrength: 2.0, detail: 0 });
    drawText3D(r, 'NEON PINBALL', [0, 3.35, Z(-26) + 0.35], 0.2, { color:'#ffd6f6', emissiveStrength: 1.5 });
    const status = S.multiball ? `BALL ${S.ballNo}  X${S.mult}  JACKPOT` : `BALL ${S.ballNo}  X${S.mult}  CORE ${S.coreHits}/${PB.CORE_HITS}`;
    drawText3D(r, status, [0, 1.35, Z(-26) + 0.35], 0.13, { color: S.multiball ? '#ffe680' : '#bfffd0', emissiveStrength: 1.2 });

    // ── WALLS, LANES, POSTS ──
    for(const s of T.walls) if(!s.plunger) wall(s);
    for(const p of T.posts){
      const rr = p.r * U * 2;
      r.draw('cylinder', { pos:[X(p.x), 0.3, Z(p.y)], scale:[rr, 0.62, rr], color:'#0b1a3a', metallic: 0.7, roughness: 0.3, rim: 1,
                           emissive: p.kind === 'post' ? '#00f5ff' : '#1fb7ff', emissiveStrength: p.kind === 'post' ? 0.8 : 0.5 });
    }
    // Slingshot faces, lit when they kick.
    for(const s of T.slings){
      const f = Math.min(1, s.flash / 0.18);
      r.beam([X(s.ax), 0.24, Z(s.ay)], [X(s.bx), 0.24, Z(s.by)], 0.14, { height: 0.44, color:'#0b1830', metallic: 0.6, roughness: 0.3, emissive: '#00f5ff', emissiveStrength: 0.45 + f * 1.6, detail: 0 });
      r.beam([X(s.ax), 0.48, Z(s.ay)], [X(s.bx), 0.48, Z(s.by)], 0.16, { height: 0.04, color:'#ffffff', emissive: '#00f5ff', emissiveStrength: 1.2 + f * 1.4, detail: 0 });
    }
    // The N·E·O·N lanes: a lit floor panel and its letter in the block type.
    const letters = ['N', 'E', 'O', 'N'];
    T.lanes.forEach((ln, i) => {
      const skill = S.skillOpen && S.skill === i && (glowT % 0.5 < 0.25);
      const on = ln.lit || ln.flash > 0;
      r.draw('box', { pos:[X(ln.x), -0.14, Z(110)], scale:[1.3, 0.02, 1.7], color:'#1a0620',
                      emissive: skill ? '#ffd700' : '#ff2bd6', emissiveStrength: on ? 1.5 : skill ? 1.0 : 0.12 });
      // Standing up behind its lane, facing the camera, so it reads at a glance.
      drawText3D(r, letters[i], [X(ln.x), 0.95, Z(PB.LANE_Y0 - 6)], 0.13, { depth: 0.08,
                  color: ln.lit ? '#ffd6f6' : '#6a5a78', emissiveStrength: ln.lit ? 1.8 : 0.35 });
    });
    // Kickback arrows in the outlanes: lit green, spent dark.
    for(const k of T.kickbacks){
      r.draw('cone', { pos:[X((k.x0 + k.x1) / 2), 0.05, Z(614)], rot:[-Math.PI / 2, 0, 0], scale:[0.55, 0.7, 0.2],
                       color:'#062a0a', emissive:'#39ff14', emissiveStrength: k.lit ? (k.flash > 0 ? 2.2 : 1.1) : 0.08 });
    }
    // SHOOT AGAIN between the flippers while the ball save runs.
    if(S.save > 0 && (S.save > 2 || glowT % 0.3 < 0.18)){
      r.draw('box', { pos:[0, -0.14, Z(700)], scale:[2.4, 0.02, 0.5], color:'#062a0a', emissive:'#39ff14', emissiveStrength: 1.5 });
    }

    // ── STARS ──
    for(const st of T.stars){
      const f = st.flash > 0;
      r.draw('thintorus', { pos:[X(st.x), -0.12, Z(st.y)], scale: 1.05, color:'#1a0a2a', emissive:'#b35cff', emissiveStrength: f ? 2.2 : 0.7 });
      if(f) r.glow([X(st.x), 0.2, Z(st.y)], 0.9, '#b35cff', 0.8);
    }
    // ── TARGETS ──
    for(const t of T.targets){
      const f = t.flash > 0;
      if(t.bank){
        const yc = (t.ay + t.by) / 2;
        r.draw('slab', { pos:[X(t.ax) - 0.1, t.down ? -0.34 : 0.34, Z(yc)], scale:[0.2, 0.7, 1.2],
                         color:'#2a2006', metallic: 0.4, roughness: 0.35, emissive:'#ffd700', emissiveStrength: t.down ? 0.05 : f ? 2.0 : 0.9 });
      }else{
        r.draw('slab', { pos:[X((t.ax + t.bx) / 2), 0.26, Z(t.ay)], scale:[1.1, 0.52, 0.2],
                         color:'#2a2006', metallic: 0.4, roughness: 0.35, emissive:'#ffd700', emissiveStrength: f ? 2.0 : t.lit ? 1.2 : 0.3 });
      }
    }
    // ── THE REACTOR CORE ──
    if(T.core){
      const c = T.core, f = c.flash > 0;
      const pulse = 0.5 + 0.5 * Math.sin(glowT * (S.multiball ? 12 : 3.5));
      r.draw('core', { pos:[X(c.x), 0.55, Z(c.y)], rot:[0, spin, 0], scale: 1.25, color:'#0a2a12', metallic: 0.6, roughness: 0.3, rim: 1.1,
                       emissive: S.multiball ? '#ffd700' : '#39ff14', emissiveStrength: f ? 2.0 : 0.6 + pulse * 0.6 });
      for(let i = 0; i < PB.CORE_HITS; i++){
        const a = spin * 0.5 + i * Math.PI * 2 / PB.CORE_HITS;
        const lit = S.multiball || i < S.coreHits;
        r.draw('sphere', { pos:[X(c.x) + Math.cos(a) * 1.0, 0.08, Z(c.y) + Math.sin(a) * 1.0], scale: 0.2,
                           color:'#0a2a12', emissive:'#39ff14', emissiveStrength: lit ? 1.6 : 0.1 });
      }
      r.light({ pos:[X(c.x), 1.6, Z(c.y)], color: S.multiball ? '#ffd700' : '#39ff14', intensity: 16 + (f ? 60 : 0) + pulse * 10, range: 5 });
    }
    // ── BUMPERS ──
    for(const bp of T.bumpers){
      const f = Math.min(1, bp.flash / 0.2), rr = bp.r * U * 2;
      r.draw('cylinder', { pos:[X(bp.x), 0.28, Z(bp.y)], scale:[rr, 0.56, rr], color:'#2a0628', metallic: 0.55, roughness: 0.3, rim: 1,
                           emissive:'#ff2bd6', emissiveStrength: 0.35 + f * 0.9 });
      r.draw('thintorus', { pos:[X(bp.x), 0.6, Z(bp.y)], scale: (bp.r * U) / 0.45 * 1.05, color:'#ffffff', emissive:'#ff2bd6', emissiveStrength: 1.1 + f * 1.6 });
      r.draw('sphere', { pos:[X(bp.x), 0.6, Z(bp.y)], scale:[rr * 0.72, 0.28, rr * 0.72], color:'#ffb8f2', emissive:'#ff2bd6', emissiveStrength: 0.5 + f * 1.4 });
      if(f > 0) r.light({ pos:[X(bp.x), 1.3, Z(bp.y)], color:'#ff2bd6', intensity: 80 * f, range: 5 });
    }
    // ── FLIPPERS ──
    for(const fl of T.flippers){
      const tip = sim.flipperTip(fl);
      const a = Math.atan2(tip.ty - fl.py, tip.tx - fl.px);
      const cx = (fl.px + tip.tx) / 2, cy = (fl.py + tip.ty) / 2;
      const len = (fl.len + fl.r0 + fl.r1) * U;
      r.draw('pill', { pos:[X(cx), 0.2, Z(cy)], rot:[0, -a, 0], scale:[len, 0.36, fl.r0 * U * 2],
                       color:'#dfe9f7', metallic: 0.72, roughness: 0.22, rim: 1.0, emissive: me, emissiveStrength: fl.held ? 0.35 : 0.12 });
      r.draw('box', { pos:[X(cx), 0.4, Z(cy)], rot:[0, -a, 0], scale:[len * 0.8, 0.03, 0.12],
                      color:'#ffffff', emissive:'#00f5ff', emissiveStrength: fl.held ? 2.0 : 1.0 });
      r.draw('cylinder', { pos:[X(fl.px), 0.25, Z(fl.py)], scale:[0.24, 0.5, 0.24], color:'#0a1230', metallic: 0.8, roughness: 0.3 });
    }
    // ── THE PLUNGER ──
    r.draw('cylinder', { pos:[X(333), 0.28, Z(716 + S.charge * 14)], rot:[Math.PI / 2, 0, 0], scale:[0.36, 1.1, 0.36],
                         color:'#cfd9ea', metallic: 0.8, roughness: 0.25, emissive: S.charging ? '#ffd700' : '#00f5ff', emissiveStrength: S.charging ? 0.9 : 0.25 });
    // ── BALLS ──
    let lights = 0;
    for(const b of sim.balls){
      r.draw('sphere', { pos:[X(b.x), 0.4, Z(b.y)], scale: PB.BALL_R * U * 2, color:'#e8eef8', metallic: 0.72, roughness: 0.16, rim: 1.1,
                         emissive:'#9fe6ff', emissiveStrength: 0.08 });
      // A small lamp rides over each ball in play (not one parked on the
      // plunger: beside the lane's chrome walls it bloomed into a glare).
      if(!b.lane && lights++ < 2) r.light({ pos:[X(b.x), 2.0, Z(b.y)], color:'#bfefff', intensity: 20, range: 4.5 });
    }
    r.light({ pos:[-9, 14, -10], color:'#ff4dd8', intensity: 260, range: 60 });
    r.light({ pos:[ 9, 14,  12], color:'#4d8bff', intensity: 240, range: 60 });
    w.end();
  });
};

})();

// <<OW:BEGIN>> — § 31 open worlds, spliced from the v56 sources


// ══════════════════════════════════════════════════════════════════════
//  § 31 · v56 — 🌐 OPEN WORLD · every mission, no borders
// ══════════════════════════════════════════════════════════════════════
// Every mission in the arcade has a second way to be played: an OPEN WORLD.
// The classic round is a board — a rectangle, a corridor, a well — and the
// open world is the same verb with the edges taken away: the neon nebula is a
// sky you can fly into in any direction, the snake has a whole plain, the
// light cycle an infinite grid, the maze never runs out. Content is generated
// around the player as they move (deterministic chunks, so the place you left
// is still there when you turn back), the camera follows them, and nothing
// ever says "you have reached the edge".
//
// It is a LANE, the way ♾️ Endless is: one pseudo-mission id (`openworld`)
// carries the results card, the award and the shared high score, and each
// mission's own best lives at players/<uid>/openworld/<gid> — a new CHILD key,
// which the live rules accept under `players/$uid/$other`, so no rules change
// and no new top-level node. The open worlds are 3D-only by nature: in 2D mode
// the round still mounts the GL surface for itself, because a world with no
// edges is not something a fixed 2D board can show.
//
// ⚠️ `var` for everything other sections read: enterHub(), the card handler
// and the gamepad poll all sit far above this line in the file.
var owRun = null;                 // { gid, t0 } while an open-world round is up
var OW_CAP = 3000;                // the results card's 100% — fanfare at 75%
var OW_GRID_KEY = 'pi_ow_grid';   // '1' when the mission grid launches open worlds

// What each mission's open world IS — one line for the picker, the briefing
// toast, and the hint under the board.
var OW_INFO = {
  click:      { tag: 'Reactor cores drift through an endless sky-dock — dive at each one and overload it before it vents.' },
  nebula:     { tag: 'Free flight through an endless asteroid belt — hunt raider squadrons and gut capital frigates.' },
  tetris:     { tag: 'A well with no walls: blocks fall on an endless floor, and any ten in a row clear.' },
  dodge:      { tag: 'An open plain under a bombardment — outlast the clock for the full cap; grab the energy, stay alive.' },
  memory:     { tag: 'Monoliths stand all over an endless field. Flip one, remember WHERE, find its twin.' },
  math:       { tag: 'Answer gates float in an open sky — read the sum, fly through the right number.' },
  reaction:   { tag: 'Beacons ignite anywhere around you — turn, burn, and reach each one before it dies.' },
  pong:       { tag: 'A rally with no walls — the ball can go anywhere, so you have to be there.' },
  snake:      { tag: 'An endless plain and a worm that never stops growing. No walls — only your own tail.' },
  flappy:     { tag: 'An endless field of pylons and rings, and you can fly around them in every direction.' },
  breaker:    { tag: 'A ceiling of bricks that never ends and no walls to bank off — chase the ball.' },
  arena:      { tag: 'A battlefield with no edge. Waves close in from every side; you pick where to fight.' },
  runner:     { tag: 'No lanes, no highway — an endless neon plain to carve across at full speed.' },
  hacker:     { tag: 'Network nodes scattered to the horizon — reach them in sequence before the trace closes.' },
  meteor:     { tag: 'Defend a station adrift in open space — meteors come from every direction now.' },
  battlebots: { tag: 'Siege across an open battlefield — deploy anywhere, burn every enemy outpost.' },
  path:       { tag: 'Lay power cable across an endless board — power 20 relays to complete the circuit (the full cap); every relay overclocks the grid.' },
  freq:       { tag: 'Radio towers across an endless dark — drive into range and tune each one in.' },
  rhythm:     { tag: 'Beat gates on an open plain — steer through each on the pulse, anywhere ahead.' },
  merge:      { tag: 'You ARE a core. Absorb your equals, double up, and never touch anything bigger.' },
  uplink:     { tag: 'A mobile launcher on endless terrain — lob shells onto targets at any range.' },
  cutter:     { tag: 'A facility with no outer wall — slip between patrols to every data cache.' },
  sorter:     { tag: 'Packets scatter across the plain — scoop each one and haul it to its own tower.' },
  trace:      { tag: 'A hidden transmitter somewhere out there — read the signal and run it down.' },
  defrag:     { tag: 'Fragments of corrupted files litter the volume — rebuild each file by colour.' },
  coolant:    { tag: 'Reactors overheating across the city — reach each one and vent it before it blows.' },
  lightcycle: { tag: 'The grid goes on forever — no walls, only light trails and rival riders.' },
  stack:      { tag: 'A tower in an open city — slabs swing in from every compass point.' },
  muncher:    { tag: 'A maze that never ends — eat your way out while the ghosts close in.' },
  cmdline:    { tag: 'Rogue processes roam an open grid — drive up and type them dead.' },
  pinball:    { tag: 'An endless table that falls forever — your flippers ride with the ball.' }
};

function owActive(){ return !!owRun; }
// While an open-world round is on the board, the controller is read directly
// (analog sticks, triggers) by the round itself, so the arcade's virtual
// pointer and synthetic arrow keys stand down — see padPoll().
function owPadOwns(){
  return !!owRun && !!document.getElementById('game-screen')?.classList.contains('active') &&
         !document.querySelector('.fb-overlay.show');
}
function owGridOn(){ try{ return localStorage.getItem(OW_GRID_KEY) === '1'; }catch(e){ return false; } }
function owSetGrid(on){
  try{ localStorage.setItem(OW_GRID_KEY, on ? '1' : '0'); }catch(e){}
  owPaintGrid();
}
function owPaintGrid(){
  const on = owGridOn();
  document.querySelector('.games-grid')?.classList.toggle('ow-mode', on);
  document.querySelectorAll('#ow-switch .ow-seg').forEach(b => {
    const mine = (b.dataset.owm === 'open') === on;
    b.classList.toggle('on', mine);
    b.setAttribute('aria-selected', String(mine));
  });
  document.querySelectorAll('.games-grid .game-card[data-game]').forEach(card => {
    let tag = card.querySelector('.gc-ow');
    if(!tag){
      tag = document.createElement('span');
      tag.className = 'gc-ow';
      tag.textContent = '🌐 OPEN WORLD';
      card.appendChild(tag);
    }
    const has = !!(window.PI3D && PI3D.hasOW && PI3D.hasOW(card.dataset.game));
    card.classList.toggle('ow-none', on && !has);
  });
}

function startOpenWorld(gid){
  if(!user || !META[gid] || !SOLO_START[gid]) return;
  if(typeof missionUnlocked === 'function' && !missionUnlocked(gid)){
    snd('deny');
    toast(`🔒 ${META[gid].name} needs CLEARANCE ${missionClearance(gid)} — open worlds unlock with their missions.`, 3200);
    return;
  }
  if(!(window.PI3D && PI3D.supported())){
    snd('deny');
    toast('🌐 Open worlds are 3D — this browser has no WebGL2.', 3400);
    return;
  }
  if(!PI3D.hasOW || !PI3D.hasOW(gid)){
    snd('deny');
    toast('🌐 ' + META[gid].name + ' has no open world on this build.', 3000);
    return;
  }
  if((typeof bossRush !== 'undefined' && bossRush) || (typeof mp !== 'undefined' && mp) ||
     (typeof endless !== 'undefined' && endless) || (typeof dailyActive !== 'undefined' && dailyActive)){
    snd('deny');
    return;
  }
  owRun = { gid, t0: Date.now() };
  owLane = null;
  if(window.PI3D) PI3D.owSalt = 0;
  curGame = gid;
  document.getElementById('g-title').textContent = '🌐 ' + META[gid].name + ' · OPEN WORLD';
  showScreen('game-screen');
  snd('success');
  owPrep(gid);
}

function owPrep(gid){
  resetGameStage(gid);
  document.getElementById('game-screen').classList.add('canvas-game');
  if(typeof chaos === 'object' && chaos){ chaos.pending = []; }
  const info = OW_INFO[gid];
  if(info) toast('🌐 ' + info.tag, 4200);
  countdown(() => {
    if(!owRun || owRun.gid !== gid) return;
    let ok = false;
    runMissionStart(() => { ok = !!(window.PI3D && PI3D.startOW(gid)); });
    if(!ok){
      owRun = null;
      toast('🌐 That open world failed to load — back to the hub.', 3200);
      enterHub();
      return;
    }
    // ⚡ v60 · The consumable kit, as every other round has it. The dock was
    // never shown out here, so a Time Dilator or a Shield Overlay bought for
    // the arcade simply did not exist in its biggest lane.
    try{ showPowerDock(); }catch(e){ console.warn('Power dock failed:', e); }
    try{ if(typeof statsEvent === 'function') statsEvent('_ow_' + gid); }catch(e){}
  });
}

// The cap an open world's score is held to: its mission's own, the same
// ceiling the 2D and 3D builds pay up to. Cyber Arena's "no ceiling" stays one.
function owCapFor(gid){ return (META[gid] && META[gid].maxPts) || OW_CAP; }

// Every open world ends here: its raw score, its breakdown rows.
//
// 📏 v60 · Held to the MISSION'S cap. An open world used to bank whatever it
// counted up to (a 400-point Reaction Time could pay 3,000 out here), which
// made the borderless lane the place to farm. The world's own count is kept —
// past the cap it is what breaks a tie between two capped runs (capRaw).
function owFinish(gid, raw, bd){
  const run = owRun;
  const full = Math.max(0, Math.round(+raw || 0));
  const cap = owCapFor(gid);
  const pts = cap < 90000 ? capRaw(cap, full) : (noteRawScore(full), full);
  owRun = null;
  bd = { ...(bd || {}) };
  if(full > pts) bd['🏆 Score'] = pts.toLocaleString() + ' PTS · capped at ' + cap.toLocaleString();
  // 🌐 A round a MODE started (Boss Rush, a campaign chapter, the Daily Hack…)
  // reports as its mission, so the mode's own seam — a stage tap, the daily
  // board, a chapter's stars — takes it exactly as it takes a classic round.
  if(run && run.lane){
    showResults(gid, pts, bd, { ow: true, name: '🌐 ' + META[gid].name + ' · OPEN WORLD' });
    return;
  }
  try{ recordLaneBest('openworld', gid, pts); }catch(e){ console.warn('Open world best not stored:', e); }
  showResults('openworld', pts, bd, {
    cap: cap < 90000 ? cap : OW_CAP,
    capGid: gid,
    emoji: '🌐',
    name: 'OPEN WORLD · ' + META[gid].name,
    badge: { text: '🌐 OPEN WORLD · NO BORDERS', cls: 'res-bonus-ow' },
    noChaosPay: true,
    ow: true,
    again: { label: '🌐 Play Again', fn: () => startOpenWorld(gid) },
    hub: { label: 'Hub', fn: () => enterHub() }
  });
}

function abortOpenWorld(){
  owRun = null;
  owLane = null;
  if(window.PI3D) PI3D.owSalt = 0;
}

// ══════════════════════════════════════════════
//  🌐 v60 · THE MODES' OPEN-WORLD LANES
// ══════════════════════════════════════════════
// Every mode that plays mission rounds — the campaign, the Network Arena's
// score races, Boss Rush, a party, a Brick Lab test run, the Daily Hack, the
// Endless Protocol and the Weekly Anomaly — can play them in the missions'
// open worlds. Each mode's banner carries its own ▶ CLASSIC / 🌐 OPEN WORLD
// switch (per device, like the grid's); a mode arms its lane as it starts
// (owLaneArm), and every round it starts goes through startMissionRound(),
// which plays the world instead of the classic build.
//
// A world reports through owFinish(), which hands its score — held to the
// mission's cap — to showResults() AS THE MISSION. So the mode's own seam takes
// it unchanged: a Boss Rush stage tap, the Daily board, a chapter's stars, a
// race's bank. Medals stay the classic builds' (settleMedal), and the pace
// ghost is not raced (it is a classic curve).
//
// The lane is only honoured while its mode is actually running (owLaneLive),
// so a lane can never leak into the next solo round. A mission with no world
// on this build plays classic inside an open-world run.
var owLane = null;
// 🧊 The running mode and the way it plays: '2d' (classic), '3d' or 'open'.
var laneMode = null, laneKind = null;
var OW_LANES_KEY = 'pi_ow_lanes';
var OW_LANE_NAMES = { campaign: 'CAMPAIGN', arena: 'NETWORK ARENA', bossrush: 'BOSS RUSH', party: 'PARTY MODE',
                      lab: 'BRICK LAB', daily: 'DAILY HACK', endless: 'ENDLESS PROTOCOL', anomaly: 'WEEKLY ANOMALY' };
function owLanePrefs(){
  try{ const o = JSON.parse(localStorage.getItem(OW_LANES_KEY) || '{}'); return (o && typeof o === 'object') ? o : {}; }
  catch(e){ return {}; }
}
// The way a mode plays on this device. Unset, it follows the arcade's 2D/3D
// setting. (v60's first cut stored 1 / 0 for open / classic.)
function laneKindPref(mode){
  const v = owLanePrefs()[mode];
  if(v === 'open' || v === 1) return 'open';
  if(v === '3d' || v === '2d') return v;
  return (window.PI3D && PI3D.wanted && PI3D.wanted() === '3d') ? '3d' : '2d';
}
function owLanePref(mode){ return laneKindPref(mode) === 'open'; }
function owSetLaneKind(mode, kind){
  const o = owLanePrefs();
  o[mode] = kind;
  try{ localStorage.setItem(OW_LANES_KEY, JSON.stringify(o)); }catch(e){}
  owPaintLanes();
}
function owWorldsOk(){ return !!(window.PI3D && PI3D.supported && PI3D.supported() && PI3D.startOW); }
function gl3dOk(){ return !!(window.PI3D && PI3D.supported && PI3D.supported()); }
// A mode arms its lane as it starts: from its banner's switch, or `on` when
// the choice was made elsewhere (a Network Arena room carries its host's).
function owLaneArm(mode, on){
  let kind = laneKindPref(mode);
  if(on === true) kind = 'open';
  else if(on === false && kind === 'open') kind = (window.PI3D && PI3D.wanted && PI3D.wanted() === '3d') ? '3d' : '2d';
  if(kind === 'open' && !owWorldsOk()) kind = '2d';
  laneMode = mode; laneKind = kind;
  owLane = kind === 'open' ? mode : null;
  try{ if(window.PI3D && PI3D.syncBody) PI3D.syncBody(); }catch(e){}
  return !!owLane;
}
function laneLive(mode){
  switch(mode){
    case 'daily':    return !!dailyActive;
    case 'bossrush': return !!bossRush;
    case 'endless':  return !!endless;
    case 'anomaly':  return !!anomalyActive;
    case 'party':    return typeof partyRunActive === 'function' && partyRunActive();
    case 'lab':      return typeof labRun !== 'undefined' && !!labRun;
    case 'campaign': return typeof campaignRunActive === 'function' && campaignRunActive();
    case 'arena':    return !!mp;
  }
  return false;
}
function owLaneLive(){ return !!owLane && laneLive(owLane); }
// The renderer asks this for every round (PI3D.is3D): the running mode's own
// 2D / 3D choice, or nothing (the arcade's setting).
if(window.PI3D) PI3D.modeOverride = () => {
  if(!laneMode || !laneLive(laneMode)) return null;
  return laneKind === '3d' ? '3d' : laneKind === '2d' ? '2d' : null;
};
// True when THIS round of the running mode is the mission's open world.
function owLaneFor(gid){
  return !!owLane && owLaneLive() && !!(window.PI3D && PI3D.hasOW && PI3D.hasOW(gid));
}
// The one start a mode's round goes through: the open world when its lane is
// on, else the 3D build, else 2D. Returns true when a world started.
function startMissionRound(gid){
  try{ if(window.PI3D && PI3D.syncBody) PI3D.syncBody(); }catch(e){}
  if(owLaneFor(gid)){
    owRun = { gid, t0: Date.now(), lane: owLane };
    document.getElementById('game-screen').classList.add('canvas-game');
    const t = document.getElementById('g-title');
    if(t && t.textContent.indexOf('🌐') < 0) t.textContent = '🌐 ' + t.textContent;
    let ok = false;
    try{ ok = !!PI3D.startOW(gid); }catch(e){ console.warn('Open world start failed:', e); ok = false; }
    if(ok){
      const info = OW_INFO[gid];
      if(info) toast('🌐 ' + info.tag, 3200);
      try{ if(typeof statsEvent === 'function') statsEvent('_ow_' + gid); }catch(e){}
      return true;
    }
    owRun = null;
    toast('🌐 That open world failed to load — playing the classic round.', 2600);
  }else owRun = null;
  if(!(window.PI3D && PI3D.startFor(gid))) SOLO_START[gid]();
  return false;
}
// A run's worlds are laid out from this salt (see makeField): the Daily Hack
// and a party turn set it from their seeds, so every operative on the day — or
// every player at the party — rides the same world.
function owSaltFrom(n){ if(window.PI3D) PI3D.owSalt = (n | 0) & 0x7fffffff; }

// The switches on the mode banners: ▶ 2D CLASSIC · 🧊 3D · 🌐 OPEN WORLD.
function owPaintLanes(){
  const okOW = owWorldsOk(), ok3 = gl3dOk();
  document.querySelectorAll('.lane-pick[data-lane]').forEach(box => {
    let kind = laneKindPref(box.dataset.lane);
    if(kind === 'open' && !okOW) kind = '2d';
    if(kind === '3d' && !ok3) kind = '2d';
    box.classList.toggle('no-ow', !okOW);
    box.querySelectorAll('.lp-seg').forEach(b => {
      const v = b.dataset.v === 'classic' ? '2d' : b.dataset.v;
      const mine = v === kind;
      b.classList.toggle('on', mine);
      b.setAttribute('aria-pressed', String(mine));
    });
    box.closest('.mp-banner')?.classList.toggle('lane-ow', kind === 'open');
  });
}
document.querySelectorAll('.lane-pick[data-lane] .lp-seg').forEach(b => b.addEventListener('click', ev => {
  ev.stopPropagation();
  const box = b.closest('.lane-pick'), mode = box.dataset.lane;
  const kind = b.dataset.v === 'classic' ? '2d' : b.dataset.v;
  if(kind === 'open' && !owWorldsOk()){ snd('deny'); toast('🌐 Open worlds are 3D — this browser has no WebGL2.', 3000); return; }
  if(kind === '3d' && !gl3dOk()){ snd('deny'); toast('🧊 This browser has no WebGL2 — 3D cannot run here.', 3000); return; }
  if(kind === laneKindPref(mode) && owLanePrefs()[mode] != null) return;
  owSetLaneKind(mode, kind);
  snd('tab');
  const name = OW_LANE_NAMES[mode] || mode.toUpperCase();
  toast(kind === 'open' ? '🌐 ' + name + ' — every round plays in its open world'
                          + (mode === 'arena' ? ' (score races only)' : '')
      : kind === '3d' ? '🧊 ' + name + ' — every round plays in 3D'
      : '▶ ' + name + ' — the classic 2D missions', 2600);
}));
try{ owPaintLanes(); }catch(e){}


// Wiring. Optional-chained: an older cached index.html has none of these.
// 🌐 v60 · No OPEN WORLD banner any more: the grid's ▶ CLASSIC / 🌐 OPEN WORLD
// switch launches a mission's world, and each mode's banner has its own.
document.querySelectorAll('#ow-switch .ow-seg').forEach(b => b.addEventListener('click', () => {
  const on = b.dataset.owm === 'open';
  if(on === owGridOn()) return;
  owSetGrid(on);
  snd('tab');
  toast(on ? '🌐 OPEN WORLD — every card now launches its world with no borders'
           : '▶ CLASSIC — the original missions', 2400);
}));
try{ owPaintGrid(); }catch(e){}


// ══════════════════════════════════════════════════════════════════════
//  🌐 OPEN WORLD · THE KIT — what every borderless world is built from
// ══════════════════════════════════════════════════════════════════════
// Thirty-one worlds is thirty-one games, so everything they share lives here
// and each world is only its own rules:
//   · INPUT   one set of virtual controls (steer, fire, alt, boost …) fed by
//             the keyboard, the mouse (aim by pointing), a touch stick and
//             touch buttons, and the controller's ANALOG sticks and triggers
//   · HUD     a canvas over the board: radar, brackets on targets, arrows to
//             what is off-screen, lock-on, bars, the touch controls
//   · FIELD   a deterministic chunked world generated around the player and
//             forgotten behind them — but what you destroyed stays destroyed
//   · CAMERA  chase rigs (the floating origin rides the camera)
//   · FX      explosions with fireball, debris, smoke and shockwave; sparks;
//             speed dust; engine plumes
//   · SET     an endless lit ground, procedural towers, distant bodies
(function(){
'use strict';

const P = window.PI3D;
if(!P) return;
const K = P.kit;
const E = window.PI3D_ENGINE;
const { begin3d, runLoop, mine, clamp, seeded } = K;

// ── REGISTRY ──
P.ow = Object.create(null);
P.hasOW = gid => !!P.ow[gid];
// Like startFor(), but for the open-world build and regardless of the 2D/3D
// setting: an open world needs WebGL2, not the player's renderer choice.
P.startOW = function(gid){
  const fn = P.ow[gid];
  if(!fn || !P.supported()) return false;
  try{
    fn();
    return true;
  }catch(err){
    P.lastOWError = String((err && (err.stack || err.message)) || err);
    console.error('[OW] open world failed to start: ' + P.lastOWError);
    try{ stopGame(); }catch(e){}
    try{ P.unmount(); }catch(e){}
    return false;
  }
};

// ── VECTORS ── plain arrays; the worlds are small enough that clarity wins.
const V = {
  add: (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]],
  sub: (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]],
  mul: (a, k) => [a[0] * k, a[1] * k, a[2] * k],
  madd: (a, b, k) => [a[0] + b[0] * k, a[1] + b[1] * k, a[2] + b[2] * k],
  dot: (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2],
  cross: (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]],
  len: a => Math.hypot(a[0], a[1], a[2]),
  norm: a => { const l = Math.hypot(a[0], a[1], a[2]) || 1; return [a[0] / l, a[1] / l, a[2] / l]; },
  lerp: (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t],
  d2: (a, b) => { const x = a[0] - b[0], y = a[1] - b[1], z = a[2] - b[2]; return x * x + y * y + z * z; },
  copy: a => [a[0], a[1], a[2]]
};
const TAU = Math.PI * 2;
const wrapAng = a => { while(a > Math.PI) a -= TAU; while(a < -Math.PI) a += TAU; return a; };
// Frame-rate independent approach: the share of the remaining gap closed in dt
// for a given half-life.
const ease = (dt, half) => 1 - Math.pow(0.5, dt / Math.max(1e-4, half));
const ihash = (x, y, z, s) => {
  let h = (Math.imul(x | 0, 73856093) ^ Math.imul(y | 0, 19349663) ^ Math.imul(z | 0, 83492791) ^ Math.imul(s | 0, 2654435761)) >>> 0;
  h ^= h >>> 13; h = Math.imul(h, 1274126177) >>> 0; h ^= h >>> 16;
  return h >>> 0;
};

// Model basis from heading (yaw about world up, 0 = −Z), pitch (up +) and a
// bank about the nose (right wing down +). Returned as the three columns
// draw({ m3 }) wants for a model whose nose is −Z: right, up, back.
function basisYPR(yaw, pitch, bank){
  const cp = Math.cos(pitch), sp = Math.sin(pitch), cy = Math.cos(yaw), sy = Math.sin(yaw);
  const f = [-sy * cp, sp, -cy * cp];
  const r0 = [cy, 0, -sy];
  const u0 = V.cross(r0, f);
  const cb = Math.cos(bank), sb = Math.sin(bank);
  const r = [r0[0] * cb - u0[0] * sb, r0[1] * cb - u0[1] * sb, r0[2] * cb - u0[2] * sb];
  const u = [u0[0] * cb + r0[0] * sb, u0[1] * cb + r0[1] * sb, u0[2] * cb + r0[2] * sb];
  return { f, r, u, m3: [r[0], r[1], r[2], u[0], u[1], u[2], -f[0], -f[1], -f[2]] };
}
// A model basis that points a +Z-nosed model (the raider) along `fwd`.
function basisLook(fwd, upHint, bank){
  const f = V.norm(fwd);
  let r = V.cross(f, upHint || [0, 1, 0]);
  if(V.len(r) < 1e-4) r = [1, 0, 0];
  r = V.norm(r);
  let u = V.cross(r, f);
  if(bank){
    const cb = Math.cos(bank), sb = Math.sin(bank);
    const r2 = V.sub(V.mul(r, cb), V.mul(u, sb)), u2 = V.add(V.mul(u, cb), V.mul(r, sb));
    r = r2; u = u2;
  }
  return { f, r, u, m3: [r[0], r[1], r[2], u[0], u[1], u[2], -f[0], -f[1], -f[2]],
           m3z: [-r[0], -r[1], -r[2], u[0], u[1], u[2], f[0], f[1], f[2]] };
}

// ── ✈️ ATTITUDE ── v57 · a free orientation, so a craft can fly a full loop.
// The flying worlds used to steer by two ANGLES, yaw about world up and a
// pitch clamped short of vertical, and the clamp was not a design choice: at
// ±90° "yaw about world up" stops meaning anything (the nose IS world up), so
// the pair has a pole there and the stick had to be stopped before reaching it.
// An attitude is a unit quaternion [x, y, z, w] instead, turned about the
// craft's OWN axes (yaw about its up, pitch about its wings), so a held stick
// carries the nose through the vertical, over the top and all the way round.
// basisQ() turns it into the same { f, r, u, m3 } basisYPR() gives, so the
// model, the guns and the chase camera read their axes exactly as before, and
// the camera's up rides the craft's, which is what keeps the view from flipping.
//
// Two gentle assists keep a world with a horizon readable without fighting a
// manoeuvre: attLevelRoll() brings the wings back level once the pitch stick is
// let go (let go upside down at the top of a loop and that is an Immelmann),
// and attElevate() is how a world that wants it eases the nose to the horizon.
// Both fade out as the nose nears vertical, where "level" has no direction.
const QT = {
  mul: (a, b) => [
    a[3] * b[0] + a[0] * b[3] + a[1] * b[2] - a[2] * b[1],
    a[3] * b[1] - a[0] * b[2] + a[1] * b[3] + a[2] * b[0],
    a[3] * b[2] + a[0] * b[1] - a[1] * b[0] + a[2] * b[3],
    a[3] * b[3] - a[0] * b[0] - a[1] * b[1] - a[2] * b[2]
  ],
  axis: (ax, ang) => { const s = Math.sin(ang / 2); return [ax[0] * s, ax[1] * s, ax[2] * s, Math.cos(ang / 2)]; },
  norm: q => { const l = Math.hypot(q[0], q[1], q[2], q[3]) || 1; return [q[0] / l, q[1] / l, q[2] / l, q[3] / l]; },
  // v rotated by q.
  rot: (q, v) => {
    const x = q[0], y = q[1], z = q[2], w = q[3];
    const tx = 2 * (y * v[2] - z * v[1]), ty = 2 * (z * v[0] - x * v[2]), tz = 2 * (x * v[1] - y * v[0]);
    return [v[0] + w * tx + (y * tz - z * ty), v[1] + w * ty + (z * tx - x * tz), v[2] + w * tz + (x * ty - y * tx)];
  }
};
const NOSE = [0, 0, -1], WING = [1, 0, 0], TOP = [0, 1, 0];
// The attitude basisYPR(yaw, pitch, 0) describes.
const attFrom = (yaw, pitch) => QT.mul(QT.axis(TOP, yaw || 0), QT.axis(WING, pitch || 0));
// Heading (0 = −Z, + = left: the yaw the angle pair used) and elevation of a nose.
const yawOf = f => Math.atan2(-f[0], -f[2]);
const elevOf = f => Math.asin(clamp(f[1], -1, 1));
// One frame of body rates (rad/s): yaw about the craft's up, pitch about its
// right wing, applied together as one rotation so the order cannot matter.
function attTurn(q, yawRate, pitchRate, dt){
  const wx = pitchRate * dt, wy = yawRate * dt, a = Math.hypot(wx, wy);
  return a < 1e-9 ? q : QT.norm(QT.mul(q, QT.axis([wx / a, wy / a, 0], a)));
}
// A world-frame turn of the whole attitude by `ang` about the unit axis `ax`.
const attSpin = (q, ax, ang) => (ang ? QT.norm(QT.mul(QT.axis(ax, ang), q)) : q);
// Rolls the wings toward level by the share k of the error. The horizon only
// gives a direction while the nose is off vertical, so the pull fades to
// nothing within ~6° of straight up or down.
function attLevelRoll(q, k){
  const f = QT.rot(q, NOSE), u = QT.rot(q, TOP);
  // World up with its component along the nose removed: the up a level craft
  // pointing this way would have.
  let ux = -f[0] * f[1], uy = 1 - f[1] * f[1], uz = -f[2] * f[1];
  const l = Math.hypot(ux, uy, uz);
  const fade = clamp((l - 0.1) / 0.4, 0, 1);
  if(fade <= 0 || !k) return q;
  ux /= l; uy /= l; uz /= l;
  const cx = u[1] * uz - u[2] * uy, cy = u[2] * ux - u[0] * uz, cz = u[0] * uy - u[1] * ux;
  const ang = Math.atan2(cx * f[0] + cy * f[1] + cz * f[2], u[0] * ux + u[1] * uy + u[2] * uz);
  return attSpin(q, f, ang * k * fade);
}
// Moves the nose's elevation the share k of the way to `el`, straight up or
// down through the vertical plane it is in, whatever the roll.
function attElevate(q, el, k){
  const f = QT.rot(q, NOSE);
  let ax = [-f[2], 0, f[0]];                      // nose × world up: turning about it raises the nose
  let l = Math.hypot(ax[0], ax[2]);
  if(l < 1e-4){ ax = QT.rot(q, WING); l = 1; }
  return attSpin(q, [ax[0] / l, ax[1] / l, ax[2] / l], (el - elevOf(f)) * k);
}
// Points the nose along `nf` by the smallest turn that does it (a bounce).
function attFace(q, nf){
  const f = QT.rot(q, NOSE);
  const c = V.cross(f, nf), s = V.len(c), d = V.dot(f, nf);
  if(s < 1e-6){
    if(d > 0) return q;
    return attSpin(q, Math.abs(f[1]) < 0.95 ? TOP : QT.rot(q, WING), Math.PI);
  }
  return attSpin(q, [c[0] / s, c[1] / s, c[2] / s], Math.atan2(s, d));
}
// The model basis for an attitude, with an optional bank about the nose (right
// wing down +), in basisYPR()'s shape: m3 is right, up, back for a −Z nose.
function basisQ(q, bank){
  const qq = bank ? QT.mul(q, QT.axis(NOSE, bank)) : q;
  const r = QT.rot(qq, WING), u = QT.rot(qq, TOP), b = QT.rot(qq, [0, 0, 1]);
  return { f: [-b[0], -b[1], -b[2]], r, u, m3: [r[0], r[1], r[2], u[0], u[1], u[2], b[0], b[1], b[2]] };
}

// ══════════════════════════════════════════════
//  🎮 INPUT
// ══════════════════════════════════════════════
// One poll a frame turns every device into the same virtual controls:
//   ax, ay    steer (−1..1; ay is SCREEN-down positive, so "up" is −1)
//   lx, ly    the raw move axes (keys + stick + left pad stick) without the mouse
//   aimX/Y    the mouse / right stick aim point, −1..1 from the board centre
//   fire      held; altHit / jumpHit edge presses; boost, brake held
// Keys a world wants for itself arrive through opts.onKey.
//
// Synthetic events (isTrusted false) are IGNORED: they come from the arcade's
// own gamepad poll, which this round reads directly instead — with analog
// sticks — and stands down while an open world owns the pad (owPadOwns()).
const GAME_KEYS = new Set(['Space', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'KeyW', 'KeyA', 'KeyS', 'KeyD',
  'KeyQ', 'KeyE', 'KeyF', 'KeyR', 'KeyX', 'KeyC', 'KeyZ', 'KeyV', 'ShiftLeft', 'ShiftRight', 'ControlLeft', 'ControlRight', 'Enter', 'Tab']);
function makeInput(opts){
  opts = opts || {};
  const frozen = () => ((typeof photoActive === 'function') && photoActive()) || ((typeof pauseActive === 'function') && pauseActive());
  const st = {
    keys: Object.create(null), hit: Object.create(null),
    mx: 0, my: 0, mouseOn: false, mDown: false, mRight: false, mRightHit: false, mouseAt: 0,
    stick: null, aimStick: null, tFire: false, tAlt: false, tBoost: false, tAltHit: false, tJumpHit: false, tAbilHit: false,
    // ⚡ v60 · abilOn: the world banks specials (makeSpecials), so the ⚡ touch
    // button exists; abilHit: V, the left bumper or that button, this frame.
    abilOn: false, abilHit: false,
    pad: null, padPrev: {},
    ax: 0, ay: 0, lx: 0, ly: 0, aimX: 0, aimY: 0, aimOn: false, fire: false, boost: false, brake: false, roll: 0,
    altHit: false, jumpHit: false, device: isTouchDevice ? 'touch' : 'keys',
    touchCfg: opts.touch || 'fly'
  };
  const offs = [];
  const on = (t, type, fn, o) => { t.addEventListener(type, fn, o || { passive: false }); offs.push(() => t.removeEventListener(type, fn, o || { passive: false })); };

  window.onkeydown = e => {
    if(!e.isTrusted) return;
    if(GAME_KEYS.has(e.code)) e.preventDefault();
    if(frozen()) return;
    if(!st.keys[e.code]) st.hit[e.code] = true;
    st.keys[e.code] = true;
    st.device = 'keys';
    if(opts.onKey) opts.onKey(e);
  };
  window.onkeyup = e => { if(!e.isTrusted) return; st.keys[e.code] = false; };

  const cv = aCanvas;
  const rel = (cx, cy) => {
    const r = cv.getBoundingClientRect();
    return [((cx - r.left) / Math.max(1, r.width)) * 2 - 1, ((cy - r.top) / Math.max(1, r.height)) * 2 - 1, r];
  };
  if(cv){
    on(cv, 'mousemove', e => {
      if(!e.isTrusted) return;
      const [x, y] = rel(e.clientX, e.clientY);
      st.mx = clamp(x, -1, 1); st.my = clamp(y, -1, 1);
      st.mouseOn = true; st.mouseAt = performance.now();
      st.device = 'mouse';
    });
    on(cv, 'mouseleave', () => { st.mouseOn = false; });
    on(cv, 'mousedown', e => {
      if(!e.isTrusted || frozen()) return;
      e.preventDefault();
      if(e.button === 2){ st.mRight = true; st.mRightHit = true; } else st.mDown = true;
      st.device = 'mouse';
    });
    on(window, 'mouseup', e => { if(e.button === 2) st.mRight = false; else st.mDown = false; });
    on(cv, 'contextmenu', e => e.preventDefault());
    // ── TOUCH ── left half: a stick born where the thumb lands. Right half:
    // FIRE by default, with ALT and BOOST buttons (see HUD.touchPad for the
    // layout, which is shared so what is drawn is what is pressed). 'twin'
    // turns the right half into an aim stick that fires while held.
    const btnAt = (u, v) => {
      const B = touchButtons(st.touchCfg, st.abilOn);
      for(const b of B){ if(Math.hypot((u - b.u) * 1.0, (v - b.v) * (cv.clientHeight / Math.max(1, cv.clientWidth))) < b.r) return b.k; }
      return null;
    };
    on(cv, 'touchstart', e => {
      if(frozen()) return;
      e.preventDefault();
      st.device = 'touch';
      for(const t of e.changedTouches){
        const [x, y] = rel(t.clientX, t.clientY);
        const u = (x + 1) / 2, v = (y + 1) / 2;
        if(u < 0.5 && !st.stick){
          st.stick = { id: t.identifier, x0: x, y0: y, x, y };
        }else{
          const b = btnAt(u, v);
          if(b === 'alt'){ st.tAlt = t.identifier; st.tAltHit = true; }
          else if(b === 'abil'){ st.tAbilHit = true; }
          else if(b === 'boost'){ st.tBoost = t.identifier; }
          else if(b === 'jump'){ st.tJumpHit = true; st.tJump = t.identifier; }
          else if(st.touchCfg === 'twin' && !st.aimStick){ st.aimStick = { id: t.identifier, x0: x, y0: y, x, y }; st.tFire = t.identifier; }
          else st.tFire = t.identifier;
        }
      }
    });
    on(cv, 'touchmove', e => {
      e.preventDefault();
      for(const t of e.changedTouches){
        const [x, y] = rel(t.clientX, t.clientY);
        if(st.stick && st.stick.id === t.identifier){ st.stick.x = x; st.stick.y = y; }
        if(st.aimStick && st.aimStick.id === t.identifier){ st.aimStick.x = x; st.aimStick.y = y; }
      }
    });
    const endT = e => {
      e.preventDefault();
      for(const t of e.changedTouches){
        const id = t.identifier;
        if(st.stick && st.stick.id === id) st.stick = null;
        if(st.aimStick && st.aimStick.id === id) st.aimStick = null;
        if(st.tFire === id) st.tFire = false;
        if(st.tAlt === id) st.tAlt = false;
        if(st.tBoost === id) st.tBoost = false;
        if(st.tJump === id) st.tJump = false;
      }
    };
    on(cv, 'touchend', endT);
    on(cv, 'touchcancel', endT);
  }

  const DEAD = 0.18;
  const dz = v => Math.abs(v) < DEAD ? 0 : (v - Math.sign(v) * DEAD) / (1 - DEAD);
  st.poll = function(){
    const k = st.keys;
    // Controller, read raw.
    let pad = null;
    try{
      if(typeof padEnabled === 'undefined' || padEnabled){
        const pads = navigator.getGamepads ? navigator.getGamepads() : [];
        for(let i = 0; i < pads.length; i++) if(pads[i] && pads[i].connected){ pad = pads[i]; break; }
      }
    }catch(e){ pad = null; }
    let plx = 0, ply = 0, prx = 0, pry = 0, pa = false, pb = false, pxb = false, py = false, plb = false, prb = false, plt = 0, prt = 0;
    if(pad){
      const ax = pad.axes || [], bt = pad.buttons || [];
      const pr = i => !!(bt[i] && bt[i].pressed), val = i => (bt[i] ? (bt[i].value || (bt[i].pressed ? 1 : 0)) : 0);
      plx = dz(ax[0] || 0); ply = dz(ax[1] || 0); prx = dz(ax[2] || 0); pry = dz(ax[3] || 0);
      if(pr(14)) plx = -1; if(pr(15)) plx = 1; if(pr(12)) ply = -1; if(pr(13)) ply = 1;
      pa = pr(0); pb = pr(1); pxb = pr(2); py = pr(3); plb = pr(4); prb = pr(5); plt = val(6); prt = val(7);
      const any = pa || pb || py || plb || prb || plt > 0.2 || prt > 0.2 || Math.abs(plx) + Math.abs(ply) + Math.abs(prx) + Math.abs(pry) > 0;
      if(any) st.device = 'pad';
    }
    const pp = st.padPrev;
    const edge = (key, v) => { const was = !!pp[key]; pp[key] = v; return v && !was; };
    const padAlt = edge('b', pb) || edge('lb', plb && opts.lbAlt);
    const padJump = edge('y', py) || edge('a2', pa && opts.aJump);
    // The left bumper fires a special wherever it is not the alt button.
    const padAbil = edge('lbA', plb && !opts.lbAlt);
    edge('x', pxb);
    const invert = typeof chaosInverse !== 'undefined' && !!chaosInverse;
    if(invert){ plx = -plx; ply = -ply; prx = -prx; pry = -pry; }
    st.pad = pad ? { lx: plx, ly: ply, rx: prx, ry: pry, lt: plt, rt: prt } : null;

    // Keys.
    const kx = (k.ArrowRight || k.KeyD ? 1 : 0) - (k.ArrowLeft || k.KeyA ? 1 : 0);
    const ky = (k.ArrowDown || k.KeyS ? 1 : 0) - (k.ArrowUp || k.KeyW ? 1 : 0);
    // Touch stick: full deflection at ~13% of the board's width from where it landed.
    let sx = 0, sy = 0;
    if(st.stick){
      const R = 0.26;
      sx = clamp((st.stick.x - st.stick.x0) / R, -1, 1);
      sy = clamp((st.stick.y - st.stick.y0) / R, -1, 1);
    }
    // 🔄 INVERSE CONTROLS (chaos): the keys arrive mirrored already (the
    // chaosRun key shim), so only the sticks are flipped — the touch stick
    // here, the pad's two above — "every direction you press".
    if(invert){ sx = -sx; sy = -sy; }
    st.lx = clamp(kx + sx + plx, -1, 1);
    st.ly = clamp(ky + sy + ply, -1, 1);
    // Mouse aim: live while the pointer is over the board and the mouse is
    // the device in use — a keyboard player whose cursor happens to rest off
    // centre must not find the ship turning on its own.
    const mouseLive = st.mouseOn && st.device === 'mouse';
    st.aimOn = mouseLive || !!st.aimStick || Math.abs(prx) + Math.abs(pry) > 0;
    st.aimX = st.aimStick ? clamp((st.aimStick.x - st.aimStick.x0) / 0.22, -1, 1) : (Math.abs(prx) + Math.abs(pry) > 0 ? prx : (mouseLive ? st.mx : 0));
    st.aimY = st.aimStick ? clamp((st.aimStick.y - st.aimStick.y0) / 0.22, -1, 1) : (Math.abs(prx) + Math.abs(pry) > 0 ? pry : (mouseLive ? st.my : 0));
    const useMouseSteer = opts.mouseSteer && mouseLive;
    st.ax = clamp(st.lx + (useMouseSteer ? st.mx * (opts.mouseGain || 1) : 0), -1, 1);
    st.ay = clamp(st.ly + (useMouseSteer ? st.my * (opts.mouseGain || 1) : 0), -1, 1);
    st.fire = !!(k.Space || st.mDown || st.tFire || pa || prt > 0.35 || (opts.enterFires && k.Enter));
    st.boost = !!(k.ShiftLeft || k.ShiftRight || st.tBoost || prb || plt > 0.6 && opts.ltBoost);
    st.brake = !!(k.ControlLeft || k.ControlRight || k.KeyX || plt > 0.35 && !opts.ltBoost);
    st.roll = (k.KeyE ? 1 : 0) - (k.KeyQ ? 1 : 0) + (opts.bumperRoll ? ((prb ? 1 : 0) - (plb ? 1 : 0)) : 0);
    st.altHit = !!(st.hit.KeyF || st.hit.KeyR || st.mRightHit || st.tAltHit || padAlt);
    st.jumpHit = !!(st.hit.Space && opts.spaceJumps) || !!st.tJumpHit || padJump || !!st.hit.KeyC;
    // opts.abilKey: a world whose letters are all for typing moves it off V.
    st.abilHit = !!st.hit[opts.abilKey || 'KeyV'] || !!st.tAbilHit || padAbil;
    // Controller START / X: pause and photo, which the arcade's own poll would
    // have done but stands down for us.
    if(pad){
      const bt = pad.buttons || [];
      if(edge('start', !!(bt[9] && bt[9].pressed)) && typeof pauseRound === 'function') pauseRound('pad');
      // Into photo mode only: once it is up, the arcade's own poll owns the
      // pad (orbit, capture, X/B out) and must be the only one toggling it.
      const inPhoto = (typeof photoActive === 'function') && photoActive();
      if(pxb && !pp.xDone && !inPhoto){ if(typeof photoToggle === 'function') photoToggle(); }
      pp.xDone = pxb;
    }
    st.pressed = st.hit;
    st.hit = Object.create(null);
    st.mRightHit = false; st.tAltHit = false; st.tJumpHit = false; st.tAbilHit = false;
    return st;
  };
  st.dispose = () => { offs.forEach(f => { try{ f(); }catch(e){} }); offs.length = 0; };
  return st;
}
// The touch buttons, in board-relative units (u, v in 0..1, r in widths).
// `abil` adds the ⚡ specials button for a world that banks them.
function touchButtons(cfg, abil){
  let B;
  if(cfg === 'twin') B = [{ k: 'alt', u: 0.9, v: 0.18, r: 0.07 }, { k: 'jump', u: 0.9, v: 0.36, r: 0.07 }];
  else if(cfg === 'drive') B = [{ k: 'alt', u: 0.66, v: 0.84, r: 0.075 }, { k: 'boost', u: 0.88, v: 0.6, r: 0.07 }, { k: 'jump', u: 0.88, v: 0.86, r: 0.09 }];
  else if(cfg === 'tap') B = [];
  else B = [{ k: 'alt', u: 0.66, v: 0.86, r: 0.075 }, { k: 'boost', u: 0.9, v: 0.58, r: 0.07 }];
  if(abil){
    if(cfg === 'twin') B.push({ k: 'abil', u: 0.9, v: 0.54, r: 0.065 });
    else if(cfg === 'drive') B.push({ k: 'abil', u: 0.66, v: 0.62, r: 0.065 });
    else if(cfg === 'tap') B.push({ k: 'abil', u: 0.92, v: 0.13, r: 0.065 });
    else B.push({ k: 'abil', u: 0.9, v: 0.36, r: 0.065 });
  }
  return B;
}

// ══════════════════════════════════════════════
//  🖥️ HUD
// ══════════════════════════════════════════════
// One canvas in the fx layer, redrawn every frame. Projection is done here
// from the world camera itself (not r.project, which refuses points behind
// the lens) because the off-screen arrows need exactly those points.
function makeHud(w){
  const fx = document.getElementById('gl-fx');
  const cv = document.createElement('canvas');
  cv.className = 'ow-hud';
  cv.setAttribute('aria-hidden', 'true');
  fx.appendChild(cv);
  const ctx = cv.getContext('2d');
  // avoid: screen rects [x0, y0, x1, y1] that edge arrows stay out of.
  const H = { cv, ctx, W: 1, H: 1, cam: null, avoid: [] };
  const FONT = '"Orbitron", "Rajdhani", sans-serif';
  H.begin = function(){
    const cw = Math.max(1, fx.clientWidth), ch = Math.max(1, fx.clientHeight);
    const d = Math.min(2, window.devicePixelRatio || 1);
    const pw = Math.round(cw * d), ph = Math.round(ch * d);
    if(cv.width !== pw || cv.height !== ph){ cv.width = pw; cv.height = ph; cv.style.width = cw + 'px'; cv.style.height = ch + 'px'; }
    ctx.setTransform(d, 0, 0, d, 0, 0);
    ctx.clearRect(0, 0, cw, ch);
    H.W = cw; H.H = ch;
    const c = (typeof photoCam === 'function') ? photoCam(w.cam) : w.cam;
    const f = V.norm(V.sub(c.target, c.eye));
    let r = V.cross(f, w.up || [0, 1, 0]);
    r = V.len(r) < 1e-5 ? [1, 0, 0] : V.norm(r);
    const u = V.cross(r, f);
    H.cam = { eye: c.eye, f, r, u, th: Math.tan((c.fov || 58) * Math.PI / 360) };
  };
  // → { x, y, z, on } in CSS px; z is depth (negative: behind the camera).
  H.proj = function(p){
    const C = H.cam, d = V.sub(p, C.eye);
    const z = V.dot(d, C.f), x = V.dot(d, C.r), y = V.dot(d, C.u);
    const asp = H.W / H.H;
    if(z <= 0.05) return { x: 0, y: 0, z, on: false, vx: x, vy: y };
    const sx = H.W / 2 + (x / z) / (C.th * asp) * (H.W / 2);
    const sy = H.H / 2 - (y / z) / C.th * (H.H / 2);
    return { x: sx, y: sy, z, on: sx >= 0 && sx <= H.W && sy >= 0 && sy <= H.H, vx: x, vy: y };
  };
  H.text = function(x, y, s, o){
    o = o || {};
    ctx.font = (o.weight || 700) + ' ' + (o.size || 12) + 'px ' + FONT;
    ctx.textAlign = o.align || 'center';
    ctx.textBaseline = o.base || 'middle';
    if(o.glow !== false){ ctx.shadowColor = o.color || '#9fe9ff'; ctx.shadowBlur = o.blur != null ? o.blur : 8; }
    ctx.fillStyle = o.color || '#dff8ff';
    ctx.globalAlpha = o.alpha != null ? o.alpha : 1;
    ctx.fillText(s, x, y);
    ctx.globalAlpha = 1; ctx.shadowBlur = 0;
  };
  // A target bracket: four corners round a projected point, sized by depth.
  H.bracket = function(p, worldSize, color, label, o){
    o = o || {};
    const q = H.proj(p);
    if(!q.on) return q;
    const s = clamp(worldSize / Math.max(q.z, 1) * H.H * 0.9, 9, 70);
    ctx.strokeStyle = color; ctx.lineWidth = o.lock ? 2 : 1.3; ctx.globalAlpha = o.alpha != null ? o.alpha : 0.9;
    ctx.shadowColor = color; ctx.shadowBlur = 6;
    const c = s * 0.38;
    ctx.beginPath();
    for(const [dx, dy] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]){
      ctx.moveTo(q.x + dx * s, q.y + dy * s - dy * c); ctx.lineTo(q.x + dx * s, q.y + dy * s); ctx.lineTo(q.x + dx * s - dx * c, q.y + dy * s);
    }
    ctx.stroke();
    if(o.lock){
      ctx.beginPath();
      const s2 = s * 0.62;
      ctx.moveTo(q.x, q.y - s2); ctx.lineTo(q.x + s2, q.y); ctx.lineTo(q.x, q.y + s2); ctx.lineTo(q.x - s2, q.y); ctx.closePath();
      ctx.stroke();
    }
    ctx.shadowBlur = 0; ctx.globalAlpha = 1;
    if(label) H.text(q.x, q.y - s - 9, label, { size: 10, color });
    if(o.dist != null) H.text(q.x, q.y + s + 9, Math.round(o.dist) + ' m', { size: 9, color, alpha: 0.8 });
    return q;
  };
  // An arrow on the screen's edge toward something off-screen (or behind).
  H.edgeArrow = function(p, color, label){
    const q = H.proj(p);
    if(q.on) return false;
    let dx = q.vx, dy = -q.vy;
    if(q.z <= 0.05 && Math.abs(dx) + Math.abs(dy) < 1e-3) dy = 1;
    const a = Math.atan2(dy, dx);
    const m = 26, cx = H.W / 2, cy = H.H / 2;
    const kx = (cx - m) / Math.max(1e-4, Math.abs(Math.cos(a))), ky = (cy - m) / Math.max(1e-4, Math.abs(Math.sin(a)));
    const k = Math.min(kx, ky);
    let x = cx + Math.cos(a) * k, y = cy + Math.sin(a) * k;
    // Never under a panel: the bottom corners carry the radar and readouts.
    for(const z of H.avoid){ if(x > z[0] && x < z[2] && y > z[1] && y < z[3]) y = z[1] - 8; }
    ctx.save();
    ctx.translate(x, y); ctx.rotate(a);
    ctx.fillStyle = color; ctx.shadowColor = color; ctx.shadowBlur = 8; ctx.globalAlpha = 0.92;
    ctx.beginPath(); ctx.moveTo(9, 0); ctx.lineTo(-6, -7); ctx.lineTo(-3, 0); ctx.lineTo(-6, 7); ctx.closePath(); ctx.fill();
    ctx.restore();
    if(label) H.text(x - Math.cos(a) * 18, y - Math.sin(a) * 18, label, { size: 9, color });
    return true;
  };
  H.crosshair = function(x, y, color, size){
    const s = size || 10;
    ctx.strokeStyle = color || '#bff6ff'; ctx.lineWidth = 1.4; ctx.globalAlpha = 0.85;
    ctx.shadowColor = color || '#bff6ff'; ctx.shadowBlur = 6;
    ctx.beginPath();
    ctx.arc(x, y, s, 0, TAU);
    ctx.moveTo(x - s * 1.9, y); ctx.lineTo(x - s * 1.2, y);
    ctx.moveTo(x + s * 1.2, y); ctx.lineTo(x + s * 1.9, y);
    ctx.moveTo(x, y - s * 1.9); ctx.lineTo(x, y - s * 1.2);
    ctx.moveTo(x, y + s * 1.2); ctx.lineTo(x, y + s * 1.9);
    ctx.stroke();
    ctx.globalAlpha = 1; ctx.shadowBlur = 0;
  };
  H.bar = function(x, y, wdt, hgt, frac, color, label, o){
    o = o || {};
    ctx.globalAlpha = 0.85;
    ctx.fillStyle = 'rgba(6,14,26,0.55)';
    ctx.fillRect(x, y, wdt, hgt);
    ctx.fillStyle = color; ctx.shadowColor = color; ctx.shadowBlur = 8;
    ctx.fillRect(x + 1, y + 1, Math.max(0, (wdt - 2) * clamp(frac, 0, 1)), hgt - 2);
    ctx.shadowBlur = 0; ctx.globalAlpha = 1;
    ctx.strokeStyle = 'rgba(160,230,255,0.35)'; ctx.lineWidth = 1; ctx.strokeRect(x + 0.5, y + 0.5, wdt - 1, hgt - 1);
    if(label) H.text(x, y - 7, label, { size: 9, align: 'left', color: o.labelColor || '#9fdcff', glow: false });
  };
  // A panel with a title and a big number — the MISSILES 14 box.
  H.panel = function(x, y, wdt, hgt, title, big, color, sub){
    ctx.fillStyle = 'rgba(5,12,24,0.62)';
    ctx.fillRect(x, y, wdt, hgt);
    ctx.fillStyle = color; ctx.fillRect(x + wdt - 2, y, 2, hgt);
    H.text(x + 8, y + 11, title, { size: 9, align: 'left', color, glow: false });
    if(big != null) H.text(x + wdt - 10, y + 14, String(big), { size: 17, align: 'right', color: '#ffffff', blur: 6 });
    if(sub) H.text(x + 8, y + hgt - 10, sub, { size: 9, align: 'left', color: '#dff8ff', glow: false, alpha: 0.9 });
  };
  // Radar: a disc in the bottom-left, the player's heading up. items: { p, c, s }.
  H.radar = function(cx, cy, R, centre, fwd, range, items){
    ctx.save();
    ctx.globalAlpha = 0.9;
    ctx.fillStyle = 'rgba(4,14,26,0.55)';
    ctx.beginPath(); ctx.arc(cx, cy, R, 0, TAU); ctx.fill();
    ctx.strokeStyle = 'rgba(120,220,255,0.45)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(cx, cy, R, 0, TAU); ctx.arc(cx, cy, R * 0.5, 0, TAU); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx - R, cy); ctx.lineTo(cx + R, cy); ctx.moveTo(cx, cy - R); ctx.lineTo(cx, cy + R); ctx.globalAlpha = 0.35; ctx.stroke();
    ctx.globalAlpha = 1;
    // ✨ v57 · The heading the scope is turned to. A craft can point straight
    // up or down now, where the nose has no horizontal direction at all, and
    // its heading flips round going over the top of a loop: the last good
    // heading is held through the vertical, and a flip is swung through over a
    // few frames instead of cut. Ordinary turns still track exactly.
    const hl = Math.hypot(fwd[0], fwd[2]);
    const now = performance.now();
    const dtR = H._radT ? Math.min(0.1, (now - H._radT) / 1000) : 0;
    H._radT = now;
    let hd = H._radH;
    if(hl > 0.25){
      const tx = fwd[0] / hl, tz = fwd[2] / hl;
      const da = hd ? Math.atan2(hd[0] * tz - hd[1] * tx, hd[0] * tx + hd[1] * tz) : 0;
      if(!hd || Math.abs(da) < 2.0 || !dtR) hd = [tx, tz];
      else{
        const s = Math.sign(da) * Math.min(Math.abs(da), 9 * dtR), c = Math.cos(s), sn = Math.sin(s);
        hd = [hd[0] * c - hd[1] * sn, hd[0] * sn + hd[1] * c];
      }
    }else if(!hd) hd = [0, -1];
    H._radH = hd;
    const fh = [hd[0], 0, hd[1]];
    const rh = [-fh[2], 0, fh[0]];
    for(const it of items){
      const d = V.sub(it.p, centre);
      let x = V.dot(d, rh) / range, y = -V.dot(d, fh) / range;
      const l = Math.hypot(x, y);
      const edge = l > 1;
      if(edge){ x /= l; y /= l; }
      ctx.fillStyle = it.c; ctx.shadowColor = it.c; ctx.shadowBlur = 5;
      ctx.globalAlpha = edge ? 0.55 : 1;
      const s = it.s || 2.4;
      const vy = d[1];
      ctx.beginPath();
      if(it.shape === 'diamond'){ ctx.moveTo(cx + x * R, cy + y * R - s * 1.4); ctx.lineTo(cx + x * R + s * 1.4, cy + y * R); ctx.lineTo(cx + x * R, cy + y * R + s * 1.4); ctx.lineTo(cx + x * R - s * 1.4, cy + y * R); ctx.closePath(); }
      else ctx.arc(cx + x * R, cy + y * R, s, 0, TAU);
      ctx.fill();
      // Above/below tick, for the worlds with height.
      if(it.tick && Math.abs(vy) > range * 0.08){ ctx.fillRect(cx + x * R - 0.5, cy + y * R + (vy > 0 ? -s - 4 : s), 1, 4); }
    }
    ctx.shadowBlur = 0; ctx.globalAlpha = 1;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.moveTo(cx, cy - 5); ctx.lineTo(cx + 3.5, cy + 4); ctx.lineTo(cx - 3.5, cy + 4); ctx.closePath(); ctx.fill();
    ctx.restore();
  };
  // The touch controls, drawn only while a finger is the thing playing.
  // `only` limits it to the buttons a world really uses (e.g. ['abil']).
  H.touchPad = function(inp, only){
    if(inp.device !== 'touch') return;
    const B = touchButtons(inp.touchCfg, inp.abilOn);
    ctx.save();
    for(const b of B){
      if(only && only.indexOf(b.k) < 0) continue;
      const x = b.u * H.W, y = b.v * H.H, r = b.r * H.W;
      ctx.globalAlpha = 0.5; ctx.strokeStyle = '#7fe8ff'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.stroke();
      H.text(x, y, b.k === 'alt' ? (inp.altLabel || 'ALT') : b.k === 'boost' ? 'BOOST' : b.k === 'abil' ? '⚡' : (inp.jumpLabel || 'JUMP'), { size: b.k === 'abil' ? 14 : 10, color: '#bff6ff' });
    }
    if(inp.stick){
      const s = inp.stick;
      const x0 = (s.x0 + 1) / 2 * H.W, y0 = (s.y0 + 1) / 2 * H.H, x = (s.x + 1) / 2 * H.W, y = (s.y + 1) / 2 * H.H;
      ctx.globalAlpha = 0.45; ctx.strokeStyle = '#00f5ff'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(x0, y0, 0.13 * H.W, 0, TAU); ctx.stroke();
      ctx.globalAlpha = 0.7; ctx.fillStyle = 'rgba(0,245,255,0.3)';
      ctx.beginPath(); ctx.arc(x, y, 0.05 * H.W, 0, TAU); ctx.fill();
    }
    ctx.restore();
  };
  H.dispose = () => { cv.remove(); };
  return H;
}

// ══════════════════════════════════════════════
//  🗺️ THE FIELD — a world that is never built, only generated around you
// ══════════════════════════════════════════════
// The world is cut into cells; a cell's contents are a pure function of its
// coordinates and the world's seed, so the asteroid you passed is exactly
// where you left it when you turn back. Cells are made as they come within
// `radius` and dropped once well past it. What the player DESTROYED is kept in
// a set by item id, so a field you cleared does not grow back behind you.
function makeField(o){
  // 🌐 v60 · plus the run's salt (owSaltFrom): a Daily Hack, a party turn or a
  // lab level lays the same world out for everyone playing it.
  const cell = o.cell, dims = o.dims || 2, seed = ((o.seed || 1) + ((window.PI3D && PI3D.owSalt) | 0)) | 0;
  const map = new Map(), dead = new Set();
  let lastKey = null, sweep = 0;
  const F = { map, dead };
  const key = (x, y, z) => x + ',' + y + ',' + z;
  F.update = function(p, radius){
    const Rr = radius || o.radius;
    const R = Math.ceil(Rr / cell);
    const ix = Math.floor(p[0] / cell), iy = dims === 3 ? Math.floor(p[1] / cell) : 0, iz = Math.floor(p[2] / cell);
    const here = key(ix, iy, iz);
    if(here !== lastKey){
      lastKey = here;
      const Ry = dims === 3 ? R : 0;
      for(let dx = -R; dx <= R; dx++) for(let dy = -Ry; dy <= Ry; dy++) for(let dz = -R; dz <= R; dz++){
        if(dims === 3 ? (dx * dx + dy * dy + dz * dz > (R + 0.5) * (R + 0.5)) : (dx * dx + dz * dz > (R + 0.5) * (R + 0.5))) continue;
        const cx = ix + dx, cy = iy + dy, cz = iz + dz, k = key(cx, cy, cz);
        if(map.has(k)) continue;
        const rng = seeded(ihash(cx, cy, cz, seed));
        let items = [];
        try{ items = o.gen(cx, cy, cz, rng, k) || []; }catch(e){ console.warn('[OW] cell gen failed', e); items = []; }
        items.forEach((it, i) => { it.id = k + '#' + i; if(dead.has(it.id)) it.dead = true; });
        map.set(k, { cx, cy, cz, items });
      }
    }
    // Drop what is far behind, a slice of the map per frame.
    if(++sweep % 20 === 0){
      const lim = R + 2;
      for(const [k, c] of map){
        if(Math.abs(c.cx - ix) > lim || Math.abs(c.cz - iz) > lim || (dims === 3 && Math.abs(c.cy - iy) > lim)) map.delete(k);
      }
    }
  };
  F.each = function(fn){
    for(const c of map.values()) for(const it of c.items) if(!it.dead) fn(it);
  };
  // Items in the cells around p (the 3×3(×3) block): collision queries.
  F.near = function(p, fn){
    const ix = Math.floor(p[0] / cell), iy = dims === 3 ? Math.floor(p[1] / cell) : 0, iz = Math.floor(p[2] / cell);
    const Ry = dims === 3 ? 1 : 0;
    for(let dx = -1; dx <= 1; dx++) for(let dy = -Ry; dy <= Ry; dy++) for(let dz = -1; dz <= 1; dz++){
      const c = map.get(key(ix + dx, iy + dy, iz + dz));
      if(!c) continue;
      for(const it of c.items) if(!it.dead) fn(it);
    }
  };
  F.kill = function(it){ it.dead = true; dead.add(it.id); };
  return F;
}

// ══════════════════════════════════════════════
//  💥 FX
// ══════════════════════════════════════════════
function makeFx(w){
  const r = w.r;
  const L = [];
  // The particle ceiling the quality governor has set, read once a frame.
  let cap = 500;
  const MAX = () => cap;
  const held = () => (typeof photoActive === 'function') && photoActive();
  const FX = { list: L };
  const rr = (a, b) => a + Math.random() * (b - a);
  const rdir = () => { const u = Math.random() * 2 - 1, th = Math.random() * TAU, s = Math.sqrt(1 - u * u); return [s * Math.cos(th), u, s * Math.sin(th)]; };
  const push = e => { if(held() || L.length >= MAX()) return; L.push(e); };
  // A full explosion. s = size (≈ the exploding thing's radius).
  // ✨ v59 · As the video's: a white-hot flash, then a churning fireball that
  // cools from yellow through orange to a red rag inside rising smoke, embers
  // flung out and debris burning as it tumbles. o.color tints the sparks only —
  // fire is fire-coloured whatever blew up. The shock ring is opt-in now
  // (ring: true, or a ringNormal for a shockwave on the ground).
  FX.explode = function(p, s, o){
    if(held()) return;
    o = o || {};
    s = s || 1;
    const hot = o.color || '#ff8a2a';
    push({ k: 'flash', p: V.copy(p), t: 0, life: 0.12 + Math.min(0.1, s * 0.015), s, c: o.light || '#ffb066', seed: Math.random() });
    const nf = Math.round(clamp(4 + s * 0.8, 4, 9));
    for(let i = 0; i < nf; i++){
      const d = rdir();
      push({ k: 'fire', p: V.madd(p, d, s * 0.3 * Math.random()), v: V.mul(d, rr(0.8, 2.6) * Math.sqrt(s)), t: -i * 0.035,
             life: rr(0.75, 1.2) * (0.9 + Math.min(0.6, s * 0.04)), s: s * rr(0.85, 1.35), seed: Math.random(), drag: 2.4, rise: 0.6 * Math.sqrt(s) });
    }
    const ns = Math.round(clamp(10 + s * 8, 10, o.sparks || 46));
    for(let i = 0; i < ns; i++){
      const d = rdir(), sp = rr(12, 38) * Math.sqrt(s);
      push({ k: 'spark', p: V.copy(p), v: V.mul(d, sp), t: 0, life: rr(0.35, 0.9), s: rr(0.06, 0.14) * Math.sqrt(s), c: Math.random() < 0.6 ? '#ffd28a' : hot, drag: 1.4 });
    }
    const nd = o.debris != null ? o.debris : Math.round(clamp(3 + s * 2.5, 3, 14));
    for(let i = 0; i < nd; i++){
      const d = rdir(), sp = rr(5, 18) * Math.sqrt(s);
      push({ k: 'deb', p: V.copy(p), v: V.mul(d, sp), t: 0, life: rr(1.2, 2.4), s: rr(0.10, 0.26) * s, rot: [Math.random() * 6, Math.random() * 6, 0], spin: [rr(-6, 6), rr(-6, 6), 0],
             g: o.debrisGeo || (Math.random() < 0.7 ? 'rock2' : 'slab'), c: o.debrisColor || '#3a3633', grav: o.grav || 0, seed: Math.random() });
    }
    const nsm = o.smoke != null ? o.smoke : Math.round(clamp(3 + s * 1.2, 3, 10));
    for(let i = 0; i < nsm; i++){
      const d = rdir();
      push({ k: 'smoke', p: V.madd(p, d, s * 0.4), v: V.add(V.mul(d, rr(0.4, 1.8) * Math.sqrt(s)), [0, rr(0.6, 1.6) * Math.sqrt(s), 0]), t: -0.25 - i * 0.05,
             life: rr(2.0, 3.4), s: s * rr(1.0, 1.6), c: o.smokeColor || '#5a4a42', seed: Math.random(), drag: 0.9, a0: 0.42 });
    }
    if(o.ring === true || o.ringNormal) push({ k: 'ring', p: V.copy(p), t: 0, life: 0.55, s: s * 5, c: o.ringColor || '#ffb86a', n: o.ringNormal || null });
    if(s > 2.5) w.kick && w.kick(Math.min(2.2, s * 0.25));
  };
  // Sparks off an impact, along a normal-ish direction.
  FX.sparks = function(p, n, color, k, speed){
    for(let i = 0; i < (n || 8); i++){
      const d = rdir();
      push({ k: 'spark', p: V.copy(p), v: V.mul(d, (speed || 18) * rr(0.4, 1)), t: 0, life: rr(0.2, 0.45), s: rr(0.04, 0.09) * (k || 1), c: color || '#bff6ff', drag: 2.2 });
    }
  };
  // ✨ v59 · A warm flash (a muzzle, a launch) is a small fireball; a cold one
  // (an energy scan, a shield) keeps the old flare.
  FX.flash = function(p, color, s, life){
    const h = (color || '#ffffff').replace('#', '');
    const warm = parseInt(h.slice(0, 2), 16) >= parseInt(h.slice(4, 6), 16);
    push({ k: warm ? 'mflash' : 'eflash', p: V.copy(p), t: 0, life: life || 0.15, s: s || 0.6, c: color || '#ffffff', seed: Math.random() });
  };
  FX.puff = function(p, color, s, life, v){ push({ k: 'smoke', p: V.copy(p), v: v ? V.copy(v) : [0, 0.4, 0], t: 0, life: life || 1.2, s: s || 0.5, c: color || '#5a5a64', seed: Math.random(), a0: 0.42 }); };
  FX.glowPop = function(p, color, s, life){ push({ k: 'ball', p: V.copy(p), t: 0, life: life || 0.35, s: s || 0.6, c: color || '#ffffff' }); };
  FX.step = function(dt){
    if(dt <= 0) return;
    try{ cap = Math.max(160, (P.quality && P.quality.parts) || 500); }catch(e){ cap = 500; }
    for(let i = L.length - 1; i >= 0; i--){
      const e = L[i];
      e.t += dt;
      if(e.t >= e.life){ L.splice(i, 1); continue; }
      if(e.v){
        const d = e.drag ? Math.max(0, 1 - e.drag * dt) : 1;
        e.v[0] *= d; e.v[1] = e.v[1] * d - (e.grav || 0) * dt + (e.rise || 0) * dt; e.v[2] *= d;
        e.p[0] += e.v[0] * dt; e.p[1] += e.v[1] * dt; e.p[2] += e.v[2] * dt;
      }
      if(e.spin){ e.rot[0] += e.spin[0] * dt; e.rot[1] += e.spin[1] * dt; }
    }
  };
  const ramp = (a) => a < 0.15 ? '#fff4d6' : a < 0.35 ? '#ffd27a' : a < 0.6 ? '#ff8a2a' : '#b8321a';
  FX.draw = function(){
    let lights = 0;
    const eye = w.cam.eye;
    for(const e of L){
      if(e.t < 0) continue;
      const a = e.t / e.life;
      switch(e.k){
        case 'flash':
          // ✨ v59 · the white-hot instant of the blast
          if(lights++ < 3) r.light({ pos: e.p, color: e.c, intensity: 320 * e.s * (1 - a), range: 18 * Math.max(1, e.s) });
          r.fire(e.p, e.s * 2.6 * (0.6 + 0.5 * a), 2.4 * (1 - a), 0.02 + 0.2 * a, e.seed);
          break;
        case 'mflash':
          if(lights++ < 3) r.light({ pos: e.p, color: '#ffb066', intensity: 120 * e.s * (1 - a), range: 10 });
          r.fire(e.p, e.s * 2.2 * (0.6 + 0.8 * a), 2.4 * (1 - a), 0.05 + 0.45 * a, e.seed);
          break;
        case 'eflash':
          r.glowFx(e.p, e.s * 3.2 * (1 - a * 0.5), e.c, 3.0 * (1 - a));
          break;
        case 'fire': {
          // ✨ v59 · a churning ball that opens and cools as it rises
          r.fire(e.p, e.s * (0.7 + 1.3 * Math.sqrt(a)), 1.5 * (1 - a * 0.3), 0.12 + 0.88 * a, e.seed);
          break;
        }
        case 'ball': {
          // a pickup's collect pop (not fire)
          const g = e.s * (0.6 + 2.2 * Math.sqrt(a));
          r.glowFx(e.p, g, ramp(a), 2.4 * (1 - a) * (1 - a));
          r.glowFx(e.p, g * 0.55, '#fff2c8', 1.6 * Math.max(0, 1 - a * 2.2));
          break;
        }
        case 'spark': {
          const tail = V.madd(e.p, e.v, -0.045);
          r.streak(tail, e.p, e.s * 2.2, e.c, 3.2 * (1 - a), 0.9);
          break;
        }
        case 'deb': {
          // Glowing hot at first and cooling to dark: the glow does the heat,
          // the hull itself only blushes, so a fragment keeps its shape.
          const heat = Math.max(0, 1 - a * 3.2);
          r.draw(e.g, { pos: e.p, rot: e.rot, scale: e.s, color: e.c, metallic: 0.35, roughness: 0.7, rim: 0.5,
                        emissive: '#ff5a10', emissiveStrength: 0.55 * heat * heat });
          // ✨ v59 · burning as it tumbles: a small flame trailing the fragment
          if(heat > 0.15) r.fire(V.madd(e.p, e.v, -0.035), e.s * 1.5, 1.3 * heat, 0.15 + 0.6 * (1 - heat), e.seed);
          break;
        }
        case 'smoke': {
          // ✨ v59 · a noise billow, not a translucent ball
          r.smoke(e.p, e.s * (1.4 + a * 2.6), e.c, (e.a0 || 0.45) * (1 - a) * Math.min(1, e.t * 5), a, e.seed);
          break;
        }
        case 'ring': {
          const n = e.n || V.norm(V.sub(eye, e.p));
          const b = basisLook(n, Math.abs(n[1]) > 0.9 ? [1, 0, 0] : [0, 1, 0]);
          // A torus lies in XZ: its axis (local Y) has to point along n.
          const m3 = [b.r[0], b.r[1], b.r[2], n[0], n[1], n[2], b.u[0], b.u[1], b.u[2]];
          const sc = e.s * 0.6 * (0.2 + Math.sqrt(a));
          const fa = (1 - a) * (1 - a);
          r.draw('thintorus', { pos: e.p, m3, scale: [sc, sc * 0.18, sc], color: e.c, emissive: e.c, emissiveStrength: 1.8 * fa, alpha: 0.32 * fa, blend: true, rim: 0 });
          break;
        }
      }
    }
  };
  return FX;
}

// Speed dust: motes fixed in the world around the camera, wrapped in a box so
// there are always some, drawn as short streaks along the camera's motion. In
// open space nothing else tells you that you are moving.
function makeDust(n, box){
  const P0 = [];
  for(let i = 0; i < n; i++) P0.push([(Math.random() - 0.5) * box, (Math.random() - 0.5) * box, (Math.random() - 0.5) * box, Math.random()]);
  let prev = null;
  return function(w, vel, o){
    o = o || {};
    const r = w.r, c = w.cam.eye, h = box / 2;
    const v = vel || [0, 0, 0];
    const sp = V.len(v);
    const k = clamp(sp * (o.len || 0.022), 0.05, o.max || 3.5);
    const dir = sp > 1e-3 ? V.mul(v, 1 / sp) : [0, 0, -1];
    for(const p of P0){
      for(let a = 0; a < 3; a++){
        let d = p[a] - c[a];
        if(d > h) p[a] -= box * Math.ceil((d - h) / box);
        else if(d < -h) p[a] += box * Math.ceil((-h - d) / box);
      }
      const head = [p[0], p[1], p[2]];
      const tail = V.madd(head, dir, -k);
      const dd = Math.sqrt(V.d2(head, c));
      const fade = clamp(1 - dd / h, 0, 1) * clamp(dd / 3, 0, 1);
      r.streak(tail, head, o.width || 0.045, o.color || '#cfe2ff', (o.gain || 0.9) * fade * (0.4 + p[3] * 0.6), 1.0);
    }
  };
}

// An engine plume out of a nozzle. dir is the way the exhaust goes (backwards).
// ✨ v59 · A turbulent flame (the streak's flame mode): white-hot at the nozzle,
// its colour in the body and the tip, flickering — the video's jets — with a
// soft afterglow beyond. No glow blob in the throat: the nozzle disc is the
// model's own lamp.
function plume(w, p, dir, o){
  o = o || {};
  const r = w.r, t = w.t;
  const len = (o.len || 2.4) * (0.92 + 0.08 * Math.sin(t * 47 + (o.ph || 0)));
  const wd = o.width || 0.5;
  const col = o.color || '#68d4ff';
  const ph = Math.abs(((o.ph || 0) * 0.137) % 1);
  r.streak(p, V.madd(p, dir, len), wd, col, (o.gain || 1) * 2.0, 2 + ph);
  r.streak(V.madd(p, dir, len * 0.15), V.madd(p, dir, len * 1.6), wd * 0.55, col, (o.gain || 1) * 0.5, 0.0);
}

// Bodies "at infinity": positioned off the camera every frame, with a little
// parallax, so a planet stays a planet however far you fly — and still sits
// behind every asteroid, because it is real geometry at a real depth.
function drawBodies(w, list){
  const r = w.r, c = w.cam.eye;
  for(const b of list){
    const par = b.par == null ? 0.004 : b.par;
    const p = [c[0] + b.off[0] - c[0] * par, c[1] + b.off[1] - c[1] * par, c[2] + b.off[2] - c[2] * par];
    if(b.kind === 'gas'){
      r.draw('planet', { pos: p, rot: b.rot || [0.2, w.t * (b.spin || 0.004), 0.32], scale: b.size, color: b.color, metallic: 0, roughness: 0.92, rim: -(b.rim || 0.5) });
      if(b.ring) r.draw('ringdisc', { pos: p, rot: b.ringRot || [0.2, 0, 0.32], scale: b.size * b.ring, color: b.ringColor || '#d6c29c', metallic: 0, roughness: 0.95, rim: -0.2, blend: true, alpha: 0.96 });
      r.glow(p, -(b.size * 0.72), b.halo || '#ffb27a', 0.08);
    }else if(b.kind === 'moon'){
      r.draw('rock' + (b.v || ''), { pos: p, rot: [0.3, w.t * 0.01, 0.1], scale: b.size, color: b.color || '#8a8580', metallic: 0, roughness: 0.95, rim: -(b.rim || 0.4) });
    }else if(b.kind === 'sun'){
      r.glow(p, -b.size, b.color || '#fff1d6', b.gain || 3.2);
      r.glow(p, -b.size * 4, b.color || '#ffd8a0', (b.gain || 3.2) * 0.12);
    }
  }
}

// An endless lit floor: a ground slab and grid beams snapped to the grid
// step under the camera, so the lines stand still in the world while the
// slab follows you. Fog does the far edge.
// 🌍 v60 · Under a World theme the floor is the theme's own: sludge-green
// lines on black for the Toxic Sector, a synthwave grid on plum in the Synth
// Desert, teal on the sea floor of Deep Net, cold blue panels on the Orbital
// Deck. The world keeps its step, radius and rhythm.
const LOOK_FLOORS = {
  toxic:  { color: '#2a9a18', floor: '#030803', glow: 0.95 },
  desert: { color: '#ff2a6d', floor: '#14060f', glow: 0.9 },
  deep:   { color: '#14b8c8', floor: '#021018', glow: 0.8 },
  orbit:  { color: '#8a9cff', floor: '#05070c', glow: 0.8 }
};
function drawFloor(w, o){
  o = o || {};
  const T = w.look && LOOK_FLOORS[w.look];
  if(T) o = Object.assign({}, o, { color: T.color, floor: T.floor, glow: o.glow != null ? o.glow : T.glow });
  const r = w.r, c = w.cam.eye;
  const step = o.step || 6, R = o.radius || 150;
  const y = o.y || 0;
  const cx = Math.round(c[0] / step) * step, cz = Math.round(c[2] / step) * step;
  r.draw('ground', { pos: [cx, y - 0.06, cz], scale: [R * 2.4, 1, R * 2.4], color: o.floor || '#05070f', metallic: o.metal != null ? o.metal : 0.8, roughness: o.rough != null ? o.rough : 0.3, rim: 0.2 });
  const col = o.color || '#123a66', em = o.glow != null ? o.glow : 1.0, wd = o.width || 0.06;
  const n = Math.ceil(R / step);
  for(let i = -n; i <= n; i++){
    const x = cx + i * step, z = cz + i * step;
    const major = o.major && (Math.round(x / step) % o.major === 0);
    const majorZ = o.major && (Math.round(z / step) % o.major === 0);
    r.beam([x, y, cz - R], [x, y, cz + R], major ? wd * 2 : wd, { color: col, emissive: col, emissiveStrength: major ? em * 1.8 : em, height: wd });
    r.beam([cx - R, y, z], [cx + R, y, z], majorZ ? wd * 2 : wd, { color: col, emissive: col, emissiveStrength: majorZ ? em * 1.8 : em, height: wd });
  }
}

// ══════════════════════════════════════════════
//  ⚡ SPECIALS — v60 · the 2D builds' abilities, out in the open
// ══════════════════════════════════════════════
// The 2D missions bank special abilities: Nebula's Smart Missile, Shield
// Burst, Time Warp and Nova Bomb; Cyber Arena's Nova Blast, Time Freeze,
// Repair Pulse, Overcharge and Aegis Shield; Meteor Shield's battery. None of
// them existed out here. This is one kit for all of them — plus four new ones
// (EMP Pulse, Magnet Field, Decoy, Phase Shift) — and each world names the
// rotation it banks and wires the few hooks its own rules need:
//   o.kinds        the rotation, e.g. ['smart', 'shield', 'warp', 'nova']
//   o.every        points per charge (default 180); worlds may grant() too
//   o.max          the bank (default 3)
//   o.player()     the player's world position
//   o.targets()    [{ p, r, obj }] — what missiles and blasts can hit
//   o.hit(obj, dmg, at)       damage one; o.clearFire()  remove enemy shots
//   o.heal(frac)   repair a share of the bar
//   o.keyName      the key the HUD names (a typing world moves it off V)
// and READS while it plays: warp() (enemy time scale), frozen(), jammed()
// (enemies hold fire), shielded(), active('overdrive' | 'magnet' | 'phase'),
// decoy() (a position enemies chase instead of you, or null), and pull(p, dt)
// for anything a magnet should draw in. V, the left bumper or ⚡ fires.
const SPECIAL_DEFS = {
  smart:     { label: '🎯 SMART MISSILES', color: '#00f5ff', t: 2.6 },
  shield:    { label: '🛡️ SHIELD BURST',   color: '#a855f7', t: 4.0 },
  warp:      { label: '⏳ TIME WARP',      color: '#ffd700', t: 5.0 },
  nova:      { label: '💥 NOVA BLAST',     color: '#ff2d9a', t: 1.0 },
  freeze:    { label: '❄️ TIME FREEZE',    color: '#7fe8ff', t: 3.0 },
  repair:    { label: '🔧 REPAIR PULSE',   color: '#39ff14', t: 1.0 },
  overdrive: { label: '🔥 OVERCHARGE',     color: '#ff6a1a', t: 6.0 },
  salvo:     { label: '🔥 RAPID SALVO',    color: '#ff8a1a', t: 2.6 },
  emp:       { label: '⚡ EMP PULSE',      color: '#9fdcff', t: 6.0 },
  magnet:    { label: '🧲 MAGNET FIELD',   color: '#39ff88', t: 8.0 },
  decoy:     { label: '🎭 DECOY',          color: '#e8f0ff', t: 6.0 },
  phase:     { label: '👻 PHASE SHIFT',    color: '#c8a2ff', t: 3.0 }
};
function makeSpecials(G, o){
  const { w, r, fx, hud, inp } = G;
  const kinds = (o.kinds || ['shield', 'warp', 'nova']).filter(k => SPECIAL_DEFS[k]);
  const every = o.every || 180, max = o.max || 3;
  const queue = [], on = Object.create(null), missiles = [];
  let earned = 0, nextAt = every, decoyP = null, salvoLeft = 0, salvoT = 0, flashT = 0, flashC = '#ffffff';
  inp.abilOn = true;
  const S = { queue, on };
  const def = k => SPECIAL_DEFS[k];
  S.grant = function(kind){
    if(queue.length >= max) return false;
    const k = kind && SPECIAL_DEFS[kind] ? kind : kinds[earned++ % kinds.length];
    queue.push(k);
    snd('powerup', { semi: 5 });
    const pp = o.player ? o.player() : null;
    // Higher than a fired special's call-out, so the two never sit on each other.
    if(pp) w.pop(V.add(pp, [0, 8, 0]), def(k).label + ' READY', def(k).color, { size: 13 });
    return true;
  };
  S.active = k => (on[k] || 0) > 0;
  S.warp = () => S.active('warp') ? 0.5 : 1;
  S.frozen = () => S.active('freeze');
  S.jammed = () => S.active('emp') || S.active('freeze');
  S.shielded = () => S.active('shield');
  S.decoy = () => (S.active('decoy') && decoyP) ? decoyP : null;
  // Moves a pickup toward the player while the magnet holds.
  S.pull = function(p, dt, speed){
    if(!S.active('magnet') || !o.player) return p;
    const pp = o.player(), d = V.sub(pp, p), l = V.len(d);
    if(l < 0.5 || l > (o.magnetR || 60)) return p;
    return V.madd(p, d, Math.min(1, (speed || 40) * dt / l));
  };
  function launch(n, dmg){
    const pp = o.player ? o.player() : [0, 0, 0];
    const T = o.targets ? o.targets() : [];
    T.sort((a, b) => V.d2(a.p, pp) - V.d2(b.p, pp));
    for(let i = 0; i < n; i++){
      const t = T.length ? T[i % T.length] : null;
      const a = (i / Math.max(1, n)) * TAU;
      missiles.push({ p: V.add(pp, [Math.cos(a) * 0.8, 1.5, Math.sin(a) * 0.8]), v: [Math.cos(a) * 8, 14, Math.sin(a) * 8],
                      tgt: t ? t.obj : null, life: 4, smoke: 0, dmg: dmg || 99 });
    }
    snd('missile');
  }
  S.use = function(){
    if(!queue.length){ snd('deny'); return false; }
    const k = queue.shift(), d = def(k);
    on[k] = d.t;
    flashT = 0.35; flashC = d.color;
    snd(k === 'nova' ? 'bigExplode' : k === 'repair' || k === 'shield' ? 'shield' : 'ability');
    const pp = o.player ? o.player() : [0, 0, 0];
    w.pop(V.add(pp, [0, 5, 0]), d.label + '!', d.color, { size: 18 });
    w.kick(k === 'nova' ? 2 : 0.8);
    if(k === 'smart') launch(o.smartN || 3, o.smartDmg);
    else if(k === 'salvo'){ salvoLeft = 6; salvoT = 0; }
    else if(k === 'nova'){
      const R = o.novaR || 60;
      fx.explode(V.add(pp, [0, 1, 0]), 4, { color: d.color, debris: 0, smoke: 2, ring: true });
      for(const t of (o.targets ? o.targets() : [])) if(V.d2(t.p, pp) < R * R && o.hit) o.hit(t.obj, o.novaDmg || 99, t.p);
      if(o.clearFire) o.clearFire(pp, R);
    }else if(k === 'shield'){
      if(o.heal && o.shieldHeals !== false) o.heal(1);
      if(o.clearFire) o.clearFire(pp, 1e9);
      // Sparks thrown outward, not a glow: anything bright AT the player sits
      // a few metres in front of every chase camera and fills the screen.
      fx.sparks(pp, 26, d.color, 1.2, 22);
    }else if(k === 'repair'){
      if(o.heal) o.heal(0.5);
      fx.sparks(pp, 20, d.color, 1.1, 16);
    }else if(k === 'emp'){
      if(o.clearFire) o.clearFire(pp, 1e9);
      fx.sparks(pp, 32, d.color, 1.3, 30);
    }else if(k === 'decoy'){
      decoyP = V.copy(pp);
    }
    if(o.onUse) o.onUse(k);
    return true;
  };
  S.tick = function(dt, I, score){
    if(dt <= 0) return;
    if(score != null){ while(score >= nextAt){ nextAt += every; S.grant(); } }
    if(I && I.abilHit) S.use();
    for(const k in on){ if(on[k] > 0){ on[k] = Math.max(0, on[k] - dt); if(!on[k] && o.onEnd) o.onEnd(k); } }
    flashT = Math.max(0, flashT - dt);
    if(salvoLeft > 0){ salvoT -= dt; if(salvoT <= 0){ salvoT = 0.13; salvoLeft--; launch(1, o.salvoDmg || o.smartDmg); } }
    // Homing: climb, then turn onto the target, re-picking the nearest live
    // one if the first is gone.
    for(let i = missiles.length - 1; i >= 0; i--){
      const m = missiles[i];
      m.life -= dt;
      const T = o.targets ? o.targets() : [];
      let t = m.tgt ? T.find(x => x.obj === m.tgt) : null;
      if(!t && T.length){ let bd = 1e18; for(const x of T){ const d = V.d2(x.p, m.p); if(d < bd){ bd = d; t = x; } } m.tgt = t ? t.obj : null; }
      const sp = V.len(m.v) || 1, cur = V.mul(m.v, 1 / sp);
      const want = t ? V.norm(V.sub(t.p, m.p)) : cur;
      const nd = V.norm(V.lerp(cur, want, clamp((m.life > 3.6 ? 1.2 : 6) * dt, 0, 1)));
      m.v = V.mul(nd, Math.min(o.missileSpeed || 90, sp + 80 * dt));
      const a = V.copy(m.p);
      m.p = V.madd(m.p, m.v, dt);
      m.smoke -= dt;
      if(m.smoke <= 0){ m.smoke = 0.03; fx.puff(m.p, '#a8aeb8', 0.36, 0.8, V.mul(m.v, -0.02)); }
      let boom = m.life <= 0;
      if(t){
        const ab = V.sub(m.p, a), L2 = V.dot(ab, ab) || 1e-6;
        const u = clamp(V.dot(V.sub(t.p, a), ab) / L2, 0, 1);
        if(V.d2(V.madd(a, ab, u), t.p) < (t.r + 1) * (t.r + 1)){ boom = true; if(o.hit) o.hit(t.obj, m.dmg, t.p); }
      }
      if(boom){ fx.explode(m.p, 1.6, { color: '#7fe8ff', debris: 2 }); snd('explode'); missiles.splice(i, 1); }
    }
    if(!S.active('decoy')) decoyP = null;
  };
  S.draw = function(){
    const pp = o.player ? o.player() : null;
    for(const m of missiles){
      const dir = V.norm(m.v);
      r.draw('missile', { pos: m.p, m3: basisLook(dir, [0, 1, 0]).m3, scale: 1.1, color: '#d9dde4', metallic: 0.3, roughness: 0.4, emissive: '#00f5ff', emissiveStrength: 0.5, accent: 4 });
      plume(w, V.madd(m.p, dir, -0.6), V.mul(dir, -1), { len: 2.2, width: 0.4, color: '#7fe8ff', gain: 1.0 });
    }
    if(!pp) return;
    const rad = o.bubbleR || 3.2;
    if(S.shielded()){
      // A rim of light rather than a filled ball: the chase cameras sit a few
      // metres off the hull, and a solid bubble filled the whole screen.
      const k = Math.min(1, on.shield * 2);
      r.draw('sphere', { pos: pp, scale: rad + Math.sin(w.t * 9) * 0.06, color: '#a855f7', emissive: '#c084fc', emissiveStrength: 0.12 * k,
                         alpha: 0.06 * k, blend: true, metallic: 0, roughness: 0.2, rim: 2.2 });
    }
    if(S.active('phase')) r.draw('sphere', { pos: pp, scale: rad * 0.9, color: '#c8a2ff', emissive: '#c8a2ff', emissiveStrength: 0.3, alpha: 0.1, blend: true, rim: 1.6 });
    if(S.active('magnet')) r.draw('thintorus', { pos: V.add(pp, [0, 0.3, 0]), rot: [0, w.t * 3, 0], scale: [rad * 2.2, 1, rad * 2.2], color: '#39ff88', emissive: '#39ff88', emissiveStrength: 1.2, alpha: 0.4, blend: true });
    if(S.active('warp') || S.frozen()){
      const c = S.frozen() ? '#7fe8ff' : '#ffd700';
      r.draw('thintorus', { pos: pp, rot: [0, -w.t * 1.5, 0], scale: [rad * 5, 1, rad * 5], color: c, emissive: c, emissiveStrength: 0.8, alpha: 0.22, blend: true });
    }
    const dp = S.decoy();
    if(dp){
      r.draw('sphere', { pos: V.add(dp, [0, 1.2 + Math.sin(w.t * 4) * 0.2, 0]), scale: 1.4, color: '#e8f0ff', emissive: '#bfe6ff', emissiveStrength: 1.2, alpha: 0.35 + 0.15 * Math.sin(w.t * 12), blend: true, rim: 1.6 });
      r.draw('thintorus', { pos: V.add(dp, [0, 0.2, 0]), rot: [0, w.t * 2, 0], scale: [5, 1, 5], color: '#e8f0ff', emissive: '#bfe6ff', emissiveStrength: 1, alpha: 0.3, blend: true });
    }
  };
  // Bottom centre: what is running (with time left) and what fires next.
  S.hud = function(){
    const H = hud, g = H.ctx, Wd = H.W, Ht = H.H;
    const cx = Wd / 2, y = Ht - 22 - (o.hudLift || 0);
    let x = cx;
    const act = Object.keys(on).filter(k => on[k] > 0);
    const items = act.map(k => ({ k, txt: def(k).label, c: def(k).color, frac: on[k] / def(k).t }));
    const keyName = inp.device === 'pad' ? 'LB' : inp.device === 'touch' ? '⚡' : (o.keyName || 'V');
    if(queue.length) items.push({ next: true, txt: keyName + ' · ' + def(queue[0]).label + (queue.length > 1 ? '  +' + (queue.length - 1) : ''), c: def(queue[0]).color });
    if(!items.length) return;
    g.save();
    g.font = '700 10px "Orbitron", "Rajdhani", sans-serif';
    const widths = items.map(it => g.measureText(it.txt).width + 22);
    const total = widths.reduce((a, b) => a + b, 0) + (items.length - 1) * 8;
    x = cx - total / 2;
    items.forEach((it, i) => {
      const wd = widths[i];
      g.globalAlpha = 0.9;
      g.fillStyle = 'rgba(4,10,20,0.72)'; g.fillRect(x, y - 13, wd, 24);
      g.strokeStyle = it.c; g.lineWidth = it.next ? 1.5 : 1; g.strokeRect(x + 0.5, y - 12.5, wd - 1, 23);
      if(it.frac != null){ g.fillStyle = it.c; g.fillRect(x + 1, y + 8, (wd - 2) * clamp(it.frac, 0, 1), 2); }
      g.globalAlpha = 1;
      H.text(x + wd / 2, y - 1, it.txt, { size: 10, color: it.next ? '#ffffff' : it.c, blur: 4 });
      x += wd + 8;
    });
    g.restore();
    if(flashT > 0){
      // A tint at the screen's edge, not a wash over the middle of it.
      const gr = g.createRadialGradient(Wd / 2, Ht / 2, Math.min(Wd, Ht) * 0.35, Wd / 2, Ht / 2, Math.max(Wd, Ht) * 0.75);
      gr.addColorStop(0, 'rgba(0,0,0,0)'); gr.addColorStop(1, flashC);
      g.save(); g.globalAlpha = flashT * 0.55; g.fillStyle = gr; g.fillRect(0, 0, Wd, Ht); g.restore();
    }
    H.avoid.push([cx - total / 2 - 10, y - 20, cx + total / 2 + 10, Ht]);
  };
  S.state = () => ({ queue: queue.slice(), on: Object.keys(on).filter(k => on[k] > 0), missiles: missiles.length, nextAt });
  return S;
}

// ══════════════════════════════════════════════
//  🌍 WORLD PRESETS
// ══════════════════════════════════════════════
const SPACE = {
  env:  { theme: 5, zenith: '#05060f', horizon: '#160d2a', ground: '#03040b', intensity: 1, stars: [1, 1, 1, 1] },
  fog:  { color: '#06050f', density: 0.0009 },
  sun:  { dir: [-0.55, -0.28, -0.78], color: '#fff0da', intensity: 2.4 },
  grade:{ exposure: 1.0, bloom: 0.55, threshold: 1.35, knee: 0.5, radius: 1.0, vignette: 0.36, aberration: 0.25, grain: 0.016, scanline: 0, saturation: 1.12 },
  ease: 1
};
const NIGHT = {
  env:  { zenith: '#050818', horizon: '#3a1050', ground: '#05060f', intensity: 1.3 },
  fog:  { color: '#0d0722', density: 0.0068 },
  sun:  { dir: [-0.4, -0.85, -0.5], color: '#6f7dff', intensity: 0.75 },
  grade:{ exposure: 0.97, bloom: 0.45, threshold: 1.55, knee: 0.5, radius: 0.95, vignette: 0.42, aberration: 0.35, grain: 0.024, scanline: 0.01, saturation: 1.12 },
  ease: 1
};

// Opens an open-world round: the world (floating origin on, far plane out),
// the HUD, the FX, the input, and the clean-up chained onto stopGame().
function owBegin(cfg){
  cfg = cfg || {};
  const base = cfg.preset === 'night' ? NIGHT : SPACE;
  const merged = {
    env: Object.assign({}, base.env, cfg.env), fog: Object.assign({}, base.fog, cfg.fog),
    sun: Object.assign({}, base.sun, cfg.sun), grade: Object.assign({}, base.grade, cfg.grade), ease: 1,
    // 🌍 A World theme dresses the ground worlds' cities (THE ENDLESS CITY);
    // a world in deep space keeps its own sky.
    noLook: base !== NIGHT
  };
  const w = begin3d(merged);
  if(!w) throw new Error('no 3D surface');
  w.origin = true;
  w.far = cfg.far || 6000;
  w.near = cfg.near || 0.3;
  if(cfg.space) w.r.spaceSky(cfg.space);
  setControls(null);
  const hud = makeHud(w);
  const fx = makeFx(w);
  const inp = makeInput(cfg.input);
  const prev = onStopGame;
  onStopGame = () => { try{ inp.dispose(); }catch(e){} try{ hud.dispose(); }catch(e){} if(prev) prev(); };
  return { w, r: w.r, hud, fx, inp };
}

// The round clock, through gTimer like every mission's (so the pause shim and
// the Time Dilator see it).
function owClock(secs, onEnd, onTick){
  let left = Math.round(secs * (typeof getTimeModifier === 'function' ? getTimeModifier() : 1));
  const el = document.getElementById('g-time');
  if(el) el.textContent = left;
  gTimer = setInterval(() => {
    left--;
    if(el) el.textContent = Math.max(0, left);
    if(left <= 5 && left > 0) snd('tick');
    if(onTick) onTick(left);
    if(left <= 0){ clearInterval(gTimer); gTimer = null; onEnd(); }
  }, 1000);
  const add = n => { left += n; if(el) el.textContent = left; };
  // ⏳ The Time Dilator's exact door (see THE ROUND CLOCK): the seconds are
  // really added, rather than the clock being held for three ticks.
  if(typeof registerRoundClock === 'function') registerRoundClock(add);
  return { get left(){ return left; }, add };
}

P.owKit = { V, TAU, wrapAng, ease, ihash, basisYPR, basisLook, makeInput, makeHud, makeField, makeFx, makeDust,
            plume, drawBodies, drawFloor, owBegin, owClock, SPACE, NIGHT, touchButtons, makeSpecials, SPECIAL_DEFS,
            QT, attFrom, attTurn, attSpin, attLevelRoll, attElevate, attFace, basisQ, yawOf, elevOf };

})();


// ══════════════════════════════════════════════
//  🚀 NEON NEBULA · OPEN WORLD — NEBULA FRONTIER
// ══════════════════════════════════════════════
// The classic round is a corridor; this is the whole sky. A free-flying
// interceptor (chase camera, mouse or stick steering, boost, barrel rolls)
// over an endless asteroid belt under a nebula, a ringed giant hanging in the
// distance. Raider squadrons find you wherever you are; capital frigates sit
// in the belt with six turrets each and a shielded reactor — strip the
// turrets, the shield falls, kill the core and the ship goes up in a chain of
// explosions. Lasers, homing missiles with lock-on, pickups in the rocks.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit) return;
const { V, TAU, ease, basisYPR, basisLook, makeField, makeDust, plume, drawBodies, owBegin, owClock,
        attFrom, attTurn, attLevelRoll, basisQ, yawOf, elevOf, makeSpecials } = P.owKit;
const { mine, clamp, runLoop, ENEMY_PAINT, ENEMY_FINISH, foeLook } = P.kit;
const FM = window.PI3D_ENGINE.mesh.FRIGATE_MOUNTS;
const rr = (a, b) => a + Math.random() * (b - a);

P.ow.nebula = function(){
  const G = owBegin({
    space: { seed: 7, a: '#8a1fb8', b: '#0e7fae', c: '#ff4fa0', dir: [0.3, 0.18, -0.94], amount: 1.0, dust: 0.85, galaxy: 1.0 },
    input: { mouseSteer: true, mouseGain: 1.15 },
    far: 14000, near: 0.3
  });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('LEFT STICK: FLY · RIGHT: FIRE · ⟲ MISSILE · BOOST · LB / ⚡: SPECIAL',
                 'MOUSE / WASD: FLY · CLICK / SPACE: FIRE · RIGHT-CLICK / F: MISSILE · SHIFT: BOOST · Q/E: ROLL · V: SPECIAL');
  inp.altLabel = 'MSL';

  // ── STATE ──
  const SC = 1.6;                                   // ship scale
  // `q` is the flight attitude (see ✈️ ATTITUDE in the kit); yaw and pitch are
  // read back off it each frame for anything that wants a heading.
  const ship = { p: [0, 0, 0], q: attFrom(0, 0), yaw: 0, pitch: 0, bank: 0, roll: 0, speed: 44, hull: 100, energy: 100,
                 cool: 0, weapon: 1, missiles: 6, mRegen: 0, inv: 0, hit: 0, dead: false };
  let B = basisQ(ship.q, 0);
  let score = 0, kills = 0, chain = 0, bestChain = 0, turretsKilled = 0, frigatesKilled = 0, over = false;
  let camOff = [0, 2.6, 9.5], camTgt = [0, 0, -26], camUp = [0, 1, 0];
  const bolts = [], flak = [], foes = [], missiles = [];
  let frig = null, frigTimer = 2, squadT = 6;
  let lockT = 0, lockOn = null, objective = '', objT = 0, msgT = 0, msg = '';
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#28d8ff,#7ff7ff)';

  const say = (s, t) => { msg = s; msgT = t || 2.6; };

  // ── THE BELT ──
  // Rocks in 3D cells. Density thickens toward the ecliptic (y ≈ 0) and in
  // broad clumps across it, so there is open space to fly fast through and
  // thick rubble to hide in. A rare cell carries a mountain of a rock.
  const ROCKS = ['rock', 'rock2', 'rock3', 'rock4', 'rock5', 'rock6'];
  const TINTS = ['#6b5d52', '#5f5a56', '#73614f', '#57524e', '#6e6258', '#655a50'];
  const belt = makeField({
    cell: 150, dims: 3, seed: 20261001, radius: 760,
    gen(cx, cy, cz, g){
      const items = [];
      const yc = cy * 150;
      const band = Math.exp(-Math.pow(yc / 520, 2));
      const clump = 0.55 + 0.45 * Math.sin(cx * 0.31 + cz * 0.23) * Math.cos(cz * 0.19 - cx * 0.11 + cy * 0.4);
      const n = Math.floor(g() * (1.5 + 10 * band * clump * clump));
      for(let i = 0; i < n; i++){
        const p = [(cx + g()) * 150, (cy + g()) * 150, (cz + g()) * 150];
        if(V.len(p) < 90) continue;
        const s = 1.2 + Math.pow(g(), 4.2) * 30;
        items.push({ t: 'rock', p, s, g: ROCKS[(g() * 6) | 0], c: TINTS[(g() * 6) | 0],
                     rot: [g() * 6, g() * 6, g() * 6], spin: [(g() - 0.5) * 0.25, (g() - 0.5) * 0.25, 0], hp: Math.ceil(s * 0.6) });
      }
      if(g() < 0.035 * (0.4 + band)){
        const p = [(cx + 0.5) * 150, (cy + 0.5) * 150, (cz + 0.5) * 150];
        if(V.len(p) > 300) items.push({ t: 'rock', p, s: 55 + g() * 70, g: ROCKS[(g() * 6) | 0], c: TINTS[(g() * 6) | 0],
                                       rot: [g() * 6, g() * 6, 0], spin: [0.01, 0.02, 0], hp: 1e9, big: true });
      }
      if(g() < 0.16){
        const roll = g();
        items.push({ t: 'pick', p: [(cx + g()) * 150, (cy + g()) * 150, (cz + g()) * 150],
                     kind: roll < 0.4 ? 'orb' : roll < 0.72 ? 'repair' : 'msl', s: 1.6, ph: g() * 6 });
      }
      return items;
    }
  });

  // ── DISTANT BODIES ──
  const BODIES = [
    { kind: 'gas', off: [2600, -700, -6400], size: 3000, color: '#c8874c', ring: 2.3, ringRot: [0.38, 0, 0.42], rot: [0.38, 0, 0.42], halo: '#ffb070', par: 0.004 },
    { kind: 'moon', off: [-3100, 900, -5200], size: 300, color: '#9a8f86', v: '3', par: 0.006 },
    { kind: 'sun', off: [-3200, 1300, 3600], size: 220, color: '#fff2da', gain: 3.4, par: 0 }
  ];

  const dust = makeDust(70, 80);

  // ── CONTROLS ──
  const SHOT_SP = 340;
  function shoot(){
    if(ship.cool > 0 || over || ship.dead) return;
    ship.cool = (ship.weapon >= 3 ? 0.075 : 0.11) * (SP.active('overdrive') ? 0.5 : 1);
    snd('shoot', { semi: 3 + ship.weapon * 2 });
    // ✨ v59 · out of the ship's two cannons (gunR/L) and, at level 2+, the nose
    const guns = ship.weapon >= 2 ? [-0.19, 0.19, 0] : [-0.19, 0.19];
    for(const gx of guns){
      const off = gx === 0 ? [0, -0.03, -1.17] : [gx, -0.05, -0.6];
      const p = V.add(ship.p, V.add(V.add(V.mul(B.r, off[0] * SC), V.mul(B.u, off[1] * SC)), V.mul(B.f, -off[2] * SC)));
      const v = V.mul(B.f, SHOT_SP + ship.speed);
      bolts.push({ p, v, life: 1.15, mine: true });
      fx.flash(V.madd(p, B.f, 0.8), '#ffb766', 0.35, 0.06);
    }
  }
  function fireMissile(){
    if(over || ship.dead) return;
    if(ship.missiles <= 0){ snd('deny'); say('NO MISSILES', 1.2); return; }
    if(!lockOn || lockT < 1){ snd('deny'); say('NO LOCK — hold a target in the reticle', 1.6); return; }
    ship.missiles--;
    snd('missile');
    const side = (ship.missiles % 2) ? 1 : -1;
    // ✨ v59 · off the under-wing pylon (the r5 ship's misR / misL anchors)
    const p = V.add(ship.p, V.add(V.add(V.mul(B.r, side * 0.64 * SC), V.mul(B.u, -0.148 * SC)), V.mul(B.f, -0.07 * SC)));
    missiles.push({ p, v: V.mul(B.f, ship.speed + 40), tgt: lockOn, life: 6, smoke: 0 });
  }

  // ── FOES ──
  // 🛩 v60 · SQUADRONS, FLOWN LIKE FIGHTERS.
  // A raider used to steer, every frame, at a point just ahead of the player's
  // nose — so whatever the player did, it turned to match. Trying to get on one's
  // tail started a turning circle that never ended (two ships chasing each
  // other's six), and the swirl made them impossible to read. They now fly
  // ATTACK RUNS, the way a fighter pass actually works:
  //   FORM    the squadron closes in a V on its leader's wing, guns cold
  //   ATTACK  one pass at the player, leading the shot, firing inside range
  //   BREAK   past the player (or too close): a hard turn AWAY from your nose,
  //           in a direction fixed when the break starts
  //   EXTEND  straight out for a few seconds, slower than your cruise, paying
  //           you no attention — THIS is the moment to get on its tail
  //   TURN    a wide, constant-rate turn back for the next pass
  // Every turn is a fixed RATE (rotateToward), never an exponential snap, so a
  // raider flies the same arc every time and you can see where it is going.
  // On 🔵 Safe Mode and 🟢 Stable Core the next squadron launches only once
  // every raider of the last one is down; the hotter tiers stack them.
  const HOT = currentDifficultyTier === 'overclocked' || currentDifficultyTier === 'meltdown';
  // One hit downs a raider on the gentle tiers; the hot ones armour them.
  const RAIDER_HP = currentDifficultyTier === 'meltdown' ? 3 : HOT ? 2 : 1;
  const spdK = clamp(diff, 0.7, 1.7);
  const AI = {
    attackSp: 58 * spdK,
    extendSp: 40 * spdK,           // under the player's 46 cruise on Stable: a tail you can catch
    turnAttack: (HOT ? 1.15 : 0.9) * Math.sqrt(spdK),
    turnBreak: (HOT ? 1.45 : 1.15) * Math.sqrt(spdK),
    turnBack: (HOT ? 0.95 : 0.75) * Math.sqrt(spdK),
    breakT: 1.15,
    extendT: HOT ? 2.2 : 3.2,
    fireGap: HOT ? [0.9, 1.8] : [1.4, 2.6]
  };
  const RAIDER_R = 2.5;            // hit sphere: the wingtips at the 2.3 draw scale
  const SQUAD_BREATHER = 5;        // seconds between one squadron's end and the next
  let squadN = 0, hitMark = 0, hitKill = false;
  // Turns unit vector `a` toward unit vector `b` by at most `maxAng` radians.
  function rotateToward(a, b, maxAng){
    const d = clamp(V.dot(a, b), -1, 1), ang = Math.acos(d);
    if(ang <= maxAng || ang < 1e-5) return V.copy(b);
    // Opposite vectors have no unique plane: turn about world up (or the side).
    let ax = V.cross(a, b);
    if(V.len(ax) < 1e-5) ax = Math.abs(a[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0];
    ax = V.norm(ax);
    const c = Math.cos(maxAng), sn = Math.sin(maxAng);
    const axa = V.cross(ax, a);
    return V.norm(V.add(V.add(V.mul(a, c), V.mul(axa, sn)), V.mul(ax, V.dot(ax, a) * (1 - c))));
  }
  function spawnSquad(){
    squadN++;
    const n = 2 + ((Math.random() * (diff > 1.2 ? 3 : 2)) | 0);
    // In front of the player and off to one side, so the squadron is seen
    // coming in rather than discovered on the radar behind you.
    const dir = V.norm(V.add(V.mul(B.f, rr(0.7, 1.2)), [rr(-0.8, 0.8), rr(-0.25, 0.25), rr(-0.8, 0.8)]));
    const lead = V.madd(ship.p, dir, rr(480, 620));
    const f0 = V.norm(V.sub(ship.p, lead));
    const right = V.norm(V.cross(f0, [0, 1, 0]));
    for(let i = 0; i < n; i++){
      // A V: the leader at the point, wingmen alternating left and right.
      const k = Math.ceil(i / 2), side = i % 2 ? -1 : 1;
      const off = i ? [side * 15 * k, -2 * k, 13 * k] : [0, 0, 0];      // right, up, back
      const p = V.add(lead, V.add(V.add(V.mul(right, off[0]), [0, off[1], 0]), V.mul(f0, -off[2])));
      foes.push({ p, prev: V.copy(p), f: V.copy(f0), hp: RAIDER_HP, hp0: RAIDER_HP, sq: squadN, slot: i, off,
                  mode: i ? 'form' : 'attack', modeT: 0, fireT: rr(1.2, 2.4), ph: Math.random() * 6,
                  bank: 0, flash: 0, smokeT: 0, dmg: 0, sp: AI.attackSp, breakDir: null, extDir: null, vel: V.mul(f0, AI.attackSp) });
    }
    say('⚠ SQUADRON ' + squadN + ' INBOUND — ' + n + ' RAIDERS', 2.4);
    snd('alarm');
  }
  // A squadron's raiders still flying.
  const squadLeft = sq => foes.reduce((a, f) => a + (f.sq === sq ? 1 : 0), 0);
  function spawnFrigate(){
    const a = Math.random() * TAU;
    const fwdH = V.norm([B.f[0], 0, B.f[2]]);
    const dir = V.norm(V.add(V.mul(fwdH, 0.6), [Math.cos(a), 0, Math.sin(a)]));
    const p = V.add(V.madd(ship.p, dir, rr(1300, 1700)), [0, rr(-120, 120), 0]);
    const yaw = Math.atan2(-dir[2], dir[0]);      // broadside-on to the approach
    const S = 115;
    const fb = basisYPR(yaw, 0, 0);
    const toW = q => V.add(p, V.add(V.add(V.mul(fb.r, q[0] * S), V.mul(fb.u, q[1] * S)), V.mul(fb.f, -q[2] * S)));
    frig = { p, yaw, S, fb, toW, drift: 3.5, hp: 1, shield: true, reactorHp: 30, dying: 0, boom: 0,
             turrets: FM.turrets.map(q => ({ q, hp: 8, cool: rr(1, 3), flash: 0, dead: false })),
             reactor: { q: FM.reactor, flash: 0 } };
    objective = 'ENGAGE — destroy the frigate\'s 6 turrets to collapse the reactor shield';
    objT = 0;
    say('🛰 CAPITAL SHIP DETECTED', 2.6);
  }
  const frigPos = q => frig.toW(q);

  function award(pts, at, label, col){
    chain++;
    bestChain = Math.max(bestChain, chain);
    const bonus = Math.min(chain, 10) * 4;
    score += pts + bonus;
    setLive(score);
    if(at) w.pop(at, '+' + (pts + bonus) + (label ? ' ' + label : ''), col || '#ffd27a', { size: 14 });
  }
  function killFoe(i, rammed){
    const f = foes[i];
    foes.splice(i, 1);
    if(!rammed){
      kills++;
      fx.explode(f.p, 2.2, { color: '#ff5a2a' });
      snd('explode');
      award(60, V.add(f.p, [0, 3, 0]), '', '#ff9a6a');
      if(kills % 5 === 0) dropPick(f.p, 'orb');
      hitMark = 0.32; hitKill = true;
    }
    if(lockOn === f){ lockOn = null; lockT = 0; }
    // The squadron's last raider: a bonus for the clean sweep, and on the
    // gentle tiers the signal for the next squadron (see SQUADRONS below).
    if(!squadLeft(f.sq)){
      if(!rammed) award(100, V.add(f.p, [0, 6, 0]), 'SQUADRON DOWN', '#ffd700');
      squadT = SQUAD_BREATHER;
      say(HOT ? '✅ SQUADRON ' + f.sq + ' DOWN' : '✅ SQUADRON ' + f.sq + ' DOWN — the next one launches in ' + SQUAD_BREATHER + 's', 2.6);
      snd('success');
    }
  }
  // A raider hit that did not bring it down: it flashes, trails smoke from
  // then on, and the reticle ticks — so a hit never passes unnoticed.
  function hurtFoe(f, dmg, at){
    f.hp -= dmg; f.flash = 0.14; f.dmg = 1 - Math.max(0, f.hp) / f.hp0;
    fx.sparks(at, 9, '#ffd8a0', 1.1, 14);
    snd('hit', { semi: 4 });
    hitMark = 0.2; hitKill = false;
  }
  function dropPick(p, kind){ pickups.push({ p: V.copy(p), kind, s: 1.6, ph: 0, life: 25 }); }
  const pickups = [];

  function damageTurret(t, dmg, at){
    t.hp -= dmg; t.flash = 0.15;
    fx.sparks(at, 6, '#ffd28a', 1.2, 14);
    if(t.hp <= 0 && !t.dead){
      t.dead = true;
      turretsKilled++;
      const tp = frigPos(t.q);
      fx.explode(tp, 4.2, { color: '#ff7a2a', debrisGeo: 'slab', debrisColor: '#4a4f58' });
      snd('bigExplode');
      award(120, V.add(tp, [0, 5, 0]), 'TURRET', '#ffb36a');
      const left = frig.turrets.filter(x => !x.dead).length;
      if(lockOn === t){ lockOn = null; lockT = 0; }
      if(left === 0){
        frig.shield = false;
        objective = 'REACTOR EXPOSED — destroy the core';
        say('🛡 SHIELD DOWN — HIT THE REACTOR', 3);
        snd('success');
      }else say('TURRET DESTROYED · ' + left + ' remaining', 2);
    }
  }
  function damageReactor(dmg, at){
    if(!frig || frig.shield || frig.dying) return;
    frig.reactorHp -= dmg; frig.reactor.flash = 0.12;
    fx.sparks(at, 8, '#bff6ff', 1.4, 16);
    if(frig.reactorHp <= 0){
      frig.dying = 2.4; frig.boom = 0;
      award(400, V.add(frig.p, [0, 20, 0]), 'REACTOR', '#7ff7ff');
      snd('bigExplode');
      say('💥 REACTOR CRITICAL', 2.4);
      if(lockOn && lockOn.reactor) { lockOn = null; lockT = 0; }
    }
  }

  function takeHit(dmg, at){
    if(ship.dead || ship.inv > 0) return;
    if(SP.shielded()){ fx.sparks(at || ship.p, 8, '#c084fc', 1, 12); return; }
    ship.hull -= dmg;
    ship.hit = 0.35;
    chain = 0;
    w.kick(0.9 + dmg * 0.04);
    snd(ship.hull <= 0 ? 'bigExplode' : 'hurt');
    if(at) fx.sparks(at, 10, '#ff7a6a', 1, 14);
    if(ship.hull <= 0 && survivedFatal()){
      ship.hull = 55; ship.inv = 1.5;
      fx.explode(ship.p, 2, { color: '#a855f7', debris: 0 });
      w.pop(V.add(ship.p, [0, 3, 0]), 'SHIELD ABSORBED', '#c084fc', { size: 18, life: 1.4 });
    }
    bar.style.width = Math.max(0, ship.hull) + '%';
    if(ship.hull <= 0){
      ship.dead = true;
      fx.explode(ship.p, 3.2, { color: '#ff7a2a' });
      w.kick(2.2);
      gLater(() => end('destroyed'), 1400);
    }
  }

  const clock = owClock(180, () => end('clock'));

  // ⚡ v60 · SPECIALS (see the kit): the 2D Nebula's four — Smart Missile,
  // Shield Burst, Time Warp, Nova — and two new ones, EMP Pulse and
  // Overcharge. One every 200 points, and a plasma orb banks one once the
  // guns are at full power, as the 2D game's fourth orb does.
  const SP = makeSpecials(G, {
    kinds: ['smart', 'shield', 'warp', 'nova', 'emp', 'overdrive'],
    every: 200, novaR: 160, bubbleR: 2.6, missileSpeed: 220,
    player: () => ship.p,
    targets: () => {
      const T = foes.map(f => ({ p: f.p, r: RAIDER_R, obj: f }));
      if(frig && !frig.dying){
        for(const t of frig.turrets) if(!t.dead) T.push({ p: frigPos(t.q), r: 5, obj: t });
        if(!frig.shield) T.push({ p: frigPos(frig.reactor.q), r: 8, obj: frig.reactor });
      }
      return T;
    },
    hit: (obj, dmg, at) => {
      const j = foes.indexOf(obj);
      if(j >= 0){ hurtFoe(obj, dmg, at); if(obj.hp <= 0){ const k = foes.indexOf(obj); if(k >= 0) killFoe(k); } return; }
      if(frig && obj === frig.reactor) damageReactor(Math.min(dmg, 8), at);
      else if(frig && obj.q && !obj.dead) damageTurret(obj, Math.min(dmg, 8), at);
    },
    clearFire: () => { flak.length = 0; },
    heal: k => { ship.hull = Math.min(100, ship.hull + 100 * k); bar.style.width = ship.hull + '%'; }
  });

  // Test hooks (console / harness only): stage a fight without flying to it.
  P.owDebug = {
    state: () => ({ score, kills, hull: ship.hull, foes: foes.length, squad: squadN, squadT: +squadT.toFixed(2), modes: foes.map(f => f.mode),
                    hp: foes.map(f => f.hp), dists: foes.map(f => Math.round(V.len(V.sub(f.p, ship.p)))),
                    frig: !!frig, turretsLeft: frig ? frig.turrets.filter(t => !t.dead).length : 0,
                    reactor: frig ? frig.reactorHp : 0, missiles: ship.missiles, lock: lockT, rocks: belt.map.size, fx: fx.list.length, p: ship.p.map(Math.round),
                    nose: B.f.map(v => +v.toFixed(3)), up: B.u.map(v => +v.toFixed(3)) }),
    frigateAhead(d){
      spawnFrigate();
      frig.p = V.add(V.madd(ship.p, B.f, d || 240), [0, -20, 0]);
      const yaw = ship.yaw + Math.PI / 2;
      frig.fb = basisYPR(yaw, 0, 0); frig.yaw = yaw; frig.drift = 0;
    },
    squad(){ spawnSquad(); for(const f of foes){ f.p = V.add(V.madd(ship.p, B.f, 90 + Math.random() * 60), [Math.random() * 40 - 20, Math.random() * 20 - 10, Math.random() * 40 - 20]); f.prev = V.copy(f.p); } },
    killAll(){ for(let i = foes.length - 1; i >= 0; i--){ if(i < foes.length) killFoe(i); } },
    specials: () => SP.state(),
    grant(k){ return SP.grant(k); },
    useSpecial(){ return SP.use(); },
    // Parks raider k `d` metres ahead, side-on, and holds every raider still (photo tests).
    pose(k, d, yawDeg){
      dbgFreeze = true;
      const f = foes[k || 0]; if(!f) return false;
      f.p = V.add(V.madd(ship.p, B.f, d || 22), V.mul(B.u, -1.5)); f.prev = V.copy(f.p);
      const a = (yawDeg || 70) * Math.PI / 180;
      f.f = V.norm(V.add(V.mul(B.r, Math.cos(a)), V.mul(B.f, -Math.sin(a)))); f.bank = 0.3;
      return true;
    },
    unfreeze(){ dbgFreeze = false; },
    // Fires one bolt straight at raider k from 60 m behind the ship's line, for hit tests.
    boltAt(k, lead){
      const f = foes[k || 0]; if(!f) return false;
      const from = V.madd(f.p, V.norm(V.sub(ship.p, f.p)), 60);
      const at = lead === false ? f.p : V.madd(f.p, f.vel || [0, 0, 0], 60 / SHOT_SP);
      bolts.push({ p: from, v: V.mul(V.norm(V.sub(at, from)), SHOT_SP), life: 1.2, mine: true });
      return true;
    },
    stripTurrets(){ if(frig) for(const t of frig.turrets) if(!t.dead) damageTurret(t, 99, frigPos(t.q)); },
    killReactor(){ if(frig){ frig.shield = false; damageReactor(999, frigPos(frig.reactor.q)); } },
    god(on){ ship.inv = on ? 1e9 : 0; },
    boom(d, s){ fx.explode(V.add(V.madd(ship.p, B.f, d || 30), V.mul(B.u, 1)), s || 3, { color: '#ff7a2a' }); },
    stop(){ ship.speed = 0; ship.inv = 1e9; }
  };

  function end(reason){
    if(over) return;
    over = true;
    owFinish('nebula', score, {
      '📡 Sortie': reason === 'clock' ? 'MISSION CLOCK EXPIRED' : 'INTERCEPTOR DESTROYED',
      '💥 Raiders Downed': kills,
      '🛰 Turrets Destroyed': turretsKilled,
      '🔥 Frigates Gutted': frigatesKilled,
      '⛓ Best Chain': bestChain + '×',
      '🛡 Hull Remaining': Math.max(0, Math.round(ship.hull)) + '%',
      '🏆 Score': score + ' PTS'
    });
  }

  // ── TARGETING ── the target nearest the reticle within the lock cone.
  function targetsEach(fn){
    for(const f of foes) fn(f, f.p, 3, '#ff4060', 'RAIDER');
    if(frig && !frig.dying){
      for(const t of frig.turrets) if(!t.dead) fn(t, frigPos(t.q), 5, '#ffb03a', 'TURRET');
      if(!frig.shield) fn(frig.reactor, frigPos(frig.reactor.q), 8, '#7ff7ff', 'REACTOR');
    }
  }
  function updateLock(dt){
    let best = null, bestA = 0.26;
    targetsEach((t, p) => {
      const d = V.sub(p, ship.p), l = V.len(d);
      if(l > 950 || l < 8) return;
      const a = Math.acos(clamp(V.dot(d, B.f) / l, -1, 1));
      if(a < bestA){ bestA = a; best = t; }
    });
    if(best && best === lockOn) lockT = Math.min(1, lockT + dt / 0.75);
    else { lockOn = best; lockT = best ? Math.min(lockT, 0.2) : 0; }
    if(lockT >= 1 && !updateLock.beeped){ updateLock.beeped = true; snd('node'); }
    if(lockT < 1) updateLock.beeped = false;
  }
  // Segment/sphere: did a bolt moving from a to b pass within rad of c?
  function segHit(a, b, c, rad){
    const ab = V.sub(b, a), ac = V.sub(c, a);
    const L2 = V.dot(ab, ab) || 1e-6;
    const t = clamp(V.dot(ac, ab) / L2, 0, 1);
    return V.d2(V.madd(a, ab, t), c) < rad * rad;
  }
  // Two things both moving in straight lines over one frame — a bolt a0→a1 and
  // a raider f0→f1: their gap is linear in t, so the closest approach has a
  // closed form. Exact for a crossing shot, whatever the frame rate.
  function sweptHit(a0, a1, f0, f1, rad){
    const d0 = V.sub(a0, f0);
    const dv = V.sub(V.sub(a1, a0), V.sub(f1, f0));
    const vv = V.dot(dv, dv);
    const t = vv > 1e-9 ? clamp(-V.dot(d0, dv) / vv, 0, 1) : 0;
    const g = V.madd(d0, dv, t);
    return V.dot(g, g) < rad * rad;
  }

  // ── RAIDER FLIGHT ── see SQUADRONS, FLOWN LIKE FIGHTERS (with spawnSquad).
  function setMode(f, mode){
    f.mode = mode; f.modeT = 0;
    const toP = V.sub(ship.p, f.p), dist = V.len(toP) || 1, dirP = V.mul(toP, 1 / dist);
    if(mode === 'break'){
      // Away from the player's line of fire: the side of the player's nose the
      // raider is already on, so a break never crosses back through the guns.
      const rel = V.sub(f.p, ship.p);
      let lat = V.sub(rel, V.mul(B.f, V.dot(rel, B.f)));
      if(V.len(lat) < 4) lat = V.cross(B.f, [0, f.slot % 2 ? -1 : 1, 0]);
      f.breakDir = V.norm(V.add(V.add(V.mul(f.f, 0.45), V.mul(V.norm(lat), 0.9)), [0, rr(-0.15, 0.3), 0]));
    }else if(mode === 'extend'){
      f.extDir = V.norm(V.add(V.mul(f.f, 0.65), V.mul(dirP, -0.55)));
    }
  }
  let dbgFreeze = false;
  function raiders(dt){
    if(dt <= 0 || dbgFreeze) return;
    const leaderOf = sq => foes.find(x => x.sq === sq && x.slot === 0 && x.mode !== 'form');
    for(let i = foes.length - 1; i >= 0; i--){
      const f = foes[i];
      f.prev = V.copy(f.p);
      f.flash = Math.max(0, f.flash - dt);
      f.modeT += dt;
      const toP = V.sub(ship.p, f.p), dist = V.len(toP) || 1, dirP = V.mul(toP, 1 / dist);
      let want = f.f, rate = AI.turnAttack, speed = AI.attackSp;
      if(f.mode === 'form'){
        // On the leader's wing until the leader breaks; then each wingman makes
        // its own pass, a beat apart, so they arrive one after another.
        const L = leaderOf(f.sq);
        if(!L || L.mode !== 'attack'){ if(f.modeT > 0.35 + f.slot * 0.45 || !L) setMode(f, 'attack'); }
        if(L){
          const r = V.norm(V.cross(L.f, [0, 1, 0]));
          const slotP = V.add(L.p, V.add(V.add(V.mul(r, f.off[0]), [0, f.off[1], 0]), V.mul(L.f, -f.off[2])));
          const tgt = V.madd(slotP, L.f, 24);
          want = V.norm(V.sub(tgt, f.p));
          rate = AI.turnBreak;
          // Faster while it is out of position, so the V closes up and holds.
          speed = AI.attackSp * clamp(0.85 + V.len(V.sub(slotP, f.p)) / 60, 0.85, 1.35);
        }
      }else if(f.mode === 'attack'){
        // Lead the player by half the flight time — near enough to threaten,
        // never a perfect solution, so a jink still beats it.
        const tt = clamp(dist / (AI.attackSp + ship.speed), 0, 2.5);
        const aimP = V.madd(ship.p, B.f, ship.speed * tt * 0.5);
        want = V.norm(V.sub(aimP, f.p));
        const passed = V.dot(f.f, dirP) < 0.15 && dist < 240;
        if(dist < 60 || passed || f.modeT > 9) setMode(f, 'break');
      }else if(f.mode === 'break'){
        want = f.breakDir; rate = AI.turnBreak; speed = AI.attackSp * 1.05;
        if(f.modeT > AI.breakT) setMode(f, 'extend');
      }else if(f.mode === 'extend'){
        // Straight out, with a slow even weave — the same rhythm every time.
        // On your tail it weaves a little wider, but it never turns into you.
        const tail = V.dot(f.f, dirP) < -0.85 && dist < 260;
        const r = V.norm(V.cross(f.f, [0, 1, 0]));
        const weave = Math.sin(w.t * 1.25 + f.ph) * (tail ? 0.3 : 0.16);
        want = V.norm(V.madd(f.extDir, r, weave));
        rate = AI.turnBack; speed = AI.extendSp;
        if(f.modeT > AI.extendT + f.slot * 0.35 || dist > 900) setMode(f, 'turn');
      }else{  // 'turn'
        want = dirP; rate = AI.turnBack; speed = (AI.attackSp + AI.extendSp) / 2;
        if(V.dot(f.f, dirP) > 0.93) setMode(f, 'attack');
      }
      // ⏳ Time Warp slows every raider's turn and its speed alike.
      const wk = SP.warp();
      speed *= wk;
      const nf = rotateToward(f.f, want, rate * wk * dt);
      // Banked into the turn by its yaw RATE (cr[1] / dt), so the bank is the
      // same at any frame rate — a fixed rate gives a steady bank, which is
      // part of what makes the arc readable.
      const cr = V.cross(f.f, nf);
      f.bank += (clamp(cr[1] / dt * 0.65, -1.1, 1.1) - f.bank) * ease(dt, 0.18);
      f.f = nf;
      f.p = V.madd(f.p, f.f, speed * dt);
      f.vel = V.mul(f.f, speed);
      // Damaged raiders trail smoke: an armoured one that took a hit says so.
      if(f.dmg > 0){
        f.smokeT -= dt;
        if(f.smokeT <= 0){ f.smokeT = 0.045; fx.puff(V.madd(f.p, f.f, -1.6), '#3a3634', 0.5 + f.dmg * 0.5, 1.1, V.mul(f.f, -4)); }
      }
      // Guns: only on an attack pass, inside range, with the nose on you —
      // and never while an EMP has them jammed.
      f.fireT -= dt * wk;
      if(f.mode === 'attack' && f.fireT <= 0 && dist < 330 && !ship.dead && !SP.jammed()){
        if(V.dot(f.f, dirP) > 0.93){
          f.fireT = rr(AI.fireGap[0], AI.fireGap[1]) / Math.sqrt(spdK);
          const lead = V.madd(ship.p, B.f, ship.speed * dist / 170);
          flak.push({ p: V.madd(f.p, f.f, 1.2), v: V.mul(V.norm(V.sub(lead, f.p)), 170), life: 2.4, c: '#ff3a5a', dmg: 7 });   // ✨ v59 off the nose
          snd('enemyShot', { semi: -3 });
        }else f.fireT = 0.25;
      }
      // Ramming the player costs both of you.
      if(dist < 3.6 && !ship.dead){ takeHit(18, f.p); fx.explode(f.p, 2, {}); killFoe(i, true); continue; }
    }
    // Keep a squadron from flying through itself.
    for(let i = 0; i < foes.length; i++) for(let j = i + 1; j < foes.length; j++){
      const a = foes[i], b = foes[j], d = V.sub(a.p, b.p), l = V.len(d);
      if(l > 0.01 && l < 9){ const push = V.mul(d, (9 - l) / l * 0.5); a.p = V.add(a.p, push); b.p = V.sub(b.p, push); }
    }
  }

  // ── FRAME ──
  runLoop(dt => {
    if(over) return false;
    const I = inp.poll();
    w.dt = dt;
    if(dt > 0 && !ship.dead){
      // Flight. Mouse/stick deflection is a turn RATE (a joystick, not a
      // pointer the nose snaps to), with a soft centre so a resting hand flies
      // straight.
      const soft = v => Math.sign(v) * Math.pow(Math.max(0, Math.abs(v) - 0.06) / 0.94, 1.35);
      const sy = soft(I.ay);
      const yawRate = -soft(I.ax) * 1.6, pitchRate = -sy * 1.3;
      // ✨ v57 · No pitch limit: the stick turns the attitude about the
      // ship's own axes, so holding it flies a full loop. Once the pitch stick
      // is let go the wings settle back to the horizon (never mid-loop).
      ship.q = attTurn(ship.q, yawRate, pitchRate, dt);
      ship.q = attLevelRoll(ship.q, ease(dt, 0.3) * clamp(1 - Math.abs(sy) * 3, 0, 1));
      const nose = basisQ(ship.q, 0).f;
      ship.yaw = yawOf(nose); ship.pitch = elevOf(nose);
      ship.bank += (clamp(-yawRate * 0.5, -0.9, 0.9) - ship.bank) * ease(dt, 0.12);
      if(I.roll) ship.roll += I.roll * 6.2 * dt;
      else ship.roll += (Math.round(ship.roll / TAU) * TAU - ship.roll) * ease(dt, 0.18);
      const boosting = I.boost && ship.energy > 2;
      ship.energy = clamp(ship.energy + (boosting ? -28 : 13) * dt, 0, 100);
      const want = boosting ? 112 : I.brake ? 16 : 46;
      ship.speed += (want - ship.speed) * ease(dt, boosting ? 0.25 : 0.4);
      B = basisQ(ship.q, ship.bank + ship.roll);
      ship.p = V.madd(ship.p, B.f, ship.speed * dt);
      ship.cool -= dt; ship.inv = Math.max(0, ship.inv - dt); ship.hit = Math.max(0, ship.hit - dt);
      if(I.fire) shoot();
      if(I.altHit) fireMissile();
      SP.tick(dt, I, score);
      ship.mRegen += dt;
      if(ship.mRegen > 12){ ship.mRegen = 0; if(ship.missiles < 8){ ship.missiles++; } }
      // Missile lock.
      updateLock(dt);
    }

    // The belt follows the ship.
    belt.update(ship.p);

    // ── ROCK COLLISIONS ──
    if(dt > 0 && !ship.dead){
      belt.near(ship.p, it => {
        if(it.t === 'rock'){
          const rad = it.s * 0.46 + 1.1 * SC * 0.6;
          const d2 = V.d2(ship.p, it.p);
          if(d2 < rad * rad){
            const n = V.norm(V.sub(ship.p, it.p));
            ship.p = V.madd(it.p, n, rad + 0.1);
            const hitV = ship.speed;
            ship.speed = Math.min(ship.speed, 14);
            takeHit(clamp(hitV * 0.22, 6, 26), V.madd(ship.p, n, -1));
            fx.explode(V.madd(ship.p, n, -1.2), 0.8, { debris: 4, smoke: 1, ring: false, debrisGeo: 'rock2', debrisColor: '#5a5048' });
          }
        }else if(it.t === 'pick'){
          if(V.d2(ship.p, it.p) < 9 * 9) collect(it, true);
        }
      });
    }
    function collect(it, fromField){
      if(fromField) belt.kill(it); else it.dead = true;
      snd('powerup');
      if(it.kind === 'orb'){
        if(ship.weapon >= 3) SP.grant();
        else{ ship.weapon = Math.min(3, ship.weapon + 1); say('⚡ WEAPON LEVEL ' + ship.weapon, 2); }
        award(25, null);
      }
      else if(it.kind === 'repair'){ ship.hull = Math.min(100, ship.hull + 30); bar.style.width = ship.hull + '%'; say('🛠 HULL +30', 1.6); award(25, null); }
      else { ship.missiles = Math.min(8, ship.missiles + 3); say('🚀 MISSILES +3', 1.6); award(25, null); }
      fx.glowPop(it.p, it.kind === 'orb' ? '#ffd700' : it.kind === 'repair' ? '#39ff88' : '#ff6aa8', 2.4, 0.5);
    }
    for(let i = pickups.length - 1; i >= 0; i--){
      const pk = pickups[i];
      pk.life -= dt;
      if(pk.life <= 0 || pk.dead){ pickups.splice(i, 1); continue; }
      if(!ship.dead && V.d2(ship.p, pk.p) < 9 * 9){ collect(pk, false); pickups.splice(i, 1); }
    }

    // ── SQUADRONS ── (before the bolts: see sweptHit)
    if(dt > 0 && !ship.dead){
      if(HOT){
        // Overclock and Meltdown stack squadrons on a clock, as they always did.
        squadT -= dt;
        if(squadT <= 0 && foes.length < 7){ spawnSquad(); squadT = rr(16, 26) / diff; }
      }else if(!foes.length){
        // Safe Mode and Stable Core: one squadron at a time. The breather only
        // runs once the sky is clear, so the next one can never overlap.
        squadT -= dt;
        if(squadT <= 0){ spawnSquad(); squadT = SQUAD_BREATHER; }
      }
    }
    raiders(dt);

    // ── BOLTS ──
    for(let i = bolts.length - 1; i >= 0; i--){
      const b = bolts[i];
      const a = V.copy(b.p);
      b.p = V.madd(b.p, b.v, dt);
      b.life -= dt;
      let hit = b.life <= 0;
      if(!hit){
        // 🎯 v60 · SWEPT, against where the raider was AND where it is now. The
        // test used to be the bolt's path against the raider's position before
        // it moved — and it was drawn after it moved, a metre or more away at
        // 60 fps and several on a slow frame — so a bolt could be seen to pass
        // clean through a raider and do nothing.
        for(let j = foes.length - 1; j >= 0 && !hit; j--){
          const f = foes[j];
          if(sweptHit(a, b.p, f.prev, f.p, RAIDER_R)){
            hit = true;
            hurtFoe(f, SP.active('overdrive') ? 2 : 1, b.p);
            if(f.hp <= 0) killFoe(j);
          }
        }
      }
      if(!hit && frig && !frig.dying){
        for(const t of frig.turrets){
          if(t.dead) continue;
          const tp = frigPos(t.q);
          if(segHit(a, b.p, tp, 4.2)){ hit = true; damageTurret(t, 1, b.p); break; }
        }
        if(!hit){
          const rp = frigPos(frig.reactor.q);
          if(segHit(a, b.p, rp, frig.shield ? 11 : 6.5)){
            hit = true;
            if(frig.shield){ fx.sparks(b.p, 4, '#7ff7ff', 1, 10); frig.shieldFlash = 0.25; }
            else damageReactor(1, b.p);
          }
        }
        if(!hit){
          // The hull itself: a capsule along the keel.
          const bow = frigPos([0, 0, -0.5]), stern = frigPos([0, 0, 0.5]);
          const ab = V.sub(stern, bow), t = clamp(V.dot(V.sub(b.p, bow), ab) / V.dot(ab, ab), 0, 1);
          if(V.d2(V.madd(bow, ab, t), b.p) < 12 * 12){ hit = true; fx.sparks(b.p, 3, '#ffd8a0', 0.8, 8); }
        }
      }
      if(!hit){
        belt.near(b.p, it => {
          if(hit || it.t !== 'rock') return;
          if(V.d2(b.p, it.p) < (it.s * 0.5) * (it.s * 0.5)){
            hit = true;
            fx.sparks(b.p, 4, '#ffcf9a', 0.9, 10);
            if(!it.big){
              it.hp--;
              if(it.hp <= 0){
                belt.kill(it);
                fx.explode(it.p, Math.max(1, it.s * 0.35), { color: '#ff9a4a', debrisGeo: it.g, debrisColor: it.c, debris: Math.min(10, 3 + (it.s | 0)), ring: it.s > 6 });
                snd('brick');
                award(it.s > 8 ? 20 : 8, null);
              }
            }
          }
        });
      }
      if(hit) bolts.splice(i, 1);
    }

    // ── MISSILES ──
    for(let i = missiles.length - 1; i >= 0; i--){
      const m = missiles[i];
      m.life -= dt;
      let tp = null;
      const tg = m.tgt;
      if(tg){
        if(foes.includes(tg)) tp = tg.p;
        else if(frig && !frig.dying && tg.q){
          if(tg === frig.reactor){ if(!frig.shield) tp = frigPos(tg.q); }
          else if(!tg.dead) tp = frigPos(tg.q);
        }
      }
      const sp = V.len(m.v);
      const want = tp ? V.norm(V.sub(tp, m.p)) : V.mul(m.v, 1 / (sp || 1));
      const cur = V.mul(m.v, 1 / (sp || 1));
      const nd = V.norm(V.lerp(cur, want, clamp(3.2 * dt, 0, 1)));
      m.v = V.mul(nd, Math.min(210, sp + 160 * dt));
      const a = V.copy(m.p);
      m.p = V.madd(m.p, m.v, dt);
      m.smoke -= dt;
      if(m.smoke <= 0){ m.smoke = 0.03; fx.puff(m.p, '#8a8f99', 0.35, 0.9, V.mul(m.v, -0.02)); }
      let boom = m.life <= 0;
      if(tp && segHit(a, m.p, tp, 4)) boom = true;
      if(boom){
        fx.explode(m.p, 2.6, { color: '#ff8a3a' });
        snd('explode');
        if(tp){
          if(foes.includes(tg)){ tg.hp -= 6; const j = foes.indexOf(tg); if(tg.hp <= 0 && j >= 0) killFoe(j); }
          else if(tg === (frig && frig.reactor)) damageReactor(6, m.p);
          else if(tg.q && !tg.dead) damageTurret(tg, 6, m.p);
        }
        missiles.splice(i, 1);
      }
    }

    // ── THE FRIGATE ──
    if(!frig){ frigTimer -= dt; if(frigTimer <= 0 && !ship.dead) spawnFrigate(); }
    if(frig){
      frig.p = V.madd(frig.p, frig.fb.f, frig.drift * dt);
      frig.toW = q => V.add(frig.p, V.add(V.add(V.mul(frig.fb.r, q[0] * frig.S), V.mul(frig.fb.u, q[1] * frig.S)), V.mul(frig.fb.f, -q[2] * frig.S)));
      frig.shieldFlash = Math.max(0, (frig.shieldFlash || 0) - dt);
      if(!frig.dying){
        for(const t of frig.turrets){
          if(t.dead) continue;
          t.flash = Math.max(0, t.flash - dt);
          t.cool -= dt * SP.warp();
          const tp = frigPos(t.q);
          const d = V.sub(ship.p, tp), l = V.len(d);
          if(t.cool <= 0 && l < 520 && !ship.dead && !SP.jammed()){
            t.cool = rr(1.3, 2.4) / diff;
            const lead = V.madd(ship.p, B.f, ship.speed * l / 130);
            const dir = V.norm(V.sub(lead, tp));
            // ✨ v59 · out of a barrel tip (the turret's muzzleR/L, in turn), aimed the
            // way the turret is drawn: yawed on its deck, pitched part of the way
            const aimD = V.norm(V.sub(ship.p, tp)), up = frig.fb.u;
            const tb = basisLook(V.norm(V.madd(aimD, up, -V.dot(aimD, up) * 0.65)), up);
            t.bk = (t.bk || 0) + 1;
            const mz = V.add(tp, V.add(V.mul(tb.r, (t.bk % 2 ? 0.16 : -0.16) * 7.2), V.mul(tb.f, 0.86 * 7.2)));
            flak.push({ p: mz, v: V.mul(dir, 130), life: 4.5, c: '#ff8a2a', dmg: 9, big: true });
            fx.flash(mz, '#ffd8a0', 1.6, 0.1);
            snd('enemyShot', { semi: -8 });
          }
        }
        // Collision with the hull.
        const bow = frigPos([0, 0, -0.5]), stern = frigPos([0, 0, 0.5]);
        const ab = V.sub(stern, bow), tt = clamp(V.dot(V.sub(ship.p, bow), ab) / V.dot(ab, ab), 0, 1);
        const cp = V.madd(bow, ab, tt);
        if(!ship.dead && V.d2(cp, ship.p) < 13 * 13){
          const n = V.norm(V.sub(ship.p, cp));
          ship.p = V.madd(cp, n, 13.2);
          ship.speed = Math.min(ship.speed, 14);
          takeHit(20, V.madd(ship.p, n, -1));
        }
      }else{
        // Going down: a chain of explosions walking the hull.
        frig.dying -= dt; frig.boom -= dt;
        if(frig.boom <= 0){
          frig.boom = rr(0.08, 0.18);
          const q = [rr(-0.1, 0.1), rr(-0.05, 0.12), rr(-0.48, 0.5)];
          fx.explode(frigPos(q), rr(4, 9), { color: '#ff7a2a', debrisGeo: 'slab', debrisColor: '#4a4f58' });
          w.kick(0.9);
        }
        if(frig.dying <= 0){
          fx.explode(frig.p, 24, { color: '#ffb06a', sparks: 46, debris: 14, smoke: 9 });
          snd('bigExplode');
          w.kick(2.6);
          frigatesKilled++;
          award(600, V.add(frig.p, [0, 30, 0]), 'FRIGATE DOWN', '#ffd700');
          for(let k = 0; k < 3; k++) dropPick(V.add(frig.p, [rr(-20, 20), rr(-10, 10), rr(-20, 20)]), ['orb', 'repair', 'msl'][k]);
          frig = null; frigTimer = 9; objective = ''; say('🔥 FRIGATE DESTROYED — another is on the scope', 3);
        }
      }
      if(frig && V.len(V.sub(frig.p, ship.p)) > 4200){ frig = null; frigTimer = 2; }
    }

    // ── ENEMY FIRE ── (half speed under a Time Warp)
    for(let i = flak.length - 1; i >= 0; i--){
      const b = flak[i];
      const a = V.copy(b.p);
      b.p = V.madd(b.p, b.v, dt * SP.warp());
      b.life -= dt;
      if(b.life <= 0){ flak.splice(i, 1); continue; }
      if(!ship.dead && segHit(a, b.p, ship.p, b.big ? 2.4 : 1.8)){
        flak.splice(i, 1);
        takeHit(b.dmg, b.p);
      }
    }

    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    // ── CAMERA ── behind and above, the offset eased in the ship's own frame
    // so the ship stays put on screen while the turn swings the view round.
    if(dt > 0){
      const boostK = clamp((ship.speed - 46) / 66, 0, 1);
      const Bc = basisQ(ship.q, ship.bank * 0.35);
      const goalOff = V.add(V.mul(Bc.f, -(7.2 + boostK * 2.6)), V.mul(Bc.u, 2.15));
      const k = ease(dt, ship.dead ? 0.6 : 0.075);
      camOff = V.lerp(camOff, goalOff, k);
      camTgt = V.lerp(camTgt, V.add(V.mul(B.f, 30), V.mul(Bc.u, 1.2)), ease(dt, 0.06));
      camUp = V.norm(V.lerp(camUp, Bc.u, ease(dt, 0.1)));
      w.goal.fov = 62 + boostK * 12;
    }
    w.cam.eye = V.add(ship.p, camOff);
    w.cam.target = V.add(ship.p, camTgt);
    w.goal.eye = w.cam.eye; w.goal.target = w.cam.target;
    w.up = camUp;
    w.step(dt);

    // ── DRAW ──
    w.begin();
    drawBodies(w, BODIES);
    const eye = w.cam.eye;
    // Rocks: frustum-culled, small ones dropped with distance.
    belt.each(it => {
      if(it.t === 'rock'){
        const d2 = V.d2(it.p, eye);
        if(!it.big && d2 > 820 * 820) return;
        if(it.s < 4 && d2 > 430 * 430) return;
        if(!r.viewDepth(it.p, 1.15 + it.s / Math.max(30, Math.sqrt(d2)))) return;
        r.draw(it.g, { pos: it.p, rot: [it.rot[0] + it.spin[0] * w.t, it.rot[1] + it.spin[1] * w.t, it.rot[2]], scale: it.s,
                       color: it.c, metallic: 0.04, roughness: 0.92, rim: 0.35 });
      }else if(it.t === 'pick'){
        drawPick(it);
      }
    });
    for(const pk of pickups) drawPick(pk);
    function drawPick(pk){
      // Culled like the rocks: a field holds a couple of hundred of these and
      // each is two high-poly meshes and a glow.
      const d2 = V.d2(pk.p, eye);
      if(d2 > 650 * 650 || !r.viewDepth(pk.p, 1.2)) return;
      const c = pk.kind === 'orb' ? '#ffd700' : pk.kind === 'repair' ? '#39ff88' : '#ff5aa8';
      const s = 1.2 + 0.15 * Math.sin(w.t * 3 + (pk.ph || 0));
      r.draw('sphere', { pos: pk.p, scale: s, color: c, emissive: c, emissiveStrength: 1.6 });
      r.draw('torus', { pos: pk.p, rot: [w.t * 1.3, w.t * 1.7, 0], scale: s * 2.4, color: '#fff3b0', emissive: c, emissiveStrength: 1.4 });
      r.glow(pk.p, s * 2.2, c, 0.9);
    }

    // The frigate, its turrets, its reactor and shield.
    if(frig){
      const fb = frig.fb;
      // ✨ v60 · PAINTED, NOT LIT (see ENEMY_PAINT): the squadrons' crimson
      // livery with black stripes, on the carrier as on its raiders.
      r.draw('frigate', { m3: fb.m3, pos: frig.p, scale: frig.S, ...foeLook(ENEMY_PAINT.red, false) });
      // Engine glow at the stern.
      for(const q of [[0, 0, 0.6], [-0.085, -0.01, 0.57], [0.085, -0.01, 0.57]]){
        const ep = frigPos(q);
        plume(w, ep, fb.f.map(v => -v), { len: q[0] ? 18 : 26, width: q[0] ? 5 : 8, color: '#ff7a3a', core: '#ffe2b8', gain: 1.2, ph: q[0] * 9 });
      }
      for(const t of frig.turrets){
        const tp = frigPos(t.q);
        if(t.dead){
          // ✨ v59 · a wreck that burns: flames licking off the plinth, smoke above
          const sd = Math.abs(t.q[0] * 7.31 + t.q[2] * 3.17) % 1;
          r.fire(V.madd(tp, fb.u, 1.4), 3.6 + 0.5 * Math.sin(w.t * 6 + sd * 9), 1.5, 0.32 + 0.1 * Math.sin(w.t * 2.3 + sd * 5), sd);
          r.fire(V.madd(tp, fb.u, 3.2), 2.4, 1.0, 0.55, (sd + 0.5) % 1);
          r.smoke(V.madd(tp, fb.u, 6.5), 8, '#1c1a19', 0.3, 0.5, (sd + 0.25) % 1);
          continue;
        }
        const aimD = V.norm(V.sub(ship.p, tp));
        // Yawed on its deck, pitched only part of the way, so the plinth stays
        // planted while the guns still swing toward you.
        const up = fb.u, flat = V.norm(V.madd(aimD, up, -V.dot(aimD, up) * 0.65));
        const tb = basisLook(flat, up);
        r.draw('turret', { pos: tp, m3: tb.m3, scale: 7.2, ...foeLook(ENEMY_PAINT.orange, t.flash > 0) });
      }
      const rp = frigPos(frig.reactor.q);
      if(!frig.dying){
        // The weak point in a paint of its own (yellow), so it reads as the
        // target against the crimson hull without a glow to point at it.
        r.draw('core', { pos: rp, rot: [0, w.t * 0.8, 0], scale: 6, ...foeLook(ENEMY_PAINT.yellow, frig.reactor.flash > 0) });
        if(frig.shield){
          r.draw('sphere', { pos: rp, scale: 22, color: '#2ad7ff', emissive: '#4ae7ff', emissiveStrength: 0.4 + (frig.shieldFlash || 0) * 3,
                             alpha: 0.18 + (frig.shieldFlash || 0), blend: true, detail: 5.8, metallic: 0, roughness: 0.2, rim: 1.4 });
        }
      }
    }

    // Raiders. ✨ v60 · PAINTED, NOT LIT (see ENEMY_PAINT): a crimson livery
    // with black stripes that the sun reads like the player's own airframe.
    // The neon sprite on the nose and the red lamp hung round each one are
    // gone — at range they were a red smudge with a dark hull nobody could see.
    // ✨ v60 · A squadron is a MIX of the Blender hulls, like the 3D
    // mission's: its leader flies the twin-nacelle HEAVY (purple), the odd
    // wingmen the needle DART (orange), the rest the RAIDER (red). Same flight
    // model and the same one-hit kill for all three — the hull is the read on
    // where each sits in the formation.
    for(const f of foes){
      const fb = basisLook(f.f, [0, 1, 0], f.bank);
      const hull = f.slot === 0 ? 'heavy' : f.slot % 2 ? 'dart' : 'raider';
      const paint = hull === 'heavy' ? ENEMY_PAINT.purple : hull === 'dart' ? ENEMY_PAINT.orange : ENEMY_PAINT.red;
      r.draw(hull, { pos: f.p, m3: fb.m3z, scale: hull === 'heavy' ? 2.2 : 2.3, color: f.flash > 0 ? '#ffffff' : paint,
                     metallic: ENEMY_FINISH.metallic, roughness: ENEMY_FINISH.roughness, rim: ENEMY_FINISH.rim, accent: 7 });
      // Flames out of each hull's own nozzles.
      const noz = hull === 'heavy' ? [[-1.23, -0.04, -1.5], [1.23, -0.04, -1.5]] : hull === 'dart' ? [[0, 0, -1.72]] : [[-0.55, -0.14, -1.45], [0.55, -0.14, -1.45]];
      noz.forEach(([x, y, z], i) => {
        const ep = V.add(V.madd(f.p, f.f, z), V.add(V.mul(fb.r, x), V.mul(fb.u, y)));
        plume(w, ep, V.mul(f.f, -1), { len: hull === 'dart' ? 3.8 : 3.2, width: hull === 'dart' ? 0.7 : 0.55, color: '#ff8a3a', core: '#ffe6c8', gain: 0.9, ph: i * 3 - 1 });
      });
    }

    // Shots.
    for(const b of bolts){
      // ✨ v59 · tracers as the video's: an orange round with a white-hot core
      r.streak(V.madd(b.p, b.v, -0.022), b.p, 0.3, '#ff8a2a', 3.6, 0.85);
      r.streak(V.madd(b.p, b.v, -0.014), b.p, 0.11, '#fff1d0', 3.0, 0.7);
    }
    for(const b of flak){
      if(b.big){ r.fire(b.p, 2.6, 1.8, 0.12, 0.37); r.streak(V.madd(b.p, b.v, -0.05), b.p, 0.9, b.c, 2.2, 1); }
      else r.streak(V.madd(b.p, b.v, -0.03), b.p, 0.34, b.c, 3.6, 0.9);
    }
    for(const m of missiles){
      const mb = basisLook(V.norm(m.v), [0, 1, 0]);
      r.draw('missile', { pos: m.p, m3: mb.m3, scale: 1.4, color: '#d9dde4', metallic: 0.3, roughness: 0.4, emissive: '#ff8a3a', emissiveStrength: 0.5, accent: 2 });   // ✨ v58
      plume(w, V.madd(m.p, V.norm(m.v), -0.8), V.mul(V.norm(m.v), -1), { len: 2.6, width: 0.5, color: '#ffb06a', core: '#fff0d0', gain: 1.1 });
    }

    // The interceptor.
    if(!ship.dead){
      const blink = ship.inv > 0 && Math.sin(w.t * 40) > 0;
      if(!blink){
        r.draw('ship', { pos: ship.p, m3: B.m3, scale: SC, color: ship.hit > 0 ? '#ff8a8a' : '#a9b1bf', metallic: 0.62, roughness: 0.3, rim: 0.7,
                         emissive: colour, emissiveStrength: 0.004, accent: 0 });
      }
      const boostK = clamp((ship.speed - 46) / 66, 0, 1);
      for(const s of [-1, 1]){
        const ep = V.add(ship.p, V.add(V.add(V.mul(B.r, s * 0.36 * SC), V.mul(B.u, -0.02 * SC)), V.mul(B.f, -0.86 * SC)));
        plume(w, ep, V.mul(B.f, -1), { len: 1.0 + boostK * 1.8, width: 0.3 + boostK * 0.08, color: boostK > 0.3 ? '#8fe6ff' : '#5ec8ff', gain: 0.7 + boostK * 0.35, glow: 0.8, ph: s * 5 });
      }
      // ✨ v57 · The sun is the key light now. These two used to sit 3.6 and
      // 1.6 units off the hull at 110 and 90 — four and fifteen times the
      // sun's strength where they landed — and burned the airframe to a white
      // blob. What is left is a soft fill from over the chase camera, so the
      // shadow side still reads, and a small hot wash just aft of the nozzles.
      r.light({ pos: V.add(ship.p, V.add(V.mul(B.u, 5), V.mul(B.f, -7))), color: '#cfe0ff', intensity: 26, range: 30 });
      r.light({ pos: V.madd(ship.p, B.f, -1.9 * SC), color: '#6fd0ff', intensity: 3 + 7 * boostK, range: 6 });
    }
    // Speed dust: the only thing in open space that says how fast you are going.
    dust(w, V.mul(B.f, ship.speed), { len: 0.045, max: 7, gain: 0.42, width: 0.03 });
    SP.draw();
    fx.draw();
    w.end();

    // ── HUD ──
    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 270, Ht], [Wd - 180, Ht - 76, Wd, Ht]];
    SP.hud();
    // Reticle where the guns converge, and the mouse's own pointer.
    const aimP = hud.proj(V.madd(ship.p, B.f, 140));
    if(aimP.on && !ship.dead) hud.crosshair(aimP.x, aimP.y, '#bff6ff', 9);
    if(I.device === 'mouse' && I.mouseOn) hud.crosshair((I.mx + 1) / 2 * Wd, (I.my + 1) / 2 * Ht, 'rgba(255,190,120,0.9)', 5);
    // 🎯 v60 · The hit marker: four ticks round the reticle for every bolt that
    // lands — gold for a hit, red and wider for a kill — so a hit is never in
    // doubt, even on a raider too far off to see the sparks.
    if(dt > 0) hitMark = Math.max(0, hitMark - dt);
    if(hitMark > 0 && aimP.on){
      const g = hud.ctx, k = hitKill ? 1.4 : 1, a = Math.min(1, hitMark * 5);
      g.save(); g.globalAlpha = a; g.strokeStyle = hitKill ? '#ff5a3a' : '#ffd27a'; g.lineWidth = 2; g.shadowColor = g.strokeStyle; g.shadowBlur = 6;
      g.beginPath();
      for(const [sx, sy] of [[1, 1], [1, -1], [-1, 1], [-1, -1]]){ g.moveTo(aimP.x + sx * 7 * k, aimP.y + sy * 7 * k); g.lineTo(aimP.x + sx * 14 * k, aimP.y + sy * 14 * k); }
      g.stroke(); g.restore();
    }
    // The squadron in the air, top right — how many are left to bring down.
    if(foes.length){
      const sq = foes[0].sq;
      hud.text(Wd - 14, 22, '✈ SQUADRON ' + sq + ' · ' + squadLeft(sq) + ' LEFT' + (foes.length > squadLeft(sq) ? ' +' + (foes.length - squadLeft(sq)) : ''),
               { size: 11, align: 'right', color: '#ffb0a0' });
    }else if(!HOT && squadT > 0 && squadN){
      hud.text(Wd - 14, 22, '✈ NEXT SQUADRON · ' + Math.ceil(squadT) + 's', { size: 11, align: 'right', color: '#9fdcff' });
    }
    // 🎯 v60 · LEAD PIPS. The cannons fire straight down the nose, and a raider
    // crossing at fifty metres a second has moved a wingspan or two by the time
    // a bolt gets there — aiming AT one is aiming behind it. Each raider ahead
    // carries a pip where it WILL be when a bolt fired now arrives: put the
    // reticle on the pip, not the ship.
    if(!ship.dead){
      const vb = SHOT_SP + ship.speed;
      let n = 0;
      for(const f of foes){
        const d = V.sub(f.p, ship.p), dist = V.len(d);
        if(dist > 700 || V.dot(d, B.f) < dist * 0.5 || n >= 3) continue;
        const tt = dist / vb;
        const lp = V.madd(f.p, f.vel || [0, 0, 0], tt);
        const q = hud.proj(lp), q0 = hud.proj(f.p);
        if(!q.on) continue;
        n++;
        const g = hud.ctx, s = 5;
        g.save();
        g.strokeStyle = '#ffd27a'; g.lineWidth = 1.5; g.globalAlpha = 0.9; g.shadowColor = '#ffb050'; g.shadowBlur = 5;
        g.beginPath(); g.moveTo(q.x, q.y - s); g.lineTo(q.x + s, q.y); g.lineTo(q.x, q.y + s); g.lineTo(q.x - s, q.y); g.closePath(); g.stroke();
        if(q0.on){ g.globalAlpha = 0.35; g.setLineDash([2, 3]); g.beginPath(); g.moveTo(q0.x, q0.y); g.lineTo(q.x, q.y); g.stroke(); }
        g.restore();
      }
    }
    // Targets.
    const tl = [];
    targetsEach((t, p, sz, col, lbl) => tl.push({ t, p, sz, col, lbl, d: Math.sqrt(V.d2(p, ship.p)) }));
    tl.sort((x, y) => x.d - y.d);
    tl.forEach((e, i) => {
      const isLock = e.t === lockOn;
      const label = isLock ? (lockT >= 1 ? 'MISSILE LOCK' : e.lbl) : (i < 2 && e.d < 450 ? e.lbl : null);
      const q = hud.bracket(e.p, e.sz * 2, e.col, label, { lock: isLock && lockT >= 1, dist: isLock ? e.d : null, alpha: isLock || i < 3 ? 0.95 : 0.55 });
      if(!q.on && e.lbl === 'RAIDER' && e.d < 520) hud.edgeArrow(e.p, e.col, null);
      if(!q.on && e.lbl === 'REACTOR') hud.edgeArrow(e.p, e.col, 'REACTOR');
    });
    if(frig && !frig.dying){
      const q = hud.proj(frig.p);
      if(!q.on) hud.edgeArrow(frig.p, '#ffb03a', 'FRIGATE ' + Math.round(V.len(V.sub(frig.p, ship.p))) + 'm');
    }
    // Radar.
    const rad = [];
    for(const f of foes) rad.push({ p: f.p, c: '#ff4060', tick: true });
    if(frig) rad.push({ p: frig.p, c: '#ffb03a', s: 4, shape: 'diamond', tick: true });
    for(const pk of pickups) rad.push({ p: pk.p, c: '#ffd700', s: 2 });
    hud.radar(70, Ht - 74, 54, ship.p, B.f, 900, rad);
    // Bars and panels.
    hud.bar(136, Ht - 52, 120, 9, ship.hull / 100, ship.hull > 35 ? '#38e6ff' : '#ff4a5a', 'HULL');
    hud.bar(136, Ht - 28, 120, 7, ship.energy / 100, '#ffb03a', 'BOOST · ' + Math.round(ship.speed) + ' m/s');
    const lockTxt = lockOn ? (lockT >= 1 ? 'LOCKED' : 'ACQUIRING ' + Math.round(lockT * 100) + '%') : 'NO LOCK';
    hud.panel(Wd - 168, Ht - 62, 154, 48, 'MISSILES', ship.missiles, lockT >= 1 ? '#ffb03a' : '#7fdcff', lockTxt);
    if(objective) hud.text(Wd / 2, 22, objective, { size: 11, color: '#ffd27a' });
    if(msgT > 0) hud.text(Wd / 2, objective ? 44 : 24, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    if(ship.hit > 0){
      const g = hud.ctx.createRadialGradient(Wd / 2, Ht / 2, Math.min(Wd, Ht) * 0.3, Wd / 2, Ht / 2, Math.max(Wd, Ht) * 0.7);
      g.addColorStop(0, 'rgba(255,0,40,0)'); g.addColorStop(1, 'rgba(255,0,40,' + (ship.hit * 0.9).toFixed(3) + ')');
      hud.ctx.fillStyle = g; hud.ctx.fillRect(0, 0, Wd, Ht);
    }
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🌐 OPEN WORLD · THE GROUND KIT
// ══════════════════════════════════════════════
// Most worlds are played on the ground: a rover, a runner, a worm, a bike on
// an endless lit plain under a city sky. Shared here: the skies, the follow
// and chase cameras, a screen → ground pick, an endless procedural city whose
// towers can be obstacles or just the horizon, and a few props.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit) return;
const KIT = P.owKit;
const { V, TAU, ease, makeField, owBegin } = KIT;
const { clamp } = P.kit;

// Sky looks. Each is a full env/fog/sun/grade set on the NIGHT base.
const SKIES = {
  night: {},
  dusk:  { env: { zenith: '#120622', horizon: '#9a2a4a', ground: '#0c0410', intensity: 1.15 }, fog: { color: '#22081e', density: 0.0058 },
           sun: { dir: [0.3, -0.35, -0.9], color: '#ff9a6a', intensity: 0.9 }, grade: { saturation: 1.15 } },
  toxic: { env: { zenith: '#020a05', horizon: '#1d6a30', ground: '#020604', intensity: 1.05 }, fog: { color: '#061a0c', density: 0.0062 },
           sun: { dir: [-0.3, -0.8, -0.5], color: '#9aff7a', intensity: 0.7 } },
  ice:   { env: { zenith: '#020a18', horizon: '#1d5a86', ground: '#020a14', intensity: 1.2 }, fog: { color: '#071a2a', density: 0.006 },
           sun: { dir: [-0.5, -0.7, -0.4], color: '#a8e6ff', intensity: 0.9 } },
  ember: { env: { zenith: '#0c0303', horizon: '#8a3410', ground: '#0a0402', intensity: 1.1 }, fog: { color: '#1e0904', density: 0.006 },
           sun: { dir: [0.4, -0.5, -0.7], color: '#ffb36a', intensity: 0.85 } },
  violet:{ env: { zenith: '#07031a', horizon: '#4a1e86', ground: '#05031a', intensity: 1.15 }, fog: { color: '#11082a', density: 0.006 },
           sun: { dir: [-0.4, -0.7, -0.6], color: '#c79bff', intensity: 0.8 } }
};
// 🌍 v60 · A World theme's own sky for the ground worlds, in place of the
// world's: the 3D missions all share one city night, so a theme only has to
// tint it, but each open world has a sky of its own, and a theme mixed into a
// green or violet one came out a flat wash. The world keeps its fog DENSITY
// when it set one (a stealth world needs its dark) — the colour is the theme's.
// The tint (applyWorldTint) keeps each sky's BRIGHTNESS and shifts its hue,
// so the Toxic Sector and Deep Net start from the 3D missions' own dark city
// night and come out as dark as they do there; the desert's sunset and the
// deck's starfield are bright by design.
const CITY_DARK = { env: { zenith: '#04061a', horizon: '#3a1050', ground: '#05060f', intensity: 1.35 }, fog: { color: '#0d0722', density: 0.0052 },
                    sun: { dir: [-0.4, -0.85, -0.5], color: '#6f7dff', intensity: 0.7 } };
const LOOK_SKIES = {
  toxic:  CITY_DARK,
  desert: { env: { zenith: '#1e0830', horizon: '#ff4d6d', ground: '#140610', intensity: 1.15 }, fog: { color: '#3a1030', density: 0.003 },
            sun: { dir: [0.25, -0.3, -0.92], color: '#ffb347', intensity: 0.95 }, grade: { saturation: 1.12 } },
  deep:   CITY_DARK,
  orbit:  { env: { zenith: '#02030a', horizon: '#1b2440', ground: '#02030a', intensity: 1.0 }, fog: { color: '#05070d', density: 0.0026 },
            sun: { dir: [-0.5, -0.6, -0.6], color: '#f0f4ff', intensity: 1.05 }, grade: { saturation: 0.95 } }
};
// The look the last ground world was built with; THE ENDLESS CITY reads it.
let curLook = null;
function groundBegin(o){
  o = o || {};
  const id = (typeof worldLook === 'function') ? worldLook() : null;
  const L = id && LOOK_SKIES[id];
  const s = L || SKIES[o.sky || 'night'] || {};
  const fog = L ? Object.assign({}, s.fog, (o.fog && o.fog.density != null) ? { density: o.fog.density } : null)
                : Object.assign({}, s.fog, o.fog);
  const G = owBegin({ preset: 'night', env: Object.assign({}, s.env, L ? null : o.env), fog,
                      sun: Object.assign({}, s.sun, L ? null : o.sun), grade: Object.assign({}, s.grade, L ? null : o.grade),
                      input: o.input, far: o.far || 1400, near: o.near || 0.3 });
  curLook = (G && G.w && G.w.look) || null;
  return G;
}

// A top-down follow camera, NEVER yawing (screen-right is always +X), eased.
function followCam(w, p, o, dt){
  o = o || {};
  const h = o.height || 26, back = o.back != null ? o.back : 17, look = o.look || 0;
  const goalEye = [p[0], p[1] + h, p[2] + back], goalTgt = [p[0], p[1], p[2] - look];
  const k = dt > 0 ? ease(dt, o.half || 0.12) : 0;
  w.cam.eye = V.lerp(w.cam.eye, goalEye, w._owCamInit ? k : 1);
  w.cam.target = V.lerp(w.cam.target, goalTgt, w._owCamInit ? k : 1);
  w._owCamInit = true;
  w.cam.fov = o.fov || 52;
  w.goal.eye = w.cam.eye; w.goal.target = w.cam.target; w.goal.fov = w.cam.fov;
  w.up = [0, 1, 0];
}
// A chase camera behind a heading (yaw: 0 = −Z), eased in the target's frame.
function chaseCam(w, p, yaw, o, dt){
  o = o || {};
  const back = o.back || 9, up = o.up || 4, ahead = o.ahead || 14;
  const f = [-Math.sin(yaw), 0, -Math.cos(yaw)];
  const goalOff = [-f[0] * back, up, -f[2] * back];
  const k = dt > 0 ? ease(dt, o.half || 0.1) : 0;
  w._ccOff = w._ccOff ? V.lerp(w._ccOff, goalOff, k) : goalOff;
  const tgt = [p[0] + f[0] * ahead, p[1] + (o.tgtUp || 1), p[2] + f[2] * ahead];
  w._ccTgt = w._ccTgt ? V.lerp(w._ccTgt, tgt, ease(dt || 0.016, o.half || 0.1)) : tgt;
  w.cam.eye = V.add(p, w._ccOff);
  w.cam.target = w._ccTgt;
  w.cam.fov = o.fov || 60;
  w.goal.eye = w.cam.eye; w.goal.target = w.cam.target; w.goal.fov = w.cam.fov;
  w.up = [0, 1, 0];
}
// Screen point (CSS px in the board) → the ground plane y = gy, using the
// HUD's own camera (call after hud.begin()). Null if the ray misses.
function screenToGround(hud, sx, sy, gy){
  const C = hud.cam;
  if(!C) return null;
  const asp = hud.W / hud.H;
  const nx = (sx / hud.W) * 2 - 1, ny = 1 - (sy / hud.H) * 2;
  const d = V.norm(V.add(V.add(C.f, V.mul(C.r, nx * C.th * asp)), V.mul(C.u, ny * C.th)));
  if(Math.abs(d[1]) < 1e-4) return null;
  const t = ((gy || 0) - C.eye[1]) / d[1];
  if(t <= 0) return null;
  return V.madd(C.eye, d, t);
}

// ── THE ENDLESS CITY ──
// Towers on a jittered grid of cells, generated around the player. `clear`
// keeps a radius round the origin open; `density` thins it; `obstacle` lets a
// world collide with them (city.hit). Drawn culled: distance and frustum.
const TOWER_GEOS = ['tower', 'tower2', 'tower3', 'tower4', 'tower', 'tower2'];
const DRESS_NEAR = 95, DRESS_FAR = 300;
const NEONS = ['#00f5ff', '#ff0090', '#a855f7', '#ffd700', '#39ff88', '#ff6600'];
function makeCity(o){
  o = o || {};
  const cell = o.cell || 70, dens = o.density != null ? o.density : 0.55, clear = o.clear || 60;
  const hMin = o.hMin || 10, hMax = o.hMax || 60;
  // 🌍 v60 · A World theme dresses this city the way it dresses the 3D
  // missions' skyline (WORLD LOOKS): its tower finish, its neon, and the props
  // its planner hangs on each building — sludge and drums, dunes and palms,
  // kelp and coral, dishes and docking rings. Planned per tower from the
  // cell's own sequence AFTER the tower is drawn from it, so the city's layout
  // is the same in every theme.
  const K = P.kit, look = curLook && K.LOOKS && K.LOOKS[curLook] ? curLook : null;
  const LK = look ? K.LOOKS[look] : null, plan = look && K.DRESS_PLAN ? K.DRESS_PLAN[look] : null;
  const F = makeField({
    cell, dims: 2, seed: o.seed || 777, radius: o.radius || 620,
    gen(cx, cy, cz, g){
      const items = [];
      if(g() > dens) return items;
      const x = (cx + 0.2 + g() * 0.6) * cell, z = (cz + 0.2 + g() * 0.6) * cell;
      if(Math.hypot(x, z) < clear) return items;
      if(o.skip && o.skip(x, z)) return items;
      const kind = TOWER_GEOS[(g() * TOWER_GEOS.length) | 0];
      let bw = 6 + g() * 10, bd = 6 + g() * 10;
      if(kind === 'tower2'){ bw *= 1.5; bd *= 0.6; } else if(kind === 'tower4'){ bd = bw; }
      const h = hMin + Math.pow(g(), 1.6) * (hMax - hMin);
      const b = { t: 'tower', p: [x, 0, z], kind, w: bw, d: bd, h, rot: g() * 0.6 - 0.3,
                  neon: NEONS[(g() * NEONS.length) | 0], lit: g() > 0.4, ph: g() * 6 };
      if(LK){
        b.neon = LK.neon[NEONS.indexOf(b.neon)] || b.neon;
        // drawDress() reads the tower as the 3D skyline has it.
        b.x = x; b.y = 0; b.z = z; b.c = Math.cos(b.rot); b.s = Math.sin(b.rot);
        try{ b.dress = plan ? plan(b, g, K.DRESS_KIND[kind] || K.DRESS_KIND.tower, g() < 0.5 ? 1 : -1) : null; }catch(e){ b.dress = null; }
      }
      items.push(b);
      return items;
    }
  });
  F.draw = function(w){
    const r = w.r, eye = w.cam.eye;
    const far = o.drawFar || 640;
    F.each(b => {
      const d2 = (b.p[0] - eye[0]) ** 2 + (b.p[2] - eye[2]) ** 2;
      if(d2 > far * far) return;
      const mid = [b.p[0], b.h * 0.5, b.p[2]];
      if(!r.viewDepth(mid, 1.3 + b.h / Math.max(40, Math.sqrt(d2))) && !r.viewDepth([b.p[0], b.h, b.p[2]], 1.3) && !r.viewDepth(b.p, 1.3)) return;
      const T = LK ? LK.tower : null;
      r.draw(b.kind, { pos: mid, rot: [0, b.rot, 0], scale: [b.w, b.h, b.d], color: T ? T.color : (o.towerColor || '#0b0d18'),
                       metallic: T ? T.metallic : 0.55, roughness: T ? T.roughness : 0.5, rim: 0.85 });
      if(b.lit){
        const pulse = 0.6 + 0.4 * Math.sin(w.t * 1.3 + b.ph);
        r.draw('box', { pos: [b.p[0], b.h + 0.4, b.p[2]], rot: [0, b.rot, 0], scale: [b.w * 0.5, 0.16, 0.5], color: b.neon, emissive: b.neon, emissiveStrength: 3.0 * pulse });
      }
      // The theme's props: everything near, only the big ones further out,
      // none past DRESS_FAR (sub-pixel slivers cost a GPU the most).
      if(b.dress && d2 < DRESS_FAR * DRESS_FAR) K.drawDress(r, w.t, b, b.p[2], b.dress, d2 < DRESS_NEAR * DRESS_NEAR);
    });
  };
  // Footprint test (axis-aligned box, ignoring the small rotation).
  F.hit = function(p, rad){
    let hit = null;
    F.near(p, b => {
      if(hit) return;
      if(Math.abs(p[0] - b.p[0]) < b.w * 0.5 + rad && Math.abs(p[2] - b.p[2]) < b.d * 0.5 + rad) hit = b;
    });
    return hit;
  };
  return F;
}

// A glowing marker ring on the ground — goals, pickups, zones.
function groundRing(w, p, rad, col, k){
  const r = w.r;
  r.draw('thintorus', { pos: [p[0], (p[1] || 0) + 0.1, p[2]], scale: [rad * 2.2, 1, rad * 2.2], color: col, emissive: col, emissiveStrength: 2.2 * (k == null ? 1 : k) });
}
// A tall light beam rising from a point: "it's over there" from far away.
function beacon(w, p, col, h, k){
  const top = [p[0], (p[1] || 0) + (h || 60), p[2]];
  w.r.streak([p[0], (p[1] || 0), p[2]], top, 1.6, col, 1.3 * (k == null ? 1 : k), 0);
  w.r.streak([p[0], (p[1] || 0), p[2]], top, 5, col, 0.25 * (k == null ? 1 : k), 0);
}

// A hover rover — the player's craft in most ground worlds: a low wedge on
// glowing skirts. Drawn from the shared ship hull, flattened, nose along yaw.
function drawRover(w, p, yaw, col, o){
  o = o || {};
  const r = w.r;
  const B = KIT.basisYPR(yaw, o.pitch || 0, o.bank || 0);
  r.draw(o.geo || 'ship', { pos: [p[0], p[1] + (o.lift != null ? o.lift : 0.9), p[2]], m3: B.m3, scale: o.scale || 1.6,
                            color: o.hit ? '#ff8a8a' : (o.color || '#b8c0cc'), metallic: 0.62, roughness: 0.3, rim: 0.7,
                            emissive: col, emissiveStrength: 0.004, accent: o.accent != null ? o.accent : 0 });
  const back = V.madd([p[0], p[1] + (o.lift != null ? o.lift : 0.9), p[2]], B.f, -1.35 * (o.scale || 1.6) / 1.6);
  for(const s of [-1, 1]){
    const ep = V.add(back, V.mul(B.r, s * 0.58 * (o.scale || 1.6) / 1.6));
    KIT.plume(w, ep, V.mul(B.f, -1), { len: 0.8 + (o.boost || 0) * 1.6, width: 0.3, color: col, gain: 0.8 });
  }
  r.glow([p[0], p[1] + 0.15, p[2]], 2.2 * (o.scale || 1.6) / 1.6, col, 0.35);
  r.light({ pos: [p[0], p[1] + 4, p[2] + 2], color: '#cfe0ff', intensity: 80, range: 18 });
  return B;
}

P.owGround = { SKIES, groundBegin, followCam, chaseCam, screenToGround, makeCity, groundRing, beacon, drawRover, NEONS };

})();


// ══════════════════════════════════════════════
//  🐍 GRID SNAKE · OPEN WORLD — ENDLESS PLAIN
// ══════════════════════════════════════════════
// No walls at all: a worm on an endless lit plain, steering freely, growing on
// the data orbs scattered everywhere. Rival worms roam it too — run one into
// your body and it bursts into a trail of food; put your head into theirs (or
// your own tail, or a tower) and it is over.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, wrapAng, ease, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, chaseCam, makeCity } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const SEG = 0.85;                     // body spacing along the path

function makeWorm(p, yaw, len, col, ai){
  const pts = [];
  const f = [-Math.sin(yaw), 0, -Math.cos(yaw)];
  for(let i = 0; i < len; i++) pts.push(V.madd(p, f, -i * SEG));
  return { pts, yaw, len, col, ai, speed: ai ? 12 : 14, dead: false, think: 0, turn: 0, grow: 0 };
}
// Advance a worm: the head moves, and the body re-samples along its own path
// at fixed spacing, so turning carves a real curve rather than a polyline.
function stepWorm(wm, dt){
  const f = [-Math.sin(wm.yaw), 0, -Math.cos(wm.yaw)];
  const head = V.madd(wm.pts[0], f, wm.speed * dt);
  const pts = [head];
  let carry = 0, prev = head;
  for(let i = 0; i < wm.pts.length && pts.length < wm.len; i++){
    const q = wm.pts[i];
    let d = Math.hypot(q[0] - prev[0], q[2] - prev[2]);
    while(d + carry >= SEG && pts.length < wm.len){
      const t = (SEG - carry) / Math.max(d, 1e-6);
      const np = [prev[0] + (q[0] - prev[0]) * t, 0, prev[2] + (q[2] - prev[2]) * t];
      pts.push(np);
      prev = np; carry = 0;
      d = Math.hypot(q[0] - prev[0], q[2] - prev[2]);
    }
    carry += d;
    prev = q;
  }
  while(pts.length < wm.len) pts.push(V.copy(pts[pts.length - 1]));
  wm.pts = pts;
}

P.ow.snake = function(){
  const G = groundBegin({ sky: 'toxic', input: { mouseSteer: true, mouseGain: 1.4 } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK / TILT: STEER · BOOST BUTTON · ⚡ / LB: SPECIAL', 'A/D or ←/→ or MOUSE: STEER · SHIFT: BOOST (costs length) · V: SPECIAL');

  const me = makeWorm([0, 0, 0], 0, 14, colour, false);
  let score = 0, eaten = 0, kills = 0, over = false, msg = '', msgT = 0, inv = 0;
  const rivals = [];
  const RCOL = ['#ff2d9a', '#ffd700', '#a855f7', '#ff6600', '#39ff88'];
  const spawnRival = () => {
    const a = Math.random() * TAU, d = rr(90, 160);
    const p = V.add(me.pts[0], [Math.cos(a) * d, 0, Math.sin(a) * d]);
    rivals.push(makeWorm(p, Math.random() * TAU, 10 + ((Math.random() * 14) | 0), RCOL[(Math.random() * RCOL.length) | 0], true));
  };
  for(let i = 0; i < 4; i++) spawnRival();

  const food = makeField({
    cell: 36, dims: 2, seed: 9091, radius: 260,
    gen(cx, cy, cz, g){
      const items = [];
      const n = 1 + Math.floor(g() * 4);
      for(let i = 0; i < n; i++){
        const p = [(cx + g()) * 36, 0, (cz + g()) * 36];
        const big = g() < 0.08;
        items.push({ p, big, c: big ? '#ffd700' : ['#39ff88', '#00f5ff', '#ff6aa8', '#c084fc'][(g() * 4) | 0], ph: g() * 6 });
      }
      return items;
    }
  });
  const dropped = [];
  const city = makeCity({ seed: 4040, density: 0.16, cell: 90, clear: 80, hMin: 12, hMax: 48, radius: 700, towerColor: '#07120a' });

  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#39ff88,#00f5ff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };
  // ⚡ Specials: a Shield Burst to slither through, a Magnet Field for the
  // orbs, a Time Warp on the rivals, and a Nova that bursts every rival near.
  const SP = P.owKit.makeSpecials(G, {
    kinds: ['shield', 'magnet', 'warp', 'nova'], every: 150, bubbleR: 2.4, magnetR: 22, novaR: 42,
    player: () => me.pts[0],
    targets: () => rivals.map(rv => ({ p: rv.pts[0], r: 1.4, obj: rv })),
    hit: rv => { const i = rivals.indexOf(rv); if(i >= 0) killRival(i); },
    onEnd: k => { if(k === 'shield') inv = Math.max(inv, 1.2); }
  });

  function die(why){
    if(over || me.dead) return;
    if(SP.shielded()) return;
    if(survivedFatal()){
      inv = 2.2;
      fx.explode(me.pts[0], 1.6, { color: '#a855f7', debris: 0 });
      say('SHIELD ABSORBED', 1.6);
      return;
    }
    me.dead = true;
    snd('bigExplode');
    for(let i = 0; i < me.pts.length; i += 3) fx.explode(me.pts[i], 0.8, { color: colour, debris: 0, smoke: 0, ring: false });
    w.kick(1.4);
    gLater(() => end(why), 1300);
  }
  function killRival(i){
    const rv = rivals[i];
    rivals.splice(i, 1);
    kills++;
    snd('explode');
    score += 100; setLive(score);
    w.pop(V.add(rv.pts[0], [0, 3, 0]), '+100 BURST', rv.col, { size: 15 });
    for(let k = 0; k < rv.pts.length; k += 2) dropped.push({ p: V.add(rv.pts[k], [rr(-0.6, 0.6), 0, rr(-0.6, 0.6)]), c: rv.col, big: false, ph: Math.random() * 6, life: 30 });
    fx.explode(rv.pts[0], 1.4, { color: rv.col, debris: 0 });
    gLater(spawnRival, 2500);
  }
  function end(why){
    if(over) return;
    over = true;
    owFinish('snake', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : why === 'tail' ? 'BIT YOUR OWN TAIL' : why === 'tower' ? 'HIT A TOWER' : 'HIT A RIVAL',
      '🍏 Orbs Eaten': eaten,
      '🐍 Final Length': me.len,
      '💥 Rivals Burst': kills,
      '🏆 Score': score + ' PTS'
    });
  }
  // Point → nearest distance to a polyline body, from index `from`.
  const bodyHit = (p, wm, from, rad) => {
    for(let i = from; i < wm.pts.length; i++){
      const q = wm.pts[i];
      if((p[0] - q[0]) ** 2 + (p[2] - q[2]) ** 2 < rad * rad) return true;
    }
    return false;
  };

  P.owDebug = { state: () => ({ score, len: me.len, rivals: rivals.length, eaten, kills }), specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use() };

  runLoop(dt => {
    if(over) return false;
    const I = inp.poll();
    if(dt > 0 && !me.dead){
      SP.tick(dt, I, score);
      inv = Math.max(0, inv - dt);
      const steer = clamp(I.ax, -1, 1);
      me.yaw = wrapAng(me.yaw - steer * 3.0 * dt);
      const boosting = I.boost && me.len > 8;
      me.speed += ((boosting ? 24 : 14) * Math.min(diff, 1.4) - me.speed) * ease(dt, 0.3);
      if(boosting){ me.boostT = (me.boostT || 0) + dt; if(me.boostT > 0.45){ me.boostT = 0; me.len--; dropped.push({ p: V.copy(me.pts[me.pts.length - 1]), c: colour, ph: 0, life: 20 }); } }
      stepWorm(me, dt);
      const head = me.pts[0];
      // Food.
      food.update(head);
      if(SP.active('magnet')){
        food.near(head, it => { it.p = SP.pull(it.p, dt, 34); });
        for(const d of dropped) d.p = SP.pull(d.p, dt, 34);
      }
      food.near(head, it => {
        if((it.p[0] - head[0]) ** 2 + (it.p[2] - head[2]) ** 2 < (it.big ? 2.6 : 1.8) ** 2){
          food.kill(it);
          eaten++;
          me.len += it.big ? 4 : 1;
          score += it.big ? 50 : 10; setLive(score);
          snd(it.big ? 'powerup' : 'eat');
          fx.glowPop(it.p, it.c, it.big ? 2.2 : 1.2, 0.3);
        }
      });
      for(let i = dropped.length - 1; i >= 0; i--){
        const d = dropped[i];
        d.life -= dt;
        if(d.life <= 0){ dropped.splice(i, 1); continue; }
        if((d.p[0] - head[0]) ** 2 + (d.p[2] - head[2]) ** 2 < 1.8 * 1.8){
          dropped.splice(i, 1); eaten++; me.len += 1; score += 10; setLive(score); snd('eat');
        }
      }
      // Collisions.
      city.update(head);
      if(inv <= 0){
        if(city.hit(head, 0.6)) die('tower');
        else if(me.len > 12 && bodyHit(head, me, 10, 0.7)) die('tail');
        else for(const rv of rivals){ if(bodyHit(head, rv, 0, 0.95)){ die('rival'); break; } }
      }
    }
    // Rivals: wander toward food, shy away from the player's head, steer
    // round towers.
    const rdt = dt * SP.warp();
    for(let i = rivals.length - 1; i >= 0; i--){
      const rv = rivals[i];
      if(dt <= 0) break;
      rv.think -= rdt;
      const h = rv.pts[0];
      if(rv.think <= 0){
        rv.think = rr(0.3, 0.8);
        let tgt = null, bd = 900;
        food.near(h, it => { const d = (it.p[0] - h[0]) ** 2 + (it.p[2] - h[2]) ** 2; if(d < bd){ bd = d; tgt = it.p; } });
        const want = tgt ? Math.atan2(-(tgt[0] - h[0]), -(tgt[2] - h[2])) : rv.yaw + rr(-1, 1);
        rv.turn = clamp(wrapAng(want - rv.yaw) * 2, -2.6, 2.6);
        // Cut across the player now and then: the only way a rival dies is
        // by hitting you, and the only way you die is hitting them.
        if(Math.random() < 0.25 && !me.dead){
          const ph = me.pts[0], ahead = V.madd(ph, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 8);
          const cut = Math.atan2(-(ahead[0] - h[0]), -(ahead[2] - h[2]));
          rv.turn = clamp(wrapAng(cut - rv.yaw) * 2.4, -2.8, 2.8);
        }
      }
      rv.yaw = wrapAng(rv.yaw + rv.turn * rdt);
      stepWorm(rv, rdt);
      const rh = rv.pts[0];
      food.near(rh, it => { if((it.p[0] - rh[0]) ** 2 + (it.p[2] - rh[2]) ** 2 < 1.6 * 1.6){ food.kill(it); rv.len = Math.min(60, rv.len + 1); } });
      if(!me.dead && bodyHit(rh, me, 1, 0.9)){ killRival(i); continue; }
      if(city.hit(rh, 0.6)){ rv.yaw += Math.PI * 0.8; }
      if(V.d2(rh, me.pts[0]) > 320 * 320){ rivals.splice(i, 1); spawnRival(); }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    // ── CAMERA ── high behind the head, so the body you are coiling is in view.
    const head = me.pts[0];
    chaseCam(w, head, me.yaw, { back: 15 + me.len * 0.06, up: 11 + me.len * 0.05, ahead: 10, fov: 62, half: 0.14, tgtUp: 0 }, dt);
    w.step(dt);

    // ── DRAW ──
    w.begin();
    drawFloor(w, { step: 6, radius: 160, color: '#0f5a2a', glow: 0.9, major: 5, floor: '#030805' });
    city.draw(w);
    const eye = w.cam.eye;
    food.each(it => {
      if(V.d2(it.p, eye) > 170 * 170 || !r.viewDepth(it.p, 1.2)) return;
      const y = 0.7 + 0.2 * Math.sin(w.t * 3 + it.ph);
      r.draw('sphere', { pos: [it.p[0], y, it.p[2]], scale: it.big ? 1.3 : 0.7, color: it.c, emissive: it.c, emissiveStrength: 1.5 });
      r.glow([it.p[0], y, it.p[2]], it.big ? 2.4 : 1.3, it.c, 0.7);
    });
    for(const d of dropped){ if(V.d2(d.p, eye) < 170 * 170) { r.draw('lowsphere', { pos: [d.p[0], 0.6, d.p[2]], scale: 0.6, color: d.c, emissive: d.c, emissiveStrength: 1.6 }); } }
    const drawWorm = (wm, isMe) => {
      const n = wm.pts.length;
      for(let i = n - 1; i >= 0; i--){
        const q = wm.pts[i];
        if(i % 1 === 0 && V.d2(q, eye) > 180 * 180) continue;
        const t = i / Math.max(1, n - 1);
        const s = (i === 0 ? 1.45 : 1.15 - t * 0.45) * (isMe ? 1 : 0.95);
        const blink = isMe && inv > 0 && Math.sin(w.t * 30) > 0;
        if(blink) continue;
        // ✨ v60 · A rival is PAINTED, NOT LIT (see ENEMY_PAINT): glossy bands
        // of its colour and white, with nothing on it glowing.
        if(isMe) r.draw(i === 0 ? 'sphere' : 'lowsphere', { pos: [q[0], s * 0.5, q[2]], scale: s, color: i % 4 === 0 ? '#ffffff' : wm.col,
                                                   metallic: 0.3, roughness: 0.3, rim: 1.0, emissive: wm.col, emissiveStrength: i % 4 === 0 ? 0.6 : 0.35 });
        else r.draw(i === 0 ? 'sphere' : 'lowsphere', { pos: [q[0], s * 0.5, q[2]], scale: s,
                                                        ...P.kit.foeLook(wm.col, false, i % 4 === 0 ? { color: '#f2f5f8' } : null) });
      }
      // Eyes.
      const h = wm.pts[0], f = [-Math.sin(wm.yaw), 0, -Math.cos(wm.yaw)], rt = [f[2] * -1, 0, f[0]];
      for(const s of [-1, 1]){
        const e = V.add(V.madd(h, f, 0.45), [rt[0] * s * 0.38, 0.95, rt[2] * s * 0.38]);
        r.draw('lowsphere', { pos: e, scale: 0.34, color: '#ffffff', metallic: 0, roughness: 0.25, emissive: '#ffffff', emissiveStrength: isMe ? 0.8 : 0.12 });
        r.draw('lowsphere', { pos: V.madd(e, f, 0.12), scale: 0.18, color: '#05060a', metallic: 0, roughness: 0.2 });
      }
    };
    if(!me.dead) drawWorm(me, true);
    for(const rv of rivals) if(V.d2(rv.pts[0], eye) < 200 * 200) drawWorm(rv, false);
    r.light({ pos: [head[0], 6, head[2]], color: colour, intensity: 120, range: 26 });
    if(!me.dead) SP.draw();
    fx.draw();
    w.end();

    // ── HUD ──
    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    SP.hud();
    const rad = [];
    for(const rv of rivals) rad.push({ p: rv.pts[0], c: rv.col, s: 3 });
    food.each(it => { if(it.big) rad.push({ p: it.p, c: '#ffd700', s: 2 }); });
    hud.radar(70, Ht - 74, 54, head, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 140, rad);
    for(const rv of rivals){ const q = hud.proj(rv.pts[0]); if(!q.on && V.d2(rv.pts[0], head) < 90 * 90) hud.edgeArrow(rv.pts[0], rv.col, null); }
    hud.text(Wd - 16, Ht - 22, 'LENGTH ' + me.len, { size: 13, align: 'right', color: '#9dffc4' });
    if(msgT > 0) hud.text(Wd / 2, 26, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🏍️ LIGHT CYCLE · OPEN WORLD — INFINITE GRID
// ══════════════════════════════════════════════
// The classic arena has four walls; this grid has none. You ride, the rival
// riders ride, and every cycle lays a wall of light behind it. Turn ninety
// degrees at a time, box the riders in, make them hit a wall — and never hit
// one yourself. Old light fades, so the grid never fills up.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ease, drawFloor, owClock, basisYPR } = P.owKit;
const { groundBegin, chaseCam, makeCity } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const DIRS = [[0, -1], [1, 0], [0, 1], [-1, 0]];            // N E S W in XZ
const yawOf = d => [0, -Math.PI / 2, Math.PI, Math.PI / 2][d];
const TRAIL_MAX = 520;                                     // units of light a cycle keeps

function makeRider(p, dir, col, ai){
  return { p: V.copy(p), dir, col, ai, alive: true, speed: 26, trail: [V.copy(p)], len: 0, think: 0, turned: 0, lean: 0, respawn: 0 };
}

P.ow.lightcycle = function(){
  const G = groundBegin({ sky: 'violet', input: { touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('TAP LEFT / RIGHT HALF: TURN · BOOST · ⚡ / LB: SPECIAL', '← → or A D: TURN 90° · SHIFT: BOOST · V: SPECIAL');

  const me = makeRider([0, 0, 0], 0, colour, false);
  const RCOL = ['#ff2d9a', '#ffd700', '#ff6600', '#39ff88'];
  const riders = [me];
  const spawnRival = () => {
    const a = Math.random() * TAU, d = rr(90, 150);
    const p = V.add(me.p, [Math.round(Math.cos(a) * d / 2) * 2, 0, Math.round(Math.sin(a) * d / 2) * 2]);
    riders.push(makeRider(p, (Math.random() * 4) | 0, RCOL[riders.length % RCOL.length], true));
  };
  for(let i = 0; i < 4; i++) spawnRival();
  let score = 0, derez = 0, over = false, msg = '', msgT = 0, inv = 0, boostE = 100;
  const city = makeCity({ seed: 2727, density: 0.12, cell: 110, clear: 120, hMin: 20, hMax: 70, radius: 760, towerColor: '#0a0716' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#a855f7,#00f5ff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };
  // ⚡ Specials: a Shield Burst rides straight through light, Smart Missiles
  // and the Nova derez riders, a Time Warp slows them, and the EMP drops every
  // rival wall and blinds their steering — they ride straight while it holds.
  const SP = P.owKit.makeSpecials(G, {
    kinds: ['shield', 'smart', 'warp', 'emp', 'nova'], every: 200, bubbleR: 2.6, novaR: 50,
    player: () => [me.p[0], 0.9, me.p[2]],
    targets: () => riders.filter(x => x.ai && x.alive).map(x => ({ p: [x.p[0], 0.9, x.p[2]], r: 1.8, obj: x })),
    hit: rd => { if(rd.alive) crash(rd); },
    onUse: k => {
      if(k !== 'emp') return;
      for(const rd of riders) if(rd.ai) rd.trail = [V.copy(rd.p)];
      say('RIVAL LIGHT WALLS DOWN', 1.6);
    },
    onEnd: k => { if(k === 'shield') inv = Math.max(inv, 1.0); }
  });

  // Turning: keys (edge), the touch halves, or a mouse click on either half.
  let pendingTurn = 0;
  const turn = (rd, s) => {
    if(!rd.alive) return;
    rd.dir = (rd.dir + s + 4) % 4;
    rd.trail.push(V.copy(rd.p));
    rd.turned = 0.18 * s;
  };
  // Segment list for collisions: every rider's trail, oldest point first.
  function trailHit(p, self){
    for(const rd of riders){
      const T = rd.trail;
      const n = T.length;
      for(let i = 0; i < n; i++){
        const a = T[i], b = i + 1 < n ? T[i + 1] : rd.p;
        // Your own newest segment always "touches" you.
        if(rd === self && i >= n - 1) continue;
        const minx = Math.min(a[0], b[0]) - 0.5, maxx = Math.max(a[0], b[0]) + 0.5;
        const minz = Math.min(a[2], b[2]) - 0.5, maxz = Math.max(a[2], b[2]) + 0.5;
        if(p[0] > minx && p[0] < maxx && p[2] > minz && p[2] < maxz){
          // A rider's own corner it just left: ignore the stub behind it.
          if(rd === self && i === n - 2 && Math.hypot(p[0] - b[0], p[2] - b[2]) < 1.2) continue;
          return rd;
        }
      }
    }
    return null;
  }
  // Free run ahead, in units, for an AI deciding where to go.
  function freeAhead(rd, dir, maxD){
    const d = DIRS[dir];
    for(let s = 2; s <= maxD; s += 2){
      const q = [rd.p[0] + d[0] * s, 0, rd.p[2] + d[1] * s];
      if(trailHit(q, rd) || city.hit(q, 0.5)) return s;
    }
    return maxD;
  }
  function trimTrail(rd){
    // Keep at most TRAIL_MAX units of light, fading out from the oldest end.
    let total = 0;
    const T = rd.trail;
    for(let i = T.length - 1; i >= 0; i--){
      const b = i + 1 < T.length ? T[i + 1] : rd.p;
      total += Math.abs(b[0] - T[i][0]) + Math.abs(b[2] - T[i][2]);
      if(total > TRAIL_MAX){
        const over = total - TRAIL_MAX;
        const a = T[i], seg = Math.abs(b[0] - a[0]) + Math.abs(b[2] - a[2]);
        const t = over / Math.max(seg, 1e-6);
        T[i] = [a[0] + (b[0] - a[0]) * t, 0, a[2] + (b[2] - a[2]) * t];
        T.splice(0, i);
        break;
      }
    }
  }
  function crash(rd){
    rd.alive = false;
    fx.explode([rd.p[0], 0.8, rd.p[2]], 1.8, { color: rd.col, debrisGeo: 'slab', debrisColor: '#1a1a2a' });
    if(rd === me){
      if(survivedFatal()){
        rd.alive = true; inv = 2; rd.dir = (rd.dir + 2) % 4; rd.trail.push(V.copy(rd.p));
        say('SHIELD ABSORBED', 1.6); return;
      }
      snd('bigExplode'); w.kick(1.6);
      gLater(() => end('crash'), 1300);
    }else{
      derez++;
      score += 150; setLive(score);
      snd('explode');
      w.pop([rd.p[0], 3, rd.p[2]], '+150 DEREZZED', rd.col, { size: 15 });
      rd.respawn = 3.5;
    }
  }
  function end(why){
    if(over) return;
    over = true;
    owFinish('lightcycle', score, {
      '📡 Ride': why === 'clock' ? 'CLOCK EXPIRED' : 'DEREZZED',
      '💥 Riders Derezzed': derez,
      '📏 Distance': Math.round(me.dist || 0) + ' u',
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = { state: () => ({ score, derez, alive: me.alive, riders: riders.length, segs: riders.reduce((s, x) => s + x.trail.length, 0) }),
                specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use() };

  runLoop(dt => {
    if(over) return false;
    const I = inp.poll();
    if(dt > 0){
      if(me.alive) SP.tick(dt, I, score);
      // Input: an edge on left/right turns once.
      if(me.alive){
        const pr = I.pressed || {};
        let t = 0;
        if(pr.ArrowLeft || pr.KeyA) t = -1;
        if(pr.ArrowRight || pr.KeyD) t = 1;
        // Touch: a fresh touch on the left half (the stick) turns left, on the
        // right half (fire) turns right. Mouse: a click on either half.
        if(I.stick && !inp._held){ inp._held = true; t = -1; }
        if(!I.stick) inp._held = false;
        const clickLike = I.device === 'touch' || I.device === 'mouse';
        if(I.fire && clickLike && !inp._fireHeld){ inp._fireHeld = true; t = I.device === 'mouse' ? (I.mx < 0 ? -1 : 1) : 1; }
        if(!I.fire) inp._fireHeld = false;
        const pad = I.pad;
        if(pad){
          const sx = pad.lx;
          if(sx < -0.6 && !inp._padHeld){ inp._padHeld = true; t = -1; }
          else if(sx > 0.6 && !inp._padHeld){ inp._padHeld = true; t = 1; }
          else if(Math.abs(sx) < 0.3) inp._padHeld = false;
        }
        if(t) turn(me, t);
      }
      const boosting = I.boost && boostE > 2;
      boostE = clamp(boostE + (boosting ? -30 : 12) * dt, 0, 100);
      me.speed += ((boosting ? 40 : 26) - me.speed) * ease(dt, 0.25);
      inv = Math.max(0, inv - dt);

      for(const rd of riders){
        if(!rd.alive){
          if(rd.ai){
            rd.respawn -= dt;
            if(rd.respawn <= 0){
              const a = Math.random() * TAU, d = rr(90, 150);
              rd.p = V.add(me.p, [Math.round(Math.cos(a) * d / 2) * 2, 0, Math.round(Math.sin(a) * d / 2) * 2]);
              rd.trail = [V.copy(rd.p)]; rd.alive = true; rd.dir = (Math.random() * 4) | 0;
            }
          }
          continue;
        }
        if(rd.ai){
          rd.speed = 26 * Math.min(1.25, diff) * SP.warp();
          rd.think -= dt;
          const ahead = SP.jammed() ? 99 : freeAhead(rd, rd.dir, 14);
          if(!SP.jammed() && (ahead < 12 || rd.think <= 0)){
            rd.think = rr(0.6, 2.2);
            const L = freeAhead(rd, (rd.dir + 3) % 4, 30), R = freeAhead(rd, (rd.dir + 1) % 4, 30);
            // Hunt: lean toward cutting across the player's path.
            const toMe = V.sub(V.madd(me.p, [DIRS[me.dir][0], 0, DIRS[me.dir][1]], 20), rd.p);
            const d = DIRS[rd.dir];
            const cross = d[0] * toMe[2] - d[1] * toMe[0];
            if(ahead < 12) turn(rd, L > R ? -1 : 1);
            else if(Math.random() < 0.5 && Math.hypot(toMe[0], toMe[2]) < 70) turn(rd, cross > 0 ? 1 : -1);
            else if(Math.random() < 0.25) turn(rd, L > R ? -1 : 1);
          }
        }
        const d = DIRS[rd.dir];
        rd.p = [rd.p[0] + d[0] * rd.speed * dt, 0, rd.p[2] + d[1] * rd.speed * dt];
        rd.spin = P.kit.wheelSpin(rd.spin, rd.speed * dt, 2.2);
        if(rd === me) me.dist = (me.dist || 0) + rd.speed * dt;
        rd.turned *= Math.max(0, 1 - 8 * dt);
        trimTrail(rd);
        city.update(rd === me ? rd.p : me.p);
        if(!(rd === me && (inv > 0 || SP.shielded()))){
          const hit = trailHit(rd.p, rd);
          if(hit || city.hit(rd.p, 0.6)){
            crash(rd);
          }
        }
      }
      // Riders that fell far behind are recycled.
      for(const rd of riders) if(rd.ai && rd.alive && V.d2(rd.p, me.p) > 360 * 360){ rd.alive = false; rd.respawn = 0.5; }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    // Distance pays a trickle; survival does the rest.
    if(dt > 0 && me.alive){ me.payT = (me.payT || 0) + dt; if(me.payT > 1){ me.payT = 0; score += 3; setLive(score); } }

    chaseCam(w, me.p, yawOf(me.dir), { back: 10, up: 4.4, ahead: 18, fov: 66, half: 0.09 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 8, radius: 200, color: '#3a1d6e', glow: 1.0, major: 4, floor: '#04030b', rough: 0.22 });
    city.draw(w);
    const eye = w.cam.eye;
    // Light walls: one emissive panel per segment, culled.
    for(const rd of riders){
      const T = rd.trail, n = T.length;
      for(let i = 0; i < n; i++){
        const a = T[i], b = i + 1 < n ? T[i + 1] : rd.p;
        const mid = [(a[0] + b[0]) / 2, 1.1, (a[2] + b[2]) / 2];
        const len = Math.abs(b[0] - a[0]) + Math.abs(b[2] - a[2]);
        if(len < 0.05) continue;
        if(V.d2(mid, eye) > (260 + len / 2) ** 2) continue;
        if(!r.viewDepth(mid, 1.4 + len / Math.max(30, Math.sqrt(V.d2(mid, eye))))) continue;
        const fade = i === 0 ? 0.55 : 1;
        r.beam([a[0], 1.1, a[2]], [b[0], 1.1, b[2]], 0.12, { color: rd.col, emissive: rd.col, emissiveStrength: 1.9 * fade, height: 2.2 });
        r.beam([a[0], 2.25, a[2]], [b[0], 2.25, b[2]], 0.16, { color: '#ffffff', emissive: rd.col, emissiveStrength: 3.0 * fade, height: 0.08 });
      }
    }
    // The cycles.
    for(const rd of riders){
      if(!rd.alive) continue;
      if(rd === me && inv > 0 && Math.sin(w.t * 30) > 0) continue;
      if(V.d2(rd.p, eye) > 300 * 300) continue;
      const B = basisYPR(yawOf(rd.dir), 0, rd.turned * 2.2);
      // ✨ v60 · A rival is PAINTED, NOT LIT (see ENEMY_PAINT): its colour as
      // a glossy livery, no lamps lit, no halo and no light hung round it —
      // its light wall is the only thing of it that glows.
      const look = rd === me ? { color: '#c9d1dd', metallic: 0.7, roughness: 0.3, rim: 0.9, emissive: rd.col, emissiveStrength: 0.004, accent: 0 }
                             : P.kit.foeLook(rd.col, false);
      r.draw('cycle', { pos: rd.p, m3: B.m3, scale: 2.2, ...look });
      // ✨ v60 · the wheels turn with the distance ridden (rd.spin).
      P.kit.drawWheels(r, rd.p, B.m3, 2.2, rd.spin || 0, look);
      if(rd === me){
        r.glow([rd.p[0], 0.8, rd.p[2]], 2.6, rd.col, 0.6);
        r.light({ pos: [rd.p[0], 3, rd.p[2]], color: rd.col, intensity: 110, range: 22 });
      }
    }
    if(me.alive) SP.draw();
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht], [Wd - 160, Ht - 44, Wd, Ht]];
    SP.hud();
    const rad = riders.filter(x => x !== me && x.alive).map(x => ({ p: x.p, c: x.col, s: 3 }));
    hud.radar(70, Ht - 74, 54, me.p, [DIRS[me.dir][0], 0, DIRS[me.dir][1]], 160, rad);
    for(const rd of riders){ if(rd === me || !rd.alive) continue; const q = hud.proj(rd.p); if(!q.on && V.d2(rd.p, me.p) < 120 * 120) hud.edgeArrow(rd.p, rd.col, null); }
    hud.bar(Wd - 150, Ht - 26, 130, 8, boostE / 100, '#a855f7', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 26, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    if(I.device === 'touch'){
      hud.text(Wd * 0.25, Ht * 0.5, '◀ TURN', { size: 12, color: '#bff6ff', alpha: 0.35 });
      hud.text(Wd * 0.75, Ht * 0.5, 'TURN ▶', { size: 12, color: '#bff6ff', alpha: 0.35 });
      hud.touchPad(I, ['boost', 'abil']);
    }
  });
};

})();


// ══════════════════════════════════════════════
//  🌌 CYBER RUNNER · OPEN WORLD — FREE RUN
// ══════════════════════════════════════════════
// No highway and no lanes: an endless dusk plain strewn with barriers you can
// jump, walls you must go round, pylons, gates to thread and lines of data to
// collect. You choose the line; the speed keeps climbing.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, wrapAng, ease, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, chaseCam, makeCity, drawRover } = P.owGround;
const { mine, clamp, runLoop } = P.kit;

P.ow.runner = function(){
  const G = groundBegin({ sky: 'dusk', input: { mouseSteer: true, mouseGain: 1.3, spaceJumps: true, touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: STEER · JUMP · BOOST · ⚡ / LB: SPECIAL', 'A/D or ←/→ or MOUSE: STEER · SPACE: JUMP · SHIFT: BOOST · V: SPECIAL');

  const me = { p: [0, 0, 0], yaw: 0, vy: 0, y: 0, speed: 30, shields: 3, inv: 0, bank: 0, dist: 0 };
  let score = 0, orbs = 0, gates = 0, over = false, msg = '', msgT = 0, boostE = 100;
  const ORB = '#00f5ff';
  const obs = makeField({
    cell: 44, dims: 2, seed: 31337, radius: 330,
    gen(cx, cy, cz, g){
      const items = [];
      const x = (cx + 0.5) * 44, z = (cz + 0.5) * 44;
      if(Math.hypot(x, z) < 50) return items;
      const roll = g();
      const yaw = g() * Math.PI;
      if(roll < 0.28) items.push({ t: 'bar', p: [x + (g() - 0.5) * 20, 0, z + (g() - 0.5) * 20], yaw, len: 8 + g() * 10, h: 1.1 });
      else if(roll < 0.44) items.push({ t: 'wall', p: [x, 0, z], yaw, len: 14 + g() * 16, h: 6 });
      else if(roll < 0.6) items.push({ t: 'pylon', p: [x + (g() - 0.5) * 24, 0, z + (g() - 0.5) * 24], r: 1.4, h: 16 + g() * 10 });
      else if(roll < 0.72) items.push({ t: 'gate', p: [x, 0, z], yaw, w: 7, h: 6, passed: false });
      // Orb lines: an arc of data across the cell.
      if(g() < 0.55){
        const n = 5 + ((g() * 4) | 0), a0 = g() * TAU, bend = (g() - 0.5) * 0.6;
        for(let i = 0; i < n; i++){
          const a = a0 + bend * i;
          items.push({ t: 'orb', p: [x + Math.cos(a0) * (i - n / 2) * 3.2 + Math.sin(a) * 2, 1.2 + (g() < 0.2 ? 2.2 : 0), z + Math.sin(a0) * (i - n / 2) * 3.2 + Math.cos(a) * 2] });
        }
      }
      return items;
    }
  });
  const city = makeCity({ seed: 5150, density: 0.1, cell: 120, clear: 140, hMin: 30, hMax: 90, radius: 800, towerColor: '#120818' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ff4f6a,#ffd700)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  // Box test in an obstacle's own frame.
  const inBox = (p, o, hw, hd) => {
    const dx = p[0] - o.p[0], dz = p[2] - o.p[2];
    const c = Math.cos(o.yaw), s = Math.sin(o.yaw);
    const lx = dx * c - dz * s, lz = dx * s + dz * c;
    return Math.abs(lx) < hw && Math.abs(lz) < hd;
  };
  function hurt(at){
    if(me.inv > 0 || over) return;
    // 🛡️ Shield Burst, and 👻 Phase Shift — straight through.
    if(SP.shielded() || SP.active('phase')) return;
    me.shields--;
    me.inv = 1.4; me.speed = Math.min(me.speed, 14);
    snd('hurt'); w.kick(1.1);
    fx.explode([at[0], 1, at[2]], 1.0, { color: '#ff5a4a', debris: 3, smoke: 1, ring: false });
    bar.style.width = (Math.max(0, me.shields) / 3 * 100) + '%';
    if(me.shields <= 0){
      if(survivedFatal()){ me.shields = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); return; }
      snd('bigExplode');
      fx.explode([me.p[0], 1, me.p[2]], 2.4, { color: '#ff8a3a' });
      over = true;
      gLater(() => finish('crash'), 1200);
    }
  }
  let finished = false;
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('runner', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'WIPED OUT',
      '📏 Distance': Math.round(me.dist) + ' m',
      '💠 Data Orbs': orbs,
      '⛩ Gates Threaded': gates,
      '🏆 Score': score + ' PTS'
    });
  }
  // ⚡ v60 · SPECIALS (the kit): Shield Burst and Nova (which clears the
  // obstacles round you), and the new Magnet Field and Phase Shift. One
  // every 150 points.
  const SP = P.owKit.makeSpecials(G, {
    kinds: ['shield', 'magnet', 'phase', 'nova'],
    every: 150, novaR: 34, bubbleR: 2.8, magnetR: 30, hudLift: 24,
    player: () => [me.p[0], me.y + 1, me.p[2]],
    targets: () => { const T = []; obs.each(o => { if(o.t !== 'orb' && o.t !== 'gate' && V.d2(o.p, me.p) < 60 * 60) T.push({ p: [o.p[0], 1, o.p[2]], r: o.r || 2, obj: o }); }); return T; },
    hit: o => { obs.kill(o); fx.explode([o.p[0], 1, o.p[2]], 1.6, { color: '#ff4fd8', debris: 4, debrisGeo: 'slab', debrisColor: '#2a1a2a', smoke: 1 }); },
    heal: () => { me.shields = Math.min(3, me.shields + 1); bar.style.width = (me.shields / 3 * 100) + '%'; }
  });
  P.owDebug = { state: () => ({ score, dist: Math.round(me.dist), speed: Math.round(me.speed), shields: me.shields }), specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use() };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      SP.tick(dt, I, score);
      me.inv = Math.max(0, me.inv - dt);
      const steer = clamp(I.ax, -1, 1);
      me.yaw = wrapAng(me.yaw - steer * 1.9 * dt);
      me.bank += (clamp(steer * 0.55, -0.6, 0.6) - me.bank) * ease(dt, 0.1);
      const base = Math.min(72, 30 + me.dist * 0.012) * Math.min(1.3, diff);
      const boosting = I.boost && boostE > 2;
      boostE = clamp(boostE + (boosting ? -32 : 10) * dt, 0, 100);
      me.speed += ((boosting ? base * 1.45 : base) - me.speed) * ease(dt, 0.6);
      if((I.jumpHit || (I.pressed && I.pressed.Space)) && me.y <= 0.01){ me.vy = 9.5; snd('jump'); }
      me.vy -= 24 * dt;
      me.y = Math.max(0, me.y + me.vy * dt);
      if(me.y <= 0) me.vy = 0;
      const f = [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)];
      me.p = V.madd(me.p, f, me.speed * dt);
      me.dist += me.speed * dt;
      // Distance pays.
      me.payT = (me.payT || 0) + me.speed * dt;
      if(me.payT > 25){ me.payT = 0; score += 5; setLive(score); }
      obs.update(me.p);
      city.update(me.p);
      const hp = [me.p[0], me.y, me.p[2]];
      // 🧲 The magnet takes every orb within thirty metres.
      if(SP.active('magnet')) obs.each(o => {
        if(o.t === 'orb' && V.d2(o.p, hp) < 30 * 30){ obs.kill(o); orbs++; score += 10; setLive(score); snd('coin'); fx.sparks(o.p, 4, ORB, 0.8, 8); }
      });
      obs.near(hp, o => {
        if(o.t === 'orb'){
          if(V.d2(o.p, [hp[0], hp[1] + 0.9, hp[2]]) < 2.2 * 2.2){ obs.kill(o); orbs++; score += 10; setLive(score); snd('coin'); fx.glowPop(o.p, ORB, 1.4, 0.3); }
        }else if(o.t === 'bar'){
          if(me.y < o.h - 0.1 && inBox(hp, o, o.len / 2, 0.9)) hurt(hp);
        }else if(o.t === 'wall'){
          if(inBox(hp, o, o.len / 2, 1.1)) hurt(hp);
        }else if(o.t === 'pylon'){
          if((hp[0] - o.p[0]) ** 2 + (hp[2] - o.p[2]) ** 2 < (o.r + 0.9) ** 2) hurt(hp);
        }else if(o.t === 'gate'){
          // The posts are solid; the space between them pays.
          for(const s of [-1, 1]){
            const px = o.p[0] + Math.cos(o.yaw) * s * o.w / 2, pz = o.p[2] - Math.sin(o.yaw) * s * o.w / 2;
            if((hp[0] - px) ** 2 + (hp[2] - pz) ** 2 < 1.6 * 1.6) hurt(hp);
          }
          if(!o.passed && inBox(hp, o, o.w / 2 - 0.8, 1.2)){ o.passed = true; gates++; score += 25; setLive(score); snd('score'); w.pop([o.p[0], o.h + 1, o.p[2]], '+25 GATE', '#ffd700', { size: 14 }); }
        }
      });
      if(city.hit(hp, 0.8) && !SP.active('phase')) hurt(hp);
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    chaseCam(w, [me.p[0], me.y * 0.6, me.p[2]], me.yaw, { back: 9.5, up: 3.6, ahead: 16, fov: 62 + clamp((me.speed - 30) / 4, 0, 14), half: 0.08 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 170, color: '#5a1a4a', glow: 1.1, major: 5, floor: '#0a0410', rough: 0.25 });
    city.draw(w);
    const eye = w.cam.eye;
    obs.each(o => {
      const d2 = V.d2(o.p, eye);
      if(d2 > 300 * 300) return;
      if(!r.viewDepth([o.p[0], 2, o.p[2]], 1.5)) return;
      if(o.t === 'orb'){
        r.draw('sphere', { pos: o.p, scale: 0.8, color: ORB, emissive: ORB, emissiveStrength: 1.8 });
        r.glow(o.p, 1.5, ORB, 0.7);
      }else if(o.t === 'bar'){
        r.draw('slab', { pos: [o.p[0], o.h / 2, o.p[2]], rot: [0, o.yaw, 0], scale: [o.len, o.h, 1.2], color: '#2a0e1a', metallic: 0.6, roughness: 0.4, emissive: '#ff2d6a', emissiveStrength: 0.004 });
        r.draw('box', { pos: [o.p[0], o.h + 0.05, o.p[2]], rot: [0, o.yaw, 0], scale: [o.len, 0.12, 1.3], color: '#ff2d6a', emissive: '#ff2d6a', emissiveStrength: 2.6 });
      }else if(o.t === 'wall'){
        r.draw('cube', { pos: [o.p[0], o.h / 2, o.p[2]], rot: [0, o.yaw, 0], scale: [o.len, o.h, 1.6], color: '#1a1424', metallic: 0.7, roughness: 0.36 });
        r.draw('box', { pos: [o.p[0], o.h * 0.5, o.p[2]], rot: [0, o.yaw, 0], scale: [o.len * 1.002, 0.16, 1.7], color: '#ffd700', emissive: '#ffb000', emissiveStrength: 2.0 });
      }else if(o.t === 'pylon'){
        r.draw('cylinder', { pos: [o.p[0], o.h / 2, o.p[2]], scale: [o.r * 2, o.h, o.r * 2], color: '#141022', metallic: 0.8, roughness: 0.3 });
        r.draw('box', { pos: [o.p[0], o.h * 0.6, o.p[2]], scale: [o.r * 2.1, o.h * 0.5, 0.2], color: '#ff4fd8', emissive: '#ff4fd8', emissiveStrength: 2.0 });
        r.glow([o.p[0], o.h + 0.5, o.p[2]], 1.4, '#ff4fd8', 0.9);
      }else if(o.t === 'gate'){
        const c = Math.cos(o.yaw), s = Math.sin(o.yaw);
        const col = o.passed ? '#39ff88' : '#ffd700';
        for(const k of [-1, 1]) r.draw('cylinder', { pos: [o.p[0] + c * k * o.w / 2, o.h / 2, o.p[2] - s * k * o.w / 2], scale: [0.7, o.h, 0.7], color: '#1c1830', metallic: 0.8, roughness: 0.3, emissive: col, emissiveStrength: 0.004 });
        r.draw('box', { pos: [o.p[0], o.h, o.p[2]], rot: [0, o.yaw, 0], scale: [o.w + 0.7, 0.35, 0.5], color: col, emissive: col, emissiveStrength: 2.4 });
        r.streak([o.p[0] + c * o.w / 2, 0.3, o.p[2] - s * o.w / 2], [o.p[0] - c * o.w / 2, 0.3, o.p[2] + s * o.w / 2], 0.3, col, 1.2, 0);
      }
    });
    if(!(me.inv > 0 && Math.sin(w.t * 30) > 0)){
      drawRover(w, [me.p[0], me.y, me.p[2]], me.yaw, colour, { bank: me.bank, boost: clamp((me.speed - 30) / 40, 0, 1), scale: 1.6, accent: 0 });
    }
    // Speed streaks off the floor.
    if(me.speed > 40){
      for(let i = 0; i < 10; i++){
        const a = (i / 10) * TAU + w.t;
        const q = V.add(me.p, [Math.cos(a) * 6, 0.2 + (i % 3) * 1.4, Math.sin(a) * 6]);
        const f = [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)];
        r.streak(V.madd(q, f, 3 * (me.speed / 60)), q, 0.04, '#ffd8f0', 0.5, 1);
      }
    }
    SP.draw();
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    SP.hud();
    const rad = [];
    obs.each(o => { if(o.t === 'gate' && !o.passed) rad.push({ p: o.p, c: '#ffd700', s: 2.4 }); });
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 160, rad);
    hud.text(Wd - 16, Ht - 40, Math.round(me.speed * 3.6) + ' km/h', { size: 15, align: 'right', color: '#ffd8a0' });
    hud.text(Wd - 16, Ht - 20, '♦'.repeat(Math.max(0, me.shields)) + '◊'.repeat(Math.max(0, 3 - me.shields)), { size: 14, align: 'right', color: '#ff6a8a' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, boostE / 100, '#ffb000', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 26, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  💥 DODGE CORES · OPEN WORLD — BOMBARDMENT
// ══════════════════════════════════════════════
// The classic board is a box the cores bounce around in. Here there is no box:
// an open plain under a bombardment. Burning cores fall on you from the sky —
// a red ring marks where, a heartbeat before — then bounce and roll on across
// the plain; rolling barrages sweep in from the horizon. Run anywhere. Energy
// shards lie everywhere for the taking.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ease, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, followCam, makeCity, groundRing, screenToGround } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const MAGMA = 10.92;           // SURF.MAGMA + intensity — rock with glowing cracks

P.ow.dodge = function(){
  const G = groundBegin({ sky: 'ember', input: { touch: 'fly' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: MOVE · BOOST · ⚡ / LB: SPECIAL', 'WASD / ←↑↓→: MOVE · MOUSE: HOLD TO RUN AT THE CURSOR · SHIFT: DASH · V: SPECIAL');

  const me = { p: [0, 0, 0], v: [0, 0, 0], hp: 3, inv: 0, dash: 0, dashCd: 0 };
  let score = 0, shards = 0, alive = 0, over = false, finished = false, spawnT = 1.5, rollT = 9, msg = '', msgT = 0;
  const cores = [], warns = [];
  const field = makeField({
    cell: 30, dims: 2, seed: 1212, radius: 230,
    gen(cx, cy, cz, g){
      const items = [];
      const n = Math.floor(g() * 3.2);
      for(let i = 0; i < n; i++){
        const p = [(cx + g()) * 30, 0.9, (cz + g()) * 30];
        items.push({ p, gold: g() < 0.07, ph: g() * 6 });
      }
      return items;
    }
  });
  const city = makeCity({ seed: 8181, density: 0.08, cell: 140, clear: 200, hMin: 30, hMax: 80, radius: 820, towerColor: '#140806' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ff6600,#ffd700)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  function drop(){
    // Aimed a little ahead of where you are going.
    const lead = V.add(me.p, V.mul(me.v, rr(0.4, 1.1)));
    const at = [lead[0] + rr(-6, 6), 0, lead[2] + rr(-6, 6)];
    warns.push({ p: at, t: 0, life: Math.max(0.7, 1.25 / Math.sqrt(diff)), s: rr(1.4, 2.4) });
  }
  function barrage(){
    const a = Math.random() * TAU;
    const dir = [Math.cos(a), 0, Math.sin(a)];
    const side = [-dir[2], 0, dir[0]];
    const start = V.madd(me.p, dir, -70);
    const n = 5 + ((Math.random() * 4) | 0);
    for(let i = 0; i < n; i++){
      const p = V.add(V.madd(start, side, (i - n / 2) * 6.5), [0, 1.6, 0]);
      cores.push({ p, v: V.mul(dir, rr(16, 22) * diff), s: 1.6, life: 9, spin: [0, 0, 0], rot: [Math.random() * 6, 0, 0], roll: true });
    }
    say('⚠ ROLLING BARRAGE', 1.6);
    snd('alarm');
  }
  function hit(at){
    if(me.inv > 0 || over) return;
    // 🛡️ Shield Burst, and 👻 Phase Shift — nothing touches you.
    if(SP.shielded() || SP.active('phase')) return;
    me.hp--;
    me.inv = 1.4;
    snd('hurt'); w.kick(1.3);
    fx.sparks([me.p[0], 1, me.p[2]], 14, '#ff8a5a', 1.2, 14);
    bar.style.width = (Math.max(0, me.hp) / 3 * 100) + '%';
    if(me.hp <= 0){
      if(survivedFatal()){ me.hp = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); return; }
      over = true;
      snd('bigExplode');
      fx.explode([me.p[0], 1, me.p[2]], 2.4, { color: colour });
      gLater(() => finish('hit'), 1200);
    }
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    // 🛡️ Outlasting the bombardment FINISHES the mission, and a finished
    // mission pays its full cap — the same rule as the classic board. What the
    // run earned on the way (time and shards) is carried past the cap, where it
    // separates two survivors.
    const survived = why === 'clock';
    const full = META.dodge.maxPts;
    owFinish('dodge', score + (survived ? full : 0), {
      '📡 Run': survived ? 'CLOCK EXPIRED — SURVIVED' : 'CORE IMPACT',
      '⏱ Survived': Math.round(alive) + ' s',
      '💠 Shards': shards,
      ...(survived ? { '🛡️ Bombardment Survived': 'FULL ' + full + ' · +' + score + ' past the cap' } : {}),
      '🏆 Score': score + ' PTS'
    });
  }
  // ⚡ v60 · SPECIALS (the kit): Shield Burst, Time Warp and Nova from the 2D
  // builds, and the new Magnet Field (shards fly to you) and Phase Shift
  // (cores pass straight through). One every 120 points.
  const SP = P.owKit.makeSpecials(G, {
    kinds: ['shield', 'warp', 'magnet', 'nova', 'phase'],
    every: 120, novaR: 26, bubbleR: 2.6, magnetR: 45,
    player: () => [me.p[0], 1.1, me.p[2]],
    targets: () => cores.map(c => ({ p: c.p, r: c.s * 0.6, obj: c })),
    hit: c => { const i = cores.indexOf(c); if(i >= 0){ cores.splice(i, 1); fx.explode(c.p, c.s * 0.7, { color: '#ff7a1a', debris: 2, smoke: 1 }); } },
    clearFire: (p, R) => { for(let i = warns.length - 1; i >= 0; i--) if(V.d2(warns[i].p, p) < R * R) warns.splice(i, 1); },
    heal: k => { me.hp = Math.min(3, me.hp + Math.max(1, Math.round(3 * k))); bar.style.width = (me.hp / 3 * 100) + '%'; }
  });
  P.owDebug = { state: () => ({ score, hp: me.hp, cores: cores.length, warns: warns.length, shards }), specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use() };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      alive += dt;
      me.payT = (me.payT || 0) + dt;
      if(me.payT >= 1){ me.payT = 0; score += 2; setLive(score); }
      SP.tick(dt, I, score);
      me.inv = Math.max(0, me.inv - dt);
      me.dashCd = Math.max(0, me.dashCd - dt);
      // Move: keys / stick on world axes; a held mouse runs at the cursor.
      let mx = I.lx, mz = I.ly;
      if(I.device === 'mouse' && I.mDown && hud.cam){
        const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
        if(g){ const d = V.sub(g, me.p); const l = Math.hypot(d[0], d[2]); if(l > 1.2){ mx = d[0] / l; mz = d[2] / l; } }
      }
      const ml = Math.hypot(mx, mz);
      if(ml > 1){ mx /= ml; mz /= ml; }
      if(I.boost && me.dashCd <= 0 && ml > 0.1){ me.dash = 0.22; me.dashCd = 1.6; snd('dash'); }
      me.dash = Math.max(0, me.dash - dt);
      const sp = (me.dash > 0 ? 46 : 19);
      const want = [mx * sp, 0, mz * sp];
      me.v = V.lerp(me.v, want, ease(dt, me.dash > 0 ? 0.02 : 0.08));
      me.p = V.madd(me.p, me.v, dt);
      field.update(me.p);
      city.update(me.p);
      // 🧲 A magnet draws in every shard in range.
      const reach = SP.active('magnet') ? 45 : 2.0;
      const grab = SP.active('magnet') ? (fn => field.each(fn)) : (fn => field.near(me.p, fn));
      grab(it => {
        if((it.p[0] - me.p[0]) ** 2 + (it.p[2] - me.p[2]) ** 2 < reach * reach){
          field.kill(it); shards++; score += it.gold ? 60 : 15; setLive(score);
          snd(it.gold ? 'powerup' : 'coin'); fx.glowPop(it.p, it.gold ? '#ffd700' : '#00f5ff', 1.6, 0.3);
        }
      });
      const tb = city.hit(me.p, 0.9);
      if(tb){ // slide off a tower
        const dx = me.p[0] - tb.p[0], dz = me.p[2] - tb.p[2];
        if(Math.abs(dx) / (tb.w / 2) > Math.abs(dz) / (tb.d / 2)) me.p[0] = tb.p[0] + Math.sign(dx) * (tb.w / 2 + 0.95);
        else me.p[2] = tb.p[2] + Math.sign(dz) * (tb.d / 2 + 0.95);
      }
      // Spawning tightens with time and tier.
      spawnT -= dt;
      if(spawnT <= 0){ drop(); if(alive > 40 && Math.random() < 0.35) drop(); spawnT = Math.max(0.35, 1.25 - alive * 0.008) / diff; }
      rollT -= dt;
      if(rollT <= 0){ barrage(); rollT = Math.max(6, 14 - alive * 0.05); }
    }
    // Warnings → impacts (slowed by a Time Warp like everything else).
    for(let i = warns.length - 1; i >= 0; i--){
      const wn = warns[i];
      wn.t += dt * SP.warp();
      if(wn.t >= wn.life){
        warns.splice(i, 1);
        const a = Math.random() * TAU;
        cores.push({ p: [wn.p[0], 42, wn.p[2]], v: [0, -38, 0], s: wn.s, life: 7.5, falling: true, rot: [0, 0, 0], spin: [rr(-3, 3), rr(-3, 3), 0], kick: [Math.cos(a), Math.sin(a)] });
      }
    }
    // Cores: fall, slam, bounce, roll. ⏳ Half speed in a Time Warp.
    const cdt = dt * SP.warp();
    for(let i = cores.length - 1; i >= 0; i--){
      const c = cores[i];
      if(dt <= 0) break;
      c.life -= cdt;
      if(c.life <= 0 || V.d2(c.p, me.p) > 260 * 260){ cores.splice(i, 1); continue; }
      c.v[1] -= 32 * cdt;
      c.p = V.madd(c.p, c.v, cdt);
      c.rot[0] += c.spin[0] * dt; c.rot[1] += c.spin[1] * dt;
      if(c.roll) c.rot[0] += V.len(c.v) / c.s * dt;
      if(c.p[1] < c.s * 0.5){
        c.p[1] = c.s * 0.5;
        if(c.falling){
          c.falling = false;
          fx.explode([c.p[0], 0.4, c.p[2]], c.s * 0.9, { color: '#ff7a1a', debrisGeo: 'rock2', debrisColor: '#2a1a14', ringNormal: [0, 1, 0], grav: 24, smoke: 3 });
          snd('explode');
          w.kick(0.4);
          const sp = rr(7, 13);
          c.v = [c.kick[0] * sp, 9, c.kick[1] * sp];
          // The slam itself: anything close is hit.
          if(Math.hypot(me.p[0] - c.p[0], me.p[2] - c.p[2]) < c.s * 1.6) hit(c.p);
        }else if(c.v[1] < 0){
          c.v[1] = -c.v[1] * 0.45;
          if(c.v[1] < 2) c.v[1] = 0;
          c.v[0] *= 0.92; c.v[2] *= 0.92;
        }
      }
      if(!over && V.d2([c.p[0], 0, c.p[2]], me.p) < (c.s * 0.5 + 0.8) ** 2 && c.p[1] < c.s + 1.2) hit(c.p);
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    followCam(w, me.p, { height: 30, back: 21, look: 2, fov: 52, half: 0.1 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 5, radius: 140, color: '#5a2a0a', glow: 0.9, major: 6, floor: '#0a0503', rough: 0.3 });
    city.draw(w);
    const eye = w.cam.eye;
    field.each(it => {
      if(V.d2(it.p, eye) > 150 * 150 || !r.viewDepth(it.p, 1.2)) return;
      const y = 0.9 + 0.25 * Math.sin(w.t * 3 + it.ph), c = it.gold ? '#ffd700' : '#00f5ff';
      r.draw('cube', { pos: [it.p[0], y, it.p[2]], rot: [w.t, w.t * 1.3, 0.6], scale: it.gold ? 1.0 : 0.7, color: c, emissive: c, emissiveStrength: 1.6, detail: 0 });
      r.glow([it.p[0], y, it.p[2]], 1.6, c, 0.6);
    });
    for(const wn of warns){
      const k = wn.t / wn.life;
      groundRing(w, wn.p, wn.s * (1.6 - k * 0.6), '#ff2a2a', 0.6 + k * 1.6);
      r.streak([wn.p[0], 0.1, wn.p[2]], [wn.p[0], 30 * (1 - k), wn.p[2]], 0.4, '#ff3a2a', 0.4 + k, 0);
    }
    let nl = 0;
    for(const c of cores){
      if(V.d2(c.p, eye) > 200 * 200) continue;
      r.draw('rock', { pos: c.p, rot: c.rot, scale: c.s, color: '#5a4038', metallic: 0.1, roughness: 0.85, rim: 0.4, emissive: '#ff6a10', emissiveStrength: 1.4, detail: MAGMA });
      if(c.falling) r.fire(V.add(c.p, [0, c.s * 0.7, 0]), c.s * 2.4, 1.5, 0.28, (c.s * 0.37) % 1);   // ✨ v59 burning as it falls
      if(c.falling) r.streak(V.add(c.p, [0, 8, 0]), c.p, c.s * 0.7, '#ff8a3a', 1.6, 1);
      if(nl++ < 3) r.light({ pos: c.p, color: '#ff7a2a', intensity: 90, range: 14 });
    }
    // You: a glowing core in a spinning ring.
    if(!over && !(me.inv > 0 && Math.sin(w.t * 30) > 0)){
      const y = 1.1;
      r.draw('sphere', { pos: [me.p[0], y, me.p[2]], scale: 1.5, color: '#e8f6ff', metallic: 0.3, roughness: 0.2, rim: 1.2, emissive: colour, emissiveStrength: 1.2 });
      r.draw('torus', { pos: [me.p[0], y, me.p[2]], rot: [Math.PI / 2 + Math.sin(w.t) * 0.3, w.t * 2, 0], scale: 3.0, color: '#cfd8e8', metallic: 0.8, roughness: 0.25, emissive: colour, emissiveStrength: 0.4 });
      r.glow([me.p[0], y, me.p[2]], 3.2, colour, 0.9);
      if(me.dash > 0) r.streak(V.madd([me.p[0], y, me.p[2]], V.norm(me.v), -6), [me.p[0], y, me.p[2]], 1.2, colour, 1.6, 1);
    }
    r.light({ pos: [me.p[0], 6, me.p[2] + 3], color: '#ffd8b0', intensity: 140, range: 26 });
    SP.draw();
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    SP.hud();
    const rad = cores.map(c => ({ p: c.p, c: '#ff6a2a', s: 2.6 })).concat(warns.map(wn => ({ p: wn.p, c: '#ff2a2a', s: 2 })));
    hud.radar(70, Ht - 74, 54, me.p, [0, 0, -1], 90, rad);
    hud.text(Wd - 16, Ht - 20, '♥'.repeat(Math.max(0, me.hp)) + '♡'.repeat(Math.max(0, 3 - me.hp)), { size: 16, align: 'right', color: '#ff6a8a' });
    hud.text(Wd - 16, Ht - 42, Math.round(alive) + ' s', { size: 13, align: 'right', color: '#ffd8a0' });
    for(const c of cores){ if(c.roll){ const q = hud.proj(c.p); if(!q.on && V.d2(c.p, me.p) < 80 * 80) hud.edgeArrow(c.p, '#ff6a2a', null); } }
    if(msgT > 0) hud.text(Wd / 2, 26, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  ⚔️ CYBER ARENA · OPEN WORLD — NO EDGE
// ══════════════════════════════════════════════
// The pit had walls to back into. This battlefield has none: a city plain
// that goes on in every direction, waves of drones, walkers and tanks closing
// in from all sides, and the towers are the only cover there is. Move with
// one hand, aim with the other — the camera never turns, so up is always up.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ease, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, followCam, makeCity, screenToGround } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);

P.ow.arena = function(){
  const G = groundBegin({ sky: 'ice', input: { touch: 'twin' } });
  const { basisLook, plume, makeSpecials } = P.owKit;
  // ✨ v59 · Where a gun really is. A point on a model (model units) → world,
  // under the yaw the model is drawn with (rot [0, face, 0], Rz·Ry·Rx).
  const onModel = (q, p, face, sc, y0) => {
    const c = Math.cos(face), sn = Math.sin(face);
    return [p[0] + (q[0] * c + q[2] * sn) * sc, y0 + q[1] * sc, p[2] + (-q[0] * sn + q[2] * c) * sc];
  };
  const POD = [[0.37, 0.57, -0.19], [-0.37, 0.57, -0.19]];     // the mech's podR / podL (tube mouths)
  const ARM = [[0.33, 0.2, -0.67], [-0.33, 0.2, -0.67]];       // its muzzleR / muzzleL
  const GUN = [0, 0.288, -0.94];                                // the tank's muzzle
  const ME_S = 2.7, ME_Y = 1.35;                                // the player walker's draw (below)
  let podK = 0, armK = 0;
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('LEFT STICK: MOVE · RIGHT STICK: AIM + FIRE · MSL: MISSILES · LB / ⚡: ABILITY', 'WASD: MOVE · MOUSE: AIM · CLICK / SPACE: FIRE · E: MISSILES · SHIFT: DASH · F: SHOCKWAVE · V: ABILITY');
  inp.altLabel = 'WAVE';
  inp.jumpLabel = 'MSL';

  const me = { p: [0, 0, 0], v: [0, 0, 0], hp: 100, inv: 0, aim: [0, 0, -1], cool: 0, dashCd: 0, dash: 0, rapid: 0, spread: 0, shock: 2, face: 0,
               msl: 8, mslCd: 0, mslRegen: 0 };
  const missiles = [];
  let score = 0, kills = 0, wave = 0, waveT = 2, over = false, finished = false, msg = '', msgT = 0;
  const foes = [], shots = [], eshots = [], drops = [];
  const KINDS = {
    drone: { geo: 'drone', hp: 2, sp: 11, sc: 1.6, pts: 40, col: '#ff2d9a', fire: 0, r: 1.2 },
    walker: { geo: 'mech', hp: 6, sp: 5.5, sc: 2.6, pts: 90, col: '#ffd700', fire: 2.2, r: 1.6 },
    tank: { geo: 'tank', hp: 10, sp: 4, sc: 2.8, pts: 140, col: '#ff6600', fire: 3.2, r: 2.0 }
  };
  const city = makeCity({ seed: 6060, density: 0.32, cell: 64, clear: 40, hMin: 8, hMax: 34, radius: 520, towerColor: '#081220' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#00f5ff,#46c8ff)';
  // ✨ v59 · NO CLOCK. The user asked for infinite time: the battle runs until
  // the avatar falls, and the timer reads ∞ as the classic Arena's always has.
  // (A Network Arena score war still ends on its own match clock.) gTimer, so
  // the pause shim stops the count of the time survived.
  let survived = 0;
  { const tEl = document.getElementById('g-time'); if(tEl) tEl.textContent = '∞'; }
  gTimer = setInterval(() => { survived++; }, 1000);
  const say = (s, t) => { msg = s; msgT = t || 2; };

  function spawnWave(){
    wave++;
    const n = Math.min(26, 4 + wave * 3);
    for(let i = 0; i < n; i++){
      const a = Math.random() * TAU, d = rr(55, 85);
      const p = [me.p[0] + Math.cos(a) * d, 0, me.p[2] + Math.sin(a) * d];
      if(city.hit(p, 2)) continue;
      const roll = Math.random();
      const k = wave > 2 && roll < 0.18 ? 'tank' : wave > 1 && roll < 0.45 ? 'walker' : 'drone';
      const K = KINDS[k];
      foes.push({ k, K, p, hp: K.hp, fire: rr(1, K.fire || 1), face: 0, flash: 0, ph: Math.random() * 6 });
    }
    say('WAVE ' + wave + ' — ' + n + ' HOSTILES', 2.2);
    snd('wave');
  }
  function shoot(){
    if(me.cool > 0 || over) return;
    // 🔥 OVERCHARGE: the 2D arena's buff — faster guns and a spread.
    const oc = SP.active('overdrive');
    me.cool = (me.rapid > 0 || oc ? 0.07 : 0.13) * (oc ? 0.75 : 1);
    const a = Math.atan2(me.aim[2], me.aim[0]);
    const spread = me.spread > 0 || oc ? [-0.18, 0, 0.18] : [0];
    // ✨ v59 · out of the arm cannons, left and right in turn
    const mz = onModel(ARM[armK++ % 2], me.p, me.face, ME_S, ME_Y);
    for(const s of spread){
      const d = [Math.cos(a + s), 0, Math.sin(a + s)];
      shots.push({ p: V.copy(mz), v: V.mul(d, 90), life: 0.9 });
    }
    fx.flash(mz, '#ffd8a0', 0.3, 0.05);
    snd('shoot', { semi: 6 });
  }
  function shockwave(){
    if(me.shock <= 0){ snd('deny'); return; }
    me.shock--;
    snd('bigExplode'); w.kick(1.6);
    fx.explode([me.p[0], 1, me.p[2]], 3, { color: colour, debris: 0, smoke: 0, ringNormal: [0, 1, 0] });
    for(let i = foes.length - 1; i >= 0; i--){ if(V.d2(foes[i].p, me.p) < 26 * 26){ foes[i].hp -= 8; if(foes[i].hp <= 0) kill(i); } }
    eshots.length = 0;
  }
  // ✨ v59 · MISSILES, out of the shoulder pods: tube by tube through each 3×3
  // grid, pods alternating. Each homes on the hostile nearest the aim (within
  // ~70°), climbs out of the tube, then dives on it; no target, it flies on.
  function fireMissile(){
    if(over || me.mslCd > 0) return;
    if(me.msl <= 0){ snd('deny'); say('🚀 RACKS EMPTY — reloading', 1.2); return; }
    me.msl--; me.mslCd = 0.26;
    const side = podK % 2, tube = (podK >> 1) % 9; podK++;
    const q = POD[side];
    const p = onModel([q[0] + ((tube % 3) - 1) * 0.046, q[1] + (((tube / 3) | 0) - 1) * 0.04, q[2]], me.p, me.face, ME_S, ME_Y);
    const fwd = [-Math.sin(me.face), 0, -Math.cos(me.face)];
    let tgt = null, bd = 1e9;
    for(const f of foes){
      const d = V.sub(f.p, me.p), l = Math.hypot(d[0], d[2]) || 1;
      if(l > 95) continue;
      const dot = (d[0] * me.aim[0] + d[2] * me.aim[2]) / l;
      if(dot < 0.34) continue;
      const sc = l * (1.6 - dot);
      if(sc < bd){ bd = sc; tgt = f; }
    }
    missiles.push({ p, v: V.add(V.mul(fwd, 9), [0, 9, 0]), tgt, life: 3.6, smoke: 0 });
    fx.flash(p, '#ffd8a0', 0.45, 0.08);
    snd('missile');
  }
  function kill(i){
    const f = foes[i];
    foes.splice(i, 1);
    kills++;
    score += f.K.pts; setLive(score);
    fx.explode([f.p[0], 1.2, f.p[2]], f.K.sc * 0.7, { color: f.K.col, grav: 18, debrisGeo: 'slab', debrisColor: '#2a2e3a' });
    snd('explode');
    w.pop([f.p[0], 4, f.p[2]], '+' + f.K.pts, f.K.col, { size: 13 });
    if(Math.random() < 0.12) drops.push({ p: [f.p[0], 1, f.p[2]], k: ['hp', 'rapid', 'spread', 'shock', 'msl'][(Math.random() * 5) | 0], life: 14 });
  }
  function hurt(dmg, at){
    if(me.inv > 0 || over) return;
    if(SP.shielded()){ fx.sparks(at, 8, '#c084fc', 1, 12); return; }
    me.hp -= dmg;
    snd('hurt'); w.kick(0.8);
    fx.sparks(at, 8, '#ff6a8a', 1, 12);
    if(me.hp <= 0){
      if(survivedFatal()){ me.hp = 50; me.inv = 1.5; say('SHIELD ABSORBED', 1.6); }
      else{ over = true; snd('bigExplode'); fx.explode([me.p[0], 1, me.p[2]], 2.6, { color: colour }); gLater(() => finish('down'), 1200); }
    }
    bar.style.width = Math.max(0, me.hp) + '%';
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('arena', score, {
      '📡 Battle': why === 'clock' ? 'CLOCK EXPIRED — STILL STANDING' : 'AVATAR DOWN',
      '⏱ Survived': Math.floor(survived / 60) + ':' + String(survived % 60).padStart(2, '0'),
      '🌊 Waves': wave,
      '💥 Kills': kills,
      '🛡 Integrity': Math.max(0, Math.round(me.hp)) + '%',
      '🏆 Score': score + ' PTS'
    });
  }
  // ⚡ v60 · ABILITIES (the specials kit): the 2D Cyber Arena's five — Nova
  // Blast, Time Freeze, Repair Pulse, Overcharge and Aegis Shield — with
  // Smart Missiles and the new EMP Pulse. One every 250 points.
  const fy = f => f.k === 'drone' ? 2.2 : f.K.sc * 0.5;
  let spinT = 0;
  const SP = makeSpecials(G, {
    kinds: ['nova', 'freeze', 'repair', 'overdrive', 'shield', 'smart', 'emp'],
    every: 250, novaR: 30, novaDmg: 12, smartN: 4, smartDmg: 8, bubbleR: 3.4,
    player: () => [me.p[0], 1.6, me.p[2]],
    targets: () => foes.map(f => ({ p: [f.p[0], fy(f), f.p[2]], r: f.K.r, obj: f })),
    hit: (f, dmg) => { const j = foes.indexOf(f); if(j < 0) return; f.hp -= dmg; f.flash = 0.12; if(f.hp <= 0) kill(j); },
    clearFire: () => { eshots.length = 0; },
    heal: k => { me.hp = Math.min(100, me.hp + 100 * k); bar.style.width = me.hp + '%'; }
  });
  P.owDebug = { state: () => ({ score, wave, kills, hp: me.hp, foes: foes.length }), specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use() };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over) SP.tick(dt, I, score);
    // The rotors' clock: stopped by a Time Freeze, slowed by a Time Warp.
    if(dt > 0) spinT += dt * (SP.frozen() ? 0 : SP.warp());
    if(dt > 0 && !over){
      me.inv = Math.max(0, me.inv - dt);
      me.cool -= dt; me.rapid = Math.max(0, me.rapid - dt); me.spread = Math.max(0, me.spread - dt); me.dashCd = Math.max(0, me.dashCd - dt);
      let mx = I.lx, mz = I.ly;
      const ml = Math.hypot(mx, mz); if(ml > 1){ mx /= ml; mz /= ml; }
      if(I.boost && me.dashCd <= 0 && ml > 0.1){ me.dash = 0.2; me.dashCd = 1.4; me.inv = Math.max(me.inv, 0.25); snd('dash'); }
      me.dash = Math.max(0, me.dash - dt);
      const sp = me.dash > 0 ? 48 : 17;
      me.v = V.lerp(me.v, [mx * sp, 0, mz * sp], ease(dt, me.dash > 0 ? 0.02 : 0.07));
      const np = V.madd(me.p, me.v, dt);
      if(!city.hit(np, 1.2)) me.p = np; else me.v = [0, 0, 0];
      city.update(me.p);
      // Aim: mouse on the ground, or the right stick / touch aim stick.
      let firing = I.fire;
      if(I.device === 'mouse' && hud.cam){
        const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
        if(g){ const d = V.sub(g, me.p); const l = Math.hypot(d[0], d[2]); if(l > 0.5) me.aim = [d[0] / l, 0, d[2] / l]; }
      }else if(Math.abs(I.aimX) + Math.abs(I.aimY) > 0.2){
        const l = Math.hypot(I.aimX, I.aimY);
        me.aim = [I.aimX / l, 0, I.aimY / l];
        firing = true;
      }else if(ml > 0.2 && !I.fire){ me.aim = [mx / Math.max(ml, 1e-3), 0, mz / Math.max(ml, 1e-3)]; }
      if(firing) shoot();
      if(I.altHit) shockwave();
      // ✨ v59 · missiles: E or C, pad Y, the touch MSL button; racks reload one every 4 s
      me.mslCd = Math.max(0, me.mslCd - dt);
      if(me.msl < 8){ me.mslRegen += dt; if(me.mslRegen >= 4){ me.mslRegen = 0; me.msl++; } } else me.mslRegen = 0;
      if(I.jumpHit || (I.pressed && I.pressed.KeyE)) fireMissile();
      me.face = Math.atan2(-me.aim[0], -me.aim[2]);
      waveT -= dt;
      if(foes.length === 0 && waveT > 2.5) waveT = 2.5;
      if(waveT <= 0){ spawnWave(); waveT = Math.max(10, 22 - wave); }
    }
    // Player shots.
    for(let i = shots.length - 1; i >= 0; i--){
      const s = shots[i];
      s.p = V.madd(s.p, s.v, dt); s.life -= dt;
      let hit = s.life <= 0 || !!city.hit(s.p, 0.2);
      if(!hit){
        for(let j = foes.length - 1; j >= 0; j--){
          const f = foes[j];
          if((f.p[0] - s.p[0]) ** 2 + (f.p[2] - s.p[2]) ** 2 < (f.K.r + 0.4) ** 2){
            hit = true; f.hp--; f.flash = 0.1;
            fx.sparks(s.p, 4, '#bff6ff', 0.8, 10);
            if(f.hp <= 0) kill(j); else snd('hit', { semi: 5 });
            break;
          }
        }
      }else if(s.life > 0) fx.sparks(s.p, 3, '#bff6ff', 0.7, 8);
      if(hit) shots.splice(i, 1);
    }
    // ✨ v59 · Missiles: climb out of the tube, turn onto the target, blast with splash.
    for(let i = missiles.length - 1; i >= 0; i--){
      const m = missiles[i];
      if(dt <= 0) break;
      m.life -= dt;
      if(m.tgt && !foes.includes(m.tgt)) m.tgt = null;
      const tp = m.tgt ? [m.tgt.p[0], m.tgt.k === 'drone' ? 2.2 : m.tgt.K.sc * 0.5, m.tgt.p[2]] : null;
      const sp = V.len(m.v) || 1;
      const cur = V.mul(m.v, 1 / sp);
      const want = tp ? V.norm(V.sub(tp, m.p)) : V.norm([cur[0], Math.min(cur[1], 0) - 0.12, cur[2]]);
      const nd = V.norm(V.lerp(cur, want, clamp((m.life > 3.1 ? 1.5 : 5) * dt, 0, 1)));
      m.v = V.mul(nd, Math.min(64, sp + 70 * dt));
      m.p = V.madd(m.p, m.v, dt);
      m.smoke -= dt;
      if(m.smoke <= 0){ m.smoke = 0.03; fx.puff(m.p, '#a8aeb8', 0.42, 1.0, V.mul(m.v, -0.02)); }
      let boom = m.life <= 0 || m.p[1] <= 0.25 || !!city.hit(m.p, 0.3);
      if(!boom){
        for(const f of foes){
          const fy = f.k === 'drone' ? 2.2 : f.K.sc * 0.5;
          if((f.p[0] - m.p[0]) ** 2 + (f.p[2] - m.p[2]) ** 2 < (f.K.r + 0.6) ** 2 && Math.abs(m.p[1] - fy) < f.K.sc + 1){ boom = true; break; }
        }
      }
      if(boom){
        fx.explode([m.p[0], Math.max(0.6, m.p[1]), m.p[2]], 1.6, { color: '#ffb36a', debris: 3 });
        snd('explode');
        for(let j = foes.length - 1; j >= 0; j--){
          const f = foes[j], d2 = (f.p[0] - m.p[0]) ** 2 + (f.p[2] - m.p[2]) ** 2;
          if(d2 < 5.5 * 5.5){ f.hp -= d2 < 4 ? 5 : 3; f.flash = 0.12; if(f.hp <= 0) kill(j); }
        }
        missiles.splice(i, 1);
      }
    }
    // Foes: close in; walkers and tanks stop at range and shoot.
    for(let i = foes.length - 1; i >= 0; i--){
      const f = foes[i];
      if(dt <= 0) break;
      f.flash = Math.max(0, f.flash - dt);
      // ❄️ TIME FREEZE: every hostile on the field stands still.
      if(SP.frozen()) continue;
      const d = V.sub(me.p, f.p), l = Math.hypot(d[0], d[2]) || 1;
      const want = f.K.fire ? (l > 22 ? 1 : l < 14 ? -0.5 : 0) : 1;
      // Steer round towers: probe ahead, sidestep if blocked.
      let dir = [d[0] / l, 0, d[2] / l];
      if(city.hit(V.madd(f.p, dir, 3), 1.5)) dir = [-dir[2] * (f.ph > 3 ? 1 : -1), 0, dir[0] * (f.ph > 3 ? 1 : -1)];
      if(f.k === 'drone') dir = V.norm(V.add(dir, [Math.cos(w.t * 2 + f.ph) * 0.5, 0, Math.sin(w.t * 2 + f.ph) * 0.5]));
      const np = V.madd(f.p, dir, f.K.sp * want * dt * Math.min(1.3, diff));
      if(!city.hit(np, f.K.r)) f.p = np;
      f.face = Math.atan2(-d[0], -d[2]);
      if(f.K.fire && !SP.jammed()){
        f.fire -= dt;
        if(f.fire <= 0 && l < 40){
          f.fire = f.K.fire * rr(0.8, 1.2) / diff;
          const lead = V.madd(me.p, me.v, l / 34);
          const ad = V.norm([lead[0] - f.p[0], 0, lead[2] - f.p[2]]);
          // ✨ v59 · out of the gun: a walker's arm cannons in turn, a tank's barrel
          const gq = f.k === 'tank' ? GUN : ARM[(f.gk = (f.gk || 0) + 1) % 2];
          const mz = onModel(gq, f.p, f.face, f.K.sc, f.K.sc * 0.5);
          eshots.push({ p: mz, v: V.mul(ad, f.k === 'tank' ? 26 : 34), life: 2.4, dmg: f.k === 'tank' ? 16 : 9, c: f.K.col, big: f.k === 'tank' });
          fx.flash(mz, '#ffd8a0', f.k === 'tank' ? 0.7 : 0.35, 0.06);
          snd('enemyShot', { semi: -3 });
        }
      }
      if(l < f.K.r + 1.2){ hurt(f.k === 'drone' ? 8 : 14, f.p); if(f.k === 'drone'){ kill(i); continue; } }
      if(l > 200) foes.splice(i, 1);
    }
    for(let i = eshots.length - 1; i >= 0; i--){
      const s = eshots[i];
      s.p = V.madd(s.p, s.v, dt); s.life -= dt;
      if(s.life <= 0 || city.hit(s.p, 0.3)){ eshots.splice(i, 1); continue; }
      if((s.p[0] - me.p[0]) ** 2 + (s.p[2] - me.p[2]) ** 2 < 1.4 * 1.4){ eshots.splice(i, 1); hurt(s.dmg, s.p); }
    }
    for(let i = drops.length - 1; i >= 0; i--){
      const d = drops[i];
      d.life -= dt;
      if(d.life <= 0){ drops.splice(i, 1); continue; }
      if((d.p[0] - me.p[0]) ** 2 + (d.p[2] - me.p[2]) ** 2 < 2.4 * 2.4){
        drops.splice(i, 1); snd('powerup');
        if(d.k === 'hp'){ me.hp = Math.min(100, me.hp + 30); bar.style.width = me.hp + '%'; say('🛠 +30 INTEGRITY'); }
        else if(d.k === 'rapid'){ me.rapid = 10; say('⚡ RAPID FIRE'); }
        else if(d.k === 'spread'){ me.spread = 10; say('✳ SPREAD SHOT'); }
        else if(d.k === 'msl'){ me.msl = Math.min(12, me.msl + 4); say('🚀 +4 MISSILES'); }
        else { me.shock++; say('💥 +1 SHOCKWAVE'); }
      }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    followCam(w, me.p, { height: 36, back: 24, look: 2, fov: 52, half: 0.1 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 150, color: '#0f3a5a', glow: 0.9, major: 5, floor: '#030812', rough: 0.45 });   // ✨ v59 no mirrored light blob
    city.draw(w);
    const eye = w.cam.eye;
    for(const f of foes){
      if(V.d2(f.p, eye) > 170 * 170) continue;
      const bob = f.k === 'drone' ? 2.2 + Math.sin(w.t * 4 + f.ph) * 0.4 : 0;
      // ✨ v60 · PAINTED, NOT LIT (see ENEMY_PAINT): magenta drones, yellow
      // walkers, orange tanks — a glossy livery the sun reads, frost-blue while
      // a Time Freeze holds them, and no glow, halo or lamp on any of them.
      const fp = [f.p[0], bob + (f.k === 'drone' ? 0 : f.K.sc * 0.5), f.p[2]];
      const look = P.kit.foeLook(SP.frozen() ? '#9fe6ff' : f.K.col, f.flash > 0);
      r.draw(f.K.geo, { pos: fp, rot: [0, f.face, 0], scale: f.K.sc, ...look });
      if(f.k === 'drone'){
        P.kit.foeShadow(r, f.p[0], f.p[2], f.K.sc * 0.9);
        P.kit.drawRotors(r, fp, [0, f.face, 0], f.K.sc, spinT + f.ph, look);
      }
    }
    for(const s of shots) r.streak(V.madd(s.p, s.v, -0.03), s.p, 0.28, colour, 3.2, 0.9);
    SP.draw();
    for(const m of missiles){
      const dir = V.norm(m.v);
      r.draw('missile', { pos: m.p, m3: basisLook(dir, [0, 1, 0]).m3, scale: 1.15, color: '#d9dde4', metallic: 0.3, roughness: 0.4, emissive: '#ff8a3a', emissiveStrength: 0.5, accent: 2 });
      plume(w, V.madd(m.p, dir, -0.6), V.mul(dir, -1), { len: 2.6, width: 0.42, color: '#ffb06a', gain: 1.1 });
    }
    for(const s of eshots){ r.glow(s.p, s.big ? 1.4 : 0.9, s.c, 1.8); r.streak(V.madd(s.p, s.v, -0.06), s.p, s.big ? 0.6 : 0.36, s.c, 1.6, 1); }
    for(const d of drops){
      const c = d.k === 'hp' ? '#39ff88' : d.k === 'rapid' ? '#ffd700' : d.k === 'spread' ? '#00f5ff' : d.k === 'msl' ? '#ff8a3a' : '#ff2d9a';
      r.draw('cube', { pos: [d.p[0], 1 + Math.sin(w.t * 3) * 0.3, d.p[2]], rot: [w.t, w.t * 1.4, 0.5], scale: 1.1, color: c, emissive: c, emissiveStrength: 1.5, detail: 0 });
      r.glow([d.p[0], 1.2, d.p[2]], 2.2, c, 0.7);
    }
    if(!over && !(me.inv > 0.3 && Math.sin(w.t * 30) > 0)){
      r.draw('mech', { pos: [me.p[0], 1.35, me.p[2]], rot: [0, me.face, 0], scale: 2.7, color: '#c9d1dd', metallic: 0.65, roughness: 0.3, rim: 0.8, emissive: colour, emissiveStrength: 0.004, accent: 0 });
      r.glow([me.p[0], 0.2, me.p[2]], 3.2, colour, 0.4);
      // Aim line.
      r.streak([me.p[0] + me.aim[0] * 2, 1.5, me.p[2] + me.aim[2] * 2], [me.p[0] + me.aim[0] * 9, 1.5, me.p[2] + me.aim[2] * 9], 0.08, colour, 0.8, 0);
    }
    r.light({ pos: [me.p[0], 7, me.p[2] + 3], color: '#cfe8ff', intensity: 150, range: 28 });
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    SP.hud();
    hud.radar(70, Ht - 74, 54, me.p, [0, 0, -1], 100, foes.map(f => ({ p: f.p, c: f.K.col, s: f.k === 'drone' ? 2 : 3 })));
    for(const f of foes){ const q = hud.proj(f.p); if(!q.on && V.d2(f.p, me.p) < 70 * 70) hud.edgeArrow(f.p, f.K.col, null); }
    hud.text(Wd - 16, Ht - 40, 'WAVE ' + wave, { size: 13, align: 'right', color: '#9fe6ff' });
    hud.text(Wd - 16, Ht - 20, '💥 ×' + me.shock, { size: 13, align: 'right', color: '#ff8ac8' });
    hud.text(Wd - 16, Ht - 60, '🚀 ×' + me.msl, { size: 13, align: 'right', color: '#ffb36a' });
    if(I.device === 'mouse' && I.mouseOn) hud.crosshair((I.mx + 1) / 2 * Wd, (I.my + 1) / 2 * Ht, colour, 7);
    if(msgT > 0) hud.text(Wd / 2, 26, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();
// ══════════════════════════════════════════════
//  🌐 OPEN WORLD · THE FLIGHT KIT
// ══════════════════════════════════════════════
// Five worlds fly rather than drive: Click Frenzy's sky-dock, Math Blitz's
// answer gates, Reaction's beacons, Flappy Drone's pylon field and Defrag's
// data volume. They share one craft — the Nebula's interceptor and its
// handling (stick deflection is a turn RATE, not a pointer the nose snaps
// to) — one chase camera, a tower test that knows about height, and the ring
// gates three of them fly through.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const KIT = P.owKit;
const { V, TAU, ease, basisLook, plume, attFrom, attTurn, attLevelRoll, attElevate, attFace, basisQ, yawOf, elevOf } = KIT;
const { clamp } = P.kit;

// `q` is the craft's attitude (see ✈️ ATTITUDE in the kit). `yaw` and `pitch`
// are READ-ONLY copies taken off it every step, for anything that wants a
// heading; writing them steers nothing.
function makeFlyer(o){
  o = o || {};
  const yaw = o.yaw || 0, q = attFrom(yaw, 0);
  return { p: o.p ? V.copy(o.p) : [0, 0, 0], q, yaw, pitch: 0, bank: 0, roll: 0,
           cruise: o.speed || 40, speed: o.speed || 40, energy: 100, boostK: 0,
           inv: 0, hit: 0, B: basisQ(q, 0), cam: null, scale: o.scale || 1.5 };
}
// Sets the nose's elevation outright (a bounce, a deck), keeping its heading.
function setPitch(f, el){
  f.q = attElevate(f.q, el, 1);
  f.B = basisQ(f.q, f.bank + f.roll);
  f.pitch = elevOf(f.B.f);
}

// One frame of flight. `level` (a half-life) eases the nose back to the
// horizon when the stick is let go: these worlds are about getting somewhere,
// and a craft that holds a dive for ever flies into the floor. `floor` and
// `ceiling` are soft — the nose is flattened, nothing is hurt.
//
// ✨ v57 · There is no pitch limit any more: the stick turns the attitude about
// the craft's own axes, so holding it flies a full loop. The wings settle back
// level once the pitch stick is let go, and `level` brings the nose round to
// the horizon on top of that — neither ever acts while the stick is held.
function flyStep(f, I, dt, o){
  o = o || {};
  P.owFly.craft = f;                                 // console / harness: the craft in the air
  const soft = v => Math.sign(v) * Math.pow(Math.max(0, Math.abs(v) - 0.06) / 0.94, 1.35);
  const sy = o.noPitch ? 0 : soft(I.ay);
  const yawRate = -soft(I.ax) * (o.yawRate || 1.6);
  const pitchRate = -sy * (o.pitchRate || 1.25);
  f.q = attTurn(f.q, yawRate, pitchRate, dt);
  f.q = attLevelRoll(f.q, ease(dt, 0.3) * clamp(1 - Math.abs(sy) * 3, 0, 1));
  if(o.level && Math.abs(I.ay) < 0.1) f.q = attElevate(f.q, 0, ease(dt, o.level));
  f.bank += (clamp(-yawRate * 0.5, -0.9, 0.9) - f.bank) * ease(dt, 0.12);
  if(I.roll && !o.noRoll) f.roll += I.roll * 6.2 * dt;
  else f.roll += (Math.round(f.roll / TAU) * TAU - f.roll) * ease(dt, 0.18);
  const boosting = !o.noBoost && I.boost && f.energy > 2;
  f.energy = clamp(f.energy + (boosting ? -(o.drain || 28) : (o.regen || 13)) * dt, 0, 100);
  const want = boosting ? f.cruise * (o.boostMul || 2.2) : (I.brake ? f.cruise * 0.35 : f.cruise);
  f.speed += (want - f.speed) * ease(dt, boosting ? 0.25 : 0.4);
  f.boostK = clamp((f.speed - f.cruise) / (f.cruise * 1.2), 0, 1);
  f.B = basisQ(f.q, f.bank + f.roll);
  f.yaw = yawOf(f.B.f); f.pitch = elevOf(f.B.f);
  f.p = V.madd(f.p, f.B.f, f.speed * dt);
  f.inv = Math.max(0, f.inv - dt);
  f.hit = Math.max(0, f.hit - dt);
  if(o.floor != null && f.p[1] < o.floor){ f.p[1] = o.floor; if(f.pitch < 0) setPitch(f, f.pitch * 0.4); }
  if(o.ceiling != null && f.p[1] > o.ceiling){ f.p[1] = o.ceiling; if(f.pitch > 0) setPitch(f, f.pitch * 0.4); }
  return boosting;
}

// The Nebula's chase rig: behind and above, eased in the craft's own frame so
// it holds still on screen while a turn swings the world round it. It looks a
// little higher than the Nebula's (`lift`), so the craft sits low in the frame
// and a target level with it far ahead shows above it rather than behind it.
// Its up is the craft's, eased, which is what carries the view through a loop.
function flyCam(w, f, dt, o){
  o = o || {};
  const Bc = basisQ(f.q, f.bank * 0.35);
  const goalOff = V.add(V.mul(Bc.f, -((o.back || 7.2) + f.boostK * 2.6)), V.mul(Bc.u, o.up || 2.15));
  const goalTgt = V.add(V.mul(f.B.f, 30), V.mul(Bc.u, o.lift != null ? o.lift : 3.2));
  if(!f.cam) f.cam = { off: goalOff, tgt: goalTgt, up: Bc.u };
  else if(dt > 0){
    f.cam.off = V.lerp(f.cam.off, goalOff, ease(dt, o.half || 0.075));
    f.cam.tgt = V.lerp(f.cam.tgt, goalTgt, ease(dt, 0.06));
    f.cam.up = V.norm(V.lerp(f.cam.up, Bc.u, ease(dt, 0.1)));
  }
  w.cam.eye = V.add(f.p, f.cam.off);
  w.cam.target = V.add(f.p, f.cam.tgt);
  w.goal.eye = w.cam.eye; w.goal.target = w.cam.target;
  w.goal.fov = (o.fov || 62) + f.boostK * 12;
  w.up = f.cam.up;
}

function drawFlyer(w, f, col, o){
  o = o || {};
  const r = w.r, B = f.B, SC = f.scale;
  if(!(f.inv > 0 && Math.sin(w.t * 40) > 0)){
    r.draw(o.geo || 'ship', { pos: f.p, m3: B.m3, scale: SC, color: f.hit > 0 ? '#ff8a8a' : (o.color || '#a9b1bf'),
                              metallic: 0.62, roughness: 0.3, rim: 0.7, emissive: col, emissiveStrength: 0.004, accent: 0 });
  }
  for(const s of [-1, 1]){
    const ep = V.add(f.p, V.add(V.add(V.mul(B.r, s * 0.36 * SC), V.mul(B.u, -0.02 * SC)), V.mul(B.f, -0.86 * SC)));
    plume(w, ep, V.mul(B.f, -1), { len: 1.0 + f.boostK * 1.8, width: 0.3 + f.boostK * 0.08, color: f.boostK > 0.3 ? '#8fe6ff' : '#5ec8ff',
                                   gain: 0.7 + f.boostK * 0.35, glow: 0.8, ph: s * 5 });
  }
  // ✨ v57 · A soft fill from over the chase camera (see the Nebula's craft for
  // why it is no longer a floodlight on the canopy).
  r.light({ pos: V.add(f.p, V.add(V.mul(B.u, 5), V.mul(B.f, -7))), color: '#cfe0ff', intensity: 26, range: 30 });
}

// A city tower in the way of something in the AIR: the ground kit's footprint
// test, plus the tower's height.
function towerAt(city, p, rad){
  let hit = null;
  city.near(p, b => {
    if(hit || p[1] - rad > b.h) return;
    if(Math.abs(p[0] - b.p[0]) < b.w * 0.5 + rad && Math.abs(p[2] - b.p[2]) < b.d * 0.5 + rad) hit = b;
  });
  return hit;
}
// Out of a tower along the shallower face, the heading turned off the wall.
function bounceOff(f, b, rad){
  const dx = f.p[0] - b.p[0], dz = f.p[2] - b.p[2];
  const px = b.w * 0.5 + rad - Math.abs(dx), pz = b.d * 0.5 + rad - Math.abs(dz), py = b.h + rad - f.p[1];
  if(py < px && py < pz){ f.p[1] = b.h + rad + 0.1; if(f.pitch < 0.25) setPitch(f, 0.25); return; }
  // The nose mirrored in the wall it hit: only the component into the wall
  // turns round, so a glancing blow stays a glance, and a craft climbing or
  // diving into the face keeps its climb or dive.
  const fw = V.copy(f.B.f);
  if(px < pz){ f.p[0] = b.p[0] + Math.sign(dx || 1) * (b.w * 0.5 + rad + 0.1); fw[0] = -fw[0]; }
  else{ f.p[2] = b.p[2] + Math.sign(dz || 1) * (b.d * 0.5 + rad + 0.1); fw[2] = -fw[2]; }
  f.q = attFace(f.q, fw);
  f.B = basisQ(f.q, f.bank + f.roll);
  f.yaw = yawOf(f.B.f); f.pitch = elevOf(f.B.f);
  f.speed = Math.min(f.speed, f.cruise * 0.6);
}

// A standing ring, its opening facing along n. 'torus' lies in XZ with its
// axis on local Y, so the basis puts Y along n.
function ringM3(n){
  const b = basisLook(n, Math.abs(n[1]) > 0.9 ? [1, 0, 0] : [0, 1, 0]);
  return [b.r[0], b.r[1], b.r[2], n[0], n[1], n[2], b.u[0], b.u[1], b.u[2]];
}
function drawRing(w, p, n, rad, col, k, o){
  o = o || {};
  const m3 = ringM3(n);
  const s = rad / 0.4;
  w.r.draw(o.thin ? 'thintorus' : 'torus', { pos: p, m3, scale: o.thin ? [rad / 0.45, s * 0.6, rad / 0.45] : s,
                                             color: o.color || '#d8e4f0', metallic: 0.7, roughness: 0.3, rim: 0.8,
                                             emissive: col, emissiveStrength: (k == null ? 1 : k) * (o.thin ? 2.4 : 1.2) });
  if(o.glow !== false) w.r.glow(p, rad * 1.1, col, 0.18 * (k == null ? 1 : k));
}
// Did a craft moving a → b pass through the disc of a ring (centre c, normal
// n, radius rad)? Returns +1 / −1 for the side it came from, 0 for a miss.
function throughRing(a, b, c, n, rad){
  const da = V.dot(V.sub(a, c), n), db = V.dot(V.sub(b, c), n);
  if(da === db || (da > 0) === (db > 0)) return 0;
  const t = da / (da - db);
  const q = V.lerp(a, b, t);
  return V.d2(q, c) < rad * rad ? (da > 0 ? 1 : -1) : 0;
}

P.owFly = { makeFlyer, flyStep, setPitch, flyCam, drawFlyer, towerAt, bounceOff, ringM3, drawRing, throughRing };

})();


// ══════════════════════════════════════════════
//  🌐 OPEN WORLD · THE DRIVING KIT
// ══════════════════════════════════════════════
// The worlds where you go somewhere and DO something there — flip a
// monolith, tune a tower, vent a reactor, haul a packet — need a rover that
// can stop, not the runner's that never does. W/S (the stick's up/down) is
// the throttle, A/D steers, SHIFT boosts; a mouse held on the ground drives
// at the cursor, the way Dodge Cores runs at it. Turning is tied to speed,
// so nothing spins on the spot.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, ease, wrapAng } = P.owKit;
const { screenToGround, drawRover, chaseCam } = P.owGround;
const { clamp } = P.kit;

function makeRover(o){
  o = o || {};
  return { p: o.p ? V.copy(o.p) : [0, 0, 0], yaw: o.yaw || 0, speed: 0, max: o.max || 26, bank: 0,
           boostE: 100, boosting: false, inv: 0, hit: 0, odo: 0 };
}
function driveStep(me, I, dt, hud, o){
  o = o || {};
  let steer = I.ax, thr = -I.ly;
  if(o.mouseDrive !== false && I.device === 'mouse' && I.mDown && hud && hud.cam){
    const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
    if(g){
      const d = V.sub(g, me.p), l = Math.hypot(d[0], d[2]);
      if(l > 2.5){
        const want = Math.atan2(-d[0], -d[2]);
        steer = clamp(-wrapAng(want - me.yaw) * 2.2, -1, 1);
        thr = clamp(l / 14, 0.3, 1);
      }else thr = 0;
    }
  }
  const boosting = !o.noBoost && I.boost && me.boostE > 2 && thr > 0.1;
  me.boostE = clamp(me.boostE + (boosting ? -(o.drain || 30) : (o.regen || 11)) * dt, 0, 100);
  me.boosting = boosting;
  const max = me.max * (boosting ? (o.boostMul || 1.6) : 1);
  const want = thr >= 0 ? thr * max : thr * me.max * 0.45;
  me.speed += (want - me.speed) * ease(dt, Math.abs(want) < Math.abs(me.speed) ? (o.brake || 0.22) : (o.accel || 0.35));
  const turnK = clamp(Math.abs(me.speed) / 8, 0.35, 1);
  me.yaw = wrapAng(me.yaw - steer * (o.turn || 2.3) * turnK * (me.speed < -0.5 ? -1 : 1) * dt);
  me.bank += (clamp(steer * 0.45 * turnK, -0.5, 0.5) - me.bank) * ease(dt, 0.1);
  me.p = V.madd(me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], me.speed * dt);
  me.odo += Math.abs(me.speed) * dt;
  me.inv = Math.max(0, me.inv - dt);
  me.hit = Math.max(0, me.hit - dt);
  return thr;
}
// Off a city tower along its shallower face, the speed scrubbed.
function slideOut(me, city, rad){
  const b = city.hit(me.p, rad);
  if(!b) return null;
  const dx = me.p[0] - b.p[0], dz = me.p[2] - b.p[2];
  if(Math.abs(dx) / (b.w / 2) > Math.abs(dz) / (b.d / 2)) me.p[0] = b.p[0] + Math.sign(dx || 1) * (b.w / 2 + rad + 0.05);
  else me.p[2] = b.p[2] + Math.sign(dz || 1) * (b.d / 2 + rad + 0.05);
  me.speed *= 0.5;
  return b;
}
// Out of a round post (a monolith, a tower base): radius `rad` + the rover's.
function pushOutCircle(me, c, rad){
  const dx = me.p[0] - c[0], dz = me.p[2] - c[2], l = Math.hypot(dx, dz);
  if(l >= rad || l < 1e-4) return false;
  me.p[0] = c[0] + dx / l * rad; me.p[2] = c[2] + dz / l * rad;
  me.speed *= 0.6;
  return true;
}
function roverCam(w, me, dt, o){
  chaseCam(w, me.p, me.yaw, Object.assign({ back: 11, up: 5.4, ahead: 14, fov: 62, half: 0.1, tgtUp: 0.5 }, o), dt);
}
function roverDraw(w, me, col, o){
  if(me.inv > 0 && Math.sin(w.t * 30) > 0) return;
  drawRover(w, me.p, me.yaw, col, Object.assign({ bank: me.bank, boost: me.boosting ? 1 : 0, hit: me.hit > 0 }, o));
}

// A wide ring on the ground as a circle of soft dots: a torus scaled to a
// big radius grows a tube as thick as a kerb.
function dotRing(w, p, rad, col, k){
  const n = Math.max(16, Math.min(56, Math.round(rad * 2.4)));
  for(let i = 0; i < n; i++){
    const a = i / n * Math.PI * 2;
    w.r.glowFx([p[0] + Math.cos(a) * rad, 0.25, p[2] + Math.sin(a) * rad], 0.55, col, 0.9 * (k == null ? 1 : k));
  }
}

// Every touch that lands on the board, counted as it happens. The shared input
// only sees a finger that is still down when the frame polls, and a quick tap
// on a slow phone can start and end between two frames. Touches on the
// world's own touch buttons are left to them.
function tapCounter(cfg){
  const cv = aCanvas;
  const buttons = P.owKit.touchButtons(cfg || 'fly');
  let n = 0;
  const on = e => {
    if(!e.isTrusted) return;
    const rc = cv.getBoundingClientRect();
    for(const t of e.changedTouches){
      const u = (t.clientX - rc.left) / Math.max(1, rc.width), v = (t.clientY - rc.top) / Math.max(1, rc.height);
      if(!buttons.some(b => Math.hypot(u - b.u, (v - b.v) * (rc.height / Math.max(1, rc.width))) < b.r)) n++;
    }
  };
  if(cv) cv.addEventListener('touchstart', on, { passive: true });
  const prev = onStopGame;
  onStopGame = () => { try{ if(cv) cv.removeEventListener('touchstart', on); }catch(e){} if(prev) prev(); };
  return { take(){ const k = n; n = 0; return k; } };
}

P.owDrive = { makeRover, driveStep, slideOut, pushOutCircle, roverCam, roverDraw, dotRing, tapCounter };

})();


// ══════════════════════════════════════════════
//  🖱️ CLICK FRENZY · OPEN WORLD — SKY-DOCK OVERLOAD
// ══════════════════════════════════════════════
// The classic is ten seconds of hammering one button. Here the button is a
// reactor core adrift over a dusk city, and there are always more of them:
// fly at one, hold it in the reticle, and hammer — every click pumps charge
// into it (eight points a click, as ever) until it overloads. Each core vents
// on its own clock, so the frenzy is choosing the next one while you click.
// Nothing shoots back; the towers and the docks only get in the way.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owFly) return;
const { V, TAU, ease, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, makeCity } = P.owGround;
const { makeFlyer, flyStep, setPitch, flyCam, drawFlyer, towerAt, bounceOff } = P.owFly;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const LOCK_R = 36;

P.ow.click = function(){
  const G = groundBegin({ sky: 'dusk', input: { mouseSteer: true, mouseGain: 1.15 }, far: 1700 });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: FLY · TAP FIRE FAST ON A LOCKED CORE · BOOST',
                 'MOUSE / WASD: FLY · CLICK / SPACE FAST: OVERLOAD THE LOCKED CORE · SHIFT: BOOST');

  const me = makeFlyer({ p: [0, 46, 0], speed: 36 });
  let score = 0, clicks = 0, overloads = 0, vented = 0, chain = 0, bestChain = 0, over = false, finished = false;
  let msg = '', msgT = 0, wasFire = false, holdT = 0, zap = 0, lock = null, spawnT = 0, elapsed = 0;
  const cores = [];
  const taps = P.owDrive ? P.owDrive.tapCounter('fly') : { take: () => 0 };
  const city = makeCity({ seed: 1717, density: 0.34, cell: 84, clear: 70, hMin: 18, hMax: 115, radius: 900, towerColor: '#100818' });
  // Floating docks: slabs hung over the city, rings of light at their berths.
  const docks = makeField({
    cell: 190, dims: 2, seed: 6161, radius: 760,
    gen(cx, cy, cz, g){
      if(g() < 0.45) return [];
      const p = [(cx + 0.25 + g() * 0.5) * 190, 40 + g() * 70, (cz + 0.25 + g() * 0.5) * 190];
      if(Math.hypot(p[0], p[2]) < 80) return [];
      return [{ p, w: 26 + g() * 18, d: 14 + g() * 10, yaw: g() * Math.PI, ph: g() * 6, col: P.owGround.NEONS[(g() * 6) | 0] }];
    }
  });
  const total = Math.round(100 * (typeof getTimeModifier === 'function' ? getTimeModifier() : 1));
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ffb35c,#ff5ab4)';
  const clock = owClock(100, () => end('clock'), left => { bar.style.width = Math.max(0, left / Math.max(1, total) * 100) + '%'; });
  const say = (s, t) => { msg = s; msgT = t || 2; };

  function spawnCore(ahead){
    const fwd = [me.B.f[0], 0, me.B.f[2]];
    const a = Math.random() * TAU;
    let dir = V.norm(V.add(V.mul(V.norm(fwd), ahead ? 1.4 : 0.5), [Math.cos(a), 0, Math.sin(a)]));
    const d = ahead ? rr(110, 190) : rr(140, 300);
    const p = V.add(me.p, V.mul(dir, d));
    p[1] = clamp(me.p[1] + rr(-30, 40), 22, 130);
    const big = Math.random() < 0.18;
    const life = (big ? rr(22, 28) : rr(15, 21)) * clamp(1.1 - elapsed / 260, 0.7, 1.1) / Math.sqrt(diff);
    cores.push({ p, v: [rr(-4, 4), rr(-0.6, 0.6), rr(-4, 4)], big, need: Math.round((big ? 22 : 12) + elapsed / 14), charge: 0,
                 vent: life, life, flash: 0, ph: Math.random() * TAU });
  }
  for(let i = 0; i < 5; i++) spawnCore(i < 2);

  // One click's worth of charge into a core.
  function pump(c, held){
    c.charge++;
    clicks++;
    c.flash = 0.08;
    zap = 0.07;
    score += 8; setLive(score);
    snd(held ? 'tick' : 'click', { semi: Math.min(12, c.charge / c.need * 12) });
    fx.sparks(c.p, 4, '#ffe0a0', 0.9, 10);
    if(c.charge >= c.need) overload(c);
  }
  function overload(c){
    const i = cores.indexOf(c);
    if(i < 0) return;
    cores.splice(i, 1);
    overloads++;
    chain++; bestChain = Math.max(bestChain, chain);
    const bonus = (c.big ? 90 : 40) + Math.round(Math.max(0, c.vent) * 4) + Math.min(60, chain * 6);
    score += bonus; setLive(score);
    fx.explode(c.p, c.big ? 5 : 3.4, { color: '#ffb35c', ringColor: '#ff5ab4', debris: 6 });
    snd('bigExplode');
    w.kick(c.big ? 1.2 : 0.7);
    w.pop(V.add(c.p, [0, 5, 0]), '+' + bonus + (chain > 1 ? ' ×' + chain : ''), '#ffd27a', { size: 16 });
    if(lock === c) lock = null;
  }
  function vent(c){
    const i = cores.indexOf(c);
    if(i >= 0) cores.splice(i, 1);
    vented++;
    if(chain > 1) say('CORE VENTED — CHAIN BROKEN', 1.6);
    chain = 0;
    for(let k = 0; k < 6; k++) fx.puff(V.add(c.p, [rr(-2, 2), rr(0, 3), rr(-2, 2)]), '#b8c8d8', 2.2, 1.6, [rr(-2, 2), rr(3, 7), rr(-2, 2)]);
    snd('glitch');
    if(lock === c) lock = null;
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('click', score, {
      '📡 Shift': why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '🖱️ Clicks': clicks,
      '💥 Cores Overloaded': overloads,
      '💨 Cores Vented': vented,
      '⛓ Best Chain': bestChain + '×',
      '🏆 Score': score + ' PTS'
    });
  }
  // Test hooks (console / harness only).
  P.owDebug = {
    state: () => ({ score, clicks, overloads, vented, chain, cores: cores.length, lock: !!lock, p: me.p.map(Math.round) }),
    coreAhead(d){ spawnCore(true); const c = cores[cores.length - 1]; c.p = V.madd(me.p, me.B.f, d || 20); c.v = [0, 0, 0]; return c.need; },
    click(n){ for(let k = 0; k < (n || 1); k++){ if(lock) pump(lock, false); } }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      elapsed += dt;
      flyStep(me, I, dt, { level: 1.4, floor: 6, ceiling: 190 });
      city.update(me.p);
      docks.update(me.p);
      const tb = towerAt(city, me.p, 1.6);
      if(tb && me.inv <= 0){ bounceOff(me, tb, 1.6); me.hit = 0.3; me.inv = 0.5; snd('bounceWall'); w.kick(0.6); fx.sparks(me.p, 8, '#ffc08a', 1, 12); }
      docks.near(me.p, d => {
        const dx = me.p[0] - d.p[0], dy = me.p[1] - d.p[1], dz = me.p[2] - d.p[2];
        const c = Math.cos(d.yaw), s = Math.sin(d.yaw), lx = dx * c - dz * s, lz = dx * s + dz * c;
        if(Math.abs(lx) < d.w / 2 + 1.4 && Math.abs(lz) < d.d / 2 + 1.4 && Math.abs(dy) < 2.6){
          me.p[1] = d.p[1] + Math.sign(dy || 1) * 2.7;
          setPitch(me, Math.sign(dy || 1) * 0.2);
          if(me.inv <= 0){ me.hit = 0.25; me.inv = 0.4; snd('bounceWall'); }
        }
      });
      // The lock: the nearest core inside the cone ahead.
      lock = null;
      let best = 1e9;
      for(const c of cores){
        const d = V.sub(c.p, me.p), l = V.len(d);
        if(l > LOCK_R + (c.big ? 6 : 0)) continue;
        const dot = V.dot(d, me.B.f) / Math.max(l, 1e-3);
        if(dot < 0.5 && l > 9) continue;
        if(l < best){ best = l; lock = c; }
      }
      const tapped = taps.take();
      const clicks = I.device === 'touch' ? tapped : (I.fire && !wasFire ? 1 : 0);
      wasFire = I.fire;
      if(lock){
        if(clicks){ for(let k = 0; k < clicks && lock; k++) pump(lock, false); holdT = 0; }
        else if(I.fire){ holdT += dt; if(holdT > 0.34){ holdT = 0; pump(lock, true); } }
      }else if(clicks) snd('ui');
      // Cores: drift, bob, vent.
      for(let i = cores.length - 1; i >= 0; i--){
        const c = cores[i];
        c.p = V.madd(c.p, c.v, dt);
        c.flash = Math.max(0, c.flash - dt);
        c.vent -= dt;
        if(c.vent <= 0){ vent(c); continue; }
        if(V.d2(c.p, me.p) > 520 * 520){ cores.splice(i, 1); continue; }
      }
      spawnT -= dt;
      const want = Math.min(8, 5 + Math.floor(elapsed / 30));
      if(cores.length < want && spawnT <= 0){ spawnCore(Math.random() < 0.6); spawnT = 0.8; }
    }
    zap = Math.max(0, zap - dt);
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    flyCam(w, me, dt, { fov: 62 });
    w.step(dt);

    // ── DRAW ──
    w.begin();
    drawFloor(w, { step: 8, radius: 220, color: '#5a1a3a', glow: 0.9, major: 5, floor: '#0a0410', rough: 0.25 });
    city.draw(w);
    const eye = w.cam.eye;
    docks.each(d => {
      if(V.d2(d.p, eye) > 700 * 700 || !r.viewDepth(d.p, 1.3)) return;
      r.draw('slab', { pos: d.p, rot: [0, d.yaw, 0], scale: [d.w, 1.6, d.d], color: '#1a1424', metallic: 0.7, roughness: 0.35, rim: 0.6 });
      const c = Math.cos(d.yaw), s = Math.sin(d.yaw);
      for(const k of [-1, 1]){
        const a = [d.p[0] + c * k * d.w / 2 - s * d.d / 2, d.p[1] + 0.9, d.p[2] - s * k * d.w / 2 - c * d.d / 2];
        const b = [d.p[0] + c * k * d.w / 2 + s * d.d / 2, d.p[1] + 0.9, d.p[2] - s * k * d.w / 2 + c * d.d / 2];
        r.beam(a, b, 0.2, { color: d.col, emissive: d.col, emissiveStrength: 2.4 });
      }
      r.draw('thintorus', { pos: [d.p[0], d.p[1] + 1, d.p[2]], scale: [7, 1, 7], color: d.col, emissive: d.col, emissiveStrength: 1.6 + Math.sin(w.t * 2 + d.ph) * 0.6 });
    });
    let nl = 0;
    for(const c of cores){
      if(V.d2(c.p, eye) > 650 * 650) continue;
      const k = c.charge / c.need, urgent = c.vent / c.life;
      const s = (c.big ? 4.2 : 3) * (1 + 0.06 * Math.sin(w.t * (6 + k * 18) + c.ph)) * (1 + k * 0.25);
      const hot = k > 0.66 ? '#ffffff' : k > 0.33 ? '#ffd27a' : '#ff9a4a';
      const pos = [c.p[0], c.p[1] + Math.sin(w.t * 1.3 + c.ph) * 0.8, c.p[2]];
      if(r.viewDepth(pos, 1.3)){
        r.draw('core', { pos, rot: [w.t * 0.6 + c.ph, w.t * (0.8 + k * 3), 0], scale: s, color: c.flash > 0 ? '#ffffff' : '#c9b8a8', metallic: 0.5, roughness: 0.3, rim: 0.9,
                         emissive: hot, emissiveStrength: 0.8 + k * 2.4 });
        // The vent ring: it closes as the core's clock runs down.
        r.draw('thintorus', { pos, rot: [Math.PI / 2, w.t, 0], scale: [s * 2.6 * (0.45 + urgent * 0.55), 1, s * 2.6 * (0.45 + urgent * 0.55)],
                              color: urgent < 0.3 ? '#ff3a3a' : '#7ff7ff', emissive: urgent < 0.3 ? '#ff3a3a' : '#7ff7ff', emissiveStrength: 2.2 });
      }
      r.glow(pos, s * (1.4 + k), hot, 0.7 + k);
      if(nl++ < 3) r.light({ pos, color: '#ffb36a', intensity: 70 + k * 120, range: 18 });
    }
    if(lock && zap > 0){
      const nose = V.madd(me.p, me.B.f, 1.6 * me.scale);
      r.streak(nose, lock.p, 0.32, colour, 3.4, 0);
      r.glow(lock.p, 2.4, '#ffffff', 1.6);
    }
    if(!over || finished === false) drawFlyer(w, me, colour);
    fx.draw();
    w.end();

    // ── HUD ──
    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    hud.radar(70, Ht - 74, 54, me.p, me.B.f, 260, cores.map(c => ({ p: c.p, c: c.vent / c.life < 0.3 ? '#ff4a4a' : '#ffb35c', s: c.big ? 3.4 : 2.6, tick: true })));
    const near = cores.slice().sort((a, b) => V.d2(a.p, me.p) - V.d2(b.p, me.p));
    for(let i = 0; i < Math.min(4, near.length); i++){
      const c = near[i];
      if(c === lock) continue;
      const q = hud.proj(c.p);
      if(q.on) hud.bracket(c.p, c.big ? 5 : 3.6, c.vent / c.life < 0.3 ? '#ff6a6a' : '#ffd27a', Math.ceil(c.vent) + 's', { dist: Math.sqrt(V.d2(c.p, me.p)), alpha: 0.7 });
      else hud.edgeArrow(c.p, '#ffb35c', null);
    }
    if(lock){
      const q = hud.bracket(lock.p, lock.big ? 5 : 3.6, '#ffffff', 'OVERLOAD', { lock: true });
      if(q.on){
        hud.bar(q.x - 40, q.y + 34, 80, 7, lock.charge / lock.need, '#ffd27a');
        hud.text(q.x, q.y + 52, 'CLICK! ' + lock.charge + ' / ' + lock.need, { size: 11, color: '#ffe8b0' });
      }
    }else{
      const aimP = hud.proj(V.madd(me.p, me.B.f, 60));
      if(aimP.on) hud.crosshair(aimP.x, aimP.y, '#ffd8b0', 8);
    }
    hud.text(Wd - 16, Ht - 40, chain > 1 ? 'CHAIN ×' + chain : '', { size: 13, align: 'right', color: '#ffd27a' });
    hud.text(Wd - 16, Ht - 20, '💥 ' + overloads, { size: 13, align: 'right', color: '#ffb35c' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.energy / 100, '#ffb35c', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 26, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🔢 MATH BLITZ · OPEN WORLD — ANSWER GATES
// ══════════════════════════════════════════════
// The classic is a sum and a text box. Here the sum hangs at the top of the
// sky and its answers float ahead of you as gates: read it, pick the right
// number, fly through it. A wrong gate costs clock time, the way a wrong
// answer always did; a slow one lets the gates dissolve and the next sum
// arrives. The faster you answer, the more each one pays.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owFly) return;
const { V, TAU, drawFloor, owClock } = P.owKit;
const { groundBegin, makeCity } = P.owGround;
const { makeFlyer, flyStep, flyCam, drawFlyer, towerAt, bounceOff, drawRing, throughRing } = P.owFly;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const RAD = 6.5;                               // a gate's opening

P.ow.math = function(){
  const G = groundBegin({ sky: 'violet', input: { mouseSteer: true, mouseGain: 1.15 }, far: 1600 });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: FLY THROUGH THE RIGHT ANSWER · BOOST', 'MOUSE / WASD: FLY THROUGH THE GATE WITH THE RIGHT ANSWER · SHIFT: BOOST');

  const me = makeFlyer({ p: [0, 40, 0], speed: 34 });
  let score = 0, right = 0, wrong = 0, missed = 0, streak = 0, bestStreak = 0, over = false, finished = false;
  let msg = '', msgT = 0, q = null, gates = [], qT = 0, qLife = 12, solved = 0, flashT = 0, flashCol = '#39ff88';
  const city = makeCity({ seed: 2424, density: 0.14, cell: 120, clear: 90, hMin: 20, hMax: 80, radius: 900, towerColor: '#0c0818' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#a855f7,#5ee7ff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  // The classic's sums (two numbers from 2 to 13, + − ×), then two-step ones.
  function makeSum(){
    const R = (typeof dailyRand === 'function') ? dailyRand : Math.random;
    const n = () => Math.floor(R() * 12) + 2;
    const ops = ['+', '-', '×'];
    let a = n(), b = n(), op = ops[Math.floor(R() * 3)];
    let text = a + ' ' + op + ' ' + b, ans = op === '+' ? a + b : op === '-' ? a - b : a * b;
    if(solved >= 8 && R() < 0.4){
      const c = Math.floor(R() * 9) + 2, op2 = R() < 0.5 ? '+' : '-';
      text = '(' + text + ') ' + op2 + ' ' + c;
      ans = op2 === '+' ? ans + c : ans - c;
    }
    // Decoys near the answer — the believable mistakes.
    const opts = new Set([ans]);
    const near = [1, -1, 2, -2, 10, -10, 3, -3, 5, -5];
    const want = solved >= 12 ? 4 : 3;
    while(opts.size < want){
      const d = near[Math.floor(Math.random() * near.length)] * (Math.random() < 0.3 ? 2 : 1);
      opts.add(ans + d);
    }
    return { text, ans, opts: [...opts].sort(() => Math.random() - 0.5) };
  }
  function placeGates(){
    const fwd = V.norm([me.B.f[0], 0, me.B.f[2]]);
    const side = [-fwd[2], 0, fwd[0]];
    const c = V.add(V.madd(me.p, fwd, 140 + Math.min(60, me.speed)), [0, 0, 0]);
    c[1] = clamp(me.p[1] + rr(-10, 10), 18, 110);
    const n = q.opts.length;
    gates = q.opts.map((v, i) => {
      const lat = (i - (n - 1) / 2) * 17 + rr(-2, 2);
      const p = V.add(V.madd(c, side, lat), [0, rr(-6, 6) + (i % 2 ? 4 : -4), 0]);
      return { p, n: V.mul(fwd, -1), v, ok: v === q.ans, hit: 0 };
    });
  }
  function nextSum(){
    q = makeSum();
    qLife = Math.max(6, 12 - solved * 0.2) / Math.sqrt(diff);
    qT = qLife;
    placeGates();
  }
  nextSum();

  function answer(g){
    if(g.ok){
      right++; solved++;
      streak++; bestStreak = Math.max(bestStreak, streak);
      const pts = 40 + Math.round(qT * 4) + Math.min(80, streak * 8);
      score += pts; setLive(score);
      snd('correct');
      fx.explode(g.p, 2.2, { color: '#39ff88', debris: 0, smoke: 0 });
      w.pop(V.add(g.p, [0, 8, 0]), '+' + pts + ' ✔ ' + q.ans, '#9dffc4', { size: 16 });
      flashCol = '#39ff88';
    }else{
      wrong++;
      streak = 0;
      clock.add(-Math.min(3, Math.max(0, clock.left - 1)));
      snd('wrong');
      w.kick(0.6);
      fx.sparks(g.p, 16, '#ff4a4a', 1.2, 14);
      w.pop(V.add(g.p, [0, 8, 0]), '✖ ' + g.v + ' — it was ' + q.ans + ' · −3s', '#ff8a8a', { size: 15 });
      flashCol = '#ff4a4a';
    }
    flashT = 0.35;
    nextSum();
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('math', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '✔ Correct Gates': right,
      '✖ Wrong Gates': wrong,
      '💨 Let Dissolve': missed,
      '⛓ Best Streak': bestStreak,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, right, wrong, missed, streak, q: q && q.text, ans: q && q.ans, gates: gates.length }),
    passCorrect(){ const g = gates.find(x => x.ok); if(g) answer(g); },
    passWrong(){ const g = gates.find(x => !x.ok); if(g) answer(g); }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      const prev = V.copy(me.p);
      flyStep(me, I, dt, { level: 1.2, floor: 8, ceiling: 160 });
      city.update(me.p);
      const tb = towerAt(city, me.p, 1.6);
      if(tb && me.inv <= 0){ bounceOff(me, tb, 1.6); me.hit = 0.3; me.inv = 0.5; snd('bounceWall'); w.kick(0.6); }
      for(const g of gates){
        if(throughRing(prev, me.p, g.p, g.n, RAD) !== 0){ answer(g); break; }
      }
      qT -= dt;
      if(qT <= 0){
        missed++; streak = 0;
        snd('glitch');
        say('TOO SLOW — it was ' + q.ans, 1.8);
        for(const g of gates) fx.sparks(g.p, 6, '#8a7aff', 1, 8);
        nextSum();
      }else{
        // Gates left far behind (or far off to a side) follow you round.
        const c = gates[0].p, d = V.sub(c, me.p);
        const ahead = V.dot(V.norm([d[0], 0, d[2]]), V.norm([me.B.f[0], 0, me.B.f[2]]));
        if(V.len(d) > 360 || (ahead < -0.2 && V.len(d) > 60)) placeGates();
      }
    }
    flashT = Math.max(0, flashT - dt);
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    flyCam(w, me, dt, { fov: 62 });
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 8, radius: 220, color: '#3a1d6e', glow: 0.95, major: 5, floor: '#05030b', rough: 0.25 });
    city.draw(w);
    const urgent = qT / qLife;
    for(const g of gates){
      const col = urgent < 0.25 ? '#ff7a9a' : '#5ee7ff';
      drawRing(w, g.p, g.n, RAD, col, 0.9 + 0.3 * Math.sin(w.t * 4));
      // A pylon under each gate, so its height reads against the floor.
      r.streak([g.p[0], 0, g.p[2]], [g.p[0], g.p[1] - RAD, g.p[2]], 0.12, col, 0.35, 0);
    }
    drawFlyer(w, me, colour);
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    hud.radar(70, Ht - 74, 54, me.p, me.B.f, 220, gates.map(g => ({ p: g.p, c: '#5ee7ff', s: 2.6, tick: true })));
    // The sum, big, and its clock under it.
    hud.text(Wd / 2, 30, q.text + ' = ?', { size: 26, color: flashT > 0 ? flashCol : '#ffffff', blur: 12 });
    hud.bar(Wd / 2 - 80, 50, 160, 6, urgent, urgent < 0.25 ? '#ff5a7a' : '#a855f7');
    for(const g of gates){
      const qp = hud.proj(g.p);
      if(qp.on){
        const sz = clamp(2200 / Math.max(qp.z, 1), 15, 48);
        hud.text(qp.x, qp.y, String(g.v), { size: sz, color: '#ffffff', blur: 10 });
      }else hud.edgeArrow(g.p, '#5ee7ff', String(g.v));
    }
    hud.text(Wd - 16, Ht - 40, streak > 1 ? 'STREAK ×' + streak : '', { size: 13, align: 'right', color: '#9dffc4' });
    hud.text(Wd - 16, Ht - 20, '✔ ' + right + '  ✖ ' + wrong, { size: 13, align: 'right', color: '#d8c8ff' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.energy / 100, '#a855f7', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 74, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  ⚡ REACTION TIME · OPEN WORLD — BEACON BURN
// ══════════════════════════════════════════════
// The classic waits for green and punishes the twitch that comes too soon.
// Out here a beacon ignites somewhere in open space — ahead, above, behind
// you — amber while it arms, green the instant it goes live. Turn, burn and
// be there: reach it on green and the time it took you is your score; reach
// it while it is still amber and it jumps away, the false start the classic
// always punished. Leave it too long and it dies.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owFly) return;
const { V, TAU, makeField, makeDust, drawBodies, owBegin, owClock } = P.owKit;
const { makeFlyer, flyStep, flyCam, drawFlyer } = P.owFly;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const REACH = 8;

P.ow.reaction = function(){
  const G = owBegin({
    space: { seed: 31, a: '#0e8a6a', b: '#1a3fae', c: '#7aff9a', dir: [-0.4, 0.3, -0.86], amount: 0.85, dust: 0.7, galaxy: 0.8 },
    input: { mouseSteer: true, mouseGain: 1.2 }, far: 12000, near: 0.3
  });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: TURN · BOOST: BURN · WAIT FOR GREEN', 'MOUSE / WASD: TURN · SHIFT: BURN · REACH THE BEACON ONLY ONCE IT IS GREEN');

  const me = makeFlyer({ p: [0, 0, 0], speed: 42 });
  let score = 0, caught = 0, early = 0, died = 0, streak = 0, bestStreak = 0, over = false, finished = false;
  let msg = '', msgT = 0, last = null, bestMs = 0, beacon = null, gap = 0.6, flash = 0, elapsed = 0;
  const rocks = makeField({
    cell: 220, dims: 3, seed: 515, radius: 700,
    gen(cx, cy, cz, g){
      const items = [];
      const n = Math.floor(g() * 3);
      for(let i = 0; i < n; i++) items.push({ p: [(cx + g()) * 220, (cy + g()) * 220, (cz + g()) * 220], s: 2 + Math.pow(g(), 3) * 16,
                                              g: ['rock', 'rock2', 'rock3', 'rock4'][(g() * 4) | 0], rot: [g() * 6, g() * 6, 0] });
      return items;
    }
  });
  const BODIES = [
    { kind: 'gas', off: [-2800, 600, -5600], size: 2200, color: '#3a8a7a', ring: 2.1, ringRot: [0.5, 0, -0.3], rot: [0.5, 0, -0.3], halo: '#7affc4', par: 0.004 },
    { kind: 'sun', off: [3600, 1500, 2600], size: 200, color: '#e8fff0', gain: 3.0, par: 0 }
  ];
  const dust = makeDust(60, 80);
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#39ff88,#00f5ff)';
  const total = Math.round(100 * (typeof getTimeModifier === 'function' ? getTimeModifier() : 1));
  const clock = owClock(100, () => end('clock'), left => { bar.style.width = Math.max(0, left / Math.max(1, total) * 100) + '%'; });
  const say = (s, t) => { msg = s; msgT = t || 2; };

  // Anywhere round you — ahead is likelier, behind is never ruled out.
  function ignite(){
    let d;
    do{ d = V.norm([rr(-1, 1), rr(-0.7, 0.7), rr(-1, 1)]); }while(V.dot(d, me.B.f) < -0.85 && Math.random() < 0.5);
    const dist = rr(85, 150);
    const arm = rr(1.0, 2.8);
    const live = Math.max(3.4, 6.2 - elapsed * 0.02) / Math.sqrt(diff);
    beacon = { p: V.madd(me.p, d, dist), arm, armT: arm, live, liveT: 0, state: 'arm', ph: Math.random() * TAU };
    snd('charge');
  }
  function reach(){
    const b = beacon;
    if(b.state === 'arm'){
      early++;
      streak = 0;
      snd('wrong');
      say('TOO EARLY — wait for green', 1.6);
      fx.sparks(b.p, 14, '#ffb35c', 1.2, 14);
      w.kick(0.5);
      beacon = null; gap = 0.5;
      return;
    }
    caught++;
    streak++; bestStreak = Math.max(bestStreak, streak);
    const ms = Math.round(b.liveT * 1000);
    last = ms;
    if(!bestMs || ms < bestMs) bestMs = ms;
    const pts = 30 + Math.round(120 * clamp(1 - b.liveT / b.live, 0, 1)) + Math.min(50, streak * 5);
    score += pts; setLive(score);
    snd('success');
    fx.explode(b.p, 2.8, { color: '#39ff88', ringColor: '#9dffc4', debris: 0, smoke: 0 });
    w.pop(V.add(b.p, [0, 5, 0]), ms + ' ms · +' + pts, '#9dffc4', { size: 16 });
    flash = 0.4;
    beacon = null; gap = rr(0.3, 0.9);
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('reaction', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '🟢 Beacons Reached': caught,
      '⚡ Best Reach': caught ? bestMs + ' ms' : '—',
      '🟠 False Starts': early,
      '💀 Burned Out': died,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, caught, early, died, streak, beacon: beacon && beacon.state, dist: beacon ? Math.round(Math.sqrt(V.d2(beacon.p, me.p))) : null }),
    goGreen(){ if(beacon && beacon.state === 'arm'){ beacon.armT = 0; } },
    reachNow(){ if(beacon) reach(); }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      elapsed += dt;
      flyStep(me, I, dt, { yawRate: 1.8, pitchRate: 1.5, boostMul: 2.4 });
      rocks.update(me.p);
      if(!beacon){ gap -= dt; if(gap <= 0) ignite(); }
      else{
        const b = beacon;
        if(b.state === 'arm'){
          b.armT -= dt;
          if(b.armT <= 0){ b.state = 'live'; snd('go'); }
        }else{
          b.liveT += dt;
          if(b.liveT >= b.live){
            died++; streak = 0;
            snd('glitch');
            say('BEACON BURNED OUT', 1.4);
            fx.sparks(b.p, 10, '#7aff9a', 1, 8);
            beacon = null; gap = 0.6;
          }
        }
        if(beacon && V.d2(beacon.p, me.p) < REACH * REACH) reach();
      }
    }
    flash = Math.max(0, flash - dt);
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    flyCam(w, me, dt, { fov: 64 });
    w.step(dt);

    w.begin();
    drawBodies(w, BODIES);
    const eye = w.cam.eye;
    rocks.each(it => {
      const d2 = V.d2(it.p, eye);
      if(d2 > 650 * 650 || !r.viewDepth(it.p, 1.2 + it.s / Math.max(30, Math.sqrt(d2)))) return;
      r.draw(it.g, { pos: it.p, rot: [it.rot[0] + w.t * 0.05, it.rot[1], 0], scale: it.s, color: '#5f6a66', metallic: 0.05, roughness: 0.9, rim: 0.35 });
    });
    if(beacon){
      const b = beacon;
      const green = b.state === 'live';
      const col = green ? '#39ff88' : '#ffb35c';
      const k = green ? 1 - b.liveT / b.live : 1 - b.armT / b.arm;
      const pulse = 1 + 0.15 * Math.sin(w.t * (green ? 10 : 4) + b.ph);
      r.draw('sphere', { pos: b.p, scale: 2.2 * pulse, color: col, emissive: col, emissiveStrength: green ? 3.2 : 1.6 });
      r.draw('thintorus', { pos: b.p, rot: [w.t * 1.1, w.t * 0.7, 0], scale: [9 * (green ? 0.4 + 0.6 * k : 1), 1, 9 * (green ? 0.4 + 0.6 * k : 1)], color: col, emissive: col, emissiveStrength: 2.4 });
      r.draw('thintorus', { pos: b.p, rot: [Math.PI / 2, 0, w.t], scale: [REACH * 2.2, 1, REACH * 2.2], color: col, emissive: col, emissiveStrength: green ? 1.6 : 0.8 });
      r.glow(b.p, 7 * pulse, col, green ? 1.6 : 0.8);
      // A pillar of light, so it can be found from anywhere.
      r.streak(V.add(b.p, [0, -60, 0]), V.add(b.p, [0, 60, 0]), 0.9, col, green ? 1.2 : 0.5, 0);
      r.light({ pos: b.p, color: col, intensity: green ? 260 : 120, range: 40 });
    }
    drawFlyer(w, me, colour);
    dust(w, V.mul(me.B.f, me.speed), { len: 0.045, max: 7, gain: 0.42, width: 0.03 });
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    hud.radar(70, Ht - 74, 54, me.p, me.B.f, 170, beacon ? [{ p: beacon.p, c: beacon.state === 'live' ? '#39ff88' : '#ffb35c', s: 3.4, tick: true }] : []);
    if(beacon){
      const green = beacon.state === 'live';
      const col = green ? '#39ff88' : '#ffb35c';
      const d = Math.sqrt(V.d2(beacon.p, me.p));
      const q = hud.bracket(beacon.p, 6, col, green ? 'GO!' : 'ARMING…', { dist: d, lock: green });
      if(!q.on) hud.edgeArrow(beacon.p, col, green ? 'GO' : 'WAIT');
      if(green) hud.bar(Wd / 2 - 80, 46, 160, 6, 1 - beacon.liveT / beacon.live, '#39ff88');
    }
    hud.text(Wd / 2, 28, beacon && beacon.state === 'live' ? '🟢 GREEN — BURN!' : beacon ? '🟠 WAIT FOR GREEN…' : '…', { size: 15, color: beacon && beacon.state === 'live' ? '#9dffc4' : '#ffd8a0' });
    if(last != null) hud.text(Wd - 16, Ht - 40, 'LAST ' + last + ' ms', { size: 13, align: 'right', color: flash > 0 ? '#ffffff' : '#9dffc4' });
    hud.text(Wd - 16, Ht - 20, '🟢 ' + caught + (streak > 1 ? '  ×' + streak : ''), { size: 13, align: 'right', color: '#9dffc4' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.energy / 100, '#39ff88', 'BURN');
    if(msgT > 0) hud.text(Wd / 2, 70, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🐦 FLAPPY DRONE · OPEN WORLD — THE PYLON FIELD
// ══════════════════════════════════════════════
// Gravity and a flap, as ever — but the firewall columns no longer come at
// you down a corridor. They stand all over an icy plain, each with its gap
// facing whichever way it faces, among bare pylons and floating rings. Steer
// where you like: go round a wall if you must, thread its gap if you want the
// points. The floor is as hard as it always was.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owFly) return;
const { V, TAU, wrapAng, ease, makeField, drawFloor, owClock, basisYPR } = P.owKit;
const { groundBegin, chaseCam, makeCity } = P.owGround;
const { drawRing, throughRing } = P.owFly;
const { mine, clamp, runLoop } = P.kit;
const CELL = 42, WALL_W = 12, WALL_T = 1.8, TOP = 46;

P.ow.flappy = function(){
  const G = groundBegin({ sky: 'ice', input: { mouseSteer: true, mouseGain: 1.2, spaceJumps: true, touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: STEER · JUMP BUTTON: FLAP · ⚡ / LB: SPECIAL', 'A/D or MOUSE: STEER · SPACE / CLICK: FLAP · SHIFT: SPRINT · V: SPECIAL');
  inp.altLabel = 'FLAP';

  const me = { p: [0, 12, 0], yaw: 0, vy: 0, speed: 24, shields: 3, inv: 0, bank: 0, tilt: 0, dist: 0, energy: 100 };
  let score = 0, threaded = 0, rings = 0, streak = 0, bestStreak = 0, over = false, finished = false, msg = '', msgT = 0, wasFlap = false;
  const taps = P.owDrive ? P.owDrive.tapCounter('drive') : { take: () => 0 };
  const field = makeField({
    cell: CELL, dims: 2, seed: 7171, radius: 340,
    gen(cx, cy, cz, g){
      const items = [];
      const x = (cx + 0.5) * CELL, z = (cz + 0.5) * CELL;
      if(Math.hypot(x, z) < 40) return items;
      const roll = g(), yaw = g() * Math.PI;
      if(roll < 0.42){
        const gh = 11 - Math.min(3, Math.abs(cx + cz) * 0.004) + g() * 2;
        items.push({ t: 'gate', p: [x + (g() - 0.5) * 14, 0, z + (g() - 0.5) * 14], yaw, gy: 9 + g() * 20, gh, passed: false });
      }else if(roll < 0.66){
        items.push({ t: 'pylon', p: [x + (g() - 0.5) * 24, 0, z + (g() - 0.5) * 24], r: 1.3 + g() * 0.8, h: 16 + g() * 30 });
      }
      if(g() < 0.4){
        const a = g() * TAU;
        items.push({ t: 'ring', p: [x + Math.cos(a) * 14, 5 + g() * 22, z + Math.sin(a) * 14], n: [Math.sin(yaw), 0, Math.cos(yaw)], got: false });
      }
      return items;
    }
  });
  const city = makeCity({ seed: 909, density: 0.08, cell: 150, clear: 200, hMin: 40, hMax: 110, radius: 900, towerColor: '#06101c' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#46c8ff,#ffffff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  // A point in a gate's own frame: x along the wall, z through it.
  const local = (p, o) => {
    const dx = p[0] - o.p[0], dz = p[2] - o.p[2], c = Math.cos(o.yaw), s = Math.sin(o.yaw);
    return [dx * c - dz * s, dx * s + dz * c];
  };
  function crash(at, why){
    if(me.inv > 0 || over) return;
    // 🛡️ Shield Burst holds; 👻 Phase Shift flies straight through.
    if(SP.shielded() || (SP.active('phase') && why !== 'HIT THE FLOOR')) return;
    me.shields--;
    me.inv = 1.5;
    streak = 0;
    snd('hurt'); w.kick(1.1);
    fx.explode(at, 1.1, { color: '#7fe8ff', debris: 3, smoke: 1, ring: false });
    bar.style.width = (Math.max(0, me.shields) / 3 * 100) + '%';
    say(why, 1.4);
    if(me.shields <= 0){
      if(survivedFatal()){ me.shields = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); return; }
      over = true;
      snd('bigExplode');
      fx.explode(me.p, 2.4, { color: colour });
      gLater(() => finish('crash'), 1200);
    }
  }
  function thread(o){
    o.passed = true;
    threaded++;
    streak++; bestStreak = Math.max(bestStreak, streak);
    const pts = 40 + Math.min(40, streak * 5);
    score += pts; setLive(score);
    snd('score');
    w.pop([o.p[0], o.gy + o.gh, o.p[2]], '+' + pts + ' THREADED', '#bff6ff', { size: 14 });
    fx.sparks([o.p[0], o.gy, o.p[2]], 10, '#bff6ff', 1, 10);
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('flappy', score, {
      '📡 Flight': why === 'clock' ? 'CLOCK EXPIRED' : 'DOWNED',
      '🧱 Gaps Threaded': threaded,
      '⭕ Rings': rings,
      '📏 Distance': Math.round(me.dist) + ' m',
      '⛓ Best Streak': bestStreak,
      '🏆 Score': score + ' PTS'
    });
  }
  // ⚡ v60 · SPECIALS (the kit): Shield Burst, and the new Phase Shift
  // (through walls and pylons) and Magnet Field (every ring in reach is
  // yours). One every 140 points.
  const SP = P.owKit.makeSpecials(G, {
    kinds: ['shield', 'phase', 'magnet'],
    every: 140, bubbleR: 2.6,
    player: () => me.p,
    heal: () => { me.shields = Math.min(3, me.shields + 1); bar.style.width = (me.shields / 3 * 100) + '%'; }
  });
  P.owDebug = {
    specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use(),
    state: () => ({ score, threaded, rings, shields: me.shields, y: Math.round(me.p[1]), dist: Math.round(me.dist) }),
    lose(){ me.inv = 0; crash(me.p, 'TEST'); },
    thread(){ let g = null; field.each(o => { if(!g && o.t === 'gate' && !o.passed) g = o; }); if(g) thread(g); return !!g; }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      SP.tick(dt, I, score);
      me.inv = Math.max(0, me.inv - dt);
      const steer = clamp(I.ax, -1, 1);
      me.yaw = wrapAng(me.yaw - steer * 1.7 * dt);
      me.bank += (clamp(steer * 0.6, -0.7, 0.7) - me.bank) * ease(dt, 0.1);
      const flap = I.jumpHit || taps.take() > 0 || (I.device !== 'touch' && I.fire && !wasFlap);
      wasFlap = I.fire;
      if(flap){ me.vy = 9.2; snd('flap'); fx.puff([me.p[0], me.p[1] - 0.6, me.p[2]], '#bfe8ff', 0.5, 0.5, [0, -2, 0]); }
      me.vy = Math.max(-26, me.vy - 23 * dt);
      const sprint = I.boost && me.energy > 2;
      me.energy = clamp(me.energy + (sprint ? -30 : 12) * dt, 0, 100);
      const base = Math.min(34, 24 + me.dist * 0.003) * Math.min(1.25, diff);
      me.speed += ((sprint ? base * 1.5 : base) - me.speed) * ease(dt, 0.4);
      me.tilt += (clamp(me.vy * 0.05, -0.5, 0.45) - me.tilt) * ease(dt, 0.08);
      const prev = V.copy(me.p);
      const f = [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)];
      me.p = V.add(V.madd(me.p, f, me.speed * dt), [0, me.vy * dt, 0]);
      me.dist += me.speed * dt;
      me.payT = (me.payT || 0) + me.speed * dt;
      if(me.payT > 10){ me.payT = 0; score += 1; setLive(score); }
      if(me.p[1] > TOP){ me.p[1] = TOP; me.vy = Math.min(me.vy, 0); }
      if(me.p[1] < 0.9){ me.p[1] = 0.9; me.vy = 8; crash(me.p, 'HIT THE FLOOR'); }
      field.update(me.p);
      city.update(me.p);
      // 🧲 The magnet takes every ring within twenty-six metres.
      if(SP.active('magnet')) field.each(o => {
        if(o.t === 'ring' && !o.got && V.d2(o.p, me.p) < 26 * 26){ o.got = true; rings++; score += 15; setLive(score); snd('coin'); fx.sparks(o.p, 8, '#ffd700', 1, 10); }
      });
      field.near(me.p, o => {
        if(o.t === 'gate'){
          const a = local(prev, o), b = local(me.p, o);
          const inWall = Math.abs(b[0]) < WALL_W / 2 + 0.6 && Math.abs(b[1]) < WALL_T / 2 + 0.7;
          const lo = o.gy - o.gh / 2, hi = o.gy + o.gh / 2;
          if(inWall && (me.p[1] < lo + 0.5 || me.p[1] > hi - 0.5) && me.p[1] < hi + 14 && !SP.active('phase')){
            crash(me.p, 'FIREWALL');
            me.p = V.madd(prev, f, -1.5);
          }else if(!o.passed && (a[1] > 0) !== (b[1] > 0) && Math.abs(b[0]) < WALL_W / 2 && me.p[1] > lo && me.p[1] < hi) thread(o);
        }else if(o.t === 'pylon'){
          if((me.p[0] - o.p[0]) ** 2 + (me.p[2] - o.p[2]) ** 2 < (o.r + 0.9) ** 2 && me.p[1] < o.h && !SP.active('phase')){ crash(me.p, 'PYLON'); me.p = V.madd(prev, f, -1.5); }
        }else if(o.t === 'ring' && !o.got){
          if(throughRing(prev, me.p, o.p, o.n, 4.2) !== 0){
            o.got = true; rings++; score += 15; setLive(score); snd('coin');
            fx.glowPop(o.p, '#ffd700', 2.4, 0.35);
          }
        }
      });
      if(city.hit(me.p, 0.8) && me.p[1] < 60 && !SP.active('phase')){ crash(me.p, 'TOWER'); me.p = V.madd(prev, f, -2); me.yaw += Math.PI * 0.5; }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    chaseCam(w, me.p, me.yaw, { back: 10, up: 3.2, ahead: 18, fov: 64, half: 0.09, tgtUp: 0.5 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 170, color: '#15507a', glow: 0.9, major: 5, floor: '#030a14', rough: 0.2 });
    city.draw(w);
    const eye = w.cam.eye;
    field.each(o => {
      if(V.d2(o.p, eye) > 260 * 260) return;
      if(o.t === 'gate'){
        if(!r.viewDepth([o.p[0], o.gy, o.p[2]], 1.6)) return;
        const lo = o.gy - o.gh / 2, hi = o.gy + o.gh / 2, top = hi + 14;
        const col = o.passed ? '#39ff88' : '#ff3a6a';
        r.draw('cube', { pos: [o.p[0], lo / 2, o.p[2]], rot: [0, o.yaw, 0], scale: [WALL_W, lo, WALL_T], color: '#16202e', metallic: 0.7, roughness: 0.35 });
        r.draw('cube', { pos: [o.p[0], (hi + top) / 2, o.p[2]], rot: [0, o.yaw, 0], scale: [WALL_W, top - hi, WALL_T], color: '#16202e', metallic: 0.7, roughness: 0.35 });
        r.draw('box', { pos: [o.p[0], lo, o.p[2]], rot: [0, o.yaw, 0], scale: [WALL_W * 1.01, 0.22, WALL_T * 1.05], color: col, emissive: col, emissiveStrength: 2.6 });
        r.draw('box', { pos: [o.p[0], hi, o.p[2]], rot: [0, o.yaw, 0], scale: [WALL_W * 1.01, 0.22, WALL_T * 1.05], color: col, emissive: col, emissiveStrength: 2.6 });
      }else if(o.t === 'pylon'){
        if(!r.viewDepth([o.p[0], o.h / 2, o.p[2]], 1.6)) return;
        r.draw('cylinder', { pos: [o.p[0], o.h / 2, o.p[2]], scale: [o.r * 2, o.h, o.r * 2], color: '#1a2434', metallic: 0.8, roughness: 0.3 });
        r.draw('box', { pos: [o.p[0], o.h + 0.2, o.p[2]], scale: [o.r * 2.2, 0.3, o.r * 2.2], color: '#7fe8ff', emissive: '#7fe8ff', emissiveStrength: 2.2 });
      }else if(o.t === 'ring' && !o.got){
        if(!r.viewDepth(o.p, 1.3)) return;
        drawRing(w, o.p, o.n, 4.2, '#ffd700', 1);
      }
    });
    if(!(me.inv > 0 && Math.sin(w.t * 30) > 0)){
      const B = basisYPR(me.yaw, me.tilt, me.bank);
      r.draw('drone', { pos: me.p, m3: B.m3, scale: 1.8, color: '#c9d4e2', metallic: 0.6, roughness: 0.3, rim: 0.9, emissive: colour, emissiveStrength: 0.5 });
      // ✨ v60 · the rotors turn, faster as the drone climbs hard.
      P.kit.drawRotors(r, me.p, B.m3, 1.8, (me.rotT = (me.rotT || 0) + dt * (1 + clamp((me.vy || 0) / 20, 0, 0.6))),
                       { color: '#c9d4e2', metallic: 0.6, roughness: 0.3, rim: 0.9, emissive: colour, emissiveStrength: 0.004 });
      r.glow(me.p, 2.4, colour, 0.6);
    }
    // Its shadow, so height reads.
    r.draw('thintorus', { pos: [me.p[0], 0.08, me.p[2]], scale: [2.4, 1, 2.4], color: '#000000', emissive: colour, emissiveStrength: clamp(1.4 - me.p[1] / 30, 0.2, 1.4) });
    r.light({ pos: [me.p[0], me.p[1] + 4, me.p[2] + 2], color: '#d8f0ff', intensity: 100, range: 22 });
    SP.draw();
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    SP.hud();
    const rad = [];
    field.each(o => { if(V.d2(o.p, me.p) > 160 * 160) return; if(o.t === 'gate' && !o.passed) rad.push({ p: o.p, c: '#ff3a6a', s: 2.4 }); else if(o.t === 'ring' && !o.got) rad.push({ p: o.p, c: '#ffd700', s: 1.8 }); });
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 120, rad);
    hud.text(Wd - 16, Ht - 40, 'ALT ' + Math.round(me.p[1]) + ' m', { size: 13, align: 'right', color: '#bff6ff' });
    hud.text(Wd - 16, Ht - 20, '♦'.repeat(Math.max(0, me.shields)) + '◊'.repeat(Math.max(0, 3 - me.shields)), { size: 14, align: 'right', color: '#7fe8ff' });
    if(streak > 1) hud.text(Wd / 2, 52, 'STREAK ×' + streak, { size: 12, color: '#bff6ff' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.energy / 100, '#46c8ff', 'SPRINT');
    if(msgT > 0) hud.text(Wd / 2, 26, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  ☄️ METEOR DEFENSE · OPEN WORLD — STATION ADRIFT
// ══════════════════════════════════════════════
// The classic defends three servers along the bottom of a screen. Here they
// ride the arms of a station adrift in open space, and the rogue code comes
// in as rock from every direction — above, below, behind. You are the
// battery on the hub: look round, tap where the meteor is, and the shell
// flies out and bursts there. A blast still takes time to travel, so lead
// the far ones. Lose all three servers and the station goes dark.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit) return;
const { V, TAU, ease, makeDust, drawBodies, owBegin, owClock, attFrom, attTurn, attLevelRoll, basisQ, yawOf } = P.owKit;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const SHELL_SP = 95, BLAST = 9.5, ARM = 11;

P.ow.meteor = function(){
  const G = owBegin({
    space: { seed: 77, a: '#6a2a10', b: '#1a2f6e', c: '#ffb36a', dir: [0.5, 0.2, -0.84], amount: 0.9, dust: 0.8, galaxy: 1.0 },
    input: { touch: 'tap' }, far: 12000, near: 0.3
  });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('DRAG LEFT SIDE: LOOK · TAP A METEOR: FIRE THERE · ⚡: BATTERY', 'WASD / ←↑↓→ / SCREEN EDGES: LOOK · CLICK A METEOR: FIRE THERE · SPACE: FIRE AT THE RETICLE · V: BATTERY');

  const C = [0, 0, 0];
  const servers = [0, 1, 2].map(i => {
    const a = i / 3 * TAU;
    return { i, a, p: [Math.cos(a) * ARM, 0, Math.sin(a) * ARM], hp: 3, dead: false, flash: 0 };
  });
  // ✨ v57 · The look is an attitude, not a yaw and a capped pitch, so the
  // battery can sweep straight up and on over the top (see ✈️ ATTITUDE).
  // `yaw` is the heading the turret on the hub is turned to.
  const view = { q: attFrom(0, 0.12), yaw: 0 };
  let score = 0, kills = 0, shots = 0, over = false, finished = false, msg = '', msgT = 0;
  let spawnT = 1.5, elapsed = 0, reload = 0, spin = 0;
  const meteors = [], shells = [], blasts = [], taps = [];
  const BODIES = [
    { kind: 'gas', off: [3000, -1200, -5200], size: 2600, color: '#b0704a', ring: 2.2, ringRot: [0.3, 0, -0.5], rot: [0.3, 0, -0.5], halo: '#ffb070', par: 0 },
    { kind: 'moon', off: [-2600, 800, -4200], size: 260, color: '#8a8580', v: '2', par: 0 },
    { kind: 'sun', off: [-3800, 1400, 2400], size: 220, color: '#fff0da', gain: 3.4, par: 0 }
  ];
  const dust = makeDust(40, 90);
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ffb36a,#ff4a4a)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  // Taps on a touch screen fire where they land (the left half is the look
  // stick, read by the shared input) — except on the ⚡ button.
  const cv = aCanvas;
  const onTouch = e => {
    if(!e.isTrusted) return;
    const rc = cv.getBoundingClientRect();
    for(const t of e.changedTouches){
      const u = (t.clientX - rc.left) / Math.max(1, rc.width), v = (t.clientY - rc.top) / Math.max(1, rc.height);
      const onAbil = P.owKit.touchButtons('tap', true).some(b => Math.hypot(u - b.u, (v - b.v) * (rc.height / Math.max(1, rc.width))) < b.r);
      if(u >= 0.5 && !onAbil) taps.push([u * 2 - 1, v * 2 - 1]);
    }
  };
  if(cv) cv.addEventListener('touchstart', onTouch, { passive: true });
  const prevStop = onStopGame;
  onStopGame = () => { try{ if(cv) cv.removeEventListener('touchstart', onTouch); }catch(e){} if(prevStop) prevStop(); };

  const liveServers = () => servers.filter(s => !s.dead);
  function spawnMeteor(big){
    const live = liveServers();
    if(!live.length) return;
    const tgt = live[(Math.random() * live.length) | 0];
    let d;
    do{ d = V.norm([rr(-1, 1), rr(-0.8, 0.8), rr(-1, 1)]); }while(V.len(d) < 0.1);
    const p = V.madd(C, d, rr(240, 300));
    const s = big ? rr(4.2, 5.4) : rr(2, 3.4);
    const sp = (big ? rr(7, 10) : rr(10, 15)) * Math.min(1.5, diff) * (1 + Math.min(0.6, elapsed / 200));
    // Aimed at a server, with a little miss in it.
    const aim = V.add(tgt.p, [rr(-2, 2), rr(-2, 2), rr(-2, 2)]);
    meteors.push({ p, v: V.mul(V.norm(V.sub(aim, p)), sp), s, big, tgt, rot: [Math.random() * 6, Math.random() * 6, 0], spin: [rr(-1, 1), rr(-1, 1), 0],
                   g: ['rock', 'rock2', 'rock3', 'rock5'][(Math.random() * 4) | 0] });
  }
  // The ray under a screen point (−1..1), from the camera.
  function rayAt(nx, ny){
    const Cc = hud.cam;
    if(!Cc) return V.copy(view.f || [0, 0, -1]);
    const asp = hud.W / hud.H;
    return V.norm(V.add(V.add(Cc.f, V.mul(Cc.r, nx * Cc.th * asp)), V.mul(Cc.u, -ny * Cc.th)));
  }
  // A shell's fuse is set at launch: the meteor nearest the ray, else 90 out.
  function fire(dir){
    if(reload > 0 || over) return;
    // ⚡ OVERCHARGE: the 2D battery's fast reload.
    reload = SP.active('overdrive') ? 0.07 : 0.2;
    shots++;
    // ✨ v59 · out of the station turret's barrel tips (drawn at y 2.8, scale 1.5,
    // yawed with the view), left and right in turn
    fire.k = (fire.k || 0) + 1;
    const tq = [fire.k % 2 ? 0.16 : -0.16, 0, -0.86], tc = Math.cos(view.yaw), ts = Math.sin(view.yaw);
    const muzzle = [C[0] + (tq[0] * tc + tq[2] * ts) * 1.5, 2.8, C[2] + (-tq[0] * ts + tq[2] * tc) * 1.5];
    let fuse = 90, best = 1e9;
    for(const m of meteors){
      const rel = V.sub(m.p, muzzle), along = V.dot(rel, dir);
      if(along < 4) continue;
      // Where the meteor will be when the shell gets there.
      const ahead = V.madd(m.p, m.v, along / SHELL_SP);
      const a2 = V.dot(V.sub(ahead, muzzle), dir);
      const off = V.len(V.sub(V.sub(ahead, muzzle), V.mul(dir, a2)));
      if(off < BLAST * 1.1 + m.s && a2 < best){ best = a2; fuse = a2; }
    }
    shells.push({ p: muzzle, v: V.mul(dir, SHELL_SP), left: fuse });
    snd('shoot', { semi: -4 });
    fx.flash(muzzle, '#ffd8a0', 0.8, 0.08);
  }
  function burst(p){
    blasts.push({ p, t: 0, big: SP.active('overdrive') });
    fx.explode(p, 2.2, { color: '#ffb36a', debris: 0, smoke: 1, ringColor: '#ffd27a' });
    snd('explode');
  }
  function killMeteor(i, inBlast){
    const m = meteors[i];
    meteors.splice(i, 1);
    kills++;
    const pts = m.big ? 40 : 25;
    score += pts; setLive(score);
    fx.explode(m.p, m.s * 0.8, { color: '#ff8a3a', debrisGeo: 'rock2', debrisColor: '#4a3a30' });
    w.pop(V.add(m.p, [0, m.s + 2, 0]), '+' + pts, '#ffd27a', { size: 13 });
    if(inBlast) inBlast.n = (inBlast.n || 0) + 1;
    // A big one breaks into two that keep coming.
    if(m.big){
      for(const k of [-1, 1]){
        const side = V.norm(V.cross(m.v, [0, 1, 0]));
        meteors.push({ p: V.madd(m.p, side, k * 3), v: V.add(m.v, V.mul(side, k * 3)), s: m.s * 0.5, big: false, tgt: m.tgt,
                       rot: [0, 0, 0], spin: [rr(-2, 2), rr(-2, 2), 0], g: 'rock2' });
      }
    }
  }
  function impact(m){
    const s = m.tgt;
    // 🛡️ AEGIS DOME: a meteor that reaches the dome burns out on it.
    if(SP.shielded()){ fx.explode(m.p, m.s * 0.7, { color: '#a855f7', debris: 0, smoke: 0 }); snd('shieldHit'); return; }
    fx.explode(m.p, m.s, { color: '#ff6a2a', debrisGeo: 'slab', debrisColor: '#3a3e48' });
    snd('bigExplode');
    w.kick(1.4);
    if(s.dead) return;
    s.hp -= m.big ? 2 : 1;
    s.flash = 0.4;
    if(s.hp <= 0){
      s.dead = true;
      fx.explode(s.p, 4, { color: '#ff7a2a', debrisGeo: 'slab', debrisColor: '#4a4f58' });
      say('🖥 SERVER ' + (s.i + 1) + ' LOST', 2.4);
      if(!liveServers().length){
        if(survivedFatal()){ s.dead = false; s.hp = 1; say('SHIELD ABSORBED', 1.6); return; }
        over = true;
        gLater(() => finish('lost'), 1500);
      }
    }else say('⚠ SERVER ' + (s.i + 1) + ' HIT', 1.4);
    bar.style.width = (servers.reduce((a, x) => a + Math.max(0, x.hp), 0) / 9 * 100) + '%';
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    const left = liveServers().length;
    const bonus = left * 100;
    score += bonus;
    owFinish('meteor', score, {
      '📡 Watch': why === 'clock' ? 'CLOCK EXPIRED' : 'STATION DARK',
      '☄️ Meteors Destroyed': kills,
      '🎯 Shells Fired': shots,
      '🖥 Servers Standing': left + ' (+' + bonus + ')',
      '🏆 Score': score + ' PTS'
    });
  }
  // ⚡ v60 · THE BATTERY (the specials kit): the 2D Meteor Shield's four —
  // Rapid Salvo, Aegis Dome, Overcharge and Nano-Repair — and Time Warp.
  // One every 150 points.
  const SP = P.owKit.makeSpecials(G, {
    kinds: ['salvo', 'shield', 'overdrive', 'repair', 'warp'],
    every: 150, bubbleR: 36, shieldHeals: false, smartDmg: 1, missileSpeed: 120,
    player: () => [0, 3, 0],
    targets: () => meteors.map(m => ({ p: m.p, r: m.s * 0.7, obj: m })),
    hit: m => { const i = meteors.indexOf(m); if(i >= 0) killMeteor(i); },
    // NANO-REPAIR: a lost server back online first, else the most damaged one.
    heal: () => {
      const dead = servers.find(x => x.dead);
      const hurt = servers.filter(x => !x.dead && x.hp < 3).sort((a, b) => a.hp - b.hp)[0];
      if(dead){ dead.dead = false; dead.hp = 2; dead.flash = 0.5; say('🔧 SERVER ' + (dead.i + 1) + ' BACK ONLINE', 2); }
      else if(hurt){ hurt.hp = 3; hurt.flash = 0.5; say('🔧 SERVER ' + (hurt.i + 1) + ' RESTORED', 2); }
      else{ score += 60; setLive(score); say('🔧 RACKS WHOLE +60', 1.6); }
      bar.style.width = (servers.reduce((a, x) => a + Math.max(0, x.dead ? 0 : x.hp), 0) / 9 * 100) + '%';
    }
  });
  P.owDebug = {
    specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use(),
    state: () => ({ score, kills, meteors: meteors.length, servers: servers.map(s => s.hp), shells: shells.length,
                    nose: view.f && view.f.map(v => +v.toFixed(3)), up: view.u && view.u.map(v => +v.toFixed(3)) }),
    lose(){ const s = servers.find(x => !x.dead); if(s){ s.hp = 1; impact({ p: V.copy(s.p), s: 2, big: false, tgt: s }); } },
    spawn(n){ for(let i = 0; i < (n || 1); i++) spawnMeteor(i % 3 === 0); },
    blastAll(){ for(const m of meteors.slice()) burst(V.copy(m.p)); }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      elapsed += dt;
      reload = Math.max(0, reload - dt);
      // Look: keys / stick, plus the screen edges for a mouse.
      let lx = I.lx, ly = I.ly;
      if(I.device === 'mouse' && I.mouseOn){
        const ex = Math.abs(I.mx) > 0.78 ? (I.mx - Math.sign(I.mx) * 0.78) / 0.22 : 0;
        const ey = Math.abs(I.my) > 0.8 ? (I.my - Math.sign(I.my) * 0.8) / 0.2 : 0;
        lx += ex; ly += ey;
      }
      view.q = attTurn(view.q, -clamp(lx, -1, 1) * 1.7, -clamp(ly, -1, 1) * 1.3, dt);
      view.q = attLevelRoll(view.q, ease(dt, 0.3) * clamp(1 - Math.abs(ly) * 3, 0, 1));
      // Fire: a click goes where the pointer is; keys and the pad at the reticle.
      if(I.fire && I.device === 'mouse' && I.mouseOn) fire(rayAt(I.mx, I.my));
      else if(I.fire && I.device !== 'touch' && hud.cam) fire(hud.cam.f);
      while(taps.length){ const t = taps.shift(); if(reload > 0) reload = 0; fire(rayAt(t[0], t[1])); }
      SP.tick(dt, I, score);
      spawnT -= dt;
      if(spawnT <= 0){
        spawnMeteor(Math.random() < 0.18 + Math.min(0.2, elapsed / 600));
        if(elapsed > 50 && Math.random() < 0.3) spawnMeteor(false);
        spawnT = Math.max(0.75, 2.4 - elapsed * 0.014) / Math.sqrt(diff);
      }
    }
    if(dt > 0){
      spin += dt * 0.05;
      for(let i = shells.length - 1; i >= 0; i--){
        const s = shells[i];
        const step = SHELL_SP * dt;
        s.p = V.madd(s.p, V.norm(s.v), step);
        s.left -= step;
        if(s.left <= 0){ shells.splice(i, 1); burst(s.p); }
      }
      for(let i = blasts.length - 1; i >= 0; i--){
        const b = blasts[i];
        b.t += dt;
        // ⚡ OVERCHARGE: wide blasts (×1.6, the 2D battery's reach).
        const rad = BLAST * (b.big ? 1.6 : 1) * Math.min(1, b.t / 0.3);
        for(let j = meteors.length - 1; j >= 0; j--){
          if(V.d2(meteors[j].p, b.p) < (rad + meteors[j].s * 0.6) ** 2) killMeteor(j, b);
        }
        if(b.t > 0.6){
          if(b.n > 1){ const bonus = (b.n - 1) * 15; score += bonus; setLive(score); w.pop(V.add(b.p, [0, 6, 0]), '×' + b.n + ' +' + bonus, '#ffffff', { size: 15 }); snd('combo'); }
          blasts.splice(i, 1);
        }
      }
      for(let i = meteors.length - 1; i >= 0; i--){
        const m = meteors[i];
        // ⏳ TIME WARP: the whole storm at half speed.
        m.p = V.madd(m.p, m.v, dt * SP.warp());
        m.rot[0] += m.spin[0] * dt; m.rot[1] += m.spin[1] * dt;
        if(V.d2(m.p, m.tgt.p) < (2.6 + m.s * 0.5) ** 2 || V.d2(m.p, C) < (3.5 + m.s * 0.5) ** 2){ meteors.splice(i, 1); impact(m); }
      }
      for(const s of servers) s.flash = Math.max(0, s.flash - dt);
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    // ── CAMERA ── on the battery, looking out along the view.
    const B = basisQ(view.q, 0);
    view.f = B.f; view.u = B.u;
    if(Math.hypot(B.f[0], B.f[2]) > 0.2) view.yaw = yawOf(B.f);
    w.cam.eye = V.add([C[0], 7.2, C[2]], V.mul(B.f, -5.5));
    w.cam.target = V.add(w.cam.eye, V.mul(B.f, 40));
    w.goal.eye = w.cam.eye; w.goal.target = w.cam.target; w.goal.fov = 66;
    w.up = B.u;
    w.step(dt);

    w.begin();
    drawBodies(w, BODIES);
    // The station: a hub, a ring, three arms and their servers.
    r.draw('cylinder', { pos: [0, 0, 0], scale: [5, 5, 5], color: '#3a404c', metallic: 0.7, roughness: 0.35, rim: 0.6 });
    r.draw('torus', { pos: [0, 0, 0], rot: [0, spin, 0], scale: 30, color: '#4a5260', metallic: 0.75, roughness: 0.3, rim: 0.5, emissive: '#7fe8ff', emissiveStrength: 0.15 });
    r.draw('turret', { pos: [0, 2.8, 0], rot: [0, view.yaw, 0], scale: 1.5, color: '#c9d1dd', metallic: 0.6, roughness: 0.3, rim: 0.7, emissive: colour, emissiveStrength: 0.2 });
    for(const s of servers){
      r.beam([0, 0, 0], s.p, 0.7, { color: '#5a606c', metallic: 0.7, roughness: 0.4 });
      if(s.dead){
        // ✨ v59 · a burning wreck
        r.fire(V.add(s.p, [0, 1.2, 0]), 3.0 + 0.4 * Math.sin(w.t * 6 + s.i), 1.4, 0.35, (s.i * 0.29) % 1);
        r.smoke(V.add(s.p, [0, 5, 0]), 6, '#1c1a19', 0.28, 0.5, (s.i * 0.53) % 1);
        continue;
      }
      const col = s.hp >= 3 ? '#39ff88' : s.hp === 2 ? '#ffd700' : '#ff4a4a';
      r.draw('rack', { pos: s.p, rot: [0, -s.a + Math.PI / 2, 0], scale: 2.6, color: s.flash > 0 ? '#ffffff' : '#8a94a6', metallic: 0.6, roughness: 0.35, emissive: col, emissiveStrength: 0.6 });
      r.glow(V.add(s.p, [0, 2.4, 0]), 1.6, col, 0.9);
      r.light({ pos: V.add(s.p, [0, 3, 0]), color: col, intensity: 60, range: 12 });
    }
    r.light({ pos: [0, 8, 0], color: '#cfe0ff', intensity: 140, range: 30 });
    for(const m of meteors){
      if(!r.viewDepth(m.p, 1.3)) continue;
      // ✨ v60 · PAINTED, NOT LIT (see ENEMY_PAINT): an orange mineral glaze
      // the sun reads, not a hull glowing from inside; the entry burn behind it
      // is the only fire it carries.
      r.draw(m.g, { pos: m.p, rot: m.rot, scale: m.s, color: m.big ? '#e3262b' : '#ff6a12', metallic: 0.12, roughness: 0.62, rim: 0.5, detail: 10.92 });
      r.fire(m.p, m.s * 2.2, 1.3, 0.3, (m.s * 0.41) % 1);   // ✨ v59 an entry burn
      r.streak(V.madd(m.p, V.norm(m.v), -m.s * 4), m.p, m.s * 0.6, '#ff9a4a', 0.9, 1);
    }
    for(const s of shells){ r.glow(s.p, 0.9, '#ffe0a0', 2.4); r.streak(V.madd(s.p, V.norm(s.v), -4), s.p, 0.3, '#ffd27a', 2.6, 0.9); }
    for(const b of blasts){
      const k = Math.min(1, b.t / 0.3), a = 1 - b.t / 0.6;
      r.fire(b.p, BLAST * 1.8 * k, 2.2 * a, 1 - a, 0.43);   // ✨ v59 a fireball
      r.draw('lowsphere', { pos: b.p, scale: BLAST * 2 * k, color: '#ffd27a', emissive: '#ff8a3a', emissiveStrength: 1.2 * a, alpha: 0.18 * a, blend: true });
    }
    dust(w, [0, 0, 0], { gain: 0.2 });
    SP.draw();
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    SP.hud();
    hud.radar(70, Ht - 74, 54, C, B.f, 300, meteors.map(m => ({ p: m.p, c: m.big ? '#ff4a4a' : '#ffb36a', s: m.big ? 3.2 : 2.2, tick: true })));
    hud.crosshair(Wd / 2, Ht / 2, '#ffd8b0', 9);
    if(I.device === 'mouse' && I.mouseOn) hud.crosshair((I.mx + 1) / 2 * Wd, (I.my + 1) / 2 * Ht, '#ffffff', 6);
    const close = meteors.slice().sort((a, b) => V.d2(a.p, C) - V.d2(b.p, C)).slice(0, 6);
    for(const m of close){
      const d = Math.sqrt(V.d2(m.p, C));
      const q = hud.proj(m.p);
      if(q.on) hud.bracket(m.p, m.s * 1.3, d < 80 ? '#ff4a4a' : '#ffb36a', null, { dist: d, alpha: 0.75 });
      else if(d < 160) hud.edgeArrow(m.p, d < 80 ? '#ff4a4a' : '#ffb36a', null);
    }
    hud.text(Wd - 16, Ht - 20, servers.map(s => s.dead ? '▫' : '▮'.repeat(s.hp)).join('  '), { size: 13, align: 'right', color: '#9dffc4' });
    hud.text(Wd - 16, Ht - 40, '☄ ' + kills, { size: 13, align: 'right', color: '#ffd27a' });
    if(msgT > 0) hud.text(Wd / 2, 26, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🧠 MEMORY MATCH · OPEN WORLD — THE MONOLITH FIELD
// ══════════════════════════════════════════════
// The classic is sixteen tiles on a board. Here the tiles are monoliths
// standing all over an endless field, three pairs to every stretch of it.
// Drive into one and it turns, showing its sign; drive into a second — the
// same sign and both are cleared, a different one and both turn back. The
// skill is the same as ever, only now it is remembering WHERE.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owDrive) return;
const { V, TAU, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, groundRing } = P.owGround;
const { makeRover, driveStep, pushOutCircle, roverCam, roverDraw } = P.owDrive;
const { mine, clamp, runLoop } = P.kit;
const CELL = 78;
const SYMS = [
  { geo: 'sphere',    col: '#ff2d9a', glyph: '●', s: 1.5 },
  { geo: 'cube',      col: '#ffd700', glyph: '■', s: 1.4 },
  { geo: 'cone',      col: '#39ff88', glyph: '▲', s: 1.9 },
  { geo: 'torus',     col: '#00f5ff', glyph: '◯', s: 3.2 },
  { geo: 'cylinder',  col: '#ff6600', glyph: '▮', s: 1.5 },
  { geo: 'pill',      col: '#a855f7', glyph: '⬬', s: 1.6 },
  { geo: 'core',      col: '#ff4a4a', glyph: '✦', s: 1.6 },
  { geo: 'drone',     col: '#7fe8ff', glyph: '✣', s: 1.5 }
];
const SLOTS = [[0.2, 0.25], [0.5, 0.2], [0.8, 0.3], [0.25, 0.72], [0.55, 0.8], [0.82, 0.7]];

P.ow.memory = function(){
  const G = groundBegin({ sky: 'night', input: { touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  setControlHint('STICK: DRIVE · DRIVE INTO A MONOLITH TO TURN IT', 'W/S: THROTTLE · A/D: STEER · HOLD THE MOUSE ON THE GROUND: DRIVE THERE · SHIFT: BOOST');

  const me = makeRover({ max: 24 });
  let score = 0, pairs = 0, misses = 0, remembered = 0, fields = 0, streak = 0, bestStreak = 0, over = false, finished = false;
  let msg = '', msgT = 0, open = [], closeT = 0, touching = null;
  const cleared = new Map();                     // cell key → pairs matched there
  const field = makeField({
    cell: CELL, dims: 2, seed: 8484, radius: 470,
    gen(cx, cy, cz, g, k){
      const items = [];
      if(cx === 0 && cz === 0) return items;     // the start: open ground
      const picks = [];
      while(picks.length < 3){ const s = (g() * SYMS.length) | 0; if(!picks.includes(s)) picks.push(s); }
      const deck = [picks[0], picks[0], picks[1], picks[1], picks[2], picks[2]];
      for(let i = deck.length - 1; i > 0; i--){ const j = (g() * (i + 1)) | 0; const t = deck[i]; deck[i] = deck[j]; deck[j] = t; }
      SLOTS.forEach((sl, i) => {
        items.push({ t: 'mono', cell: k, p: [(cx + sl[0] + (g() - 0.5) * 0.12) * CELL, 0, (cz + sl[1] + (g() - 0.5) * 0.12) * CELL],
                     sym: deck[i], state: 'hidden', seen: false, yaw: g() * Math.PI, ph: g() * TAU, turn: 0 });
      });
      return items;
    }
  });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#00f5ff,#a855f7)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  function flip(m){
    if(m.state !== 'hidden' || closeT > 0 || open.length >= 2) return;
    m.state = 'open'; m.turn = 0;
    open.push(m);
    snd('flip');
    fx.sparks([m.p[0], 6, m.p[2]], 8, SYMS[m.sym].col, 1, 8);
    if(open.length === 2){
      const [a, b] = open;
      if(a.sym === b.sym) match(a, b);
      else{
        misses++;
        streak = 0;
        a.seen = b.seen = true;
        closeT = 1.15;
        snd('wrong');
        say('NO MATCH — remember where they stand', 1.6);
      }
    }
  }
  function match(a, b){
    pairs++;
    streak++; bestStreak = Math.max(bestStreak, streak);
    const mem = a.seen || b.seen;
    if(mem) remembered++;
    const pts = 50 + Math.min(60, streak * 10) + (mem ? 30 : 0);
    score += pts; setLive(score);
    snd('match');
    for(const m of [a, b]){
      fx.explode([m.p[0], 4, m.p[2]], 1.8, { color: SYMS[m.sym].col, debris: 0, smoke: 0 });
      field.kill(m);
      m.state = 'done';
    }
    w.pop([(a.p[0] + b.p[0]) / 2, 9, (a.p[2] + b.p[2]) / 2], '+' + pts + (mem ? ' REMEMBERED' : ''), SYMS[a.sym].col, { size: 15 });
    open = [];
    const n = (cleared.get(a.cell) || 0) + 1;
    cleared.set(a.cell, n);
    if(n === 3){
      fields++;
      score += 100; setLive(score);
      snd('success');
      say('🏁 FIELD CLEARED +100', 2);
    }
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('memory', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '🧩 Pairs Matched': pairs,
      '🧠 Remembered': remembered,
      '✖ Mismatches': misses,
      '🏁 Fields Cleared': fields,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, pairs, misses, remembered, fields, open: open.length, p: me.p.map(Math.round) }),
    matchPair(){
      const by = new Map(); let pair = null;
      field.each(m => { if(pair || m.state !== 'hidden') return; const k = m.cell + ':' + m.sym; if(by.has(k)) pair = [by.get(k), m]; else by.set(k, m); });
      if(pair){ closeT = 0; open = []; flip(pair[0]); flip(pair[1]); }
      return !!pair;
    },
    mismatch(){
      const hid = []; field.each(m => { if(m.state === 'hidden') hid.push(m); });
      const a = hid[0], b = hid.find(m => m.sym !== a.sym);
      if(a && b){ closeT = 0; open = []; flip(a); flip(b); }
    }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      driveStep(me, I, dt, hud);
      field.update(me.p);
      let near = null;
      field.near(me.p, m => {
        if(m.state === 'done') return;
        pushOutCircle(me, m.p, 2.9);
        if(V.d2(m.p, me.p) < 3.4 * 3.4) near = m;
      });
      if(near && near !== touching) flip(near);
      touching = near;
      if(closeT > 0){
        closeT -= dt;
        if(closeT <= 0){ for(const m of open) if(m.state === 'open') m.state = 'hidden'; open = []; snd('flip', { semi: -5 }); }
      }
      // A lone open monolith left far behind turns back on its own.
      if(open.length === 1 && V.d2(open[0].p, me.p) > 260 * 260){ open[0].state = 'hidden'; open[0].seen = true; open = []; }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    roverCam(w, me, dt, { back: 13, up: 7 });
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 170, color: '#0f3a5a', glow: 0.85, major: 13, floor: '#03060c', rough: 0.24 });
    const eye = w.cam.eye;
    let nl = 0;
    field.each(m => {
      if(V.d2(m.p, eye) > 260 * 260 || !r.viewDepth([m.p[0], 4, m.p[2]], 1.4)) return;
      const S = SYMS[m.sym];
      const up = m.state === 'open';
      if(up) m.turn = Math.min(1, m.turn + (w.dt || 0) * 3);
      const tint = up ? S.col : '#2a3a5a';
      r.draw('slab', { pos: [m.p[0], 4, m.p[2]], rot: [0, m.yaw + (up ? m.turn * Math.PI : 0), 0], scale: [3, 8, 1.3], color: '#10141e', metallic: 0.75, roughness: 0.32, rim: 0.7,
                       emissive: tint, emissiveStrength: up ? 0.35 : 0.06 });
      r.draw('box', { pos: [m.p[0], 8.1, m.p[2]], rot: [0, m.yaw, 0], scale: [3.1, 0.22, 1.4], color: up ? tint : '#46c8ff', emissive: up ? tint : '#46c8ff', emissiveStrength: up ? 2.6 : 2.0 });
      if(up){
        const y = 11 + Math.sin(w.t * 2 + m.ph) * 0.4;
        P.kit.drawMachine(r, S.geo, { pos: [m.p[0], y, m.p[2]], rot: [S.geo === 'torus' ? Math.PI / 2 : 0, w.t * 1.5, 0], scale: S.s, color: S.col, metallic: 0.4, roughness: 0.3, emissive: S.col, emissiveStrength: 1.4 }, w.t);
        r.glow([m.p[0], y, m.p[2]], 3, S.col, 0.9);
        groundRing(w, m.p, 3.4, S.col, 1);
        if(nl++ < 2) r.light({ pos: [m.p[0], 9, m.p[2]], color: S.col, intensity: 90, range: 18 });
      }else{
        r.glow([m.p[0], 8.4, m.p[2]], 2.2, '#7fe8ff', 0.45 + 0.2 * Math.sin(w.t * 2 + m.ph));
      }
    });
    roverDraw(w, me, colour);
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    const rad = [];
    field.each(m => { if(V.d2(m.p, me.p) < 75 * 75 || m.state === 'open') rad.push({ p: m.p, c: m.state === 'open' ? SYMS[m.sym].col : '#4a6a8a', s: m.state === 'open' ? 3.2 : 2 }); });
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 70, rad);
    if(open.length === 1){
      const S = SYMS[open[0].sym];
      hud.text(Wd / 2, 28, 'OPEN ' + S.glyph + '  — find its twin', { size: 16, color: S.col });
      if(!hud.proj(open[0].p).on) hud.edgeArrow(open[0].p, S.col, S.glyph);
    }else if(closeT > 0) hud.text(Wd / 2, 28, '✖ ' + SYMS[open[0].sym].glyph + ' ≠ ' + SYMS[open[1].sym].glyph, { size: 16, color: '#ff8a8a' });
    hud.text(Wd - 16, Ht - 40, streak > 1 ? 'STREAK ×' + streak : '', { size: 13, align: 'right', color: '#9dffc4' });
    hud.text(Wd - 16, Ht - 20, '🧩 ' + pairs, { size: 14, align: 'right', color: '#bff6ff' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.boostE / 100, '#00f5ff', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 56, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  📻 FREQUENCY · OPEN WORLD — TOWERS IN THE DARK
// ══════════════════════════════════════════════
// The classic is one waveform and two sliders. Out here every radio tower in
// an endless dark broadcasts its own: drive into a tower's range and stop,
// and the dials come up — frequency and amplitude, the classic's two — and a
// match held inside the margin for a second and a half tunes it in. Then on
// to the next mast blinking on the horizon. The later towers drift.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owDrive) return;
const { V, TAU, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, groundRing, beacon } = P.owGround;
const { makeRover, driveStep, pushOutCircle, roverCam, roverDraw, dotRing } = P.owDrive;
const { mine, clamp, runLoop } = P.kit;
const CELL = 150, RANGE = 17, HOLD = 1.5;
const F0 = 1, F1 = 4, A0 = 0.25, A1 = 1;
const FTOL = 0.13, ATOL = 0.07;

P.ow.freq = function(){
  const G = groundBegin({ sky: 'night', env: { zenith: '#02030a', horizon: '#0e1430', intensity: 0.8 }, fog: { color: '#03050e', density: 0.0075 }, input: { touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: DRIVE · STOP IN RANGE, THEN STICK: TUNE · BOOST: LEAVE',
                 'W/S A/D: DRIVE · STOP IN A TOWER\'S RANGE TO TUNE: A/D FREQUENCY, W/S AMPLITUDE (OR THE MOUSE) · SHIFT: LEAVE');

  const me = makeRover({ max: 26 });
  const dial = { f: 2.5, a: 0.6 };
  let score = 0, tuned = 0, streak = 0, bestStreak = 0, over = false, finished = false, msg = '', msgT = 0;
  let tuning = null, holdT = 0, tuneT = 0, stillT = 0, blocked = null, elapsed = 0;
  const towers = makeField({
    cell: CELL, dims: 2, seed: 4545, radius: 760,
    gen(cx, cy, cz, g){
      if(g() < 0.3 || (cx === 0 && cz === 0)) return [];
      const p = [(cx + 0.2 + g() * 0.6) * CELL, 0, (cz + 0.2 + g() * 0.6) * CELL];
      return [{ p, f: F0 + 0.2 + g() * (F1 - F0 - 0.4), a: A0 + 0.1 + g() * (A1 - A0 - 0.2), h: 28 + g() * 26, ph: g() * TAU,
                drift: Math.hypot(cx, cz) > 2 && g() < 0.5, done: false }];
    }
  });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#00f5ff,#39ff88)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  // What the tower is sending right now (a drifting one wanders).
  const tf = t => t.f + (t.drift ? Math.sin(w.t * 0.5 + t.ph) * 0.22 : 0);
  function lockIn(t){
    t.done = true;
    tuned++;
    streak++; bestStreak = Math.max(bestStreak, streak);
    const pts = 150 + Math.round(Math.max(0, 90 - tuneT * 9)) + Math.min(80, (streak - 1) * 20);
    score += pts; setLive(score);
    snd('success');
    w.pop([t.p[0], t.h + 4, t.p[2]], '+' + pts + ' TUNED', '#9dffc4', { size: 16 });
    fx.explode([t.p[0], t.h, t.p[2]], 2.2, { color: '#39ff88', debris: 0, smoke: 0 });
    tuning = null; holdT = 0; blocked = t;
  }
  function leave(){
    if(!tuning) return;
    blocked = tuning; tuning = null; holdT = 0;
    streak = 0;
    snd('uiBack');
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('freq', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '📻 Towers Tuned': tuned,
      '⛓ Best Streak': bestStreak,
      '📏 Distance': Math.round(me.odo) + ' m',
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, tuned, tuning: !!tuning, f: +dial.f.toFixed(2), a: +dial.a.toFixed(2) }),
    tuneNearest(){
      let best = null, bd = 1e12;
      towers.each(t => { if(t.done) return; const d = V.d2(t.p, me.p); if(d < bd){ bd = d; best = t; } });
      if(!best) return false;
      me.p = [best.p[0] + 6, 0, best.p[2]]; me.speed = 0;
      tuning = best; tuneT = 0; dial.f = tf(best); dial.a = best.a; holdT = HOLD;
      return true;
    }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      elapsed += dt;
      towers.update(me.p);
      if(!tuning){
        driveStep(me, I, dt, hud);
        let inRange = null;
        towers.near(me.p, t => {
          pushOutCircle(me, t.p, 2.6);
          if(!t.done && V.d2(t.p, me.p) < RANGE * RANGE) inRange = t;
        });
        if(blocked && (!inRange || inRange !== blocked)) blocked = null;
        if(inRange && inRange !== blocked && Math.abs(me.speed) < 3.5){
          stillT += dt;
          if(stillT > 0.35){ tuning = inRange; tuneT = 0; holdT = 0; stillT = 0; snd('toggle'); }
        }else stillT = 0;
      }else{
        // Tuning: the rover holds; the stick, the keys or the mouse turn the dials.
        me.speed *= Math.max(0, 1 - 6 * dt);
        tuneT += dt;
        if(I.device === 'mouse' && I.mouseOn){
          dial.f += (F0 + (I.mx + 1) / 2 * (F1 - F0) - dial.f) * Math.min(1, dt * 10);
          dial.a += (A0 + (1 - (I.my + 1) / 2) * (A1 - A0) - dial.a) * Math.min(1, dt * 10);
        }else{
          dial.f = clamp(dial.f + I.lx * 0.9 * dt, F0, F1);
          dial.a = clamp(dial.a - I.ly * 0.45 * dt, A0, A1);
        }
        const ok = Math.abs(dial.f - tf(tuning)) < FTOL && Math.abs(dial.a - tuning.a) < ATOL;
        if(ok){ holdT += dt; if(((holdT * 6) | 0) !== (((holdT - dt) * 6) | 0)) snd('tick', { semi: holdT * 8 }); }
        else holdT = Math.max(0, holdT - dt * 2);
        if(holdT >= HOLD) lockIn(tuning);
        else if(I.boost || I.altHit) leave();
      }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    roverCam(w, me, dt, tuning ? { back: 18, up: 9, ahead: 0, fov: 58 } : { back: 12, up: 6 });
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 8, radius: 200, color: '#0a2a3a', glow: 0.7, major: 6, floor: '#020308', rough: 0.3 });
    const eye = w.cam.eye;
    let nl = 0;
    towers.each(t => {
      if(V.d2(t.p, eye) > 700 * 700) return;
      const col = t.done ? '#39ff88' : t === tuning ? '#ffffff' : '#00f5ff';
      const blink = 0.5 + 0.5 * Math.sin(w.t * 3 + t.ph);
      beacon(w, t.p, col, t.h + 30, t.done ? 0.8 : 0.35 + blink * 0.3);
      if(!r.viewDepth([t.p[0], t.h / 2, t.p[2]], 1.5)) return;
      r.draw('cylinder', { pos: [t.p[0], t.h / 2, t.p[2]], scale: [1.4, t.h, 1.4], color: '#1a2230', metallic: 0.85, roughness: 0.3, rim: 0.7 });
      for(let k = 1; k <= 3; k++) r.draw('torus', { pos: [t.p[0], t.h * k / 4, t.p[2]], scale: 4 - k * 0.7, color: '#2a3446', metallic: 0.8, roughness: 0.3, emissive: col, emissiveStrength: 0.4 });
      r.draw('sphere', { pos: [t.p[0], t.h + 1, t.p[2]], scale: 1.6, color: col, emissive: col, emissiveStrength: 1.5 + blink * 2 });
      // The broadcast: rings swelling off the mast at its own frequency.
      const per = 1 / tf(t);
      for(let k = 0; k < 3; k++){
        const a = ((w.t / per + k / 3) % 1);
        r.draw('thintorus', { pos: [t.p[0], t.h + 1, t.p[2]], scale: [4 + a * 30 * t.a, 1, 4 + a * 30 * t.a], color: col, emissive: col, emissiveStrength: 1.6 * (1 - a) });
      }
      if(!t.done) dotRing(w, t.p, RANGE, col, t === tuning ? 1.2 : 0.55);
      if(nl++ < 3) r.light({ pos: [t.p[0], t.h, t.p[2]], color: col, intensity: 120, range: 40 });
    });
    roverDraw(w, me, colour);
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H, ctx = hud.ctx;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    const rad = [];
    let next = null, nd = 1e12;
    towers.each(t => {
      const d = V.d2(t.p, me.p);
      if(!t.done && d < nd){ nd = d; next = t; }
      if(d < 420 * 420) rad.push({ p: t.p, c: t.done ? '#39ff88' : '#00f5ff', s: 2.8 });
    });
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 320, rad);
    if(tuning){
      // The scope: the tower's wave and yours.
      const pw = Math.min(360, Wd - 40), ph = 96, px = Wd / 2 - pw / 2, py = Ht - ph - 34;
      ctx.fillStyle = 'rgba(3,10,20,0.72)'; ctx.fillRect(px, py, pw, ph);
      ctx.strokeStyle = 'rgba(120,220,255,0.35)'; ctx.strokeRect(px + 0.5, py + 0.5, pw - 1, ph - 1);
      const wave = (f, a, col, dash, wid) => {
        ctx.save(); ctx.beginPath();
        for(let i = 0; i <= 120; i++){
          const x = i / 120, y = py + ph / 2 - Math.sin(x * TAU * f + w.t * 2) * a * (ph / 2 - 8);
          if(i === 0) ctx.moveTo(px + x * pw, y); else ctx.lineTo(px + x * pw, y);
        }
        ctx.strokeStyle = col; ctx.lineWidth = wid; ctx.shadowColor = col; ctx.shadowBlur = 8;
        if(dash) ctx.setLineDash([5, 4]);
        ctx.stroke(); ctx.restore();
      };
      wave(tf(tuning), tuning.a, 'rgba(255,255,255,0.85)', true, 1.6);
      const ok = Math.abs(dial.f - tf(tuning)) < FTOL && Math.abs(dial.a - tuning.a) < ATOL;
      wave(dial.f, dial.a, ok ? '#39ff88' : colour, false, 2.2);
      hud.text(px + 8, py - 10, 'FREQ ' + dial.f.toFixed(2) + '  ·  AMP ' + dial.a.toFixed(2), { size: 11, align: 'left', color: '#bff6ff' });
      hud.text(px + pw - 8, py - 10, ok ? 'LOCKED — HOLD' : 'MATCH THE DASHED WAVE', { size: 11, align: 'right', color: ok ? '#9dffc4' : '#ffd8a0' });
      hud.bar(px, py + ph + 6, pw, 6, holdT / HOLD, '#39ff88');
      hud.text(Wd / 2, 28, tuning.drift ? '📻 DRIFTING SIGNAL — follow it' : '📻 TUNING', { size: 14, color: '#bff6ff' });
    }else if(next){
      const d = Math.sqrt(nd);
      if(!hud.proj(next.p).on) hud.edgeArrow(next.p, '#00f5ff', Math.round(d) + 'm');
      if(d < RANGE) hud.text(Wd / 2, 28, 'STOP TO TUNE', { size: 14, color: '#bff6ff' });
    }
    hud.text(Wd - 16, Ht - 20, '📻 ' + tuned, { size: 14, align: 'right', color: '#9dffc4' });
    if(!tuning) hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.boostE / 100, '#00f5ff', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 56, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  ❄️ COOLANT · OPEN WORLD — CITY MELTDOWN
// ══════════════════════════════════════════════
// The classic flies a shaft on a core that heats while it burns. Out here the
// heat is everywhere: reactors all over a dense city are running away, a few
// at a time. Reach one, stop in its ring and hold to vent it — the hotter it
// was, the more it pays — before it blows and takes a piece of the grid with
// it. Your own core still heats on the burn: boost too long and you stall.
// The blue cells in the street cool you down.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owDrive) return;
const { V, TAU, ihash, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, makeCity, groundRing } = P.owGround;
const { makeRover, driveStep, slideOut, pushOutCircle, roverCam, roverDraw } = P.owDrive;
const { mine, clamp, runLoop, seeded } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const RC = 115, RSEED = 2323, VENT_R = 8;

// Where a reactor-field cell keeps its reactor — a pure function of the cell,
// so the city can leave room for it before either is generated.
function reactorIn(cx, cz){
  const g = seeded(ihash(cx, 0, cz, RSEED));
  if(g() < 0.32 || (cx === 0 && cz === 0)) return null;
  return [(cx + 0.25 + g() * 0.5) * RC, 0, (cz + 0.25 + g() * 0.5) * RC];
}

P.ow.coolant = function(){
  const G = groundBegin({ sky: 'toxic', env: { horizon: '#2a6a8a', zenith: '#020a12' }, fog: { color: '#04121a' }, sun: { color: '#8ad8ff' }, input: { touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: DRIVE · HOLD FIRE IN A RING: VENT · BOOST (HEATS YOU)', 'W/S A/D: DRIVE · SPACE / CLICK HELD IN A REACTOR RING: VENT · SHIFT: BOOST (HEATS YOUR CORE)');

  const me = makeRover({ max: 25 });
  let heat = 0, stall = 0, grid = 3;
  let score = 0, vented = 0, blown = 0, cells = 0, streak = 0, bestStreak = 0, over = false, finished = false, msg = '', msgT = 0, elapsed = 0;
  let venting = null;
  const reactors = makeField({
    cell: RC, dims: 2, seed: RSEED + 1, radius: 620,
    gen(cx, cy, cz, g){
      const items = [];
      const p = reactorIn(cx, cz);
      if(p) items.push({ t: 'reactor', p, heat: 0, on: false, peak: 0, ph: g() * TAU });
      // Coolant cells along the streets.
      const n = Math.floor(g() * 3);
      for(let i = 0; i < n; i++) items.push({ t: 'cell', p: [(cx + g()) * RC, 0.9, (cz + g()) * RC], ph: g() * TAU });
      return items;
    }
  });
  const city = makeCity({
    seed: 1919, density: 0.5, cell: 62, clear: 45, hMin: 14, hMax: 75, radius: 640, towerColor: '#0a1218',
    skip(x, z){
      const cx = Math.floor(x / RC), cz = Math.floor(z / RC);
      for(let dx = -1; dx <= 1; dx++) for(let dz = -1; dz <= 1; dz++){
        const p = reactorIn(cx + dx, cz + dz);
        if(p && Math.hypot(p[0] - x, p[2] - z) < 26) return true;
      }
      return false;
    }
  });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#00f5ff,#46c8ff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };
  const heatCol = h => h > 75 ? '#ff3a2a' : h > 50 ? '#ff8a2a' : h > 25 ? '#ffd27a' : '#7fe8ff';

  function activate(){
    const cand = [];
    reactors.each(it => { if(it.t === 'reactor' && !it.on){ const d = V.d2(it.p, me.p); if(d > 50 * 50 && d < 280 * 280) cand.push(it); } });
    if(!cand.length) return;
    const it = cand[(Math.random() * cand.length) | 0];
    it.on = true; it.heat = rr(18, 45); it.rate = rr(2.2, 3.4) * Math.min(1.5, diff) * (1 + Math.min(0.5, elapsed / 240));
    snd('alarm');
  }
  function ventDone(it){
    it.on = false;
    vented++;
    streak++; bestStreak = Math.max(bestStreak, streak);
    const pts = 40 + Math.round(it.peak * 0.8) + Math.min(60, (streak - 1) * 10);
    score += pts; setLive(score);
    snd('success');
    w.pop([it.p[0], 10, it.p[2]], '+' + pts + ' VENTED', '#9ff0ff', { size: 15 });
    for(let k = 0; k < 8; k++) fx.puff([it.p[0] + rr(-2, 2), 8, it.p[2] + rr(-2, 2)], '#d8f4ff', 2.6, 2, [rr(-1, 1), rr(5, 9), rr(-1, 1)]);
    venting = null;
  }
  function blow(it){
    it.on = false;
    reactors.kill(it);
    blown++;
    streak = 0;
    grid--;
    fx.explode([it.p[0], 4, it.p[2]], 7, { color: '#ff6a2a', debrisGeo: 'slab', debrisColor: '#2a2a30', ringNormal: [0, 1, 0] });
    snd('bigExplode');
    w.kick(2);
    say('💥 REACTOR LOST — grid ' + Math.max(0, grid) + '/3', 2.4);
    if(V.d2(it.p, me.p) < 26 * 26){ me.speed = 0; me.inv = 1.2; me.hit = 0.4; }
    if(venting === it) venting = null;
    bar.style.width = (Math.max(0, grid) / 3 * 100) + '%';
    if(grid <= 0){
      if(survivedFatal()){ grid = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); return; }
      over = true;
      gLater(() => finish('meltdown'), 1400);
    }
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('coolant', score, {
      '📡 Shift': why === 'clock' ? 'CLOCK EXPIRED' : 'GRID MELTDOWN',
      '❄️ Reactors Vented': vented,
      '💥 Reactors Lost': blown,
      '🧊 Coolant Cells': cells,
      '⛓ Best Streak': bestStreak,
      '🏆 Score': score + ' PTS'
    });
  }
  const active = () => { const a = []; reactors.each(it => { if(it.t === 'reactor' && it.on) a.push(it); }); return a; };
  P.owDebug = {
    state: () => ({ score, vented, blown, grid, heat: Math.round(heat), active: active().length, venting: !!venting }),
    lose(){ if(!active().length) activate(); const a = active()[0]; if(a) blow(a); else{ grid--; if(grid <= 0){ over = true; gLater(() => finish('meltdown'), 1400); } } },
    ventNearest(){ const a = active().sort((x, y) => V.d2(x.p, me.p) - V.d2(y.p, me.p))[0]; if(a){ a.peak = a.heat; ventDone(a); } return !!a; },
    blowNearest(){ const a = active()[0]; if(a) blow(a); return !!a; }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      elapsed += dt;
      stall = Math.max(0, stall - dt);
      const thr = driveStep(me, stall > 0 ? { ax: I.ax, ly: 0, boost: false, device: I.device } : I, dt, hud, { noBoost: stall > 0 });
      if(stall > 0) me.speed *= Math.max(0, 1 - 3 * dt);
      heat = clamp(heat + (me.boosting ? 30 : -11) * dt + (venting ? 8 * dt : 0), 0, 100);
      if(heat >= 100 && stall <= 0){ stall = 2.5; heat = 60; snd('glitch'); say('🔥 CORE STALL — coast to cool', 2); w.kick(0.8); }
      reactors.update(me.p);
      city.update(me.p);
      if(slideOut(me, city, 1.2) && me.inv <= 0){ me.hit = 0.2; snd('bounceWall'); }
      // Venting: stopped in a ring, fire held.
      let ring = null;
      reactors.near(me.p, it => {
        if(it.t === 'reactor'){
          pushOutCircle(me, it.p, 3.4);
          if(it.on && V.d2(it.p, me.p) < VENT_R * VENT_R) ring = it;
        }else if(V.d2(it.p, me.p) < 2.4 * 2.4){
          reactors.kill(it); cells++; heat = Math.max(0, heat - 45); score += 10; setLive(score);
          snd('freeze'); fx.glowPop(it.p, '#7fe8ff', 2, 0.35);
        }
      });
      if(ring && I.fire && Math.abs(me.speed) < 7 && stall <= 0){
        if(venting !== ring){ venting = ring; ring.peak = ring.heat; snd('charge'); }
        ring.heat -= 42 * dt;
        if(Math.random() < dt * 14) fx.puff([ring.p[0] + rr(-1.5, 1.5), 7, ring.p[2] + rr(-1.5, 1.5)], '#e0f6ff', 1.6, 1.4, [rr(-1, 1), rr(6, 10), rr(-1, 1)]);
        if(ring.heat <= 0){ ring.heat = 0; ventDone(ring); }
      }else venting = null;
      // The rest run away.
      const act = active();
      for(const it of act){
        if(it === venting) continue;
        it.heat += it.rate * dt;
        if(it.heat >= 100) blow(it);
      }
      const want = Math.min(6, 3 + Math.floor(elapsed / 35));
      if(act.length < want && Math.random() < dt * 1.5) activate();
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    roverCam(w, me, dt, { back: 12, up: 7 });
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 170, color: '#0f4a5a', glow: 0.8, major: 6, floor: '#020a0e', rough: 0.25 });
    city.draw(w);
    const eye = w.cam.eye;
    let nl = 0;
    reactors.each(it => {
      if(V.d2(it.p, eye) > 420 * 420) return;
      if(it.t === 'cell'){
        if(!r.viewDepth(it.p, 1.2)) return;
        const y = 0.9 + Math.sin(w.t * 3 + it.ph) * 0.2;
        r.draw('pill', { pos: [it.p[0], y, it.p[2]], rot: [0, w.t, 0.4], scale: [0.7, 1.2, 0.7], color: '#7fe8ff', emissive: '#46c8ff', emissiveStrength: 1.6 });
        r.glow([it.p[0], y, it.p[2]], 1.4, '#7fe8ff', 0.6);
        return;
      }
      if(!r.viewDepth([it.p[0], 5, it.p[2]], 1.4)) return;
      const h = it.on ? it.heat : 0, col = it.on ? heatCol(h) : '#3a5a6a';
      const shake = h > 80 ? Math.sin(w.t * 60) * 0.12 * (h - 80) / 20 : 0;
      r.draw('cylinder', { pos: [it.p[0], 2.5, it.p[2]], scale: [6, 5, 6], color: '#1e2630', metallic: 0.8, roughness: 0.35, rim: 0.6 });
      r.draw('core', { pos: [it.p[0] + shake, 7, it.p[2]], rot: [0, w.t * (it.on ? 0.5 + h / 40 : 0.2), 0], scale: 3.2, color: '#8a96a8', metallic: 0.5, roughness: 0.3,
                       emissive: col, emissiveStrength: it.on ? 0.6 + h / 40 : 0.2 });
      for(const s of [-1, 1]) r.draw('cylinder', { pos: [it.p[0] + s * 4.2, 4, it.p[2]], scale: [1.6, 8, 1.6], color: '#2a3440', metallic: 0.7, roughness: 0.4 });
      if(it.on){
        r.glow([it.p[0], 7, it.p[2]], 4 + h / 25, col, 0.5 + h / 80);
        groundRing(w, it.p, VENT_R, col, it === venting ? 1.6 : 0.8);
        if(h > 60 && Math.random() < 0.3) fx.puff([it.p[0], 10, it.p[2]], '#3a3a40', 1.6, 1.6, [rr(-1, 1), 4, rr(-1, 1)]);
        if(nl++ < 3) r.light({ pos: [it.p[0], 9, it.p[2]], color: col, intensity: 80 + h * 1.5, range: 26 });
      }
    });
    roverDraw(w, me, colour, { color: stall > 0 ? '#ff9a7a' : undefined });
    if(me.boosting || heat > 70) r.glow([me.p[0], 1.4, me.p[2]], 1.6 + heat / 50, heatCol(heat), 0.5);
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    const act = active();
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 220, act.map(it => ({ p: it.p, c: heatCol(it.heat), s: 3 })));
    const near = act.sort((a, b) => V.d2(a.p, me.p) - V.d2(b.p, me.p)).slice(0, 4);
    for(const it of near){
      const q = hud.proj([it.p[0], 9, it.p[2]]);
      if(q.on) hud.bracket([it.p[0], 9, it.p[2]], 5, heatCol(it.heat), Math.round(it.heat) + '%', { dist: Math.sqrt(V.d2(it.p, me.p)), alpha: 0.85 });
      else hud.edgeArrow(it.p, heatCol(it.heat), Math.round(it.heat) + '%');
    }
    if(venting) hud.text(Wd / 2, 28, '❄ VENTING ' + Math.round(venting.heat) + '%', { size: 15, color: '#bff6ff' });
    else if(stall > 0) hud.text(Wd / 2, 28, '🔥 STALLED', { size: 15, color: '#ff8a6a' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, heat / 100, heatCol(heat), 'YOUR CORE HEAT');
    hud.text(Wd - 16, Ht - 40, '❄ ' + vented, { size: 13, align: 'right', color: '#bff6ff' });
    hud.text(Wd - 16, Ht - 20, 'GRID ' + '▮'.repeat(Math.max(0, grid)) + '▯'.repeat(Math.max(0, 3 - grid)), { size: 13, align: 'right', color: grid > 1 ? '#9dffc4' : '#ff8a8a' });
    if(msgT > 0) hud.text(Wd / 2, 56, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  📦 PACKET SORT · OPEN WORLD — THE HAUL ROUTE
// ══════════════════════════════════════════════
// The classic drags packets into ports while the sorting rule flips every
// twenty seconds. Out here the packets lie scattered across the plain and the
// ports are towers, each with a colour AND a shape: scoop up to three, haul
// them to the tower the rule says, and every one that fits is taken. The rule
// still flips — by colour, by shape, or shifted one colour along — and the
// strip at the top always says which.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owDrive) return;
const { V, TAU, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, groundRing, beacon, makeCity } = P.owGround;
const { makeRover, driveStep, slideOut, pushOutCircle, roverCam, roverDraw } = P.owDrive;
const { mine, clamp, runLoop } = P.kit;
const COLS = ['#ff2d9a', '#ffd700', '#39ff88', '#00f5ff'];
const SHAPES = [{ geo: 'cube', g: '■', s: 1 }, { geo: 'sphere', g: '●', s: 1.1 }, { geo: 'cone', g: '▲', s: 1.3 }, { geo: 'pill', g: '⬬', s: 1.1 }];
const RULES = ['colour', 'shape', 'shift'];
const RULE_TXT = { colour: 'BY COLOUR', shape: 'BY SHAPE', shift: 'COLOUR, SHIFTED ONE →' };
const PC = 130, CAP = 3, PORT_R = 9, FLIP = 20;
const mod = (a, n) => ((a % n) + n) % n;

P.ow.sorter = function(){
  const G = groundBegin({ sky: 'dusk', input: { touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  setControlHint('STICK: DRIVE OVER PACKETS, THEN INTO THE RIGHT PORT', 'W/S A/D or HOLD THE MOUSE: DRIVE · SCOOP PACKETS, DELIVER AT THE PORT THE RULE NAMES · SHIFT: BOOST');

  const me = makeRover({ max: 26 });
  let score = 0, delivered = 0, drops = 0, bestDrop = 0, over = false, finished = false, msg = '', msgT = 0;
  let ruleI = 0, ruleT = FLIP, carry = [], elapsed = 0, inPort = null;
  const ports = makeField({
    cell: PC, dims: 2, seed: 3131, radius: 760,
    gen(cx, cy, cz, g){
      return [{ t: 'port', p: [(cx + 0.3 + g() * 0.4) * PC, 0, (cz + 0.3 + g() * 0.4) * PC], c: mod(cx * 3 + cz * 5, 4), s: mod(cx * 5 + cz * 3 + 1, 4), ph: g() * TAU }];
    }
  });
  const packets = makeField({
    cell: 44, dims: 2, seed: 3232, radius: 360,
    gen(cx, cy, cz, g){
      const items = [];
      const n = Math.floor(g() * 3.2);
      for(let i = 0; i < n; i++) items.push({ p: [(cx + g()) * 44, 0, (cz + g()) * 44], c: (g() * 4) | 0, s: (g() * 4) | 0, ph: g() * TAU });
      return items;
    }
  });
  const city = makeCity({ seed: 3333, density: 0.12, cell: 110, clear: 70, hMin: 20, hMax: 60, radius: 700, towerColor: '#120a14',
                          skip(x, z){ const cx = Math.floor(x / PC), cz = Math.floor(z / PC); return Math.abs(x - (cx + 0.5) * PC) < 40 && Math.abs(z - (cz + 0.5) * PC) < 40; } });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ff2d9a,#ffd700,#39ff88,#00f5ff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  const rule = () => RULES[ruleI];
  const fits = (pk, port) => rule() === 'colour' ? pk.c === port.c : rule() === 'shape' ? pk.s === port.s : mod(pk.c + 1, 4) === port.c;
  function deliver(port){
    const keep = [], took = [];
    for(const pk of carry) (fits(pk, port) ? took : keep).push(pk);
    if(!took.length){ snd('deny'); say('NONE OF YOURS FIT THIS PORT — ' + RULE_TXT[rule()], 1.8); return; }
    carry = keep;
    delivered += took.length;
    drops++;
    bestDrop = Math.max(bestDrop, took.length);
    const pts = took.length * 30 + (took.length - 1) * 15;
    score += pts; setLive(score);
    snd(took.length > 1 ? 'combo' : 'score');
    w.pop([port.p[0], 14, port.p[2]], '+' + pts + (took.length > 1 ? ' ×' + took.length : ''), COLS[port.c], { size: 16 });
    for(const pk of took) fx.glowPop([port.p[0], 9, port.p[2]], COLS[pk.c], 2.2, 0.4);
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('sorter', score, {
      '📡 Shift': why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '📦 Packets Delivered': delivered,
      '🚚 Drops': drops,
      '🏅 Best Drop': bestDrop + ' at once',
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, delivered, carry: carry.length, rule: rule(), ruleT: Math.round(ruleT) }),
    deliverNow(){
      let port = null, bd = 1e12;
      ports.each(pt => { const d = V.d2(pt.p, me.p); if(d < bd){ bd = d; port = pt; } });
      if(!port) return false;
      const c = rule() === 'shift' ? mod(port.c - 1, 4) : port.c;
      carry = [{ c, s: port.s }, { c, s: port.s }, { c: mod(c + 2, 4), s: mod(port.s + 2, 4) }];
      deliver(port);
      return true;
    },
    flip(){ ruleT = 0.01; }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      elapsed += dt;
      ruleT -= dt;
      if(ruleT <= 0){
        ruleT = FLIP;
        let n = ruleI;
        while(n === ruleI) n = (Math.random() * RULES.length) | 0;
        ruleI = n;
        snd('alarm');
        say('🔁 RULE FLIP — ' + RULE_TXT[rule()], 2.4);
      }
      driveStep(me, I, dt, hud);
      ports.update(me.p);
      packets.update(me.p);
      city.update(me.p);
      if(slideOut(me, city, 1.2)) me.hit = 0.15;
      let port = null;
      ports.near(me.p, pt => {
        pushOutCircle(me, pt.p, 3.6);
        if(V.d2(pt.p, me.p) < PORT_R * PORT_R) port = pt;
      });
      if(port && port !== inPort && carry.length) deliver(port);
      inPort = port;
      if(carry.length < CAP){
        packets.near(me.p, pk => {
          if(carry.length >= CAP || V.d2(pk.p, me.p) > 2.6 * 2.6) return;
          packets.kill(pk);
          carry.push({ c: pk.c, s: pk.s });
          snd('pickup');
          fx.glowPop([pk.p[0], 1, pk.p[2]], COLS[pk.c], 1.4, 0.25);
          if(carry.length === CAP) say('HOLD FULL — find a port', 1.4);
        });
      }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    roverCam(w, me, dt, { back: 12, up: 6.5 });
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 170, color: '#4a1a40', glow: 0.85, major: 5, floor: '#08040a', rough: 0.25 });
    city.draw(w);
    const eye = w.cam.eye;
    let nl = 0;
    ports.each(pt => {
      if(V.d2(pt.p, eye) > 650 * 650) return;
      const col = COLS[pt.c], S = SHAPES[pt.s];
      const any = carry.some(pk => fits(pk, pt));
      beacon(w, pt.p, col, 70, any ? 1 : 0.35);
      if(!r.viewDepth([pt.p[0], 6, pt.p[2]], 1.4)) return;
      r.draw('techblock', { pos: [pt.p[0], 3, pt.p[2]], scale: [5, 6, 5], color: '#1a1a26', metallic: 0.7, roughness: 0.35, emissive: col, emissiveStrength: 0.15 });
      r.draw(S.geo, { pos: [pt.p[0], 9.5 + Math.sin(w.t * 2 + pt.ph) * 0.4, pt.p[2]], rot: [0, w.t, 0], scale: S.s * 2.6, color: col, emissive: col, emissiveStrength: 1.4 });
      groundRing(w, pt.p, PORT_R, col, any ? 1.3 : 0.5);
      if(nl++ < 3) r.light({ pos: [pt.p[0], 10, pt.p[2]], color: col, intensity: 90, range: 24 });
    });
    packets.each(pk => {
      if(V.d2(pk.p, eye) > 170 * 170 || !r.viewDepth(pk.p, 1.2)) return;
      const y = 0.9 + Math.sin(w.t * 3 + pk.ph) * 0.2, S = SHAPES[pk.s];
      r.draw(S.geo, { pos: [pk.p[0], y, pk.p[2]], rot: [0, w.t * 1.3 + pk.ph, 0], scale: S.s * 0.9, color: COLS[pk.c], emissive: COLS[pk.c], emissiveStrength: 1.3 });
    });
    roverDraw(w, me, colour);
    // The load, stacked over the rover.
    carry.forEach((pk, i) => {
      const S = SHAPES[pk.s];
      r.draw(S.geo, { pos: [me.p[0], 2.6 + i * 1.3, me.p[2]], rot: [0, w.t * 2, 0], scale: S.s * 0.75, color: COLS[pk.c], emissive: COLS[pk.c], emissiveStrength: 1.5 });
    });
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    const rad = [];
    ports.each(pt => { if(V.d2(pt.p, me.p) < 380 * 380) rad.push({ p: pt.p, c: COLS[pt.c], s: 3.4, shape: 'diamond' }); });
    packets.each(pk => { if(V.d2(pk.p, me.p) < 120 * 120) rad.push({ p: pk.p, c: COLS[pk.c], s: 1.5 }); });
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 260, rad);
    hud.text(Wd / 2, 26, 'RULE: ' + RULE_TXT[rule()] + '  ·  flips in ' + Math.ceil(ruleT) + 's', { size: 14, color: ruleT < 4 ? '#ffd27a' : '#ffffff' });
    // Where the load can go.
    if(carry.length){
      let best = null, bd = 1e12;
      ports.each(pt => { if(!carry.some(pk => fits(pk, pt))) return; const d = V.d2(pt.p, me.p); if(d < bd){ bd = d; best = pt; } });
      if(best && !hud.proj([best.p[0], 9, best.p[2]]).on) hud.edgeArrow(best.p, COLS[best.c], SHAPES[best.s].g);
    }
    let x = Wd - 16;
    for(let i = CAP - 1; i >= 0; i--){
      const pk = carry[i];
      hud.text(x, Ht - 22, pk ? SHAPES[pk.s].g : '·', { size: 18, align: 'right', color: pk ? COLS[pk.c] : '#3a4a5a' });
      x -= 24;
    }
    hud.text(Wd - 16, Ht - 46, '📦 ' + delivered, { size: 13, align: 'right', color: '#ffe8b0' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.boostE / 100, '#ffd700', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 52, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  📡 SIGNAL TRACE · OPEN WORLD — THE FOX HUNT
// ══════════════════════════════════════════════
// The classic deduces a hidden cipher from probes that answer "warmer" in
// pegs. Out here the hidden thing is a transmitter somewhere on a dusk plain,
// and the deduction is the same: a signal meter, a bearing needle that only
// settles when you stop and listen, and a handful of PROBES — each one a
// clean fix on its direction and its range, and there are never enough. Run
// it down, and the next one starts transmitting.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owDrive) return;
const { V, TAU, wrapAng, drawFloor, owClock } = P.owKit;
const { groundBegin, makeCity, groundRing } = P.owGround;
const { makeRover, driveStep, slideOut, roverCam, roverDraw } = P.owDrive;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const PROBES = 6, FOUND = 7, HEAR = 440;

P.ow.trace = function(){
  const G = groundBegin({ sky: 'dusk', env: { horizon: '#6a2a5a' }, input: { touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  setControlHint('STICK: DRIVE · ALT: PROBE · STOP TO STEADY THE NEEDLE', 'W/S A/D or HOLD THE MOUSE: DRIVE · F / RIGHT-CLICK: PROBE · STOP TO STEADY THE NEEDLE · SHIFT: BOOST');
  inp.altLabel = 'PROBE';

  const me = makeRover({ max: 27 });
  let score = 0, found = 0, probesUsed = 0, over = false, finished = false, msg = '', msgT = 0;
  let tx = null, huntT = 0, probes = PROBES, steady = 0, needle = 0, needleT = 0, sig = 0, probeT = 0, probeBand = '', tickT = 0;
  const city = makeCity({ seed: 4141, density: 0.16, cell: 100, clear: 60, hMin: 16, hMax: 70, radius: 720, towerColor: '#140814' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ff5ab4,#ffd27a)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  function hide(){
    for(let k = 0; k < 40; k++){
      const a = Math.random() * TAU, d = rr(170, 320);
      const p = [me.p[0] + Math.cos(a) * d, 0, me.p[2] + Math.sin(a) * d];
      city.update(p);
      if(!city.hit(p, 6)){ tx = { p, ph: Math.random() * TAU }; break; }
    }
    if(!tx) tx = { p: [me.p[0] + 200, 0, me.p[2]], ph: 0 };
    huntT = 0; probes = PROBES; probeT = 0;
    snd('glitch');
    say('📡 A NEW TRANSMITTER IS ON THE AIR', 2.2);
  }
  hide();
  const band = d => d < 25 ? 'BURNING' : d < 70 ? 'HOT' : d < 150 ? 'WARM' : d < 260 ? 'COOL' : 'COLD';
  function probe(){
    if(probes <= 0){ snd('deny'); say('NO PROBES LEFT — trust the needle', 1.6); return; }
    probes--; probesUsed++;
    probeT = 2.6;
    probeBand = band(Math.sqrt(V.d2(tx.p, me.p)));
    snd('node');
    fx.flash([me.p[0], 2, me.p[2]], '#ffd27a', 1.4, 0.2);
  }
  function caught(){
    found++;
    const pts = 150 + Math.round(Math.max(0, 150 - huntT * 4)) + probes * 20;
    score += pts; setLive(score);
    snd('success');
    fx.explode([tx.p[0], 3, tx.p[2]], 2.6, { color: '#ffd27a', debris: 4 });
    w.pop([tx.p[0], 8, tx.p[2]], '+' + pts + ' FOUND', '#ffd27a', { size: 16 });
    tx = null;
    gLater(() => { if(!over) hide(); }, 900);
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('trace', score, {
      '📡 Hunt': why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '🦊 Transmitters Found': found,
      '🔎 Probes Spent': probesUsed,
      '📏 Distance': Math.round(me.odo) + ' m',
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, found, probes, sig: Math.round(sig * 100), dist: tx ? Math.round(Math.sqrt(V.d2(tx.p, me.p))) : null }),
    probe(){ if(tx) probe(); },
    findNow(){ if(tx){ me.p = [tx.p[0] + 3, 0, tx.p[2]]; caught(); return true; } return false; }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      driveStep(me, I, dt, hud);
      city.update(me.p);
      if(slideOut(me, city, 1.2)) me.hit = 0.15;
      probeT = Math.max(0, probeT - dt);
      if(tx){
        huntT += dt;
        if(I.altHit) probe();
        const d = Math.sqrt(V.d2(tx.p, me.p));
        // Listening: the needle and the meter settle while you hold still.
        steady = clamp(steady + (Math.abs(me.speed) < 3 ? dt * 1.2 : -dt * 2), 0, 1);
        const truth = clamp(1 - d / HEAR, 0, 1);
        sig += (truth + (Math.random() - 0.5) * 0.25 * (1 - steady) - sig) * Math.min(1, dt * 4);
        needleT -= dt;
        if(needleT <= 0){
          needleT = 0.18;
          const bearing = Math.atan2(-(tx.p[0] - me.p[0]), -(tx.p[2] - me.p[2]));
          const noise = (0.25 + 1.1 * (1 - truth)) * (1 - steady * 0.8) * (probeT > 0 ? 0 : 1);
          const goal = wrapAng(bearing - me.yaw + rr(-noise, noise));
          needle = wrapAng(needle + wrapAng(goal - needle) * 0.5);
        }
        tickT -= dt;
        if(tickT <= 0){ tickT = 0.12 + (1 - truth) * 1.1; snd('tick', { semi: truth * 12 }); }
        if(d < FOUND) caught();
      }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    roverCam(w, me, dt, { back: 12, up: 6 });
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 170, color: '#5a1a4a', glow: 0.8, major: 5, floor: '#0a040a', rough: 0.25 });
    city.draw(w);
    if(tx){
      const d = Math.sqrt(V.d2(tx.p, w.cam.eye));
      if(d < 60){
        // Close enough to see: a mast and its dish, pulsing.
        const k = clamp(1 - d / 60, 0, 1);
        r.draw('cylinder', { pos: [tx.p[0], 2.5, tx.p[2]], scale: [0.6, 5, 0.6], color: '#2a2a36', metallic: 0.8, roughness: 0.3 });
        r.draw('turret', { pos: [tx.p[0], 5.4, tx.p[2]], rot: [0, w.t * 0.7, 0], scale: 1.2, color: '#9a8aa8', metallic: 0.6, roughness: 0.3, emissive: '#ffd27a', emissiveStrength: 0.6 * k });
        r.glow([tx.p[0], 6, tx.p[2]], 2 + Math.sin(w.t * 8) * 0.5, '#ffd27a', 1.2 * k);
        groundRing(w, tx.p, FOUND, '#ffd27a', k);
      }
      if(probeT > 0){
        // The probe's fix: a line along the ground toward it, fading.
        const dir = V.norm([tx.p[0] - me.p[0], 0, tx.p[2] - me.p[2]]);
        const a = probeT / 2.6;
        for(let i = 1; i <= 8; i++) r.glowFx(V.add(V.madd(me.p, dir, i * 6), [0, 0.4, 0]), 0.9, '#ffd27a', 1.6 * a);
        r.streak(V.add(me.p, [0, 0.4, 0]), V.add(V.madd(me.p, dir, 50), [0, 0.4, 0]), 0.35, '#ffd27a', 1.6 * a, 0.2);
      }
    }
    roverDraw(w, me, colour);
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H, ctx = hud.ctx;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 200, probeT > 0 && tx ? [{ p: tx.p, c: '#ffd27a', s: 3 }] : []);
    // The direction finder: a dial at the top, the needle relative to the nose.
    const cx = Wd / 2, cy = 58, R = 38;
    ctx.save();
    ctx.globalAlpha = 0.9;
    ctx.fillStyle = 'rgba(10,4,14,0.6)'; ctx.beginPath(); ctx.arc(cx, cy, R, 0, TAU); ctx.fill();
    ctx.strokeStyle = 'rgba(255,180,220,0.5)'; ctx.lineWidth = 1.2; ctx.beginPath(); ctx.arc(cx, cy, R, 0, TAU); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx, cy - R); ctx.lineTo(cx, cy - R + 6); ctx.stroke();
    const na = -needle - Math.PI / 2;
    ctx.strokeStyle = probeT > 0 ? '#ffd27a' : '#ff5ab4'; ctx.shadowColor = ctx.strokeStyle; ctx.shadowBlur = 8; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + Math.cos(na) * (R - 6), cy + Math.sin(na) * (R - 6)); ctx.stroke();
    ctx.restore();
    hud.text(cx, cy + R + 12, steady > 0.8 ? 'STEADY' : 'LISTENING…', { size: 9, color: steady > 0.8 ? '#9dffc4' : '#ffb8d8' });
    hud.bar(cx + R + 16, cy - 4, 120, 8, sig, '#ff5ab4', 'SIGNAL');
    if(probeT > 0) hud.text(cx - R - 16, cy, probeBand, { size: 15, align: 'right', color: '#ffd27a' });
    hud.text(Wd - 16, Ht - 40, 'PROBES ' + '●'.repeat(probes) + '○'.repeat(Math.max(0, PROBES - probes)), { size: 12, align: 'right', color: '#ffd27a' });
    hud.text(Wd - 16, Ht - 20, '🦊 ' + found + '  ·  ' + Math.round(huntT) + 's', { size: 13, align: 'right', color: '#ffe8b0' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.boostE / 100, '#ff5ab4', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 118, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🔓 NODE HACKER · OPEN WORLD — THE SEQUENCE RUN
// ══════════════════════════════════════════════
// The classic pulses a sequence on a keypad and asks for it back. Here every
// mainframe is a ring of network nodes standing out on the grid: watch them
// light in order, then DRIVE the sequence — into each node's ring in turn —
// before the trace closes on you. A wrong node feeds the trace; a finished
// sequence hacks the mainframe, and the next one is a step longer.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owDrive) return;
const { V, TAU, drawFloor, owClock } = P.owKit;
const { groundBegin, groundRing, beacon, makeCity } = P.owGround;
const { makeRover, driveStep, slideOut, pushOutCircle, roverCam, roverDraw } = P.owDrive;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const NODE_COLS = ['#00f5ff', '#ff2d9a', '#ffd700', '#39ff88'];
const GLYPHS = 'ABCDEFGH';
const RING = 5.2, ON = 0.62, GAP = 0.26;

P.ow.hacker = function(){
  const G = groundBegin({ sky: 'night', env: { horizon: '#103a3a' }, input: { touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: DRIVE · WATCH, THEN DRIVE THROUGH THE NODES IN ORDER · ALT: REPLAY', 'W/S A/D or HOLD THE MOUSE: DRIVE · WATCH THE PULSE, THEN DRIVE INTO THE NODES IN ORDER · F: SHOW IT AGAIN (+TRACE)');
  inp.altLabel = 'SHOW';

  const me = makeRover({ max: 25 });
  let score = 0, hacked = 0, traced = 0, wrongs = 0, bestLen = 0, over = false, finished = false, msg = '', msgT = 0;
  let len = 3, nodes = [], seq = [], phase = 'show', showT = 0, step = 0, trace = 0, inside = null, flash = null, flashT = 0;
  const city = makeCity({ seed: 5252, density: 0.1, cell: 130, clear: 150, hMin: 20, hMax: 60, radius: 760, towerColor: '#061212' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '0%';
  bar.style.background = 'linear-gradient(90deg,#39ff88,#ffd700,#ff2d6a)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  function mainframe(){
    // A ring of eight nodes ahead of the rover.
    const f = [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)];
    const c = V.madd(me.p, f, 55);
    const a0 = Math.random() * TAU;
    nodes = [];
    for(let i = 0; i < 8; i++){
      const a = a0 + i / 8 * TAU + rr(-0.2, 0.2), d = rr(22, 40);
      const p = [c[0] + Math.cos(a) * d, 0, c[2] + Math.sin(a) * d];
      city.update(p);
      if(city.hit(p, 4)) p[0] += 12;
      nodes.push({ p, col: NODE_COLS[i % 4], g: GLYPHS[i], lit: 0 });
    }
    seq = [];
    while(seq.length < len){
      const n = (Math.random() * 8) | 0;
      if(seq.length && seq[seq.length - 1] === n) continue;
      seq.push(n);
    }
    step = 0; trace = 0; inside = null;
    startShow();
  }
  function startShow(){ phase = 'show'; showT = 0; snd('wave'); }
  function enter(i){
    if(phase !== 'replay') return;
    const n = nodes[i];
    if(i === seq[step]){
      step++;
      n.lit = 0.5;
      snd('node', { semi: i * 2 });
      fx.sparks([n.p[0], 5, n.p[2]], 8, n.col, 1, 10);
      if(step >= seq.length) win();
    }else{
      wrongs++;
      trace += 22;
      flash = n; flashT = 0.5;
      snd('wrong');
      w.kick(0.5);
      say('✖ WRONG NODE — the trace jumps', 1.4);
    }
  }
  function win(){
    hacked++;
    bestLen = Math.max(bestLen, len);
    const pts = 40 * len + Math.round((100 - trace) * 1.5);
    score += pts; setLive(score);
    snd('success');
    for(const n of nodes) fx.explode([n.p[0], 5, n.p[2]], 1.2, { color: n.col, debris: 0, smoke: 0 });
    say('🔓 MAINFRAME HACKED +' + pts + ' — the next is ' + (len + 1) + ' long', 2.4);
    len++;
    phase = 'done';
    gLater(() => { if(!over) mainframe(); }, 1300);
  }
  function caught(){
    traced++;
    snd('alarm');
    w.kick(1);
    say('🚨 TRACED — mainframe locked out', 2.2);
    len = Math.max(3, len - 1);
    phase = 'done';
    gLater(() => { if(!over) mainframe(); }, 1500);
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('hacker', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '🔓 Mainframes Hacked': hacked,
      '🧬 Longest Sequence': bestLen,
      '🚨 Traced': traced,
      '✖ Wrong Nodes': wrongs,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, hacked, traced, phase, step, len, trace: Math.round(trace) }),
    skipShow(){ if(phase === 'show') showT = 1e3; },
    replayCorrect(){ if(phase === 'show') showT = 1e3; phase = 'replay'; for(const i of seq.slice(step)) enter(i); },
    wrongNode(){ if(phase !== 'replay') return; const i = (seq[step] + 1) % 8; enter(i); }
  };
  mainframe();

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      driveStep(me, I, dt, hud);
      city.update(me.p);
      if(slideOut(me, city, 1.2)) me.hit = 0.15;
      if(phase === 'show'){
        showT += dt;
        const per = ON + GAP, k = Math.floor(showT / per);
        if(k < seq.length){
          const n = nodes[seq[k]];
          const on = showT - k * per < ON;
          if(on && n.lit <= 0){ snd('node', { semi: seq[k] * 2 }); }
          n.lit = on ? 0.12 : 0;
        }else{ phase = 'replay'; snd('go'); }
      }else if(phase === 'replay'){
        trace += 100 / (18 + len * 4) * Math.min(1.4, diff) * dt;
        if(I.altHit){ trace += 18; startShow(); }
        if(trace >= 100) caught();
      }
      let here = null;
      nodes.forEach((n, i) => {
        pushOutCircle(me, n.p, 1.9);
        if(V.d2(n.p, me.p) < RING * RING) here = i;
      });
      if(here != null && here !== inside) enter(here);
      inside = here;
      bar.style.width = clamp(trace, 0, 100) + '%';
    }
    for(const n of nodes) n.lit = Math.max(0, n.lit - dt);
    flashT = Math.max(0, flashT - dt);
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    roverCam(w, me, dt, phase === 'show' ? { back: 22, up: 18, ahead: 26, fov: 62 } : { back: 13, up: 8 });
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 170, color: '#0f5a4a', glow: 0.85, major: 5, floor: '#020a08', rough: 0.25 });
    city.draw(w);
    let nl = 0;
    nodes.forEach((n, i) => {
      const lit = n.lit > 0 || (flash === n && flashT > 0);
      const col = flash === n && flashT > 0 ? '#ff3a3a' : n.col;
      const doneHere = phase === 'replay' && seq.slice(0, step).includes(i);
      r.draw('cylinder', { pos: [n.p[0], 2, n.p[2]], scale: [2.4, 4, 2.4], color: '#14201e', metallic: 0.8, roughness: 0.3, emissive: col, emissiveStrength: lit ? 0.6 : 0.05 });
      r.draw('sphere', { pos: [n.p[0], 5, n.p[2]], scale: lit ? 2.4 : 1.5, color: col, emissive: col, emissiveStrength: lit ? 3.4 : doneHere ? 1.2 : 0.5 });
      groundRing(w, n.p, RING, col, lit ? 1.6 : 0.4);
      if(lit){
        beacon(w, n.p, col, 50, 1.4);
        r.glow([n.p[0], 5, n.p[2]], 5, col, 1.4);
        if(nl++ < 2) r.light({ pos: [n.p[0], 7, n.p[2]], color: col, intensity: 200, range: 30 });
      }
    });
    roverDraw(w, me, colour);
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 90, nodes.map(n => ({ p: n.p, c: n.col, s: 2.6 })));
    nodes.forEach(n => {
      const q = hud.proj([n.p[0], 8, n.p[2]]);
      if(q.on) hud.text(q.x, q.y, n.g, { size: 15, color: n.col });
    });
    const head = phase === 'show' ? '👁 WATCH THE PULSE — ' + seq.length + ' STEPS' : phase === 'replay' ? '⌁ DRIVE IT: ' + step + ' / ' + seq.length : '';
    hud.text(Wd / 2, 28, head, { size: 15, color: phase === 'show' ? '#ffd27a' : '#9dffc4' });
    if(phase === 'replay'){
      let s = '';
      for(let i = 0; i < seq.length; i++) s += i < step ? nodes[seq[i]].g + ' ' : '• ';
      hud.text(Wd / 2, 50, s, { size: 13, color: '#bff6ff' });
      hud.bar(Wd / 2 - 80, 64, 160, 6, trace / 100, trace > 70 ? '#ff2d6a' : '#ffd700', 'TRACE');
    }
    hud.text(Wd - 16, Ht - 20, '🔓 ' + hacked + '  ·  NEXT ' + len, { size: 13, align: 'right', color: '#9dffc4' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.boostE / 100, '#39ff88', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 90, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🏓 CYBER PONG · OPEN WORLD — A RALLY WITH NO WALLS
// ══════════════════════════════════════════════
// The classic rally bounces between two walls. This one has none: two hover
// paddles on an endless floor, and a ball that goes wherever it was sent.
// The droid never hits it back at you — it hits it to where you are NOT, so
// every return is a chase. Angle still comes off where the ball strikes your
// paddle; get past the droid and the point is yours.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, wrapAng, ease, drawFloor, owClock } = P.owKit;
const { groundBegin, followCam, screenToGround, groundRing } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const HALF = 3.6, BALL_R = 0.9, MISS = 9;

P.ow.pong = function(){
  const G = groundBegin({ sky: 'violet', input: { touch: 'tap' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: MOVE YOUR PADDLE INTO THE BALL', 'WASD / ARROWS or THE MOUSE: MOVE YOUR PADDLE · THE BALL LEAVES AT THE ANGLE IT STRIKES');

  const me = { p: [0, 0, 8], v: [0, 0, 0], face: 0, flash: 0 };
  const ai = { p: [0, 0, -30], v: [0, 0, 0], face: Math.PI, flash: 0, err: 0 };
  const ball = { p: [0, 1.1, -2], v: [0, 0, -24], sp: 24, to: 'ai', live: false, trail: [] };
  let score = 0, lives = 3, rally = 0, bestRally = 0, returns = 0, aiMisses = 0, over = false, finished = false, msg = '', msgT = 0;
  let serveT = 1.2, server = 'me';
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#a855f7,#00f5ff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  // The paddle's long axis, perpendicular to the way it faces.
  const axis = pd => [Math.cos(pd.face), 0, -Math.sin(pd.face)];
  const facing = pd => [-Math.sin(pd.face), 0, -Math.cos(pd.face)];
  function serve(){
    const from = server === 'me' ? me : ai, to = server === 'me' ? ai : me;
    const d = V.norm([to.p[0] - from.p[0], 0, to.p[2] - from.p[2]]);
    ball.p = V.add(V.madd(from.p, d, 2.4), [0, 1.1, 0]);
    ball.sp = 24 * Math.min(1.3, diff);
    ball.v = V.mul(d, ball.sp);
    ball.to = server === 'me' ? 'ai' : 'me';
    ball.live = true;
    rally = 0;
    snd('go');
  }
  // Paddle vs ball: the closest point on the paddle's segment.
  function strike(pd){
    const ax = axis(pd);
    const rel = V.sub([ball.p[0], 0, ball.p[2]], pd.p);
    const along = clamp(V.dot(rel, ax), -HALF, HALF);
    const cp = V.madd(pd.p, ax, along);
    const d = Math.hypot(ball.p[0] - cp[0], ball.p[2] - cp[2]);
    if(d > BALL_R + 0.75) return null;
    const n = facing(pd);
    if(V.dot(ball.v, n) > 0) return null;          // already leaving
    return along / HALF;                           // −1 … 1 along the paddle
  }
  function playerReturn(off){
    returns++; rally++; bestRally = Math.max(bestRally, rally);
    const n = facing(me);
    const a = Math.atan2(n[0], n[2]) + off * 0.75;
    ball.sp = Math.min(62, ball.sp + 1.6);
    // A pinch of where the droid is, so a return can be aimed past it.
    let dir = [Math.sin(a), 0, Math.cos(a)];
    dir = V.norm(V.add(dir, V.mul(V.norm([ai.p[0] - me.p[0], 0, ai.p[2] - me.p[2]]), 0.25)));
    ball.v = V.add(V.mul(dir, ball.sp), V.mul(me.v, 0.25));
    ball.to = 'ai';
    me.flash = 0.15;
    const pts = 10 + Math.min(30, rally * 2);
    score += pts; setLive(score);
    snd('bounce', { semi: Math.min(12, rally) });
    fx.sparks(ball.p, 10, colour, 1, 12);
    // The droid decides now how well it will read this one.
    ai.err = (Math.random() < 0.12 * diff * (1 + rally * 0.04) ? 1 : 0) * rr(4, 7) * (Math.random() < 0.5 ? -1 : 1);
  }
  function aiReturn(){
    rally++;
    // Away from you: somewhere you have to run to.
    const side = V.norm(V.cross([me.p[0] - ai.p[0], 0, me.p[2] - ai.p[2]], [0, 1, 0]));
    const lat = rr(7, 16) * (Math.random() < 0.5 ? -1 : 1) * Math.min(1.4, diff);
    const aim = V.add(me.p, V.mul(side, lat));
    const d = V.norm([aim[0] - ai.p[0], 0, aim[2] - ai.p[2]]);
    ball.sp = Math.min(62, ball.sp + 1.2);
    ball.v = V.mul(d, ball.sp);
    ball.to = 'me';
    ai.flash = 0.15;
    snd('bounceWall');
    fx.sparks(ball.p, 8, '#ff2d9a', 1, 10);
  }
  function point(winner){
    ball.live = false;
    if(winner === 'me'){
      aiMisses++;
      const pts = 100 + Math.min(150, rally * 10);
      score += pts; setLive(score);
      snd('success');
      w.pop(V.add(ball.p, [0, 4, 0]), '+' + pts + ' POINT', '#9dffc4', { size: 17 });
      say('THE DROID MISSED — rally ' + rally, 1.8);
      server = 'me';
    }else{
      lives--;
      snd('hurt');
      w.kick(0.8);
      bar.style.width = (Math.max(0, lives) / 3 * 100) + '%';
      say('MISSED IT — ' + Math.max(0, lives) + ' left', 1.8);
      if(lives <= 0){
        if(survivedFatal()){ lives = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); }
        else{ over = true; gLater(() => finish('out'), 1000); return; }
      }
      server = 'ai';
    }
    fx.explode(ball.p, 1.4, { color: winner === 'me' ? '#39ff88' : '#ff4a4a', debris: 0, smoke: 0 });
    serveT = 1.3;
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('pong', score, {
      '📡 Match': why === 'clock' ? 'CLOCK EXPIRED' : 'OUT OF BALLS',
      '🏓 Returns': returns,
      '🤖 Droid Misses': aiMisses,
      '⛓ Longest Rally': bestRally,
      '❤ Balls Left': Math.max(0, lives),
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, lives, rally, returns, aiMisses, to: ball.to, live: ball.live }),
    lose(){ ball.live = true; point('ai'); },
    playerHit(){ if(ball.live){ ball.p = V.add(me.p, [0, 1.1, -1]); ball.v = [0, 0, 10]; me.face = Math.atan2(-(ai.p[0] - me.p[0]), -(ai.p[2] - me.p[2])); playerReturn(0.3); } },
    aiMiss(){ if(ball.live) point('me'); },
    playerMiss(){ if(ball.live) point('ai'); }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      // You: keys / stick, or the paddle chases the mouse on the floor.
      let mx = I.lx, mz = I.ly;
      if(I.device === 'mouse' && I.mouseOn && hud.cam){
        const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
        if(g){ const d = V.sub(g, me.p), l = Math.hypot(d[0], d[2]); mx = l > 0.6 ? d[0] / l * Math.min(1, l / 4) : 0; mz = l > 0.6 ? d[2] / l * Math.min(1, l / 4) : 0; }
      }
      const ml = Math.hypot(mx, mz); if(ml > 1){ mx /= ml; mz /= ml; }
      me.v = V.lerp(me.v, [mx * 27, 0, mz * 27], ease(dt, 0.07));
      me.p = V.madd(me.p, me.v, dt);
      // Both paddles turn to face the ball's way in.
      const turnTo = (pd, tgt, k) => { const want = Math.atan2(-(tgt[0] - pd.p[0]), -(tgt[2] - pd.p[2])); pd.face = wrapAng(pd.face + wrapAng(want - pd.face) * Math.min(1, dt * k)); };
      turnTo(me, ball.live ? ball.p : ai.p, 10);
      turnTo(ai, ball.live ? ball.p : me.p, 8);
      // The droid: run to where the ball will cross it, keep a distance from you.
      let goal;
      if(ball.live && ball.to === 'ai'){
        const t = Math.max(0, V.dot(V.sub(ai.p, ball.p), V.norm(ball.v)) / Math.max(ball.sp, 1));
        goal = V.madd([ball.p[0], 0, ball.p[2]], ball.v, Math.min(t, 2.5));
        goal = V.add(goal, V.mul(V.norm(V.cross(ball.v, [0, 1, 0])), ai.err));
      }else{
        const away = V.norm([ai.p[0] - me.p[0], 0, ai.p[2] - me.p[2]]);
        goal = V.madd(me.p, away, 34);
      }
      const gd = V.sub(goal, ai.p), gl = Math.hypot(gd[0], gd[2]);
      const aiSp = 22 * Math.min(1.3, diff);
      ai.v = V.lerp(ai.v, gl > 0.4 ? [gd[0] / gl * Math.min(aiSp, gl * 4), 0, gd[2] / gl * Math.min(aiSp, gl * 4)] : [0, 0, 0], ease(dt, 0.12));
      ai.p = V.madd(ai.p, ai.v, dt);
      me.flash = Math.max(0, me.flash - dt); ai.flash = Math.max(0, ai.flash - dt);

      if(!ball.live){ serveT -= dt; if(serveT <= 0) serve(); }
      else{
        ball.p = V.madd(ball.p, ball.v, dt);
        ball.p[1] = 1.1 + Math.abs(Math.sin(w.t * 5)) * 0.4;
        ball.trail.unshift(V.copy(ball.p)); if(ball.trail.length > 10) ball.trail.pop();
        if(ball.to === 'ai'){
          const hit = strike(ai);
          if(hit != null) aiReturn();
          else if(V.dot(V.sub(ball.p, ai.p), V.norm(ball.v)) > MISS) point('me');
        }else{
          const hit = strike(me);
          if(hit != null) playerReturn(hit);
          else if(V.dot(V.sub(ball.p, me.p), V.norm(ball.v)) > MISS) point('ai');
        }
      }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    // The camera holds you and the ball both.
    const mid = ball.live ? V.lerp(me.p, [ball.p[0], 0, ball.p[2]], 0.35) : me.p;
    followCam(w, mid, { height: 44, back: 28, look: 4, fov: 54, half: 0.14 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 170, color: '#3a1d6e', glow: 1.0, major: 5, floor: '#05030b', rough: 0.2 });
    const drawPaddle = (pd, col, mineToo) => {
      r.draw('paddle', { pos: [pd.p[0], 1.1, pd.p[2]], rot: [0, pd.face + Math.PI / 2, 0], scale: [1.1, 1.4, HALF * 2.1], color: pd.flash > 0 ? '#ffffff' : '#c9d1dd',
                         metallic: 0.6, roughness: 0.3, rim: 0.8, emissive: col, emissiveStrength: mineToo ? 0.9 : 0.7 });
      r.glow([pd.p[0], 1.1, pd.p[2]], 3.4, col, 0.5);
      groundRing(w, pd.p, 2.2, col, 0.6);
      r.light({ pos: [pd.p[0], 5, pd.p[2]], color: col, intensity: 90, range: 18 });
    };
    drawPaddle(me, colour, true);
    drawPaddle(ai, '#ff2d9a', false);
    if(ball.live){
      r.draw('sphere', { pos: ball.p, scale: BALL_R * 2, color: '#ffffff', emissive: '#e8f6ff', emissiveStrength: 2.4 });
      r.glow(ball.p, 2.2, '#bff6ff', 1.2);
      for(let i = 1; i < ball.trail.length; i++) r.streak(ball.trail[i], ball.trail[i - 1], 0.5 * (1 - i / 10), ball.to === 'ai' ? colour : '#ff2d9a', 1.6 * (1 - i / 10), 0);
      // Where it is going to cross you.
      if(ball.to === 'me'){
        const t = Math.max(0, V.dot(V.sub(me.p, ball.p), V.norm(ball.v)) / Math.max(ball.sp, 1));
        const land = V.madd([ball.p[0], 0, ball.p[2]], ball.v, t);
        groundRing(w, land, 1.3, '#ffd27a', 0.8);
      }
    }
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    hud.radar(70, Ht - 74, 54, me.p, [0, 0, -1], 70, [{ p: ai.p, c: '#ff2d9a', s: 3 }].concat(ball.live ? [{ p: ball.p, c: '#ffffff', s: 2.4 }] : []));
    if(ball.live && !hud.proj(ball.p).on) hud.edgeArrow(ball.p, '#ffffff', 'BALL');
    if(!hud.proj(ai.p).on) hud.edgeArrow(ai.p, '#ff2d9a', 'DROID');
    hud.text(Wd / 2, 26, ball.live ? 'RALLY ' + rally : server === 'me' ? 'YOUR SERVE…' : 'DROID SERVES…', { size: 15, color: '#ffffff' });
    hud.text(Wd - 16, Ht - 40, '🤖 ' + aiMisses + ' missed', { size: 13, align: 'right', color: '#ff8ac8' });
    hud.text(Wd - 16, Ht - 20, '●'.repeat(Math.max(0, lives)) + '○'.repeat(Math.max(0, 3 - lives)), { size: 15, align: 'right', color: '#ffffff' });
    if(msgT > 0) hud.text(Wd / 2, 52, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🧊 ICE BREAKER · OPEN WORLD — THE ENDLESS CEILING
// ══════════════════════════════════════════════
// The classic is a wall of ice between two side walls. This one has no sides:
// the ceiling of bricks runs on for ever in both directions, and nothing
// banks the ball back to you. Send it in at an angle and it travels — so you
// travel too, the paddle chasing it along an endless line. Break through and
// the back wall still returns it; the deeper rows are harder ice.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ihash, ease, drawFloor, owClock } = P.owKit;
const { groundBegin, screenToGround } = P.owGround;
const { mine, clamp, runLoop, seeded } = P.kit;
const BW = 4.4, BD = 2.4, ROWS = 18, Z0 = -22, R = 0.75, CH = 12;
const ZBACK = Z0 - ROWS * BD - 1.5;
const ICE = ['#7fe8ff', '#a855f7', '#ff2d9a'];

P.ow.breaker = function(){
  const G = groundBegin({ sky: 'ice', input: { touch: 'tap' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK / DRAG: SLIDE THE PADDLE · TAP: LAUNCH', 'A/D, ←/→ or THE MOUSE: SLIDE THE PADDLE · SPACE / CLICK: LAUNCH · NO WALLS — CHASE THE BALL');

  const pad = { x: 0, v: 0, w: 7, wideT: 0, flash: 0 };
  // ⚡ v60 · The 2D wall's chips, all of them: WIDE DEFLECTOR, TIME DILATION
  // (the ball at 0.72× for six seconds) and +50 DATA drop from ordinary ice as
  // they do on the classic board; gold still drops wide or MULTI-BALL.
  let slowT = 0;
  let balls = [], lives = 3, score = 0, broken = 0, combo = 0, bestCombo = 0, over = false, finished = false, msg = '', msgT = 0;
  let held = true, heldT = 1.6, caps = [], camX = 0;
  const live = new Map(), gone = new Set(), loaded = new Set();
  const key = (c, row) => c + ',' + row;
  // The ice, as a pure function of the column and row: gaps, gold, depth.
  function brickAt(c, row){
    const g = seeded(ihash(c, row, 0, 4747));
    const v = g();
    const band = 0.5 + 0.5 * Math.sin(c * 0.37) * Math.cos(row * 0.9 + c * 0.11);
    if(v < 0.06 + band * 0.06) return null;
    const hp = row < 5 ? 1 : row < 11 ? 2 : 3;
    return { hp, max: hp, gold: g() < 0.05 };
  }
  function loadChunk(cc){
    if(loaded.has(cc)) return;
    loaded.add(cc);
    for(let c = cc * CH; c < cc * CH + CH; c++){
      for(let row = 0; row < ROWS; row++){
        const k = key(c, row);
        if(gone.has(k)) continue;
        const b = brickAt(c, row);
        if(b) live.set(k, Object.assign(b, { c, row }));
      }
    }
  }
  function unloadChunk(cc){
    loaded.delete(cc);
    for(let c = cc * CH; c < cc * CH + CH; c++) for(let row = 0; row < ROWS; row++) live.delete(key(c, row));
  }
  const bx = c => (c + 0.5) * BW, bz = row => Z0 - (row + 0.5) * BD;
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#7fe8ff,#a855f7)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  function newBall(){ balls = [{ p: [pad.x, 1, -1.6], v: [0, 0, 0], sp: 30 * Math.min(1.3, diff) }]; held = true; heldT = 1.6; }
  newBall();
  function launch(){
    if(!held) return;
    held = false;
    const b = balls[0];
    const a = (Math.random() - 0.5) * 0.8;
    b.v = [Math.sin(a) * b.sp, 0, -Math.cos(a) * b.sp];
    snd('go');
  }
  function hitBrick(br, b){
    br.hp--;
    score += 5;
    if(br.hp <= 0){
      const k = key(br.c, br.row);
      live.delete(k); gone.add(k);
      broken++;
      combo++; bestCombo = Math.max(bestCombo, combo);
      const pts = 10 * br.max + Math.min(40, combo * 2);
      score += pts;
      snd('brick', { semi: Math.min(12, combo) });
      fx.explode([bx(br.c), 1, bz(br.row)], 1.1, { color: br.gold ? '#ffd700' : ICE[br.max - 1], debris: 3, debrisGeo: 'slab', debrisColor: '#cfe8ff', smoke: 0, ring: false, grav: 20 });
      if(br.gold) caps.push({ p: [bx(br.c), 1, bz(br.row)], k: Math.random() < 0.5 ? 'wide' : 'multi' });
      else if(Math.random() < 0.12) caps.push({ p: [bx(br.c), 1, bz(br.row)], k: ['wide', 'slow', 'bonus'][(Math.random() * 3) | 0] });
      if(combo > 0 && combo % 10 === 0) w.pop([bx(br.c), 4, bz(br.row)], '×' + combo + ' COMBO', '#ffd27a', { size: 15 });
    }else{
      snd('shatter', { semi: -4 });
      fx.sparks([bx(br.c), 1, bz(br.row)], 6, '#dff8ff', 0.8, 8);
    }
    setLive(score);
  }
  // Circle vs the bricks around it: reflect on the shallower axis of the first hit.
  function collide(b){
    const c0 = Math.floor((b.p[0] - R) / BW), c1 = Math.floor((b.p[0] + R) / BW);
    const r0 = Math.floor((Z0 - (b.p[2] + R)) / BD), r1 = Math.floor((Z0 - (b.p[2] - R)) / BD);
    for(let c = c0; c <= c1; c++) for(let row = Math.max(0, r0); row <= Math.min(ROWS - 1, r1); row++){
      const br = live.get(key(c, row));
      if(!br) continue;
      const cx = bx(c), cz = bz(row);
      const dx = b.p[0] - cx, dz = b.p[2] - cz;
      const px = BW / 2 + R - Math.abs(dx), pz = BD / 2 + R - Math.abs(dz);
      if(px <= 0 || pz <= 0) continue;
      if(px < pz){ b.p[0] += Math.sign(dx || 1) * px; b.v[0] = Math.abs(b.v[0]) * Math.sign(dx || 1); }
      else{ b.p[2] += Math.sign(dz || 1) * pz; b.v[2] = Math.abs(b.v[2]) * Math.sign(dz || 1); }
      hitBrick(br, b);
      return true;
    }
    return false;
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('breaker', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'OUT OF BALLS',
      '🧊 Ice Broken': broken,
      '⛓ Best Combo': bestCombo,
      '❤ Balls Left': Math.max(0, lives),
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, broken, lives, balls: balls.length, held, bricks: live.size, x: Math.round(pad.x) }),
    launch(){ launch(); },
    lose(){ held = false; balls = [{ p: [pad.x, 1, 9], v: [0, 0, 10], sp: 30 }]; },
    breakSome(n){ let k = 0; for(const br of [...live.values()]){ if(k >= (n || 5)) break; if(br.row < 3){ br.hp = 1; hitBrick(br, balls[0]); k++; } } return k; },
    loseBall(){ if(!held && balls[0]) balls[0].p[2] = 9; }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      // The paddle: keys / stick, or it follows the mouse along the line.
      let want = I.lx * 46;
      if(I.device === 'mouse' && I.mouseOn && hud.cam){
        const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
        if(g) want = clamp((g[0] - pad.x) * 9, -60, 60);
      }else if(I.stick){
        want = clamp((I.stick.x - I.stick.x0) / 0.2, -1, 1) * 46;
      }
      pad.v += (want - pad.v) * ease(dt, 0.05);
      pad.x += pad.v * dt;
      pad.wideT = Math.max(0, pad.wideT - dt);
      slowT = Math.max(0, slowT - dt);
      pad.w += ((pad.wideT > 0 ? 11 : 7) - pad.w) * ease(dt, 0.2);
      pad.flash = Math.max(0, pad.flash - dt);
      const cc = Math.floor(pad.x / (CH * BW));
      for(let k = -4; k <= 4; k++) loadChunk(cc + k);
      for(const c of [...loaded]) if(Math.abs(c - cc) > 7) unloadChunk(c);
      if(held){
        balls[0].p = [pad.x, 1, -1.6];
        heldT -= dt;
        if(I.fire || I.jumpHit || heldT <= 0) launch();
      }else{
        // ⏱ TIME DILATION slows the ball itself.
        const bdt = dt * (slowT > 0 ? 0.72 : 1);
        for(let i = balls.length - 1; i >= 0; i--){
          const b = balls[i];
          const steps = Math.max(1, Math.ceil(b.sp * bdt / 0.6));
          for(let s = 0; s < steps; s++){
            b.p[0] += b.v[0] * bdt / steps; b.p[2] += b.v[2] * bdt / steps;
            if(b.p[2] < ZBACK + R){ b.p[2] = ZBACK + R; b.v[2] = Math.abs(b.v[2]); snd('bounceWall'); }
            collide(b);
            // The paddle.
            if(b.v[2] > 0 && b.p[2] > -1.2 - R && b.p[2] < 0.4 && Math.abs(b.p[0] - pad.x) < pad.w / 2 + R){
              const off = clamp((b.p[0] - pad.x) / (pad.w / 2), -1, 1);
              b.sp = Math.min(58, b.sp + 0.5);
              const a = off * 1.05;
              b.v = [Math.sin(a) * b.sp + pad.v * 0.12, 0, -Math.cos(a) * b.sp];
              const l = Math.hypot(b.v[0], b.v[2]); b.v[0] *= b.sp / l; b.v[2] *= b.sp / l;
              b.p[2] = -1.2 - R;
              combo = 0;
              pad.flash = 0.12;
              snd('bounce');
            }
          }
          if(b.p[2] > 6){
            balls.splice(i, 1);
            fx.sparks(b.p, 10, '#ff6a8a', 1, 10);
            if(!balls.length){
              lives--;
              combo = 0;
              snd('hurt'); w.kick(0.6);
              bar.style.width = (Math.max(0, lives) / 3 * 100) + '%';
              if(lives <= 0){
                if(survivedFatal()){ lives = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); newBall(); }
                else{ over = true; gLater(() => finish('out'), 900); }
              }else{ say('BALL LOST — ' + lives + ' left', 1.6); newBall(); }
            }
          }
        }
      }
      for(let i = caps.length - 1; i >= 0; i--){
        const cp = caps[i];
        cp.p[2] += 12 * dt;
        if(cp.p[2] > -1.6 && cp.p[2] < 0.6 && Math.abs(cp.p[0] - pad.x) < pad.w / 2 + 1){
          caps.splice(i, 1);
          snd('powerup');
          if(cp.k === 'wide'){ pad.wideT = 12; say('↔ WIDE PADDLE', 1.6); }
          else if(cp.k === 'slow'){ slowT = 6; say('⏱ TIME DILATION', 1.6); }
          else if(cp.k === 'bonus'){ score += 50; setLive(score); say('★ +50 DATA', 1.4); }
          else if(balls.length && !held){
            const b0 = balls[0];
            for(const a of [-0.5, 0.5]) balls.push({ p: V.copy(b0.p), v: [Math.sin(a) * b0.sp, 0, -Math.cos(a) * b0.sp], sp: b0.sp });
            say('✳ MULTI-BALL', 1.6);
          }
        }else if(cp.p[2] > 8) caps.splice(i, 1);
      }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    // The camera rides between the paddle and the ball it is chasing.
    const lead = balls.length ? balls[0].p[0] : pad.x;
    if(dt > 0) camX += (pad.x * 0.6 + lead * 0.4 - camX) * ease(dt, 0.18);
    w.cam.eye = [camX, 30, 24]; w.cam.target = [camX, 0, -22];
    w.goal.eye = w.cam.eye; w.goal.target = w.cam.target; w.goal.fov = 56;
    w.up = [0, 1, 0];
    w.step(dt);

    w.begin();
    drawFloor(w, { step: BW, radius: 120, color: '#15507a', glow: 0.8, major: 6, floor: '#030a14', rough: 0.2 });
    // The back wall: the far side of the ceiling.
    r.draw('box', { pos: [camX, 2, ZBACK - 0.6], scale: [240, 4, 0.6], color: '#0e1a2a', metallic: 0.7, roughness: 0.3, emissive: '#46c8ff', emissiveStrength: 0.15 });
    r.beam([camX - 120, 4.1, ZBACK - 0.4], [camX + 120, 4.1, ZBACK - 0.4], 0.2, { color: '#7fe8ff', emissive: '#7fe8ff', emissiveStrength: 2.2 });
    const c0 = Math.floor((camX - 75) / BW), c1 = Math.floor((camX + 75) / BW);
    for(let c = c0; c <= c1; c++) for(let row = 0; row < ROWS; row++){
      const br = live.get(key(c, row));
      if(!br) continue;
      const col = br.gold ? '#ffd700' : ICE[br.max - 1];
      const k = br.hp / br.max;
      r.draw('slab', { pos: [bx(c), 1, bz(row)], scale: [BW - 0.4, 1.6, BD - 0.4], color: '#dff4ff', metallic: 0.2, roughness: 0.15, rim: 0.9,
                       emissive: col, emissiveStrength: 0.35 + 0.9 * k });
    }
    // The paddle.
    r.draw('paddle', { pos: [pad.x, 1, -0.6], rot: [0, Math.PI / 2, 0], scale: [1.2, 1.3, pad.w], color: pad.flash > 0 ? '#ffffff' : '#c9d1dd', metallic: 0.6, roughness: 0.3, rim: 0.8, emissive: colour, emissiveStrength: 0.8 });
    r.glow([pad.x, 1, -0.6], pad.w * 0.5, colour, 0.4);
    r.light({ pos: [pad.x, 6, 2], color: '#d8f0ff', intensity: 120, range: 26 });
    let nl = 0;
    for(const b of balls){
      r.draw('sphere', { pos: b.p, scale: R * 2, color: '#ffffff', emissive: '#e8f6ff', emissiveStrength: 2.4 });
      r.glow(b.p, 2, '#bff6ff', 1.1);
      if(!held) r.streak(V.madd(b.p, V.norm(b.v), -3), b.p, 0.5, '#bff6ff', 1.2, 1);
      if(nl++ < 2) r.light({ pos: [b.p[0], 4, b.p[2]], color: '#bff6ff', intensity: 60, range: 14 });
    }
    for(const cp of caps){
      const col = cp.k === 'wide' ? '#39ff88' : cp.k === 'slow' ? '#00f5ff' : cp.k === 'bonus' ? '#ffe14a' : '#ffd700';
      r.draw('pill', { pos: cp.p, rot: [0, 0, Math.PI / 2], scale: [0.9, 1.6, 0.9], color: col, emissive: col, emissiveStrength: 1.8 });
      r.glow(cp.p, 1.8, col, 0.8);
    }
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    for(const b of balls){ if(!hud.proj(b.p).on) hud.edgeArrow(b.p, '#ffffff', 'BALL'); }
    if(held) hud.text(Wd / 2, Ht * 0.6, 'SPACE / CLICK TO LAUNCH', { size: 13, color: '#bff6ff', alpha: 0.8 });
    hud.text(Wd / 2, 26, combo > 2 ? 'COMBO ×' + combo : '', { size: 15, color: '#ffd27a' });
    hud.text(Wd - 16, Ht - 40, '🧊 ' + broken, { size: 13, align: 'right', color: '#bff6ff' });
    hud.text(Wd - 16, Ht - 20, '●'.repeat(Math.max(0, lives)) + '○'.repeat(Math.max(0, 3 - lives)), { size: 15, align: 'right', color: '#ffffff' });
    if(msgT > 0) hud.text(Wd / 2, 52, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🎱 NEON PINBALL · OPEN WORLD — THE ENDLESS TABLE
// ══════════════════════════════════════════════
// The classic table has a top, two sides and a drain. This one only has the
// drain. It runs downhill for ever, and your flippers ride down it with the
// ball — sliding across to stay under it, sinking a little further every
// second — while the bumpers, the stars and the drop-target banks rise out of
// the table behind them. Pull the plunger, keep it alive, and drop a full
// bank to raise the multiplier. There are no walls: a ball that gets away
// sideways is as gone as one down the middle.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ease, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, groundRing } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const BR = 0.62, GRAV = 30, VMAX = 62, DESC = 4.2, FOLLOW = 17;
const FL = { len: 4.6, r0: 0.55, r1: 0.32, rest: 0.49, up: -0.52, wUp: 22, wDown: 13, e: 0.28, half: 5.2 };
const RISE = 6.5;                     // bumpers stand only this far above the flippers

P.ow.pinball = function(){
  const G = groundBegin({ sky: 'violet', env: { horizon: '#5a1a7a' }, input: { touch: 'tap' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('LEFT / RIGHT HALF: FLIPPERS · HOLD TO PULL THE PLUNGER', 'A / ← : LEFT FLIPPER · D / → : RIGHT · SPACE: BOTH, OR HOLD TO PULL THE PLUNGER · MOUSE BUTTONS: FLIPPERS');

  const car = { x: 0, z: 0, vx: 0 };
  const flip = [{ s: 1, a: FL.rest, w: 0 }, { s: -1, a: FL.rest, w: 0 }];
  const ball = { x: 0, z: -1.6, vx: 0, vz: 0, held: true, charge: 0, heldT: 3 };
  let score = 0, balls = 3, mult = 1, bumps = 0, banks = 0, over = false, finished = false, msg = '', msgT = 0, descended = 0, saveT = 0;
  const table = makeField({
    cell: 24, dims: 2, seed: 6363, radius: 150,
    gen(cx, cy, cz, g){
      const items = [];
      const x0 = cx * 24, z0 = cz * 24;
      if(cz >= -1 && Math.abs(cx) <= 1) return items;      // the launch lane
      const roll = g();
      if(roll < 0.55){
        const n = 1 + (g() < 0.4 ? 1 : 0);
        for(let i = 0; i < n; i++) items.push({ t: 'bump', p: [x0 + 4 + g() * 16, 0, z0 + 4 + g() * 16], r: 1.3 + g() * 0.4, flash: 0, ph: g() * TAU });
      }else if(roll < 0.78){
        const bank = { hits: 0 };
        const x = x0 + 5 + g() * 10, z = z0 + 6 + g() * 12;
        for(let i = 0; i < 3; i++) items.push({ t: 'target', p: [x + i * 2.2, 0, z], r: 0.75, down: false, bank, flash: 0 });
      }
      if(g() < 0.5){
        const x = x0 + 4 + g() * 16, z = z0 + 4 + g() * 16, a = g() * TAU;
        for(let i = 0; i < 4; i++) items.push({ t: 'star', p: [x + Math.cos(a) * i * 2, 0, z + Math.sin(a) * i * 2], lit: 0 });
      }
      return items;
    }
  });
  // Touch: a tap on a half kicks that flipper up for a moment, so a quick tap
  // on a slow phone still flips, and any tap pulls the plunger.
  const kick = [0, 0];
  let tapped = 0;
  const cv = aCanvas;
  const onTouch = e => {
    if(!e.isTrusted) return;
    const rc = cv.getBoundingClientRect();
    for(const t of e.changedTouches){ kick[(t.clientX - rc.left) / Math.max(1, rc.width) < 0.5 ? 0 : 1] = 0.16; tapped++; }
  };
  if(cv) cv.addEventListener('touchstart', onTouch, { passive: true });
  const prevStop = onStopGame;
  onStopGame = () => { try{ if(cv) cv.removeEventListener('touchstart', onTouch); }catch(e){} if(prevStop) prevStop(); };
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ff2bd6,#00f5ff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  const pivot = f => [car.x - f.s * FL.half, car.z - 0.8];
  const tipOf = f => { const p = pivot(f); return [p[0] + f.s * Math.cos(f.a) * FL.len, p[1] + Math.sin(f.a) * FL.len]; };
  const award = (pts, at, label, col) => {
    score += pts * mult; setLive(score);
    if(label) w.pop([at[0], 3, at[1]], '+' + pts * mult + ' ' + label, col || '#ffd27a', { size: 14 });
  };
  // Ball vs a flipper's capsule; the flipper's surface speed goes into the bounce.
  function hitFlipper(f){
    const a = pivot(f), b = tipOf(f);
    const abx = b[0] - a[0], abz = b[1] - a[1], L2 = abx * abx + abz * abz;
    const t = clamp(((ball.x - a[0]) * abx + (ball.z - a[1]) * abz) / L2, 0, 1);
    const cx = a[0] + abx * t, cz = a[1] + abz * t;
    const rad = FL.r0 + (FL.r1 - FL.r0) * t;
    const dx = ball.x - cx, dz = ball.z - cz, d = Math.hypot(dx, dz);
    if(d >= rad + BR || d < 1e-6) return;
    const nx = dx / d, nz = dz / d;
    ball.x = cx + nx * (rad + BR); ball.z = cz + nz * (rad + BR);
    const rx = cx - a[0], rz = cz - a[1];
    const svx = -f.s * f.w * rz + car.vx, svz = f.s * f.w * rx + DESC;
    const rvx = ball.vx - svx, rvz = ball.vz - svz, vn = rvx * nx + rvz * nz;
    if(vn < 0){
      ball.vx -= (1 + FL.e) * vn * nx; ball.vz -= (1 + FL.e) * vn * nz;
      if(Math.abs(vn) > 8) snd('bounce', { semi: -6 });
    }
  }
  function hitItem(it){
    const dx = ball.x - it.p[0], dz = ball.z - it.p[2], d = Math.hypot(dx, dz);
    if(it.t === 'star'){ if(d < 1 && it.lit <= 0){ it.lit = 3; award(5, [it.p[0], it.p[2]]); snd('coin'); } return; }
    if(it.t === 'target' && it.down) return;
    const rad = it.r + BR;
    if(d >= rad || d < 1e-6) return;
    const nx = dx / d, nz = dz / d;
    ball.x = it.p[0] + nx * rad; ball.z = it.p[2] + nz * rad;
    const vn = ball.vx * nx + ball.vz * nz;
    if(vn < 0){ ball.vx -= 1.8 * vn * nx; ball.vz -= 1.8 * vn * nz; }
    if(it.t === 'bump'){
      ball.vx += nx * 13; ball.vz += nz * 13;
      it.flash = 0.15;
      bumps++;
      award(10, [it.p[0], it.p[2]]);
      snd('bounceWall', { semi: 4 });
      fx.sparks([it.p[0], 1.2, it.p[2]], 6, '#ff2bd6', 0.8, 10);
    }else{
      it.down = true; it.flash = 0.3;
      it.bank.hits++;
      award(25, [it.p[0], it.p[2]], 'TARGET', '#ffd700');
      snd('hit');
      if(it.bank.hits === 3){
        banks++;
        award(100, [it.p[0], it.p[2]], 'BANK!', '#39ff88');
        if(mult < 4){ mult++; say('✦ MULTIPLIER ×' + mult, 2); }
        snd('levelUp');
      }
    }
  }
  function drain(){
    balls--;
    mult = 1;
    snd('gameOver');
    w.kick(0.8);
    bar.style.width = (Math.max(0, balls) / 3 * 100) + '%';
    if(balls <= 0){
      if(survivedFatal()){ balls = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); }
      else{ over = true; gLater(() => finish('drain'), 900); return; }
    }else say('DRAINED — ' + balls + ' left', 1.8);
    ball.held = true; ball.charge = 0; ball.heldT = 3;
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('pinball', score, {
      '📡 Game': why === 'clock' ? 'CLOCK EXPIRED' : 'LAST BALL DRAINED',
      '💥 Bumper Hits': bumps,
      '🎯 Banks Dropped': banks,
      '📏 Table Descended': Math.round(descended) + ' m',
      '🎱 Balls Left': Math.max(0, balls),
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, balls, mult, bumps, banks, held: ball.held, x: +ball.x.toFixed(1), z: +(ball.z - car.z).toFixed(1) }),
    launch(){ if(ball.held){ ball.held = false; ball.vx = rr(-4, 4); ball.vz = -40; saveT = 4; } },
    bumpers(n){ let k = 0; table.each(it => { if(k < (n || 3) && it.t === 'bump'){ ball.x = it.p[0] + it.r + BR - 0.1; ball.z = it.p[2]; ball.vx = -5; ball.vz = 0; hitItem(it); k++; } }); return k; },
    bank(){ let done = false; table.each(it => { if(!done && it.t === 'target' && !it.down && it.bank.hits === 0){ done = true; table.each(o => { if(o.t === 'target' && o.bank === it.bank){ ball.x = o.p[0] + 1.2; ball.z = o.p[2]; ball.vx = -4; ball.vz = 0; hitItem(o); } }); } }); return done; },
    drain(){ if(!ball.held) drain(); },
    lose(){ ball.held = false; saveT = 0; drain(); }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      const k = I.keys || {};
      const pad = I.pad || {};
      const both = !ball.held && !!k.Space;
      kick[0] = Math.max(0, kick[0] - dt); kick[1] = Math.max(0, kick[1] - dt);
      const L = both || k.KeyA || k.ArrowLeft || k.KeyZ || (I.mDown && I.device === 'mouse') || !!I.stick || kick[0] > 0 || (pad.lt || 0) > 0.3;
      const Rt = both || k.KeyD || k.ArrowRight || k.KeyM || k.Slash || (I.mRight && I.device === 'mouse') || !!I.tFire || kick[1] > 0 || (pad.rt || 0) > 0.3;
      // The carriage: down the table for ever, across to stay under the ball.
      car.z += DESC * dt;
      descended += DESC * dt;
      // Only while the ball is well up the table: a carriage that kept sliding
      // under a ball resting on a flipper would roll it into the drain.
      const track = ball.held ? 0 : clamp((car.z - 8 - ball.z) / 10, 0, 1);
      const want = clamp((ball.x - car.x) * 3, -FOLLOW, FOLLOW) * track;
      car.vx += (want - car.vx) * ease(dt, 0.12);
      car.x += car.vx * dt;
      if(((descended / 2) | 0) !== (((descended - DESC * dt) / 2) | 0)){ score += 1; setLive(score); }
      table.update([car.x, 0, car.z - 20]);
      const tapsNow = tapped; tapped = 0;
      if(ball.held){
        ball.x = car.x; ball.z = car.z - 1.9; ball.vx = car.vx; ball.vz = DESC;
        const pull = I.fire || I.jumpHit || !!k.Space;
        if(tapsNow && !pull && ball.charge < 0.05) ball.charge = 0.55;
        if(pull) ball.charge = Math.min(1, ball.charge + dt / 0.9);
        ball.heldT -= dt;
        if((!pull && ball.charge > 0.05) || ball.heldT <= 0){
          ball.held = false;
          ball.vz = -(26 + 30 * (ball.charge || 0.5));
          ball.vx = rr(-5, 5);
          ball.charge = 0;
          saveT = 4;
          snd('missile');
        }
      }
      // The flippers, then the ball in sub-steps so nothing thin is skipped.
      const steps = Math.max(2, Math.ceil(Math.hypot(ball.vx, ball.vz) * dt / 0.28));
      const h = dt / steps;
      for(let s = 0; s < steps; s++){
        for(const [i, f] of flip.entries()){
          const on = i === 0 ? L : Rt;
          const target = on ? FL.up : FL.rest;
          const wmax = on ? FL.wUp : FL.wDown;
          const prev = f.a;
          f.a += clamp(target - f.a, -wmax * h, wmax * h);
          f.w = (f.a - prev) / h;
        }
        if(ball.held) break;
        ball.vz += GRAV * Math.min(1.25, diff) * h;
        const sp = Math.hypot(ball.vx, ball.vz);
        if(sp > VMAX){ ball.vx *= VMAX / sp; ball.vz *= VMAX / sp; }
        ball.x += ball.vx * h; ball.z += ball.vz * h;
        hitFlipper(flip[0]); hitFlipper(flip[1]);
        table.near([ball.x, 0, ball.z], it => { if(it.t === 'star' || it.p[2] < car.z - RISE) hitItem(it); });
      }
      for(const [i, f] of flip.entries()){
        const on = i === 0 ? L : Rt;
        if(on && !f.was) snd('click', { semi: -8 });
        f.was = on;
      }
      saveT = Math.max(0, saveT - dt);
      if(!ball.held && (ball.z > car.z + 3.2 || Math.abs(ball.x - car.x) > 34 && ball.z > car.z - 4)){
        if(saveT > 0){ ball.held = true; ball.charge = 0; ball.heldT = 2; say('BALL SAVED', 1.4); snd('shield'); }
        else drain();
      }
      table.each(it => { if(it.flash > 0) it.flash -= dt; if(it.lit > 0) it.lit -= dt; });
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    // Behind the flippers, looking up the table.
    w.cam.eye = [car.x, 23, car.z + 19];
    w.cam.target = [car.x * 0.7 + ball.x * 0.3, 0, car.z - 15];
    w.goal.eye = w.cam.eye; w.goal.target = w.cam.target; w.goal.fov = 58;
    w.up = [0, 1, 0];
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 4, radius: 120, color: '#4a1a6e', glow: 0.9, major: 6, floor: '#07030e', rough: 0.15, metal: 0.9 });
    const zLine = car.z - RISE;
    let nl = 0;
    table.each(it => {
      const dz = it.p[2] - car.z;
      if(dz < -90 || dz > 30 || Math.abs(it.p[0] - car.x) > 70) return;
      const up = it.p[2] < zLine;
      if(it.t === 'bump'){
        const h = up ? 1.8 : 0.15, col = '#ff2bd6';
        r.draw('cylinder', { pos: [it.p[0], h / 2, it.p[2]], scale: [it.r * 2, h, it.r * 2], color: it.flash > 0 ? '#ffffff' : '#2a1030', metallic: 0.7, roughness: 0.3, emissive: col, emissiveStrength: up ? (it.flash > 0 ? 3 : 0.8) : 0.2 });
        if(up){
          r.draw('thintorus', { pos: [it.p[0], h + 0.1, it.p[2]], scale: [it.r * 2.3, 1, it.r * 2.3], color: col, emissive: col, emissiveStrength: 2 + (it.flash > 0 ? 3 : 0) });
          r.glow([it.p[0], h, it.p[2]], it.r * 1.5, col, it.flash > 0 ? 1.6 : 0.5);
          if(it.flash > 0 && nl++ < 3) r.light({ pos: [it.p[0], 3, it.p[2]], color: col, intensity: 140, range: 12 });
        }
      }else if(it.t === 'target'){
        const col = '#ffd700';
        if(!it.down) r.draw('slab', { pos: [it.p[0], up ? 0.8 : 0.1, it.p[2]], scale: [1.4, up ? 1.6 : 0.2, 0.5], color: '#3a3010', metallic: 0.6, roughness: 0.3, emissive: col, emissiveStrength: up ? 1.4 : 0.3 });
        else r.glow([it.p[0], 0.2, it.p[2]], 0.8, col, 0.4);
      }else{
        const col = it.lit > 0 ? '#ffffff' : '#00f5ff';
        r.glow([it.p[0], 0.15, it.p[2]], 0.7, col, it.lit > 0 ? 1.8 : 0.6);
      }
    });
    // The flippers.
    for(const f of flip){
      const a = pivot(f), b = tipOf(f);
      r.beam([a[0], 0.7, a[1]], [b[0], 0.7, b[1]], 0.9, { geo: 'pill', color: '#d8e0ec', metallic: 0.6, roughness: 0.3, emissive: colour, emissiveStrength: 0.5, height: 1.1 });
      r.draw('cylinder', { pos: [a[0], 0.7, a[1]], scale: [1.2, 1.3, 1.2], color: '#3a3e48', metallic: 0.8, roughness: 0.3 });
    }
    groundRing(w, [car.x, 0, car.z + 0.6], 3.2, saveT > 0 ? '#39ff88' : '#ff4a6a', 0.6);
    r.light({ pos: [car.x, 8, car.z + 4], color: '#e8d8ff', intensity: 160, range: 30 });
    // The ball.
    const bp = [ball.x, BR, ball.z];
    r.draw('sphere', { pos: bp, scale: BR * 2, color: '#e8eef8', metallic: 0.9, roughness: 0.12, rim: 1.1, emissive: '#9fe6ff', emissiveStrength: 0.1 });
    r.glow(bp, 1.2, '#bff6ff', 0.6);
    r.light({ pos: [ball.x, 2.4, ball.z], color: '#bfefff', intensity: 40, range: 6 });
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    if(!hud.proj(bp).on) hud.edgeArrow(bp, '#ffffff', 'BALL');
    if(ball.held){
      hud.text(Wd / 2, Ht * 0.62, 'HOLD SPACE / FIRE — PULL THE PLUNGER', { size: 12, color: '#ffd8ff', alpha: 0.85 });
      hud.bar(Wd / 2 - 60, Ht * 0.62 + 14, 120, 6, ball.charge, '#ff2bd6');
    }
    hud.text(Wd / 2, 26, mult > 1 ? 'MULTIPLIER ×' + mult : '', { size: 15, color: '#39ff88' });
    hud.text(Wd - 16, Ht - 40, '💥 ' + bumps + '  🎯 ' + banks, { size: 13, align: 'right', color: '#ffd8ff' });
    hud.text(Wd - 16, Ht - 20, '●'.repeat(Math.max(0, balls)) + '○'.repeat(Math.max(0, 3 - balls)), { size: 15, align: 'right', color: '#ffffff' });
    if(msgT > 0) hud.text(Wd / 2, 52, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    if(I.device === 'touch'){
      hud.text(Wd * 0.25, Ht * 0.85, '◀ FLIP', { size: 12, color: '#ffd8ff', alpha: 0.35 });
      hud.text(Wd * 0.75, Ht * 0.85, 'FLIP ▶', { size: 12, color: '#ffd8ff', alpha: 0.35 });
    }
  });
};

})();


// ══════════════════════════════════════════════
//  📡 UPLINK · OPEN WORLD — THE ARTILLERY RUN
// ══════════════════════════════════════════════
// The classic lobs one shot over one firewall in a crosswind. Out here you
// drive the launcher: relay dishes and moving convoys sit at every range
// across an endless plain, towers stand between, and the wind keeps
// changing its mind. Point and click (or tap) where the shell should land,
// or hold FIRE to wind the range out like the classic's drag; the wind does
// the rest, so lead it. The longer the shot, the more it pays.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owDrive) return;
const { V, TAU, wrapAng, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, makeCity, groundRing, screenToGround } = P.owGround;
const { makeRover, driveStep, slideOut, roverCam, roverDraw } = P.owDrive;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const GRAV = 26, RMIN = 12, RMAX = 170, BLAST = 5.5, RELOAD = 0.75;

P.ow.uplink = function(){
  const G = groundBegin({ sky: 'ember', input: { touch: 'tap' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: DRIVE · TAP WHERE THE SHELL SHOULD LAND', 'W/S A/D: DRIVE · CLICK WHERE THE SHELL SHOULD LAND · or HOLD SPACE TO SET THE RANGE, RELEASE TO LOB · Q/E: TURN THE LAUNCHER');

  const me = makeRover({ max: 22 });
  let score = 0, hits = 0, shots = 0, longest = 0, over = false, finished = false, msg = '', msgT = 0;
  let reload = 0, aimYaw = 0, aimOff = 0, charge = 0, charging = false, wind = [0, 0, 0], windT = 0, wasFire = false;
  const shells = [], taps = [];
  const targets = makeField({
    cell: 110, dims: 2, seed: 7373, radius: 560,
    gen(cx, cy, cz, g){
      if(g() < 0.25 || (cx === 0 && cz === 0)) return [];
      const p = [(cx + 0.2 + g() * 0.6) * 110, 0, (cz + 0.2 + g() * 0.6) * 110];
      const convoy = g() < 0.3;
      return [{ p, home: V.copy(p), k: convoy ? 'convoy' : 'dish', yaw: g() * TAU, ph: g() * TAU, sp: 4 + g() * 4 }];
    }
  });
  const city = makeCity({ seed: 7474, density: 0.24, cell: 80, clear: 40, hMin: 12, hMax: 45, radius: 640, towerColor: '#140a06' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ff8a3a,#ffd27a)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  const cv = aCanvas;
  const onTouch = e => {
    if(!e.isTrusted) return;
    const rc = cv.getBoundingClientRect();
    for(const t of e.changedTouches){ const u = (t.clientX - rc.left) / Math.max(1, rc.width); if(u >= 0.5) taps.push([t.clientX - rc.left, t.clientY - rc.top]); }
  };
  if(cv) cv.addEventListener('touchstart', onTouch, { passive: true });
  const prevStop = onStopGame;
  onStopGame = () => { try{ if(cv) cv.removeEventListener('touchstart', onTouch); }catch(e){} if(prevStop) prevStop(); };

  const muzzle = () => [me.p[0], 2.6, me.p[2]];
  // At 45°, the speed that lands a shell `range` away on flat ground (no wind).
  function lob(yaw, range){
    if(reload > 0 || over) return;
    range = clamp(range, RMIN, RMAX);
    reload = RELOAD;
    shots++;
    const v0 = Math.sqrt(GRAV * range);
    const d = [-Math.sin(yaw), 0, -Math.cos(yaw)];
    shells.push({ p: muzzle(), v: [d[0] * v0 * Math.SQRT1_2, v0 * Math.SQRT1_2, d[2] * v0 * Math.SQRT1_2], from: V.copy(me.p) });
    snd('missile');
    fx.flash(muzzle(), '#ffd27a', 1.2, 0.1);
    w.kick(0.3);
  }
  function landing(yaw, range){
    const d = [-Math.sin(yaw), 0, -Math.cos(yaw)];
    return V.add(me.p, V.mul(d, clamp(range, RMIN, RMAX)));
  }
  function boom(p, from){
    fx.explode([p[0], 0.8, p[2]], 2.4, { color: '#ff8a3a', debrisGeo: 'rock2', debrisColor: '#3a2a20', ringNormal: [0, 1, 0], grav: 20 });
    snd('explode');
    let n = 0;
    targets.near(p, t => {
      if(Math.hypot(t.p[0] - p[0], t.p[2] - p[2]) > BLAST + (t.k === 'convoy' ? 1.6 : 2.2)) return;
      targets.kill(t);
      n++; hits++;
      const range = Math.hypot(t.p[0] - from[0], t.p[2] - from[2]);
      longest = Math.max(longest, range);
      const pts = 25 + Math.round(range * 0.5) + (t.k === 'convoy' ? 30 : 0);
      score += pts; setLive(score);
      fx.explode([t.p[0], 2, t.p[2]], 3.2, { color: '#ffb36a', debrisGeo: 'slab', debrisColor: '#4a4f58' });
      snd('bigExplode');
      w.pop([t.p[0], 7, t.p[2]], '+' + pts + ' · ' + Math.round(range) + ' m', '#ffd27a', { size: 15 });
    });
    if(n > 1){ score += 40 * (n - 1); setLive(score); say('×' + n + ' IN ONE SHELL', 1.6); }
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('uplink', score, {
      '📡 Barrage': why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '🎯 Targets Hit': hits,
      '💣 Shells Lobbed': shots,
      '📏 Longest Hit': Math.round(longest) + ' m',
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, hits, shots, shells: shells.length, wind: wind.map(v => +v.toFixed(1)) }),
    hitNearest(){ let best = null, bd = 1e12; targets.each(t => { const d = V.d2(t.p, me.p); if(d < bd){ bd = d; best = t; } }); if(best){ boom(V.copy(best.p), me.p); return true; } return false; },
    lobAt(range){ reload = 0; lob(aimYaw, range || 60); }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      driveStep(me, I, dt, hud, { mouseDrive: false });
      city.update(me.p);
      targets.update(me.p);
      if(slideOut(me, city, 1.3)) me.hit = 0.15;
      reload = Math.max(0, reload - dt);
      windT -= dt;
      if(windT <= 0){
        windT = 18;
        const a = Math.random() * TAU, s = rr(1, 6) * Math.min(1.4, diff);
        wind = [Math.cos(a) * s, 0, Math.sin(a) * s];
        say('🌬 THE WIND SHIFTS', 1.6);
      }
      // Aim: the mouse on the ground, else the launcher's own yaw (Q/E) off the nose.
      let aimRange = null;
      if(I.device === 'mouse' && I.mouseOn && hud.cam){
        const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
        if(g){ aimYaw = Math.atan2(-(g[0] - me.p[0]), -(g[2] - me.p[2])); aimRange = Math.hypot(g[0] - me.p[0], g[2] - me.p[2]); }
        if(I.fire && !wasFire && aimRange != null) lob(aimYaw, aimRange);
      }else{
        const k = I.keys || {};
        const turn = (k.KeyE ? 1 : 0) - (k.KeyQ ? 1 : 0) + (I.pad ? I.pad.rx : 0);
        aimOff = wrapAng(aimOff - turn * 1.6 * dt);
        aimYaw = wrapAng(me.yaw + aimOff);
        if(I.fire && I.device !== 'touch'){ charging = true; charge = Math.min(1, charge + dt / 1.4); }
        else if(charging){ charging = false; lob(aimYaw, RMIN + charge * (RMAX - RMIN)); charge = 0; }
      }
      wasFire = I.fire;
      while(taps.length && hud.cam){
        const t = taps.shift();
        const g = screenToGround(hud, t[0], t[1], 0);
        if(g){ aimYaw = Math.atan2(-(g[0] - me.p[0]), -(g[2] - me.p[2])); reload = Math.min(reload, 0.2); lob(aimYaw, Math.hypot(g[0] - me.p[0], g[2] - me.p[2])); }
      }
      me.aimRange = aimRange != null ? aimRange : (charging ? RMIN + charge * (RMAX - RMIN) : null);
      // Convoys drive their beat.
      targets.each(t => { if(t.k === 'convoy'){ t.ph += dt * t.sp / 30; t.p = [t.home[0] + Math.cos(t.ph) * 30, 0, t.home[2] + Math.sin(t.ph * 2) * 12]; t.yaw = Math.atan2(-(-Math.sin(t.ph) * 30), -(Math.cos(t.ph * 2) * 24)); } });
    }
    if(dt > 0){
      for(let i = shells.length - 1; i >= 0; i--){
        const s = shells[i];
        s.v = V.add(s.v, [wind[0] * dt, -GRAV * dt, wind[2] * dt]);
        s.p = V.madd(s.p, s.v, dt);
        const tb = city.hit(s.p, 0.3);
        if((tb && s.p[1] < tb.h) || s.p[1] <= 0){ shells.splice(i, 1); boom([s.p[0], 0, s.p[2]], s.from); }
      }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    roverCam(w, me, dt, { back: 15, up: 10, ahead: 20, fov: 60 });
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 180, color: '#5a2a0a', glow: 0.8, major: 6, floor: '#0a0503', rough: 0.3 });
    city.draw(w);
    const eye = w.cam.eye;
    targets.each(t => {
      if(V.d2(t.p, eye) > 500 * 500 || !r.viewDepth([t.p[0], 3, t.p[2]], 1.4)) return;
      // ✨ v60 · PAINTED, NOT LIT (see ENEMY_PAINT): red dishes on their masts,
      // orange tanks — no emissive, no beacon glow, no lamp hung over them.
      if(t.k === 'dish'){
        r.draw('cylinder', { pos: [t.p[0], 2, t.p[2]], scale: [1.2, 4, 1.2], color: '#2a2a34', metallic: 0.8, roughness: 0.3 });
        r.draw('turret', { pos: [t.p[0], 4.4, t.p[2]], rot: [0, t.yaw + w.t * 0.3, 0], scale: 2, ...P.kit.foeLook('#ff4a4a', false) });
      }else{
        r.draw('tank', { pos: [t.p[0], 1.2, t.p[2]], rot: [0, t.yaw, 0], scale: 2.4, ...P.kit.foeLook('#ff8a3a', false) });
      }
      P.kit.foeShadow(r, t.p[0], t.p[2], 2.6);
    });
    for(const s of shells){ r.glow(s.p, 0.9, '#ffe0a0', 2); r.streak(V.madd(s.p, V.norm(s.v), -3), s.p, 0.32, '#ffb36a', 2, 0.9); }
    // The launcher, its barrel on the aim, and the arc it would fly with no wind.
    roverDraw(w, me, colour);
    const ad = [-Math.sin(aimYaw), 0, -Math.cos(aimYaw)];
    // ✨ v59 · the barrel ENDS where the shell leaves (it used to start there)
    r.beam(V.sub(muzzle(), [ad[0] * 1.6, 1.6, ad[2] * 1.6]), muzzle(), 0.45, { color: '#c9d1dd', metallic: 0.7, roughness: 0.3 });
    if(me.aimRange != null){
      const land = landing(aimYaw, me.aimRange), range = clamp(me.aimRange, RMIN, RMAX);
      const v0 = Math.sqrt(GRAV * range) * Math.SQRT1_2;
      for(let i = 1; i < 16; i++){
        const t = i / 16 * (2 * v0 / GRAV);
        const q = [me.p[0] + ad[0] * v0 * t, 2.6 + v0 * t - GRAV * t * t / 2, me.p[2] + ad[2] * v0 * t];
        r.glowFx(q, 0.35, '#ffd27a', 0.8);
      }
      groundRing(w, land, BLAST, reload > 0 ? '#8a6a4a' : '#ffd27a', 1.0);
    }
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H, ctx = hud.ctx;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    const rad = [];
    targets.each(t => { if(V.d2(t.p, me.p) < 260 * 260) rad.push({ p: t.p, c: t.k === 'convoy' ? '#ffb36a' : '#ff4a4a', s: 2.6 }); });
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], RMAX, rad);
    // The wind sock: drawn relative to where the camera looks.
    const ws = Math.hypot(wind[0], wind[2]);
    const camYaw = hud.cam ? Math.atan2(-hud.cam.f[0], -hud.cam.f[2]) : me.yaw;
    const wa = Math.atan2(-wind[0], -wind[2]) - camYaw;
    const cx = Wd - 60, cy = 60;
    ctx.save();
    ctx.translate(cx, cy); ctx.rotate(-wa - Math.PI / 2);
    ctx.strokeStyle = '#bff6ff'; ctx.fillStyle = '#bff6ff'; ctx.shadowColor = '#bff6ff'; ctx.shadowBlur = 6; ctx.lineWidth = 2.4;
    const L = 8 + ws * 4;
    ctx.beginPath(); ctx.moveTo(-L, 0); ctx.lineTo(L, 0); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(L + 6, 0); ctx.lineTo(L - 3, -6); ctx.lineTo(L - 3, 6); ctx.closePath(); ctx.fill();
    ctx.restore();
    hud.text(cx, cy + 34, '🌬 ' + ws.toFixed(1), { size: 11, color: '#bff6ff' });
    if(me.aimRange != null) hud.text(Wd / 2, 26, Math.round(clamp(me.aimRange, RMIN, RMAX)) + ' m' + (reload > 0 ? ' · RELOADING' : ''), { size: 14, color: reload > 0 ? '#c8a888' : '#ffd27a' });
    hud.text(Wd - 16, Ht - 40, '🎯 ' + hits, { size: 13, align: 'right', color: '#ffd27a' });
    hud.text(Wd - 16, Ht - 20, 'LONGEST ' + Math.round(longest) + ' m', { size: 12, align: 'right', color: '#ffe8c8' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.boostE / 100, '#ff8a3a', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 52, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🧱 MATRIX DROP · OPEN WORLD — THE ENDLESS FLOOR
// ══════════════════════════════════════════════
// The classic well is ten wide. This one has no walls at all: the blocks fall
// on an endless floor, you steer each one anywhere over it, and they stack up
// in three dimensions. Any ten in a row — along either axis, at any height —
// clear, and what stood on them drops. Several at once pay far more than one,
// as ever. Build too high (ten levels) and the stack topples.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ease, drawFloor, owClock } = P.owKit;
const { groundBegin, followCam } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const S = 2, TOP = 10, RUN = 10;
const PIECES = [
  { n: 'I', c: '#00f5ff', b: [[-1, 0], [0, 0], [1, 0], [2, 0]] },
  { n: 'O', c: '#ffd700', b: [[0, 0], [1, 0], [0, 1], [1, 1]] },
  { n: 'T', c: '#a855f7', b: [[-1, 0], [0, 0], [1, 0], [0, 1]] },
  { n: 'S', c: '#39ff88', b: [[0, 0], [1, 0], [-1, 1], [0, 1]] },
  { n: 'Z', c: '#ff2d6a', b: [[-1, 0], [0, 0], [0, 1], [1, 1]] },
  { n: 'J', c: '#4d8bff', b: [[-1, 0], [0, 0], [1, 0], [1, 1]] },
  { n: 'L', c: '#ff8a3a', b: [[-1, 0], [0, 0], [1, 0], [-1, 1]] }
];

P.ow.tetris = function(){
  const G = groundBegin({ sky: 'night', env: { horizon: '#1a2a6a' }, input: { touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: MOVE · ALT: ROTATE · JUMP: DROP · BOOST: FALL FASTER', 'WASD / ARROWS: MOVE OVER THE FLOOR · Q/E: ROTATE · SPACE: DROP · SHIFT: FALL FASTER');
  inp.altLabel = 'ROT';

  const grid = new Map();                          // "x,y,z" → colour
  const tops = new Map();                          // "x,z" → height of the column
  const K = (x, y, z) => x + ',' + y + ',' + z, C = (x, z) => x + ',' + z;
  let score = 0, lines = 0, pieces = 0, best = 0, lives = 3, over = false, finished = false, msg = '', msgT = 0;
  let cur = null, next = (Math.random() * 7) | 0, fallT = 0, moveT = 0, lastDir = null, camP = [0, 0, 0];
  const flashes = [];
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#00f5ff,#a855f7,#ffd700)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  const height = (x, z) => tops.get(C(x, z)) || 0;
  const cells = pc => pc.b.map(([a, b]) => { let u = a, v = b; for(let i = 0; i < pc.rot; i++){ const t = u; u = -v; v = t; } return [pc.x + u, pc.z + v]; });
  const fits = (pc, y) => y >= 0 && cells(pc).every(([x, z]) => !grid.has(K(x, y, z)));
  const restY = pc => { let y = pc.y; while(fits(pc, y - 1)) y--; return y; };
  function spawn(){
    const t = next;
    next = (Math.random() * 7) | 0;
    const x = cur ? cur.x : 0, z = cur ? cur.z : 0;
    const pc = { t, b: PIECES[t].b, c: PIECES[t].c, x, z, rot: 0, y: 0 };
    let h = 0;
    for(const [cx, cz] of cells(pc)) h = Math.max(h, height(cx, cz));
    pc.y = h + 7;
    cur = pc;
    fallT = 0;
  }
  // Every run through a cell at level y, along x and along z: ten or more clear.
  function runAt(x, y, z, dx, dz){
    let a = 0, b = 0;
    while(grid.has(K(x - (a + 1) * dx, y, z - (a + 1) * dz))) a++;
    while(grid.has(K(x + (b + 1) * dx, y, z + (b + 1) * dz))) b++;
    return { n: a + b + 1, from: [x - a * dx, z - a * dz] };
  }
  function land(){
    const y = cur.y;
    const placed = cells(cur);
    let topped = false;
    for(const [x, z] of placed){
      grid.set(K(x, y, z), cur.c);
      tops.set(C(x, z), Math.max(height(x, z), y + 1));
      if(y + 1 > TOP) topped = true;
    }
    pieces++;
    score += 5; setLive(score);
    snd('land');
    // Lines.
    const kill = new Set();
    let runs = 0;
    for(const [x, z] of placed){
      for(const [dx, dz] of [[1, 0], [0, 1]]){
        const rn = runAt(x, y, z, dx, dz);
        if(rn.n >= RUN){
          const key = rn.from.join(',') + ':' + dx + ',' + dz + ':' + y;
          if(!kill.has('R' + key)){ kill.add('R' + key); runs++; }
          for(let i = 0; i < rn.n; i++) kill.add(K(rn.from[0] + i * dx, y, rn.from[1] + i * dz));
        }
      }
    }
    const gone = [...kill].filter(k => k[0] !== 'R');
    if(runs){
      lines += runs;
      best = Math.max(best, runs);
      const pts = Math.round(100 * runs * (1 + (runs - 1) * 0.5));
      score += pts; setLive(score);
      snd(runs > 1 ? 'combo' : 'lineClear');
      for(const k of gone){
        const [x, yy, z] = k.split(',').map(Number);
        grid.delete(k);
        flashes.push({ p: [x * S, yy * S + S / 2, z * S], t: 0 });
      }
      // What stood on a cleared cell drops into it.
      for(const k of gone){
        const [x, yy, z] = k.split(',').map(Number);
        let h = height(x, z);
        for(let yv = yy + 1; yv < h; yv++){
          const c = grid.get(K(x, yv, z));
          grid.delete(K(x, yv, z));
          if(c) grid.set(K(x, yv - 1, z), c);
        }
        let t = 0; for(let yv = 0; yv < h + 1; yv++) if(grid.has(K(x, yv, z))) t = yv + 1;
        tops.set(C(x, z), t);
      }
      const at = [cur.x * S, y * S + 4, cur.z * S];
      w.pop(at, (runs > 1 ? runs + ' LINES · ' : 'LINE · ') + '+' + pts, '#ffd27a', { size: 17 });
      fx.explode(at, 1.6 + runs * 0.6, { color: '#ffd27a', debris: 0, smoke: 0 });
    }
    if(topped){
      // The column that went over the top topples: its blocks shatter.
      lives--;
      snd('shatter'); w.kick(1);
      for(const [x, z] of placed){
        const h = height(x, z);
        for(let yv = 0; yv < h; yv++){ if(grid.delete(K(x, yv, z))) fx.sparks([x * S, yv * S + 1, z * S], 3, '#ff8a8a', 0.8, 8); }
        tops.set(C(x, z), 0);
      }
      bar.style.width = (Math.max(0, lives) / 3 * 100) + '%';
      say('⚠ TOPPLED — ' + Math.max(0, lives) + ' left', 2);
      if(lives <= 0){
        if(survivedFatal()){ lives = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); }
        else{ over = true; gLater(() => finish('topple'), 900); return; }
      }
    }
    spawn();
  }
  function tryMove(dx, dz){
    const t = Object.assign({}, cur, { x: cur.x + dx, z: cur.z + dz });
    if(fits(t, cur.y)){ cur.x += dx; cur.z += dz; snd('move'); }
  }
  function tryRotate(d){
    const t = Object.assign({}, cur, { rot: (cur.rot + d + 4) % 4 });
    for(const [kx, kz] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]){
      t.x = cur.x + kx; t.z = cur.z + kz;
      if(fits(t, cur.y)){ cur.rot = t.rot; cur.x = t.x; cur.z = t.z; snd('rotate'); return; }
    }
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('tetris', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'TOPPLED',
      '🧱 Lines Cleared': lines,
      '✦ Best Drop': best + (best === 1 ? ' line' : ' lines'),
      '🔷 Pieces Placed': pieces,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, lines, pieces, lives, blocks: grid.size, piece: cur && PIECES[cur.t].n, y: cur && cur.y }),
    // Lay nine in a row and drop an I piece into the tenth.
    line(){
      const x0 = cur.x + 6, z0 = cur.z + 6;
      for(let i = 0; i < 9; i++){ grid.set(K(x0 + i, 0, z0), '#888888'); tops.set(C(x0 + i, z0), 1); }
      cur = { t: 0, b: PIECES[0].b, c: PIECES[0].c, x: x0 + 10, z: z0, rot: 0, y: 0 };
      land();
      return lines;
    },
    drop(){ cur.y = restY(cur); land(); },
    lose(){ for(const [x, z] of cells(cur)){ for(let y = 0; y < TOP; y++) grid.set(K(x, y, z), '#666666'); tops.set(C(x, z), TOP); } cur.y = TOP; land(); }
  };
  spawn();

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over && cur){
      // Moves: an edge steps once, a held direction repeats.
      const k = I.keys || {}, pr = I.pressed || {};
      let dx = 0, dz = 0;
      if(I.lx < -0.5) dx = -1; else if(I.lx > 0.5) dx = 1;
      if(I.ly < -0.5) dz = -1; else if(I.ly > 0.5) dz = 1;
      const dir = dx || dz ? dx + ',' + dz : null;
      if(dir !== lastDir){ moveT = 0; if(dir) tryMove(dx, dz); }
      else if(dir){ moveT += dt; if(moveT > 0.22){ moveT -= 0.075; tryMove(dx, dz); } }
      lastDir = dir;
      if(pr.KeyE || pr.KeyR || I.altHit) tryRotate(1);
      if(pr.KeyQ) tryRotate(-1);
      if(pr.Space || I.jumpHit){ cur.y = restY(cur); land(); }
      else{
        const rate = Math.max(0.16, 0.75 - pieces * 0.006) / Math.min(1.5, diff);
        fallT += dt * (I.boost ? 6 : 1);
        if(fallT >= rate){
          fallT = 0;
          if(fits(cur, cur.y - 1)) cur.y--;
          else land();
        }
      }
    }
    for(let i = flashes.length - 1; i >= 0; i--){ flashes[i].t += dt; if(flashes[i].t > 0.5) flashes.splice(i, 1); }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    if(cur && dt > 0) camP = V.lerp(camP, [cur.x * S, 0, cur.z * S], ease(dt, 0.15));
    followCam(w, camP, { height: 34, back: 24, look: 2, fov: 56, half: 0.1 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: S, radius: 90, color: '#13306a', glow: 0.7, major: RUN, floor: '#03040c', rough: 0.2 });
    const eye = w.cam.eye;
    for(const [k, c] of grid){
      const [x, y, z] = k.split(',').map(Number);
      const p = [x * S, y * S + S / 2, z * S];
      if(V.d2(p, eye) > 110 * 110) continue;
      r.draw('cube', { pos: p, scale: S * 0.96, color: c, metallic: 0.3, roughness: 0.35, rim: 0.7, emissive: c, emissiveStrength: 0.35 });
    }
    // Rows that are close: a guide line under every run of six or more.
    if(cur){
      const ghost = restY(cur);
      for(const [x, z] of cells(cur)){
        r.draw('cube', { pos: [x * S, cur.y * S + S / 2, z * S], scale: S * 0.96, color: cur.c, metallic: 0.3, roughness: 0.3, emissive: cur.c, emissiveStrength: 1.2 });
        r.draw('cube', { pos: [x * S, ghost * S + S / 2, z * S], scale: S * 0.9, color: cur.c, emissive: cur.c, emissiveStrength: 0.6, alpha: 0.25, blend: true });
        r.streak([x * S, ghost * S + S, z * S], [x * S, cur.y * S, z * S], 0.08, cur.c, 0.6, 0);
      }
      for(const [x, z] of cells(cur)){
        for(const [dx, dz] of [[1, 0], [0, 1]]){
          const rn = runAt(x, ghost, z, dx, dz);
          if(rn.n >= 6){
            const a = [rn.from[0] * S - dx * S / 2, ghost * S + 0.1, rn.from[1] * S - dz * S / 2];
            r.beam(a, [a[0] + dx * RUN * S, a[1], a[2] + dz * RUN * S], 0.25, { color: '#ffd27a', emissive: '#ffd27a', emissiveStrength: 1.4 * Math.min(1, rn.n / RUN) });
          }
        }
      }
      r.light({ pos: [cur.x * S, cur.y * S + 6, cur.z * S], color: cur.c, intensity: 120, range: 30 });
    }
    // The ceiling: ten levels up, a faint lid.
    if(cur) r.draw('thintorus', { pos: [cur.x * S, TOP * S, cur.z * S], scale: [10, 1, 10], color: '#ff4a6a', emissive: '#ff4a6a', emissiveStrength: 0.8 });
    for(const f of flashes) r.fire(f.p, 2.6, 2 * (1 - f.t / 0.5), 0.1 + f.t, 0.71);   // ✨ v59
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.text(Wd / 2, 26, 'TEN IN A ROW CLEARS · ' + lines + ' cleared', { size: 13, color: '#bff6ff' });
    if(cur) hud.text(Wd - 16, Ht - 62, 'NEXT ' + PIECES[next].n, { size: 14, align: 'right', color: PIECES[next].c });
    hud.text(Wd - 16, Ht - 40, 'HEIGHT ' + (cur ? Math.max(...cells(cur).map(([x, z]) => height(x, z))) : 0) + ' / ' + TOP, { size: 12, align: 'right', color: '#ffb8c8' });
    hud.text(Wd - 16, Ht - 20, '▮'.repeat(Math.max(0, lives)) + '▯'.repeat(Math.max(0, 3 - lives)), { size: 14, align: 'right', color: '#bff6ff' });
    if(msgT > 0) hud.text(Wd / 2, 52, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🔷 CORE MERGE · OPEN WORLD — YOU ARE A CORE
// ══════════════════════════════════════════════
// The classic pushes cores together on a lattice: two of a height fuse into
// one taller. Out here the lattice is gone and the core is YOU, rolling over
// an endless plain among thousands of others. Touch one your own size and you
// fuse — twice the core, twice the size. The smaller ones bounce off you. The
// bigger ones hunt you, and a touch from one halves you.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ease, drawFloor, owClock } = P.owKit;
const { groundBegin, followCam, screenToGround, groundRing } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const PAL = ['#00f5ff', '#39ff88', '#ffd700', '#ff8a3a', '#ff2d6a', '#ff2bd6', '#a855f7', '#4d8bff'];
const lg = v => Math.round(Math.log2(v));
const rad = v => 1.1 + 0.5 * lg(v);
const colOf = v => PAL[lg(v) % PAL.length];

P.ow.merge = function(){
  const G = groundBegin({ sky: 'night', env: { horizon: '#2a1060' }, input: { touch: 'fly' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: ROLL · FUSE WITH YOUR SIZE · NEVER TOUCH BIGGER', 'WASD / ARROWS or HOLD THE MOUSE: ROLL · TOUCH A CORE YOUR OWN SIZE TO FUSE · NEVER TOUCH A BIGGER ONE · SHIFT: DASH');

  const me = { p: [0, 0, 0], v: [0, 0, 0], val: 2, inv: 0, dash: 0, dashCd: 0, roll: [0, 0, 0] };
  let score = 0, merges = 0, lives = 3, peak = 2, bumps = 0, over = false, finished = false, msg = '', msgT = 0;
  const cores = [];
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#00f5ff,#a855f7)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  function spawn(force){
    const a = Math.random() * TAU, d = rr(45, 150);
    const p = [me.p[0] + Math.cos(a) * d, 0, me.p[2] + Math.sin(a) * d];
    const u = Math.random();
    let val = me.val;
    if(force === 'equal'){ val = me.val; }
    else if(u < 0.4) val = me.val;
    else if(u < 0.66) val = Math.max(2, me.val / 2);
    else if(u < 0.76) val = Math.max(2, me.val / 4);
    else if(u < 0.92) val = me.val * 2;
    else val = me.val * 4;
    cores.push({ p, v: [0, 0, 0], val, ph: Math.random() * TAU, turn: 0, head: Math.random() * TAU });
  }
  for(let i = 0; i < 26; i++) spawn(i < 8 ? 'equal' : null);

  function fuse(c, i){
    cores.splice(i, 1);
    me.val *= 2;
    merges++;
    peak = Math.max(peak, me.val);
    const pts = 30 + 10 * lg(me.val);
    score += pts; setLive(score);
    snd('match', { semi: Math.min(12, lg(me.val)) });
    fx.explode([me.p[0], rad(me.val), me.p[2]], rad(me.val) * 0.8, { color: colOf(me.val), debris: 0, smoke: 0, ringNormal: [0, 1, 0] });
    w.pop([me.p[0], rad(me.val) * 2 + 2, me.p[2]], me.val.toLocaleString() + ' · +' + pts, colOf(me.val), { size: 16 });
  }
  function bitten(c){
    if(me.inv > 0 || over) return;
    lives--;
    me.val = Math.max(2, me.val / 2);
    me.inv = 1.6;
    const away = V.norm([me.p[0] - c.p[0], 0, me.p[2] - c.p[2]]);
    me.v = V.mul(away, 40);
    snd('hurt'); w.kick(1);
    fx.sparks([me.p[0], 1, me.p[2]], 14, '#ff4a4a', 1.2, 14);
    bar.style.width = (Math.max(0, lives) / 3 * 100) + '%';
    say('✖ BITTEN BY A ' + c.val.toLocaleString() + ' — halved to ' + me.val, 2);
    if(lives <= 0){
      if(survivedFatal()){ lives = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); }
      else{ over = true; gLater(() => finish('bitten'), 1000); }
    }
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('merge', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'DEVOURED',
      '🔷 Fusions': merges,
      '🏔 Biggest Core': peak.toLocaleString(),
      '💥 Bounced Off': bumps,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, val: me.val, merges, lives, cores: cores.length, equals: cores.filter(c => c.val === me.val).length }),
    mergeOne(){ spawn('equal'); const c = cores[cores.length - 1]; c.p = V.add(me.p, [rad(me.val) * 1.5, 0, 0]); return true; },
    lose(){ me.inv = 0; spawn(); const c = cores[cores.length - 1]; c.val = me.val * 4; bitten(c); },
    bite(){ spawn(); const c = cores[cores.length - 1]; c.val = me.val * 4; bitten(c); }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      me.inv = Math.max(0, me.inv - dt);
      me.dashCd = Math.max(0, me.dashCd - dt);
      let mx = I.lx, mz = I.ly;
      if(I.device === 'mouse' && I.mDown && hud.cam){
        const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
        if(g){ const d = V.sub(g, me.p), l = Math.hypot(d[0], d[2]); if(l > 1){ mx = d[0] / l; mz = d[2] / l; } }
      }
      const ml = Math.hypot(mx, mz); if(ml > 1){ mx /= ml; mz /= ml; }
      if(I.boost && me.dashCd <= 0 && ml > 0.1){ me.dash = 0.25; me.dashCd = 2; snd('dash'); }
      me.dash = Math.max(0, me.dash - dt);
      const sp = Math.max(10, 21 - lg(me.val) * 0.6) * (me.dash > 0 ? 2.4 : 1);
      me.v = V.lerp(me.v, [mx * sp, 0, mz * sp], ease(dt, me.dash > 0 ? 0.03 : 0.12));
      me.p = V.madd(me.p, me.v, dt);
      me.roll[0] += me.v[2] / rad(me.val) * dt; me.roll[2] -= me.v[0] / rad(me.val) * dt;
      const R = rad(me.val);
      let equals = 0;
      for(let i = cores.length - 1; i >= 0; i--){
        const c = cores[i];
        const d = V.sub(me.p, c.p), l = Math.hypot(d[0], d[2]) || 1e-3, cr = rad(c.val);
        if(c.val === me.val) equals++;
        // Bigger ones hunt, smaller ones shy off, equals drift.
        c.head += rr(-1, 1) * dt * 1.5;
        let want = [Math.cos(c.head), 0, Math.sin(c.head)], csp = 5;
        if(c.val > me.val && l < 38){ want = [d[0] / l, 0, d[2] / l]; csp = Math.max(7, sp * 0.62) * Math.min(1.3, diff); }
        else if(c.val < me.val && l < 16){ want = [-d[0] / l, 0, -d[2] / l]; csp = 9; }
        c.v = V.lerp(c.v, V.mul(want, csp), ease(dt, 0.5));
        c.p = V.madd(c.p, c.v, dt);
        if(l < R + cr - 0.3){
          if(c.val === me.val){ fuse(c, i); continue; }
          if(c.val < me.val){
            bumps++;
            const n = [-d[0] / l, 0, -d[2] / l];
            c.p = V.madd(me.p, n, R + cr);
            c.v = V.mul(n, 22);
            snd('bounce', { semi: 6 });
          }else bitten(c);
        }
        if(l > 220) cores.splice(i, 1);
      }
      if(cores.length < 26) spawn(equals < 6 ? 'equal' : null);
      // Small fry go stale as you grow: they are cleared off the board.
      for(let i = cores.length - 1; i >= 0; i--) if(cores[i].val < me.val / 8) cores.splice(i, 1);
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    const R = rad(me.val);
    followCam(w, me.p, { height: 26 + R * 5, back: 18 + R * 3, look: 2, fov: 56, half: 0.14 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 180, color: '#2a1a6e', glow: 0.85, major: 5, floor: '#04030c', rough: 0.2 });
    const eye = w.cam.eye;
    let nl = 0;
    for(const c of cores){
      if(V.d2(c.p, eye) > 200 * 200) continue;
      const cr = rad(c.val), col = colOf(c.val);
      const pos = [c.p[0], cr, c.p[2]];
      if(!r.viewDepth(pos, 1.3)) continue;
      r.draw('sphere', { pos, scale: cr * 2, color: col, metallic: 0.3, roughness: 0.25, rim: 1, emissive: col, emissiveStrength: 0.55 });
      const tag = c.val === me.val ? '#39ff88' : c.val > me.val ? '#ff3a3a' : '#5a6a7a';
      r.draw('thintorus', { pos: [c.p[0], 0.1, c.p[2]], scale: [cr * 2.6, 1, cr * 2.6], color: tag, emissive: tag, emissiveStrength: c.val === me.val ? 2.2 : c.val > me.val ? 1.8 : 0.6 });
      if(c.val > me.val && nl++ < 3) r.light({ pos: [c.p[0], cr * 2 + 2, c.p[2]], color: '#ff4a4a', intensity: 60, range: 14 });
    }
    if(!(me.inv > 0 && Math.sin(w.t * 30) > 0)){
      const col = colOf(me.val);
      r.draw('sphere', { pos: [me.p[0], R, me.p[2]], rot: me.roll, scale: R * 2, color: '#e8f0ff', metallic: 0.5, roughness: 0.2, rim: 1.2, emissive: col, emissiveStrength: 0.9 });
      r.draw('torus', { pos: [me.p[0], R, me.p[2]], rot: [Math.PI / 2, w.t, 0], scale: R * 2.8, color: '#cfd8e8', metallic: 0.8, roughness: 0.25, emissive: colour, emissiveStrength: 0.6 });
      r.glow([me.p[0], R, me.p[2]], R * 2, col, 0.6);
    }
    r.light({ pos: [me.p[0], R * 2 + 6, me.p[2] + 3], color: '#e0e8ff', intensity: 150, range: 30 + R * 4 });
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    hud.radar(70, Ht - 74, 54, me.p, [0, 0, -1], 80, cores.filter(c => c.val >= me.val / 2).map(c => ({ p: c.p, c: c.val === me.val ? '#39ff88' : c.val > me.val ? '#ff3a3a' : '#7a8a9a', s: c.val > me.val ? 3 : 2.2 })));
    for(const c of cores){
      if(V.d2(c.p, me.p) > 70 * 70) continue;
      const q = hud.proj([c.p[0], rad(c.val) * 2 + 0.6, c.p[2]]);
      if(q.on) hud.text(q.x, q.y - 6, c.val >= 1024 ? Math.round(c.val / 1024) + 'K' : String(c.val), { size: 11, color: c.val === me.val ? '#9dffc4' : c.val > me.val ? '#ff9a9a' : '#9aaaba' });
    }
    hud.text(Wd / 2, 26, 'YOU ARE ' + me.val.toLocaleString() + ' — fuse with a ' + me.val.toLocaleString(), { size: 14, color: colOf(me.val) });
    hud.text(Wd - 16, Ht - 20, '◆'.repeat(Math.max(0, lives)) + '◇'.repeat(Math.max(0, 3 - lives)), { size: 14, align: 'right', color: '#bff6ff' });
    hud.text(Wd - 16, Ht - 40, '🔷 ' + merges, { size: 13, align: 'right', color: '#bff6ff' });
    if(msgT > 0) hud.text(Wd / 2, 52, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  💽 DEFRAG · OPEN WORLD — THE DATA VOLUME
// ══════════════════════════════════════════════
// The classic clears a board of sectors by reading the numbers. Out here the
// drive is a volume you fly through, its files shattered into fragments that
// drift in every direction. Rebuild one file at a time — fly through the
// fragments of ITS colour. Some fragments are corrupt and look like any
// other: the counter says how many are close (the classic's number), a SCAN
// shows them for a moment, and touching one costs a drive.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owFly) return;
const { V, TAU, makeField, makeDust, drawBodies, owBegin, owClock } = P.owKit;
const { makeFlyer, flyStep, flyCam, drawFlyer } = P.owFly;
const { mine, clamp, runLoop } = P.kit;
const COLS = ['#00f5ff', '#ffd700', '#39ff88', '#ff2bd6', '#ff8a3a', '#a855f7'];
const NAMES = ['CYAN', 'GOLD', 'GREEN', 'PINK', 'ORANGE', 'VIOLET'];
const GRAB = 3.8, NEAR = 26, LAT = 40;

P.ow.defrag = function(){
  const G = owBegin({
    space: { seed: 404, a: '#0e6a6a', b: '#0a1f4a', c: '#39ff88', dir: [0.2, 0.5, -0.84], amount: 0.7, dust: 0.6, galaxy: 0.5 },
    input: { mouseSteer: true, mouseGain: 1.2 }, far: 9000, near: 0.3
  });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  setControlHint('STICK: FLY · ALT: SCAN · BOOST', 'MOUSE / WASD: FLY THROUGH THE FILE\'S FRAGMENTS · F / RIGHT-CLICK: SCAN FOR CORRUPTION · SHIFT: BOOST');
  inp.altLabel = 'SCAN';

  const me = makeFlyer({ p: [0, 0, 0], speed: 30 });
  let score = 0, files = 0, frags = 0, drives = 3, corrupt = 0, over = false, finished = false, msg = '', msgT = 0;
  let fc = 0, need = 5, got = 0, scanT = 0, scanCd = 0, nearBad = 0;
  const vol = makeField({
    cell: 70, dims: 3, seed: 9090, radius: 330,
    gen(cx, cy, cz, g){
      const items = [];
      const n = 3 + Math.floor(g() * 4);
      for(let i = 0; i < n; i++){
        const p = [(cx + g()) * 70, (cy + g()) * 70, (cz + g()) * 70];
        if(V.len(p) < 18) continue;
        items.push({ p, c: (g() * 6) | 0, bad: g() < 0.13, rot: [g() * 6, g() * 6, 0], ph: g() * TAU });
      }
      return items;
    }
  });
  const BODIES = [{ kind: 'gas', off: [-2400, -500, -4800], size: 1800, color: '#1a6a7a', ring: 2, ringRot: [0.6, 0, 0.2], rot: [0.6, 0, 0.2], halo: '#5affd8', par: 0.004 }];
  const dust = makeDust(50, 70);
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#39ff88,#00f5ff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  function nextFile(){
    let n = fc;
    while(n === fc) n = (Math.random() * 6) | 0;
    fc = n; got = 0;
    need = Math.min(10, 5 + files);
    snd('wave');
    say('💽 FILE ' + (files + 1) + ' — ' + NAMES[fc] + ' · ' + need + ' fragments', 2.4);
  }
  function grab(it){
    vol.kill(it);
    if(it.bad){
      corrupt++;
      drives--;
      got = Math.max(0, got - 2);
      snd('glitch'); w.kick(1.2);
      fx.explode(it.p, 2.4, { color: '#ff3a3a', debris: 4, debrisGeo: 'slab', debrisColor: '#3a1a1a' });
      me.hit = 0.4; me.inv = 1;
      bar.style.width = (Math.max(0, drives) / 3 * 100) + '%';
      say('☠ CORRUPT SECTOR — ' + Math.max(0, drives) + ' drives left', 2);
      if(drives <= 0){
        if(survivedFatal()){ drives = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); }
        else{ over = true; gLater(() => finish('corrupt'), 1000); }
      }
      return;
    }
    got++; frags++;
    score += 12; setLive(score);
    snd('pickup', { semi: got });
    fx.glowPop(it.p, COLS[it.c], 2, 0.3);
    if(got >= need){
      files++;
      const pts = 100 + need * 15;
      score += pts; setLive(score);
      snd('success');
      w.pop(V.madd(me.p, me.B.f, 12), '💽 FILE REBUILT +' + pts, COLS[fc], { size: 16 });
      nextFile();
    }
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('defrag', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'DRIVES LOST',
      '💽 Files Rebuilt': files,
      '🧩 Fragments': frags,
      '☠ Corrupt Sectors Hit': corrupt,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, files, got, need, drives, nearBad, fc: NAMES[fc] }),
    collect(n){ let k = 0; vol.each(it => { if(k < (n || 1) && !it.bad && it.c === fc){ grab(it); k++; } }); return k; },
    lose(){ me.inv = 0; grab({ bad: true, p: V.copy(me.p), c: 0, id: 'test' + Math.random() }); },
    hitBad(){ let done = false; vol.each(it => { if(!done && it.bad){ done = true; grab(it); } }); return done; }
  };
  nextFile();

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      flyStep(me, I, dt, { yawRate: 1.7, pitchRate: 1.4 });
      vol.update(me.p);
      scanT = Math.max(0, scanT - dt); scanCd = Math.max(0, scanCd - dt);
      if(I.altHit){
        if(scanCd > 0){ snd('deny'); }
        else{ scanT = 4; scanCd = 7; snd('node'); fx.flash(me.p, '#ff6a6a', 2, 0.25); }
      }
      nearBad = 0;
      vol.near(me.p, it => {
        const d2 = V.d2(it.p, me.p);
        if(it.bad && d2 < NEAR * NEAR) nearBad++;
        // Another file's fragments drift straight through you.
        if(d2 < GRAB * GRAB && (it.bad ? me.inv <= 0 : it.c === fc)) grab(it);
      });
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    flyCam(w, me, dt, { fov: 64 });
    w.step(dt);

    w.begin();
    drawBodies(w, BODIES);
    // The lattice: the drive's own grid, standing still while you fly through it.
    const gx = Math.round(me.p[0] / LAT) * LAT, gy = Math.round(me.p[1] / LAT) * LAT, gz = Math.round(me.p[2] / LAT) * LAT;
    for(let i = -2; i <= 2; i++) for(let j = -2; j <= 2; j++){
      const k = 0.35 - 0.06 * (Math.abs(i) + Math.abs(j));
      r.streak([gx - 100, gy + i * LAT, gz + j * LAT], [gx + 100, gy + i * LAT, gz + j * LAT], -0.06, '#1a8a7a', k, 0);
      r.streak([gx + i * LAT, gy - 100, gz + j * LAT], [gx + i * LAT, gy + 100, gz + j * LAT], -0.06, '#1a8a7a', k, 0);
      r.streak([gx + i * LAT, gy + j * LAT, gz - 100], [gx + i * LAT, gy + j * LAT, gz + 100], -0.06, '#1a8a7a', k, 0);
    }
    const eye = w.cam.eye;
    let nl = 0;
    vol.each(it => {
      const d2 = V.d2(it.p, eye);
      if(d2 > 300 * 300 || !r.viewDepth(it.p, 1.2)) return;
      // Corrupt fragments wear a random file's colour — unless scanned, or
      // for the odd frame where the glitch shows through.
      const glitch = it.bad && (scanT > 0 || Math.sin(w.t * 1.7 + it.ph * 7) > 0.985);
      const col = glitch ? '#ff2a2a' : COLS[it.c];
      const mineFile = !it.bad && it.c === fc;
      const s = mineFile ? 1.5 : 1.2;
      r.draw('cube', { pos: it.p, rot: [it.rot[0] + w.t * 0.6, it.rot[1] + w.t * 0.9, 0], scale: s, color: col, metallic: 0.3, roughness: 0.3, emissive: col,
                       emissiveStrength: mineFile ? 1.8 : glitch ? 2.4 : 0.7, detail: 0 });
      if(mineFile || glitch) r.glow(it.p, s * 1.8, col, mineFile ? 0.7 : 1);
      if(glitch && nl++ < 2) r.light({ pos: it.p, color: '#ff3a3a', intensity: 60, range: 12 });
    });
    if(scanT > 0) r.draw('lowsphere', { pos: me.p, scale: 2 * NEAR * (1 - scanT / 4 * 0.2), color: '#ff6a6a', emissive: '#ff4a4a', emissiveStrength: 0.4, alpha: 0.06 * scanT, blend: true });
    drawFlyer(w, me, colour);
    dust(w, V.mul(me.B.f, me.speed), { len: 0.045, max: 6, gain: 0.35, width: 0.03 });
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    const rad = [];
    vol.each(it => { if(!it.bad && it.c === fc && V.d2(it.p, me.p) < 160 * 160) rad.push({ p: it.p, c: COLS[fc], s: 2.4, tick: true }); else if(it.bad && scanT > 0 && V.d2(it.p, me.p) < 90 * 90) rad.push({ p: it.p, c: '#ff3a3a', s: 2, tick: true }); });
    hud.radar(70, Ht - 74, 54, me.p, me.B.f, 120, rad);
    hud.text(Wd / 2, 26, '💽 ' + NAMES[fc] + '  ' + got + ' / ' + need, { size: 16, color: COLS[fc] });
    hud.bar(Wd / 2 - 80, 42, 160, 6, got / need, COLS[fc]);
    hud.text(Wd / 2, 62, nearBad ? '☠ ' + nearBad + ' CORRUPT NEARBY' : '· clear ·', { size: 12, color: nearBad ? '#ff8a8a' : '#7affc8' });
    // The nearest fragment of the file, if it is off-screen.
    let best = null, bd = 1e12;
    vol.each(it => { if(!it.bad && it.c === fc){ const d = V.d2(it.p, me.p); if(d < bd){ bd = d; best = it; } } });
    if(best && !hud.proj(best.p).on) hud.edgeArrow(best.p, COLS[fc], null);
    hud.text(Wd - 16, Ht - 40, scanCd > 0 ? 'SCAN ' + Math.ceil(scanCd) + 's' : 'SCAN READY', { size: 12, align: 'right', color: scanCd > 0 ? '#8aa' : '#ff9a9a' });
    hud.text(Wd - 16, Ht - 20, 'DRIVES ' + '▮'.repeat(Math.max(0, drives)) + '▯'.repeat(Math.max(0, 3 - drives)), { size: 13, align: 'right', color: '#9dffc4' });
    hud.bar(Wd / 2 - 70, Ht - 18, 140, 7, me.energy / 100, '#39ff88', 'BOOST');
    if(msgT > 0) hud.text(Wd / 2, 84, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  ⚡ PATH · OPEN WORLD — CABLE ACROSS THE ENDLESS BOARD
// ══════════════════════════════════════════════
// The classic routes current through every live node once, never crossing
// its own trace. Out here the board has no edge: you are the head of a power
// cable crawling across it square by square, and every relay you reach is
// powered and locks the cable in behind you — and overclocks the grid, so the
// next relay pays more. Cross your own trace or run the spool dry and the
// live cable shorts out back to the last relay, and the overclock with it.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ihash, ease, drawFloor, owClock } = P.owKit;
const { groundBegin, followCam, screenToGround, beacon } = P.owGround;
const { mine, clamp, runLoop, seeded } = P.kit;
const S = 4, SPOOL = 34, OC_MAX = 6;
const DIRS = [[0, -1], [1, 0], [0, 1], [-1, 0]];

P.ow.path = function(){
  const G = groundBegin({ sky: 'night', env: { horizon: '#0a3a5a' }, input: { touch: 'tap' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: STEER THE CABLE · REACH THE RELAYS', 'WASD / ARROWS or THE MOUSE: STEER THE CABLE HEAD · REACH A RELAY BEFORE THE SPOOL RUNS DRY · NEVER CROSS YOUR TRACE');

  // The board, as pure functions of the square.
  // Memoised: the board is drawn and searched thousands of squares a frame.
  const key = (x, z) => x + ',' + z;
  const kinds = new Map();
  const kindAt = (x, z) => {
    const k = key(x, z);
    let v = kinds.get(k);
    if(v === undefined){
      v = (Math.abs(x) + Math.abs(z) > 3 && seeded(ihash(x, z, 1, 5151))() < 0.03) ? 1
        : (Math.abs(x) + Math.abs(z) > 2 && seeded(ihash(x, z, 2, 5252))() < 0.07) ? 2 : 0;
      kinds.set(k, v);
    }
    return v;
  };
  const relayAt = (x, z) => kindAt(x, z) === 1;
  const deadAt = (x, z) => kindAt(x, z) === 2;
  const cable = new Map();                      // square → { locked, oc }
  const powered = new Set();
  let live = [];                                // squares laid since the last relay
  let head = [0, 0], prev = [0, 0], dir = 0, want = 0, stepT = 0, pause = 0, last = [0, 0];
  let score = 0, relays = 0, shorts = 0, oc = 1, bestOc = 1, laid = 0, over = false, finished = false, msg = '', msgT = 0;
  cable.set(key(0, 0), { locked: true, oc: 1 });
  powered.add(key(0, 0));
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#00f5ff,#ffd700)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };
  const stepTime = () => Math.max(0.11, 0.17 - relays * 0.0015) / Math.min(1.3, diff);

  // 🔌 v60 · COMPLETING the circuit: power RELAY_GOAL relays and the mission
  // is done — it pays its full cap, as the classic board does when every
  // square is routed. What the run banks after that is carried past the cap,
  // where it separates two finished circuits.
  const RELAY_GOAL = 20;
  function connect(x, z){
    relays++;
    if(relays === RELAY_GOAL){
      snd('victory'); w.kick(1.4);
      say('🔌 CIRCUIT COMPLETE — FULL ' + META.path.maxPts + ' BANKED · KEEP ROUTING', 3.2);
    }
    powered.add(key(x, z));
    for(const k of live){ const c = cable.get(k); if(c) c.locked = true; }
    const left = SPOOL - live.length;
    const pts = 15 * oc + Math.max(0, left);
    score += pts; setLive(score);
    oc = Math.min(OC_MAX, oc + 1); bestOc = Math.max(bestOc, oc);
    live = [];
    last = [x, z];
    snd('success', { semi: oc });
    const p = [x * S, 2, z * S];
    fx.explode(p, 1.8, { color: '#ffd700', debris: 0, smoke: 0, ringNormal: [0, 1, 0] });
    w.pop([p[0], 6, p[2]], '+' + pts + ' · OVERCLOCK ×' + oc, '#ffd700', { size: 15 });
  }
  function short(why){
    shorts++;
    for(const k of live) cable.delete(k);
    live = [];
    head = [last[0], last[1]]; prev = [last[0], last[1]];
    oc = 1;
    pause = 0.7;
    snd('glitch'); w.kick(0.9);
    fx.sparks([head[0] * S, 1, head[1] * S], 18, '#ff4a4a', 1.2, 14);
    say(why + ' — back to the last relay, overclock lost', 2);
    // Face a free way out.
    for(let k = 0; k < 4; k++){
      const d = (dir + k) % 4, nx = head[0] + DIRS[d][0], nz = head[1] + DIRS[d][1];
      if(!cable.has(key(nx, nz)) && !deadAt(nx, nz)){ dir = want = d; break; }
    }
  }
  function advance(){
    if(want !== (dir + 2) % 4) dir = want;
    const nx = head[0] + DIRS[dir][0], nz = head[1] + DIRS[dir][1];
    prev = [head[0], head[1]];
    if(cable.has(key(nx, nz))){ short('⚡ SHORT CIRCUIT'); return; }
    if(deadAt(nx, nz)){ short('⚡ DEAD SQUARE'); return; }
    head = [nx, nz];
    cable.set(key(nx, nz), { locked: false, oc });
    live.push(key(nx, nz));
    laid++;
    if(relayAt(nx, nz)) connect(nx, nz);
    else if(live.length >= SPOOL) short('🧵 SPOOL RAN DRY');
    else if(live.length > SPOOL - 6) snd('tick');
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    const done = relays >= RELAY_GOAL, full = META.path.maxPts;
    owFinish('path', score + (done ? full : 0), {
      '📡 Run': done ? 'CIRCUIT COMPLETE' : why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '⚡ Relays Powered': relays + ' / ' + RELAY_GOAL,
      ...(done ? { '🔌 Circuit Complete': 'FULL ' + full + ' · +' + score + ' past the cap' } : {}),
      '⏫ Best Overclock': '×' + bestOc,
      '🧵 Cable Laid': laid * S + ' m',
      '💥 Shorts': shorts,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, relays, shorts, oc, live: live.length, head: head.slice() }),
    connect(){ connect(head[0], head[1]); },
    short(){ short('TEST'); }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      // Steering: the strongest axis of whatever is pushing.
      let sx = I.lx, sz = I.ly;
      if(I.device === 'mouse' && I.mouseOn && hud.cam){
        const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
        if(g){ const dx = g[0] - head[0] * S, dz = g[2] - head[1] * S; if(Math.hypot(dx, dz) > S * 1.5){ sx = dx; sz = dz; } else{ sx = 0; sz = 0; } }
      }else if(I.stick){ sx = I.stick.x - I.stick.x0; sz = I.stick.y - I.stick.y0; if(Math.hypot(sx, sz) < 0.06){ sx = 0; sz = 0; } }
      if(Math.abs(sx) > 0.3 || Math.abs(sz) > 0.3 || (I.device === 'mouse' && (sx || sz))){
        const d = Math.abs(sx) > Math.abs(sz) ? (sx > 0 ? 1 : 3) : (sz > 0 ? 2 : 0);
        if(d !== (dir + 2) % 4) want = d;
      }
      if(pause > 0) pause -= dt;
      else{
        stepT += dt;
        const st = stepTime();
        while(stepT >= st && !over){ stepT -= st; advance(); }
      }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    const t = pause > 0 ? 1 : clamp(stepT / stepTime(), 0, 1);
    const hp = [(prev[0] + (head[0] - prev[0]) * t) * S, 0, (prev[1] + (head[1] - prev[1]) * t) * S];
    followCam(w, hp, { height: 42, back: 22, look: 3, fov: 54, half: 0.12 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: S, radius: 110, color: '#0f3a5a', glow: 0.7, major: 5, floor: '#020610', rough: 0.25 });
    const R = 22, hx = Math.round(hp[0] / S), hz = Math.round(hp[2] / S);
    let nl = 0;
    for(let x = hx - R; x <= hx + R; x++) for(let z = hz - R; z <= hz + R; z++){
      const p = [x * S, 0, z * S];
      if(relayAt(x, z)){
        const on = powered.has(key(x, z));
        const col = on ? '#ffd700' : '#5ee7ff';
        r.draw('cylinder', { pos: [p[0], 1, p[2]], scale: [2.2, 2, 2.2], color: '#1a2230', metallic: 0.8, roughness: 0.3 });
        r.draw('core', { pos: [p[0], 2.8, p[2]], rot: [0, w.t * (on ? 2 : 0.5), 0], scale: 1.6, color: col, emissive: col, emissiveStrength: on ? 2.2 : 0.9 });
        if(!on){ beacon(w, p, col, 26, 0.5 + 0.3 * Math.sin(w.t * 3 + x)); }
        else if(nl++ < 3) r.light({ pos: [p[0], 5, p[2]], color: '#ffd700', intensity: 80, range: 16 });
      }else if(deadAt(x, z)){
        r.draw('cube', { pos: [p[0], 0.8, p[2]], scale: [S * 0.9, 1.6, S * 0.9], color: '#120c10', metallic: 0.4, roughness: 0.7, emissive: '#ff3a3a', emissiveStrength: 0.25 });
      }
    }
    // The cable: a glowing run between squares, live in white, locked in its overclock's colour.
    const OCC = ['#00f5ff', '#39ff88', '#ffd700', '#ff8a3a', '#ff2d6a', '#ff2bd6'];
    for(const [k, c] of cable){
      const [x, z] = k.split(',').map(Number);
      if(Math.abs(x - hx) > R + 2 || Math.abs(z - hz) > R + 2) continue;
      const col = c.locked ? OCC[(c.oc - 1) % OCC.length] : '#ffffff';
      r.draw('box', { pos: [x * S, 0.35, z * S], scale: [1.2, 0.5, 1.2], color: col, emissive: col, emissiveStrength: c.locked ? 1.5 : 2.4 });
      for(const [dx, dz] of [[1, 0], [0, 1]]){
        const n = cable.get(key(x + dx, z + dz));
        if(n) r.beam([x * S, 0.35, z * S], [(x + dx) * S, 0.35, (z + dz) * S], 0.6, { color: col, emissive: col, emissiveStrength: c.locked ? 1.4 : 2.2, height: 0.4 });
      }
    }
    // The head.
    r.draw('sphere', { pos: [hp[0], 1.2, hp[2]], scale: 2.2, color: '#ffffff', emissive: colour, emissiveStrength: 2.4 });
    r.glow([hp[0], 1.2, hp[2]], 3.2, colour, 1.2);
    r.light({ pos: [hp[0], 5, hp[2]], color: colour, intensity: 140, range: 24 });
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    const rad = [];
    for(let x = hx - 16; x <= hx + 16; x++) for(let z = hz - 16; z <= hz + 16; z++){ if(relayAt(x, z) && !powered.has(key(x, z))) rad.push({ p: [x * S, 0, z * S], c: '#5ee7ff', s: 2.6 }); }
    hud.radar(70, Ht - 74, 54, hp, [0, 0, -1], 15 * S, rad);
    hud.text(Wd / 2, 26, 'OVERCLOCK ×' + oc, { size: 16, color: OCC[(oc - 1) % OCC.length] });
    const left = SPOOL - live.length;
    hud.bar(Wd / 2 - 80, 54, 160, 7, left / SPOOL, left < 8 ? '#ff4a4a' : '#00f5ff', 'SPOOL');
    hud.text(Wd - 16, Ht - 40, '⚡ ' + relays + (relays < RELAY_GOAL ? ' / ' + RELAY_GOAL : ' ✓ COMPLETE'), { size: 14, align: 'right', color: '#ffd700' });
    hud.text(Wd - 16, Ht - 20, live.length + ' / ' + SPOOL + ' laid', { size: 12, align: 'right', color: '#bff6ff' });
    if(msgT > 0) hud.text(Wd / 2, 80, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🏗️ SERVER STACK · OPEN WORLD — THE TOWER IN THE CITY
// ══════════════════════════════════════════════
// The classic stacks in a column with the slab always sliding in from the
// same side. This tower stands in an open city, and its slabs swing in from
// every compass point — north, then east, then a diagonal — so every drop is
// read from a new angle. Whatever hangs over is cut off; a perfect drop cuts
// nothing, and three in a row grow the slab back. A slab that misses the
// tower falls into the street — three of those and the build is over.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ease, drawFloor, owClock } = P.owKit;
const { groundBegin, makeCity } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const H = 1.2, BASE = 10, AMP = 13, PERFECT = 0.3;
const PAL = ['#00f5ff', '#39ff88', '#ffd700', '#ff8a3a', '#ff2d6a', '#ff2bd6', '#a855f7', '#4d8bff'];
const COMPASS = [[0, -1, 'N'], [1, 0, 'E'], [0, 1, 'S'], [-1, 0, 'W'], [1, -1, 'NE'], [1, 1, 'SE'], [-1, 1, 'SW'], [-1, -1, 'NW']];

P.ow.stack = function(){
  const G = groundBegin({ sky: 'dusk', input: { touch: 'tap' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('TAP: DROP THE SLAB', 'SPACE / CLICK: DROP THE SLAB · A PERFECT DROP CUTS NOTHING');

  const slabs = [{ x: 0, z: 0, sx: BASE, sz: BASE, y: 0, c: '#3a4a5a' }];
  let cur = null, ph = 0, perfects = 0, bestRun = 0, run = 0, score = 0, misses = 0, over = false, finished = false, msg = '', msgT = 0, wasFire = false;
  let camA = Math.PI * 0.25, camH = 10;
  const debris = [];
  const taps = P.owDrive ? P.owDrive.tapCounter('tap') : { take: () => 0 };
  const city = makeCity({ seed: 4444, density: 0.4, cell: 60, clear: 48, hMin: 20, hMax: 150, radius: 700, towerColor: '#100814' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ff8a3a,#ff2bd6)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  const top = () => slabs[slabs.length - 1];
  function nextSlab(){
    const t = top(), n = slabs.length;
    const pool = n < 8 ? 4 : 8;
    const k = n < 8 ? (n - 1) % 4 : (Math.random() * pool) | 0;
    const [dx, dz, name] = COMPASS[k];
    const l = Math.hypot(dx, dz);
    cur = { ax: [dx / l, 0, dz / l], name, sx: t.sx, sz: t.sz, y: t.y + H, c: PAL[n % PAL.length] };
    ph = -Math.PI / 2;                      // it starts out at the far end of its swing
    snd('tick');
  }
  nextSlab();
  const curPos = () => { const t = top(), o = Math.sin(ph) * AMP; return [t.x + cur.ax[0] * o, t.z + cur.ax[2] * o]; };
  function drop(force){
    const t = top();
    let [x, z] = force ? [t.x, t.z] : curPos();
    // A near-perfect drop snaps square.
    const off = Math.hypot(x - t.x, z - t.z);
    const perfect = off < PERFECT;
    if(perfect){ x = t.x; z = t.z; }
    const x0 = Math.max(x - cur.sx / 2, t.x - t.sx / 2), x1 = Math.min(x + cur.sx / 2, t.x + t.sx / 2);
    const z0 = Math.max(z - cur.sz / 2, t.z - t.sz / 2), z1 = Math.min(z + cur.sz / 2, t.z + t.sz / 2);
    if(x1 - x0 <= 0.05 || z1 - z0 <= 0.05){
      // Missed the tower entirely.
      debris.push({ p: [x, cur.y + H / 2, z], s: [cur.sx, H, cur.sz], v: [cur.ax[0] * 4, 0, cur.ax[2] * 4], rot: [0, 0, 0], spin: [1, 0, 2], c: cur.c, t: 0 });
      misses++;
      run = 0;
      snd('gameOver'); w.kick(1.4);
      bar.style.width = (Math.max(0, 3 - misses) / 3 * 100) + '%';
      if(misses >= 3){
        if(survivedFatal()){ misses = 2; bar.style.width = '33%'; say('SHIELD ABSORBED — the slab is gone, the tower stands', 2); nextSlab(); return; }
        over = true;
        cur = null;
        gLater(() => finish('miss'), 1400);
        return;
      }
      say('✖ MISSED THE TOWER — ' + (3 - misses) + ' left', 1.8);
      nextSlab();
      return;
    }
    // Whatever hangs over falls.
    const cut = (ax0, ax1, az0, az1) => { if(ax1 - ax0 > 0.05 && az1 - az0 > 0.05) debris.push({ p: [(ax0 + ax1) / 2, cur.y + H / 2, (az0 + az1) / 2], s: [ax1 - ax0, H, az1 - az0], v: [Math.sign((ax0 + ax1) / 2 - (x0 + x1) / 2) * 3, 0, Math.sign((az0 + az1) / 2 - (z0 + z1) / 2) * 3], rot: [0, 0, 0], spin: [Math.random() * 3, 0, Math.random() * 3], c: cur.c, t: 0 }); };
    if(!perfect){
      const fx0 = x - cur.sx / 2, fx1 = x + cur.sx / 2, fz0 = z - cur.sz / 2, fz1 = z + cur.sz / 2;
      cut(fx0, x0, fz0, fz1); cut(x1, fx1, fz0, fz1);
      cut(x0, x1, fz0, z0); cut(x0, x1, z1, fz1);
    }
    let sx = x1 - x0, sz = z1 - z0;
    const level = slabs.length;
    let pts = 10 + level;
    if(perfect){
      perfects++; run++; bestRun = Math.max(bestRun, run);
      pts += 25 + 10 * Math.min(5, run);
      snd('combo', { semi: Math.min(12, run * 2) });
      if(run % 3 === 0 && (sx < BASE || sz < BASE)){ sx = Math.min(BASE, sx + 1); sz = Math.min(BASE, sz + 1); say('✦ THREE PERFECT — THE SLAB GROWS', 1.8); }
      fx.explode([(x0 + x1) / 2, cur.y + H, (z0 + z1) / 2], 2, { color: '#ffffff', debris: 0, smoke: 0, ringNormal: [0, 1, 0] });
    }else{
      run = 0;
      snd('land', { semi: -Math.min(8, off * 2) });
    }
    score += pts; setLive(score);
    w.pop([(x0 + x1) / 2, cur.y + 3, (z0 + z1) / 2], '+' + pts + (perfect ? ' PERFECT' : ''), perfect ? '#ffffff' : cur.c, { size: 14 });
    slabs.push({ x: (x0 + x1) / 2, z: (z0 + z1) / 2, sx, sz, y: cur.y, c: cur.c });
    nextSlab();
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('stack', score, {
      '📡 Build': why === 'clock' ? 'CLOCK EXPIRED' : 'THREE SLABS LOST',
      '🏗️ Slabs Stacked': slabs.length - 1,
      '📏 Height': Math.round((slabs.length - 1) * H) + ' m',
      '✦ Perfect Drops': perfects,
      '⛓ Best Perfect Run': bestRun,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, slabs: slabs.length - 1, perfects, run, misses, size: top().sx.toFixed(1) + '×' + top().sz.toFixed(1), from: cur && cur.name }),
    perfect(){ if(cur) drop(true); },
    lose(){ if(cur){ ph = Math.PI / 2; drop(false); } },
    dropNow(){ if(cur) drop(false); }
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over && cur){
      const level = slabs.length;
      ph += dt * Math.min(4.2, 1.5 + level * 0.045) * Math.min(1.4, diff);
      const fire = I.device !== 'touch' && (I.fire || I.jumpHit);
      if((fire && !wasFire) || taps.take() > 0) drop(false);
      wasFire = fire;
    }
    for(let i = debris.length - 1; i >= 0; i--){
      const d = debris[i];
      if(dt <= 0) break;
      d.t += dt;
      d.v[1] -= 22 * dt;
      d.p = V.madd(d.p, d.v, dt);
      d.rot[0] += d.spin[0] * dt; d.rot[2] += d.spin[2] * dt;
      if(d.t > 3.5) debris.splice(i, 1);
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    // The camera stands off the swing at an angle, rising with the tower.
    const t = top();
    const want = cur ? Math.atan2(cur.ax[0], cur.ax[2]) + Math.PI * 0.62 : camA;
    if(dt > 0){
      let dA = want - camA; while(dA > Math.PI) dA -= TAU; while(dA < -Math.PI) dA += TAU;
      camA += dA * ease(dt, 0.5);
      camH += (t.y + 10 - camH) * ease(dt, 0.4);
    }
    w.cam.eye = [t.x + Math.sin(camA) * 30, camH + 8, t.z + Math.cos(camA) * 30];
    w.cam.target = [t.x, camH - 4, t.z];
    w.goal.eye = w.cam.eye; w.goal.target = w.cam.target; w.goal.fov = 58;
    w.up = [0, 1, 0];
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 8, radius: 220, color: '#5a1a4a', glow: 0.8, major: 5, floor: '#0a040a', rough: 0.25 });
    city.draw(w);
    const lo = Math.max(0, slabs.length - 60);
    for(let i = lo; i < slabs.length; i++){
      const s = slabs[i];
      r.draw('slab', { pos: [s.x, s.y + H / 2, s.z], scale: [s.sx, H, s.sz], color: s.c, metallic: 0.5, roughness: 0.3, rim: 0.8, emissive: s.c, emissiveStrength: i === slabs.length - 1 ? 0.9 : 0.4 });
    }
    if(lo > 0){ const s = slabs[lo]; r.draw('cube', { pos: [s.x, s.y / 2, s.z], scale: [s.sx, s.y, s.sz], color: '#1a1424', metallic: 0.6, roughness: 0.4 }); }
    if(cur){
      const [x, z] = curPos();
      r.draw('slab', { pos: [x, cur.y + H / 2, z], scale: [cur.sx, H, cur.sz], color: cur.c, metallic: 0.5, roughness: 0.3, rim: 0.9, emissive: cur.c, emissiveStrength: 1.4 });
      // The swing's track, and where it came from.
      const a = [t.x - cur.ax[0] * AMP, cur.y + H / 2, t.z - cur.ax[2] * AMP], b = [t.x + cur.ax[0] * AMP, cur.y + H / 2, t.z + cur.ax[2] * AMP];
      r.streak(a, b, 0.12, cur.c, 0.5, 0);
      r.light({ pos: [x, cur.y + 6, z], color: cur.c, intensity: 160, range: 30 });
    }
    for(const d of debris) r.draw('slab', { pos: d.p, rot: d.rot, scale: d.s, color: d.c, metallic: 0.5, roughness: 0.4, emissive: d.c, emissiveStrength: 0.3 });
    r.light({ pos: [t.x + 10, t.y + 14, t.z + 10], color: '#ffe0d0', intensity: 200, range: 50 });
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.text(Wd / 2, 26, cur ? 'FROM THE ' + cur.name + '  ·  ' + (slabs.length - 1) + ' STACKED' : '', { size: 15, color: '#ffe8d8' });
    if(run > 1) hud.text(Wd / 2, 48, 'PERFECT ×' + run, { size: 13, color: '#ffffff' });
    hud.text(Wd - 16, Ht - 40, 'SLAB ' + t.sx.toFixed(1) + ' × ' + t.sz.toFixed(1), { size: 12, align: 'right', color: '#ffd8e8' });
    hud.text(Wd - 16, Ht - 20, '📏 ' + Math.round((slabs.length - 1) * H) + ' m  ' + '▮'.repeat(Math.max(0, 3 - misses)) + '▯'.repeat(Math.min(3, misses)), { size: 13, align: 'right', color: '#ffe8d8' });
    if(msgT > 0) hud.text(Wd / 2, 70, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
  });
};

})();


// ══════════════════════════════════════════════
//  👾 MUNCHER · OPEN WORLD — THE MAZE THAT NEVER ENDS
// ══════════════════════════════════════════════
// The classic maze is one screen and you eat it bare. This one goes on for
// ever in every direction, generated square by square so there is no dead
// end anywhere in it — and every square holds a data bit. Eat your way out
// while the four security daemons close in; a power core turns them, for a
// few seconds, into something you can eat.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ihash, ease, drawFloor, owClock } = P.owKit;
const { groundBegin, followCam, screenToGround } = P.owGround;
const { mine, clamp, runLoop, seeded } = P.kit;
const S = 4, WALL = 0.34, VIEW = 13;
const DIRS = [[0, -1], [1, 0], [0, 1], [-1, 0]];
const GHOST = ['#ff2d6a', '#ff2bd6', '#00f5ff', '#ff8a3a'];
const GHOST_PAINT = ['#e3262b', '#ee2496', '#16c4d4', '#ff7a1a'];   // ✨ v60 the daemons' liveries

P.ow.muncher = function(){
  const G = groundBegin({ sky: 'night', env: { horizon: '#1a1060' }, input: { touch: 'tap' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: STEER THROUGH THE MAZE · ⚡ / LB: SPECIAL', 'WASD / ARROWS or THE MOUSE: STEER · EAT THE DATA, DODGE THE DAEMONS · A POWER CORE TURNS THEM · V: SPECIAL');

  // ── THE MAZE ── edges are open or walled by hash; a square left with one
  // way in is given a second, so the maze has no dead ends at all.
  const h01 = (i, j, k) => seeded(ihash(i, j, k, 3939))();
  const memo = new Map();
  const baseE = (i, j) => (Math.abs(i) <= 1 && Math.abs(j) <= 1) || h01(i, j, 0) >= WALL;   // (i,j)–(i+1,j)
  const baseS = (i, j) => (Math.abs(i) <= 1 && Math.abs(j) <= 1) || h01(i, j, 1) >= WALL;   // (i,j)–(i,j+1)
  const baseOpen = (i, j, d) => d === 0 ? baseS(i, j - 1) : d === 1 ? baseE(i, j) : d === 2 ? baseS(i, j) : baseE(i - 1, j);
  function choice(i, j){
    const k = i + ',' + j;
    let v = memo.get(k);
    if(v !== undefined) return v;
    let deg = 0;
    for(let d = 0; d < 4; d++) if(baseOpen(i, j, d)) deg++;
    v = -1;
    if(deg <= 1){
      const s = (h01(i, j, 2) * 4) | 0;
      for(let n = 0; n < 4; n++){ const d = (s + n) % 4; if(!baseOpen(i, j, d)){ v = d; break; } }
    }
    memo.set(k, v);
    return v;
  }
  const open = (i, j, d) => baseOpen(i, j, d) || choice(i, j) === d || choice(i + DIRS[d][0], j + DIRS[d][1]) === (d + 2) % 4;
  const isPower = (i, j) => (Math.abs(i) + Math.abs(j) > 4) && h01(i, j, 3) < 0.022;
  const eaten = new Set();
  const key = (i, j) => i + ',' + j;
  eaten.add(key(0, 0));

  // ── MOVERS ── square to square; `t` runs 0→1 along the current edge.
  const mk = (i, j, d) => ({ i, j, d, t: 0, want: d });
  const me = Object.assign(mk(0, 0, 1), { inv: 1.5 });
  const pos = m => m.d < 0 ? [m.i * S, 0, m.j * S] : [(m.i + DIRS[m.d][0] * m.t) * S, 0, (m.j + DIRS[m.d][1] * m.t) * S];
  let score = 0, bits = 0, powers = 0, ghostsEaten = 0, lives = 3, frightT = 0, chainK = 0, over = false, finished = false, msg = '', msgT = 0;
  const ghosts = [];
  function placeGhost(gh, near){
    for(let k = 0; k < 60; k++){
      const a = Math.random() * TAU, d = near ? 9 + Math.random() * 6 : 14 + Math.random() * 6;
      const i = me.i + Math.round(Math.cos(a) * d), j = me.j + Math.round(Math.sin(a) * d);
      let ways = 0; for(let q = 0; q < 4; q++) if(open(i, j, q)) ways++;
      if(ways >= 2){ gh.i = i; gh.j = j; gh.t = 0; gh.d = -1; gh.away = 0; return; }
    }
  }
  for(let g = 0; g < 4; g++){ const gh = Object.assign(mk(0, 0, -1), { c: GHOST[g], k: g, away: 0 }); placeGhost(gh, true); ghosts.push(gh); }
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ffd700,#ff2d6a)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };
  // ⚡ Specials: Time Freeze stops the daemons dead (and harmless), Time Warp
  // halves them, a Shield Burst lets them pass through you, the Magnet Field
  // eats the bits on the squares around you, and the Nova blows every daemon
  // near you back to its pen.
  const sucked = [];
  const SP = P.owKit.makeSpecials(G, {
    kinds: ['freeze', 'magnet', 'shield', 'warp', 'nova'], every: 240, bubbleR: 2.6, novaR: 7 * S,
    player: () => { const p = pos(me); return [p[0], 1.3, p[2]]; },
    targets: () => ghosts.filter(g => g.away <= 0).map(g => { const p = pos(g); return { p: [p[0], 1.4, p[2]], r: 2, obj: g }; }),
    hit: gh => { if(gh.away <= 0) blastGhost(gh); },
    onEnd: k => { if(k === 'shield' || k === 'freeze') me.inv = Math.max(me.inv, 1.0); }
  });
  function blastGhost(gh){
    ghostsEaten++;
    score += 100; setLive(score);
    const p = pos(gh);
    fx.explode([p[0], 1.4, p[2]], 1.6, { color: gh.c, debris: 0, smoke: 0 });
    w.pop([p[0], 4, p[2]], '+100', '#ffffff', { size: 15 });
    gh.away = 4;
    gh.d = -1;
  }

  // Reaching a square: eat what is on it, then pick the next edge.
  function arrive(m, isMe){
    if(isMe){
      const k = key(m.i, m.j);
      if(!eaten.has(k)){
        eaten.add(k);
        if(isPower(m.i, m.j)){
          powers++;
          score += 25;
          frightT = Math.max(4, 7.5 - powers * 0.2);
          chainK = 0;
          snd('powerup');
          say('⚡ POWER CORE — the daemons are yours', 2);
          for(const gh of ghosts) if(gh.d >= 0 && gh.away <= 0) gh.d = (gh.d + 2) % 4, gh.t = 1 - gh.t, gh.i += DIRS[(gh.d + 2) % 4][0], gh.j += DIRS[(gh.d + 2) % 4][1];
        }else{ bits++; score += 5; if(bits % 2 === 0) snd('eat'); }
        setLive(score);
      }
      if(m.want >= 0 && open(m.i, m.j, m.want)) m.d = m.want;
      else if(m.d < 0 || !open(m.i, m.j, m.d)) m.d = -1;
    }
  }
  function ghostChoose(gh){
    const opts = [];
    for(let d = 0; d < 4; d++){ if(open(gh.i, gh.j, d) && (gh.d < 0 || d !== (gh.d + 2) % 4)) opts.push(d); }
    if(!opts.length){ for(let d = 0; d < 4; d++) if(open(gh.i, gh.j, d)) opts.push(d); }
    if(!opts.length){ gh.d = -1; return; }
    if(frightT > 0){ gh.d = opts[(Math.random() * opts.length) | 0]; return; }
    // Each daemon aims somewhere a little different: you, ahead of you, beside you.
    const md = me.d >= 0 ? me.d : 1;
    const off = [[0, 0], [DIRS[md][0] * 4, DIRS[md][1] * 4], [DIRS[(md + 1) % 4][0] * 3, DIRS[(md + 1) % 4][1] * 3], [-DIRS[md][0] * 2, -DIRS[md][1] * 2]][gh.k];
    const ti = me.i + off[0], tj = me.j + off[1];
    let best = opts[0], bd = 1e9;
    for(const d of opts){ const ni = gh.i + DIRS[d][0], nj = gh.j + DIRS[d][1]; const dd = (ni - ti) ** 2 + (nj - tj) ** 2 + Math.random() * 0.5; if(dd < bd){ bd = dd; best = d; } }
    gh.d = best;
  }
  function step(m, sp, dt, isMe){
    if(m.d < 0){ if(isMe) arrive(m, true); else ghostChoose(m); if(m.d < 0) return; }
    m.t += sp * dt;
    while(m.t >= 1){
      m.t -= 1;
      m.i += DIRS[m.d][0]; m.j += DIRS[m.d][1];
      if(isMe) arrive(m, true); else ghostChoose(m);
      if(m.d < 0){ m.t = 0; break; }
    }
  }
  function caught(){
    if(me.inv > 0 || over || SP.shielded()) return;
    lives--;
    snd('gameOver'); w.kick(1.2);
    fx.explode([...pos(me).slice(0, 1), 1.2, pos(me)[2]], 2, { color: colour, debris: 0 });
    bar.style.width = (Math.max(0, lives) / 3 * 100) + '%';
    if(lives <= 0){
      if(survivedFatal()){ lives = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); }
      else{ over = true; gLater(() => finish('caught'), 1100); return; }
    }else say('CAUGHT — ' + lives + ' left', 1.8);
    me.inv = 2;
    for(const gh of ghosts) placeGhost(gh, false);
  }
  function eatGhost(gh){
    ghostsEaten++;
    const pts = 100 * Math.pow(2, Math.min(3, chainK));
    chainK++;
    score += pts; setLive(score);
    snd('bigExplode');
    const p = pos(gh);
    fx.explode([p[0], 1.4, p[2]], 1.8, { color: gh.c, debris: 0, smoke: 0 });
    w.pop([p[0], 4, p[2]], '+' + pts, '#ffffff', { size: 16 });
    gh.away = 4;
    gh.d = -1;
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('muncher', score, {
      '📡 Run': why === 'clock' ? 'CLOCK EXPIRED' : 'CAUGHT',
      '💾 Data Bits': bits,
      '⚡ Power Cores': powers,
      '👾 Daemons Eaten': ghostsEaten,
      '❤ Lives Left': Math.max(0, lives),
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, bits, powers, ghostsEaten, lives, fright: +frightT.toFixed(1), at: [me.i, me.j] }),
    power(){ frightT = 7; chainK = 0; },
    eatGhost(){ const gh = ghosts.find(g => g.away <= 0); if(gh){ frightT = Math.max(frightT, 3); eatGhost(gh); } },
    die(){ me.inv = 0; caught(); },
    lose(){ me.inv = 0; caught(); },
    specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use()
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      SP.tick(dt, I, score);
      me.inv = Math.max(0, me.inv - dt);
      frightT = Math.max(0, frightT - dt);
      // Steering: the strongest axis of keys / stick / mouse.
      let sx = I.lx, sz = I.ly;
      const mp = pos(me);
      if(I.device === 'mouse' && I.mouseOn && hud.cam){
        const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
        if(g){ sx = g[0] - mp[0]; sz = g[2] - mp[2]; if(Math.hypot(sx, sz) < S * 0.8){ sx = 0; sz = 0; } }
      }else if(I.stick){ sx = I.stick.x - I.stick.x0; sz = I.stick.y - I.stick.y0; if(Math.hypot(sx, sz) < 0.05){ sx = 0; sz = 0; } }
      if(Math.abs(sx) > 0.3 || Math.abs(sz) > 0.3 || (I.device === 'mouse' && (sx || sz))){
        me.want = Math.abs(sx) > Math.abs(sz) ? (sx > 0 ? 1 : 3) : (sz > 0 ? 2 : 0);
        // A reversal is allowed at once, mid-edge.
        if(me.d >= 0 && me.want === (me.d + 2) % 4){ me.i += DIRS[me.d][0]; me.j += DIRS[me.d][1]; me.d = me.want; me.t = 1 - me.t; }
      }
      step(me, 3.4, dt, true);
      if(SP.active('magnet')){
        // The eight squares round you, walls or no walls; the bits fly in.
        const np = pos(me), ci = Math.round(np[0] / S), cj = Math.round(np[2] / S);
        let got = 0;
        for(let i = ci - 1; i <= ci + 1; i++) for(let j = cj - 1; j <= cj + 1; j++){
          const k = key(i, j);
          if(eaten.has(k) || isPower(i, j)) continue;
          eaten.add(k); bits++; score += 5; got++;
          sucked.push({ p: [i * S, 0.9, j * S], t: 0 });
        }
        if(got){ setLive(score); snd('eat'); }
      }
      const gsp = (frightT > 0 ? 2.1 : 3.05) * Math.min(1.25, diff) * SP.warp();
      for(const gh of ghosts){
        if(gh.away > 0){ gh.away -= dt; if(gh.away <= 0) placeGhost(gh, false); continue; }
        if(!SP.frozen()) step(gh, gsp, dt, false);
        const gp = pos(gh);
        if(Math.hypot(gp[0] - mp[0], gp[2] - mp[2]) < S * 0.55){ if(frightT > 0) eatGhost(gh); else if(!SP.frozen()) caught(); }
        if(Math.abs(gh.i - me.i) + Math.abs(gh.j - me.j) > 34) placeGhost(gh, false);
      }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    const mp = pos(me);
    followCam(w, mp, { height: 36, back: 17, look: 2, fov: 56, half: 0.1 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: S, radius: 80, color: '#141a5a', glow: 0.5, major: 100, floor: '#03030a', rough: 0.3 });
    const ci = Math.round(mp[0] / S), cj = Math.round(mp[2] / S);
    const wc = frightT > 0 ? '#4d8bff' : '#2a5aff';
    for(let i = ci - VIEW; i <= ci + VIEW; i++) for(let j = cj - VIEW; j <= cj + VIEW; j++){
      if(!open(i, j, 1)) r.draw('box', { pos: [(i + 0.5) * S, 0.8, j * S], scale: [0.5, 1.6, S + 0.5], color: '#0a0e2a', emissive: wc, emissiveStrength: 0.9 });
      if(!open(i, j, 2)) r.draw('box', { pos: [i * S, 0.8, (j + 0.5) * S], scale: [S + 0.5, 1.6, 0.5], color: '#0a0e2a', emissive: wc, emissiveStrength: 0.9 });
      if(!eaten.has(key(i, j))){
        if(isPower(i, j)){
          r.draw('sphere', { pos: [i * S, 1, j * S], scale: 1.2 + 0.2 * Math.sin(w.t * 6), color: '#ffffff', emissive: '#ffd700', emissiveStrength: 2.4 });
          r.glow([i * S, 1, j * S], 2.2, '#ffd700', 1);
        }else r.glow([i * S, 0.9, j * S], 0.55, '#ffe8a0', 1.1);
      }
    }
    for(const gh of ghosts){
      if(gh.away > 0) continue;
      const p = pos(gh);
      const scared = frightT > 0, blink = scared && frightT < 1.6 && Math.sin(w.t * 18) > 0;
      // ✨ v60 · PAINTED, NOT LIT (see ENEMY_PAINT): each daemon a glossy
      // livery in its colour — blue while it is yours to eat, frost while a
      // Time Freeze holds it — with no emissive, no halo, no lamp round it.
      // Their own paints (not enemyPaint's nearest): the cyan daemon must not
      // read as a frightened blue one.
      const col = scared ? (blink ? '#ffffff' : '#2340ff') : SP.frozen() ? '#9fe6ff' : GHOST_PAINT[gh.k];
      r.draw('pill', { pos: [p[0], 1.4 + Math.sin(w.t * 6 + gh.k) * 0.15, p[2]], scale: [2, 2.6, 2], ...P.kit.foeLook(col, false, { color: col, accent: 1 }) });
      const f = gh.d >= 0 ? DIRS[gh.d] : [0, 1];
      for(const s of [-1, 1]){
        const e = [p[0] + f[0] * 0.8 + f[1] * s * 0.45, 1.9, p[2] + f[1] * 0.8 - f[0] * s * 0.45];
        r.draw('lowsphere', { pos: e, scale: 0.45, color: '#ffffff', metallic: 0, roughness: 0.25, emissive: '#ffffff', emissiveStrength: 0.12 });
        r.draw('lowsphere', { pos: [e[0] + f[0] * 0.2, 1.9, e[2] + f[1] * 0.2], scale: 0.22, color: '#05060a', metallic: 0, roughness: 0.2 });
      }
    }
    if(!(me.inv > 0 && Math.sin(w.t * 30) > 0)){
      const chomp = 1 + 0.12 * Math.abs(Math.sin(w.t * 14));
      r.draw('sphere', { pos: [mp[0], 1.3, mp[2]], scale: 2.4 * chomp, color: '#ffe680', metallic: 0.2, roughness: 0.3, rim: 1, emissive: colour, emissiveStrength: 0.7 });
      r.glow([mp[0], 1.3, mp[2]], 3, '#ffe680', 0.6);
    }
    r.light({ pos: [mp[0], 7, mp[2] + 2], color: '#fff0c0', intensity: 140, range: 28 });
    for(let i = sucked.length - 1; i >= 0; i--){
      const s = sucked[i];
      s.t += dt * 4;
      if(s.t >= 1){ sucked.splice(i, 1); continue; }
      r.glow(V.lerp(s.p, [mp[0], 1.3, mp[2]], s.t * s.t), 0.55, '#ffe8a0', 1.1);
    }
    SP.draw();
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht], [Wd - 120, Ht - 56, Wd, Ht]];
    SP.hud();
    hud.touchPad(I, ['abil']);
    hud.radar(70, Ht - 74, 54, mp, [0, 0, -1], 18 * S, ghosts.filter(g => g.away <= 0).map(g => ({ p: pos(g), c: frightT > 0 ? '#4d8bff' : g.c, s: 3 })));
    for(const gh of ghosts){ if(gh.away > 0) continue; const p = pos(gh); if(!hud.proj(p).on && Math.hypot(p[0] - mp[0], p[2] - mp[2]) < 60) hud.edgeArrow(p, frightT > 0 ? '#4d8bff' : gh.c, null); }
    if(frightT > 0) hud.bar(Wd / 2 - 70, 40, 140, 7, frightT / 7.5, '#4d8bff', 'POWER');
    hud.text(Wd / 2, 24, '💾 ' + bits, { size: 15, color: '#ffe8a0' });
    hud.text(Wd - 16, Ht - 40, '👾 ' + ghostsEaten, { size: 13, align: 'right', color: '#bff6ff' });
    hud.text(Wd - 16, Ht - 20, '●'.repeat(Math.max(0, lives)) + '○'.repeat(Math.max(0, 3 - lives)), { size: 15, align: 'right', color: '#ffe680' });
    if(msgT > 0) hud.text(Wd / 2, 64, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
  });
};

})();


// ══════════════════════════════════════════════
//  🤖 BATTLE BOTS · OPEN WORLD — THE SIEGE
// ══════════════════════════════════════════════
// The classic fights in lanes, spending RAM on units from a deck. Out here the
// lanes are gone: an open battlefield studded with enemy outposts, each one
// turning out defenders while you are near. Drive your command rover, spend
// RAM, and drop units anywhere round you — drones, walkers, tanks — and they
// march on whatever is closest. Deploy where you are losing; burn every post.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ease, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, followCam, screenToGround, groundRing, beacon, makeCity } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const DEPLOY_R = 34, RAM_MAX = 100;
const UNITS = [
  { k: 'drone',  name: 'DRONE',  geo: 'drone', cost: 18, hp: 4,  sp: 13, range: 9,  dmg: 1, rate: 0.35, sc: 1.6, h: 2.2, key: '1' },
  { k: 'walker', name: 'WALKER', geo: 'mech',  cost: 34, hp: 9,  sp: 7,  range: 16, dmg: 2, rate: 0.7,  sc: 2.4, h: 0,   key: '2' },
  { k: 'tank',   name: 'TANK',   geo: 'tank',  cost: 58, hp: 18, sp: 4.5, range: 24, dmg: 5, rate: 1.4, sc: 2.6, h: 0,   key: '3' }
];
const FOE = { geo: 'drone', hp: 4, sp: 9, range: 12, dmg: 1, rate: 0.6, sc: 1.6, h: 2.2 };

P.ow.battlebots = function(){
  const G = groundBegin({ sky: 'ember', env: { horizon: '#6a3410' }, input: { touch: 'tap' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('LEFT: DRIVE · TAP A CARD, THEN THE GROUND: DEPLOY · ⚡ / LB: SPECIAL', 'WASD: DRIVE · 1 / 2 / 3 or Q/E: PICK A UNIT · CLICK THE GROUND: DEPLOY IT THERE · SPACE: DEPLOY AHEAD · V: SPECIAL');

  const me = { p: [0, 0, 0], v: [0, 0, 0], hp: 100, inv: 0, face: 0 };
  let ram = 60, pick = 0, score = 0, burned = 0, kills = 0, deployed = 0, lost = 0, over = false, finished = false, msg = '', msgT = 0, wasFire = false;
  const units = [], foes = [], shots = [], taps = [];
  const posts = makeField({
    cell: 150, dims: 2, seed: 8686, radius: 600,
    gen(cx, cy, cz, g){
      if(g() < 0.25 || (cx === 0 && cz === 0)) return [];
      return [{ p: [(cx + 0.2 + g() * 0.6) * 150, 0, (cz + 0.2 + g() * 0.6) * 150], hp: 70, max: 70, spawnT: g() * 4, alive: 0, flash: 0, ph: g() * TAU }];
    }
  });
  const city = makeCity({ seed: 8787, density: 0.12, cell: 120, clear: 60, hMin: 14, hMax: 50, radius: 600, towerColor: '#140806' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#00f5ff,#39ff88)';
  const clock = owClock(150, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  // Touch: a tap on the right half deploys where it lands.
  const cv = aCanvas;
  const onTouch = e => {
    if(!e.isTrusted) return;
    const rc = cv.getBoundingClientRect();
    const ab = P.owKit.touchButtons(inp.touchCfg, true).find(b => b.k === 'abil');
    for(const t of e.changedTouches){
      const x = t.clientX - rc.left, y = t.clientY - rc.top;
      const card = deckAt(x, y);
      if(card >= 0){ pick = card; snd('tab'); continue; }
      // The ⚡ button is the input's, not a place to deploy.
      const u = x / Math.max(1, rc.width), v = y / Math.max(1, rc.height);
      if(ab && Math.hypot(u - ab.u, (v - ab.v) * rc.height / Math.max(1, rc.width)) < ab.r) continue;
      if(u >= 0.5) taps.push([x, y]);
    }
  };
  if(cv) cv.addEventListener('touchstart', onTouch, { passive: true });
  // The deck's three cards, where the HUD draws them (see the bottom of the frame).
  const CW = 92;
  function deckAt(x, y){
    const x0 = hud.W / 2 - CW * 1.5 - 6;
    if(y < hud.H - 64 || y > hud.H - 30) return -1;
    for(let i = 0; i < 3; i++){ const cx = x0 + i * (CW + 6); if(x >= cx && x <= cx + CW) return i; }
    return -1;
  }
  const prevStop = onStopGame;
  onStopGame = () => { try{ if(cv) cv.removeEventListener('touchstart', onTouch); }catch(e){} if(prevStop) prevStop(); };

  function deploy(at){
    const U = UNITS[pick];
    if(ram < U.cost){ snd('deny'); say('NOT ENOUGH RAM for a ' + U.name, 1.2); return false; }
    let d = V.sub(at, me.p), l = Math.hypot(d[0], d[2]);
    if(l > DEPLOY_R){ at = V.add(me.p, V.mul([d[0] / l, 0, d[2] / l], DEPLOY_R)); }
    if(city.hit(at, 2)) at = V.add(me.p, [rr(-4, 4), 0, rr(-4, 4)]);
    ram -= U.cost;
    deployed++;
    units.push({ U, p: [at[0], 0, at[2]], hp: U.hp, cool: rr(0, U.rate), face: me.face, flash: 0 });
    snd('equip');
    fx.flash([at[0], 1.5, at[2]], '#7fe8ff', 1.6, 0.25);
    groundRingFlash.push({ p: [at[0], 0, at[2]], t: 0 });
    return true;
  }
  const groundRingFlash = [];
  function fire(from, tgt, dmg, mineSide, col){
    // ✨ v59 · out of the unit's gun: a walker's arm cannons in turn, a tank's
    // barrel, a drone's sensor turret (drawn yawed by face, at U.h or sc/2)
    const U = from.U || FOE, fc = Math.cos(from.face || 0), fs = Math.sin(from.face || 0);
    from.gk = (from.gk || 0) + 1;
    const gq = U.geo === 'tank' ? [0, 0.288, -0.94] : U.geo === 'mech' ? [from.gk % 2 ? 0.33 : -0.33, 0.2, -0.67] : [0, -0.15, -0.305];
    const gy = U.h ? U.h : U.sc * 0.5;
    const a = [from.p[0] + (gq[0] * fc + gq[2] * fs) * U.sc, gy + gq[1] * U.sc, from.p[2] + (-gq[0] * fs + gq[2] * fc) * U.sc];
    const b = tgt.p ? [tgt.p[0], 1.4, tgt.p[2]] : tgt;
    shots.push({ a, b, t: 0, dmg, tgt, mine: mineSide, col });
    snd(mineSide ? 'shoot' : 'enemyShot', { semi: mineSide ? 4 : -4 });
  }
  function hurtPost(pt, dmg){
    pt.hp -= dmg; pt.flash = 0.12;
    if(pt.hp <= 0 && !pt.dead){
      pt.dead = true;
      posts.kill(pt);
      burned++;
      const pts = 150;
      score += pts; setLive(score);
      ram = Math.min(RAM_MAX, ram + 30);
      fx.explode([pt.p[0], 4, pt.p[2]], 6, { color: '#ff7a2a', debrisGeo: 'slab', debrisColor: '#3a3e48' });
      snd('bigExplode'); w.kick(1.4);
      w.pop([pt.p[0], 12, pt.p[2]], '🔥 OUTPOST BURNED +' + pts, '#ffd27a', { size: 16 });
    }
  }
  function hurtMe(dmg, at){
    if(me.inv > 0 || over || SP.shielded()) return;
    me.hp -= dmg;
    snd('hurt'); w.kick(0.5);
    fx.sparks(at, 6, '#ff6a6a', 1, 10);
    bar.style.width = Math.max(0, me.hp) + '%';
    if(me.hp <= 0){
      if(survivedFatal()){ me.hp = 50; me.inv = 1.5; bar.style.width = '50%'; say('SHIELD ABSORBED', 1.6); }
      else{ over = true; snd('bigExplode'); fx.explode([me.p[0], 1, me.p[2]], 3, { color: colour }); gLater(() => finish('down'), 1200); }
    }
  }
  // ⚡ Specials: the Smart Missiles and the Nova hit defenders and outposts,
  // a Shield Burst and the EMP stop their fire, Repair Pulse patches the rover
  // and every unit, Overcharge triples the RAM feed and doubles your units'
  // rate of fire, and Time Warp halves the defenders.
  const SP = P.owKit.makeSpecials(G, {
    kinds: ['smart', 'shield', 'overdrive', 'repair', 'emp', 'warp', 'nova'], every: 220, bubbleR: 4.4, novaR: 44, smartN: 4, hudLift: 70,
    player: () => [me.p[0], 1.6, me.p[2]],
    targets: () => {
      const T = foes.filter(f => f.hp > 0).map(f => ({ p: [f.p[0], FOE.h, f.p[2]], r: 1.6, obj: f }));
      posts.each(pt => { if(!pt.dead && V.d2(pt.p, me.p) < 160 * 160) T.push({ p: [pt.p[0], 5, pt.p[2]], r: 6, obj: pt }); });
      return T;
    },
    hit: (o, dmg) => { if(o.max){ if(!o.dead) hurtPost(o, Math.min(30, dmg)); } else if(o.hp > 0){ o.hp -= dmg; o.flash = 0.1; } },
    clearFire: (p, R) => { for(let i = shots.length - 1; i >= 0; i--) if(!shots[i].mine && V.d2(V.lerp(shots[i].a, shots[i].b, shots[i].t), p) < R * R) shots.splice(i, 1); },
    heal: frac => {
      me.hp = Math.min(100, me.hp + 100 * frac);
      bar.style.width = Math.max(0, me.hp) + '%';
      for(const u of units){ u.hp = u.U.hp; u.flash = 0.15; }
    }
  });
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('battlebots', score, {
      '📡 Siege': why === 'clock' ? 'CLOCK EXPIRED' : 'COMMANDER DOWN',
      '🔥 Outposts Burned': burned,
      '💥 Defenders Destroyed': kills,
      '🤖 Units Deployed': deployed + ' (' + lost + ' lost)',
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, ram: Math.round(ram), units: units.length, foes: foes.length, burned, kills, hp: me.hp }),
    lose(){ me.inv = 0; hurtMe(200, [me.p[0], 1, me.p[2]]); },
    deploy(k){ pick = k || 0; ram = RAM_MAX; return deploy(V.add(me.p, [0, 0, -10])); },
    burnNearest(){ let best = null, bd = 1e12; posts.each(pt => { const d = V.d2(pt.p, me.p); if(d < bd){ bd = d; best = pt; } }); if(best) hurtPost(best, 999); return !!best; },
    specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use()
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      SP.tick(dt, I, score);
      me.inv = Math.max(0, me.inv - dt);
      ram = Math.min(RAM_MAX, ram + (9 + burned * 0.5) * (SP.active('overdrive') ? 3 : 1) * dt);
      // Driving: world axes, the camera never turns.
      let mx = I.lx, mz = I.ly;
      const ml = Math.hypot(mx, mz); if(ml > 1){ mx /= ml; mz /= ml; }
      me.v = V.lerp(me.v, [mx * 18, 0, mz * 18], ease(dt, 0.1));
      const np = V.madd(me.p, me.v, dt);
      if(!city.hit(np, 1.6)) me.p = np; else me.v = [0, 0, 0];
      if(ml > 0.1) me.face = Math.atan2(-mx, -mz);
      city.update(me.p);
      posts.update(me.p);
      // The deck.
      const pr = I.pressed || {};
      if(pr.Digit1 || pr.Numpad1) pick = 0;
      if(pr.Digit2 || pr.Numpad2) pick = 1;
      if(pr.Digit3 || pr.Numpad3) pick = 2;
      if(pr.KeyE || I.altHit) pick = (pick + 1) % 3;
      if(pr.KeyQ) pick = (pick + 2) % 3;
      const click = I.fire && !wasFire;
      wasFire = I.fire;
      if(click){
        if(I.device === 'mouse' && I.mouseOn && hud.cam){
          const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
          if(g) deploy(g);
        }else if(I.device !== 'touch') deploy(V.add(me.p, [-Math.sin(me.face) * 10, 0, -Math.cos(me.face) * 10]));
      }
      while(taps.length && hud.cam){ const t = taps.shift(); const g = screenToGround(hud, t[0], t[1], 0); if(g) deploy(g); }
      // Outposts turn out defenders while you are near.
      posts.each(pt => {
        pt.flash = Math.max(0, pt.flash - dt);
        if(V.d2(pt.p, me.p) > 170 * 170) return;
        pt.spawnT -= dt;
        if(pt.spawnT <= 0 && pt.alive < 3 && foes.length < 18){
          pt.spawnT = rr(5, 8) / Math.min(1.4, diff);
          pt.alive++;
          const a = Math.random() * TAU;
          foes.push({ p: [pt.p[0] + Math.cos(a) * 7, 0, pt.p[2] + Math.sin(a) * 7], hp: FOE.hp, cool: rr(0.5, 1.5), post: pt, face: 0, flash: 0, ph: Math.random() * TAU });
        }
      });
    }
    if(dt > 0){
      // Your units: march on the nearest thing to fight.
      for(let i = units.length - 1; i >= 0; i--){
        const u = units[i];
        u.flash = Math.max(0, u.flash - dt);
        let tgt = null, bd = 1e12, isPost = false;
        for(const f of foes){ const d = V.d2(f.p, u.p); if(d < bd && d < 90 * 90){ bd = d; tgt = f; isPost = false; } }
        if(!tgt) posts.each(pt => { if(pt.dead) return; const d = V.d2(pt.p, u.p); if(d < bd && d < 200 * 200){ bd = d; tgt = pt; isPost = true; } });
        if(tgt){
          const d = V.sub(tgt.p, u.p), l = Math.hypot(d[0], d[2]) || 1;
          u.face = Math.atan2(-d[0], -d[2]);
          const reach = u.U.range + (isPost ? 5 : 0);
          if(l > reach){
            const np = V.madd(u.p, [d[0] / l, 0, d[2] / l], u.U.sp * dt);
            if(!city.hit(np, 1.5)) u.p = np; else u.p = V.madd(u.p, [-d[2] / l, 0, d[0] / l], u.U.sp * dt);
          }
          u.cool -= dt * (SP.active('overdrive') ? 2 : 1);
          if(l <= reach + 1 && u.cool <= 0){ u.cool = u.U.rate; fire(u, tgt, u.U.dmg, true, '#7fe8ff'); }
        }else{
          // Nothing to fight: fall in near the rover.
          const d = V.sub(me.p, u.p), l = Math.hypot(d[0], d[2]);
          if(l > 12) u.p = V.madd(u.p, [d[0] / l, 0, d[2] / l], u.U.sp * dt);
        }
        if(u.hp <= 0){ units.splice(i, 1); lost++; fx.explode([u.p[0], 1.5, u.p[2]], 1.6, { color: '#7fe8ff', debrisGeo: 'slab', debrisColor: '#2a2e3a' }); snd('explode'); }
      }
      // Defenders: go for the nearest unit, else the rover.
      for(let i = foes.length - 1; i >= 0; i--){
        const f = foes[i];
        f.flash = Math.max(0, f.flash - dt);
        let tgt = me, bd = V.d2(me.p, f.p);
        for(const u of units){ const d = V.d2(u.p, f.p); if(d < bd){ bd = d; tgt = u; } }
        const d = V.sub(tgt.p, f.p), l = Math.hypot(d[0], d[2]) || 1;
        f.face = Math.atan2(-d[0], -d[2]);
        if(l > FOE.range){
          const wob = [Math.cos(w.t * 2 + f.ph) * 0.4, 0, Math.sin(w.t * 2 + f.ph) * 0.4];
          const np = V.madd(f.p, V.norm(V.add([d[0] / l, 0, d[2] / l], wob)), FOE.sp * Math.min(1.3, diff) * SP.warp() * dt);
          if(!city.hit(np, 1.2)) f.p = np;
        }
        f.cool -= dt * SP.warp();
        if(l <= FOE.range + 1 && f.cool <= 0 && !over && !SP.jammed()){ f.cool = FOE.rate * rr(0.8, 1.3) / Math.min(1.3, diff); fire(f, tgt, tgt === me ? 4 : FOE.dmg, false, '#ff4a4a'); }
        if(f.hp <= 0){
          foes.splice(i, 1);
          if(f.post) f.post.alive = Math.max(0, f.post.alive - 1);
          kills++;
          score += 20; setLive(score);
          ram = Math.min(RAM_MAX, ram + 4);
          fx.explode([f.p[0], 2, f.p[2]], 1.4, { color: '#ff6a4a', debris: 2 });
          snd('explode');
        }else if(V.d2(f.p, me.p) > 260 * 260){ foes.splice(i, 1); if(f.post) f.post.alive = Math.max(0, f.post.alive - 1); }
      }
      // Shots land after a beat.
      for(let i = shots.length - 1; i >= 0; i--){
        const s = shots[i];
        s.t += dt * 4;
        if(s.t < 1) continue;
        shots.splice(i, 1);
        const T = s.tgt;
        if(s.mine){
          if(T.max){ if(!T.dead) hurtPost(T, s.dmg); }
          else if(T.hp > 0){ T.hp -= s.dmg; T.flash = 0.1; }
        }else if(T === me) hurtMe(s.dmg, s.b);
        else if(T.hp > 0){ T.hp -= s.dmg; T.flash = 0.1; }
        fx.sparks(s.b, 4, s.col, 0.8, 8);
      }
      for(let i = groundRingFlash.length - 1; i >= 0; i--){ groundRingFlash[i].t += dt; if(groundRingFlash[i].t > 0.6) groundRingFlash.splice(i, 1); }
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    followCam(w, me.p, { height: 48, back: 30, look: 4, fov: 54, half: 0.12 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 8, radius: 200, color: '#5a2a0a', glow: 0.8, major: 6, floor: '#0a0503', rough: 0.3 });
    city.draw(w);
    const eye = w.cam.eye;
    posts.each(pt => {
      if(V.d2(pt.p, eye) > 500 * 500) return;
      beacon(w, pt.p, '#ff4a4a', 60, 0.5 + 0.3 * Math.sin(w.t * 2 + pt.ph));
      if(!r.viewDepth([pt.p[0], 5, pt.p[2]], 1.4)) return;
      // ✨ v60 · PAINTED, NOT LIT (see ENEMY_PAINT): a dark bunker under a
      // red-painted gun — no emissive panels and no lamp hung over it.
      r.draw('techblock', { pos: [pt.p[0], 4, pt.p[2]], scale: [9, 8, 9], color: pt.flash > 0 ? '#ffffff' : '#3a2c28', metallic: 0.6, roughness: 0.45, rim: 0.4 });
      r.draw('turret', { pos: [pt.p[0], 8.6, pt.p[2]], rot: [0, w.t * 0.6, 0], scale: 2.4, ...P.kit.foeLook('#ff4a4a', pt.flash > 0) });
    });
    // ✨ v60 · Every unit PAINTED, NOT LIT: the defenders red, yours silver
    // with blue livery stripes — no emissive hull, no halo.
    const drawBot = (b, U, col, enemy) => {
      if(V.d2(b.p, eye) > 260 * 260) return;
      const y = U.h ? U.h + Math.sin(w.t * 4 + (b.ph || 0)) * 0.3 : U.sc * 0.5;
      const look = enemy ? P.kit.foeLook(SP.frozen() ? '#9fe6ff' : '#ff4a4a', b.flash > 0)
                         : P.kit.foeLook('#c9d1dd', b.flash > 0, { color: b.flash > 0 ? '#ffffff' : '#c9d1dd', metallic: 0.65, accent: 4 });
      r.draw(U.geo, { pos: [b.p[0], y, b.p[2]], rot: [0, b.face, 0], scale: U.sc, ...look });
      if(U.geo === 'drone'){
        P.kit.foeShadow(r, b.p[0], b.p[2], U.sc * 0.9);
        P.kit.drawRotors(r, [b.p[0], y, b.p[2]], [0, b.face, 0], U.sc, w.t + (b.ph || 0), look);
      }
    };
    for(const u of units) drawBot(u, u.U, '#00f5ff', false);
    for(const f of foes) drawBot(f, FOE, '#ff4a4a', true);
    for(const s of shots){
      const p = V.lerp(s.a, s.b, s.t);
      r.streak(V.lerp(s.a, s.b, Math.max(0, s.t - 0.25)), p, 0.25, s.col, 2.4, 0.9);
    }
    for(const g of groundRingFlash) groundRing(w, g.p, 2 + g.t * 6, '#7fe8ff', 1.6 * (1 - g.t / 0.6));
    // The command rover and its deploy radius.
    if(!(me.inv > 0 && Math.sin(w.t * 30) > 0)) r.draw('tank', { pos: [me.p[0], 1.3, me.p[2]], rot: [0, me.face, 0], scale: 2.6, color: '#d8e0ec', metallic: 0.65, roughness: 0.3, rim: 0.8, emissive: colour, emissiveStrength: 0.4, accent: 0 });
    if(P.owDrive) P.owDrive.dotRing(w, me.p, DEPLOY_R, colour, 0.5);
    r.light({ pos: [me.p[0], 10, me.p[2] + 4], color: '#e0f0ff', intensity: 170, range: 40 });
    if(!over) SP.draw();
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht], [Wd / 2 - 150, Ht - 70, Wd / 2 + 150, Ht]];
    SP.hud();
    const rad = [];
    posts.each(pt => { if(V.d2(pt.p, me.p) < 300 * 300) rad.push({ p: pt.p, c: '#ff4a4a', s: 3.6, shape: 'diamond' }); });
    for(const u of units) rad.push({ p: u.p, c: '#00f5ff', s: 1.6 });
    for(const f of foes) rad.push({ p: f.p, c: '#ff9a6a', s: 1.6 });
    hud.radar(70, Ht - 74, 54, me.p, [0, 0, -1], 220, rad);
    let near = null, nd = 1e12;
    posts.each(pt => { const d = V.d2(pt.p, me.p); if(d < nd){ nd = d; near = pt; } });
    if(near){
      const q = hud.proj([near.p[0], 10, near.p[2]]);
      if(q.on) hud.bar(q.x - 30, q.y - 16, 60, 5, near.hp / near.max, '#ff4a4a');
      else hud.edgeArrow(near.p, '#ff4a4a', 'POST');
    }
    // The deck: three cards and the RAM bar.
    const cw = CW, x0 = Wd / 2 - cw * 1.5 - 6;
    UNITS.forEach((U, i) => {
      const x = x0 + i * (cw + 6), can = ram >= U.cost;
      hud.panel(x, Ht - 64, cw, 34, U.key + ' ' + U.name, U.cost, i === pick ? '#7fe8ff' : can ? '#4a7a9a' : '#3a3a48');
    });
    hud.bar(Wd / 2 - 140, Ht - 20, 280, 8, ram / RAM_MAX, '#39ff88', 'RAM ' + Math.floor(ram));
    hud.text(Wd - 16, Ht - 20, '🔥 ' + burned, { size: 14, align: 'right', color: '#ffd27a' });
    if(msgT > 0) hud.text(Wd / 2, 26, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🕶️ ICE CUTTER · OPEN WORLD — THE FACILITY WITH NO OUTER WALL
// ══════════════════════════════════════════════
// The classic is one room of sweeping patrol beams. This facility never ends:
// low walls in every direction, searchlight posts sweeping, drones walking
// their beats with a cone of light ahead of them, and data caches tucked
// among it all. Standing in any beam fills EXPOSURE; the dark drains it; the
// walls throw shadows the beams cannot cross. Fill it and you are caught.
// Stopping is usually the right move.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround) return;
const { V, TAU, ease, makeField, drawFloor, owClock } = P.owKit;
const { groundBegin, followCam, screenToGround, groundRing } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const CELL = 56;

P.ow.cutter = function(){
  const G = groundBegin({ sky: 'night', env: { zenith: '#020308', horizon: '#0a1830', intensity: 0.7 }, fog: { color: '#020409', density: 0.008 }, input: { touch: 'fly' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: CREEP · BOOST: RUN (LOUD) · STAY OUT OF THE LIGHT · ⚡ / LB: SPECIAL', 'WASD / ARROWS or HOLD THE MOUSE: CREEP · SHIFT: RUN (THE BEAMS SEE IT FASTER) · STAY IN THE DARK · V: SPECIAL');

  const me = { p: [0, 0, 0], v: [0, 0, 0], inv: 2 };
  let exposure = 0, lives = 3, caches = 0, ghostRuns = 0, caught = 0, score = 0, over = false, finished = false, msg = '', msgT = 0, lit = false;
  // Each cell: a few low walls, a searchlight post or a patrol drone, caches.
  const fac = makeField({
    cell: CELL, dims: 2, seed: 9191, radius: 280,
    gen(cx, cy, cz, g){
      const items = [];
      const x0 = cx * CELL, z0 = cz * CELL;
      const home = Math.abs(cx) <= 0 && Math.abs(cz) <= 0;
      const nw = 1 + Math.floor(g() * 3);
      for(let i = 0; i < nw; i++){
        const horiz = g() < 0.5, len = 10 + g() * 18;
        const x = x0 + 6 + g() * (CELL - 12), z = z0 + 6 + g() * (CELL - 12);
        if(home && Math.hypot(x, z) < 12) continue;
        items.push({ t: 'wall', x, z, hw: horiz ? len / 2 : 0.8, hd: horiz ? 0.8 : len / 2 });
      }
      if(!home){
        const roll = g();
        if(roll < 0.4) items.push({ t: 'light', p: [x0 + 10 + g() * (CELL - 20), 0, z0 + 10 + g() * (CELL - 20)], a0: g() * TAU, sweep: 0.6 + g() * 0.6, sp: 0.35 + g() * 0.4, range: 20 + g() * 6, half: 0.32 + g() * 0.12, ph: g() * TAU });
        else if(roll < 0.75){
          const c = [x0 + CELL / 2, 0, z0 + CELL / 2], s = 10 + g() * 8;
          items.push({ t: 'drone', c, s, u: g() * 4, sp: 0.09 + g() * 0.06, range: 14, half: 0.42, dirn: g() < 0.5 ? 1 : -1 });
        }
      }
      const nc = (g() < 0.7 ? 1 : 0) + (g() < 0.3 ? 1 : 0);
      for(let i = 0; i < nc; i++){ if(!home) items.push({ t: 'cache', p: [x0 + 5 + g() * (CELL - 10), 0, z0 + 5 + g() * (CELL - 10)], ph: g() * TAU }); }
      return items;
    }
  });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '0%';
  bar.style.background = 'linear-gradient(90deg,#ffd27a,#ff2d6a)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  // ⚡ Specials, for a thief: the EMP blacks out every beam, the Decoy draws
  // the searchlights and stops the drones to stare at it, Time Warp slows the
  // whole patrol, Phase Shift walks through walls unseen, and the Nova burns
  // out the posts and drones round you.
  let spinT = 0;
  const SP = P.owKit.makeSpecials(G, {
    kinds: ['emp', 'decoy', 'phase', 'warp', 'nova'], every: 200, bubbleR: 2, novaR: 30,
    player: () => [me.p[0], 1.1, me.p[2]],
    targets: () => {
      const T = [];
      fac.near(me.p, it => {
        if(it.t === 'light') T.push({ p: [it.p[0], 2, it.p[2]], r: 2, obj: it });
        else if(it.t === 'drone'){ const D = droneAt(it); T.push({ p: [D.p[0], 2, D.p[2]], r: 2, obj: it }); }
      });
      return T;
    },
    hit: (it, dmg, at) => { if(it.dead) return; fac.kill(it); fx.explode(at, 1.4, { color: it.t === 'light' ? '#ffd27a' : '#ff6a6a', debrisGeo: 'slab', debrisColor: '#2a2e3a' }); snd('explode'); },
    onEnd: k => {
      if(k !== 'phase') return;
      // Out of the wall you were inside when the phase ran out.
      for(const wl of walls){
        const dx = me.p[0] - wl.x, dz = me.p[2] - wl.z;
        const ox = wl.hw + 0.9 - Math.abs(dx), oz = wl.hd + 0.9 - Math.abs(dz);
        if(ox > 0 && oz > 0){ if(ox < oz) me.p[0] += Math.sign(dx || 1) * ox; else me.p[2] += Math.sign(dz || 1) * oz; }
      }
    }
  });
  // A drone walks the perimeter of a square: u in 0..4 is the distance round it.
  // A decoy near it turns its head (and its cone) toward the decoy.
  const droneAt = d => {
    const u = ((d.u % 4) + 4) % 4, s = d.s, e = Math.floor(u), f = u - e;
    const C = [[-s, -s], [s, -s], [s, s], [-s, s]];
    const a = C[e], b = C[(e + 1) % 4];
    const p = [d.c[0] + a[0] + (b[0] - a[0]) * f, 0, d.c[2] + a[1] + (b[1] - a[1]) * f];
    let dir = [b[0] - a[0], 0, b[1] - a[1]];
    if(d.dirn < 0) dir = V.mul(dir, -1);
    const dp = SP.decoy();
    if(dp && V.d2(dp, p) < 40 * 40 && V.d2(dp, p) > 0.01) dir = [dp[0] - p[0], 0, dp[2] - p[2]];
    return { p, dir: V.norm(dir) };
  };
  const walls = [];
  // Does the segment a→b cross any wall near it?
  function blocked(a, b){
    for(const wl of walls){
      // Slab test against the wall's box in XZ.
      let t0 = 0, t1 = 1;
      const d = [b[0] - a[0], b[2] - a[2]];
      const mn = [wl.x - wl.hw, wl.z - wl.hd], mx = [wl.x + wl.hw, wl.z + wl.hd], o = [a[0], a[2]];
      let hit = true;
      for(let k = 0; k < 2 && hit; k++){
        if(Math.abs(d[k]) < 1e-6){ if(o[k] < mn[k] || o[k] > mx[k]) hit = false; }
        else{
          let ta = (mn[k] - o[k]) / d[k], tb = (mx[k] - o[k]) / d[k];
          if(ta > tb){ const t = ta; ta = tb; tb = t; }
          t0 = Math.max(t0, ta); t1 = Math.min(t1, tb);
          if(t0 > t1) hit = false;
        }
      }
      if(hit) return true;
    }
    return false;
  }
  // Is p inside this light's cone, with nothing in between?
  function inCone(o, dir, range, half, p){
    const d = [p[0] - o[0], 0, p[2] - o[2]], l = Math.hypot(d[0], d[2]);
    if(l > range || l < 0.01) return 0;
    const cos = (d[0] * dir[0] + d[2] * dir[2]) / l;
    if(cos < Math.cos(half)) return 0;
    if(blocked([o[0], 0, o[2]], p)) return 0;
    return 1 - l / range * 0.6;
  }
  // The patrol keeps its own clock, so a Time Warp slows every sweep.
  let patrolT = 0;
  const sweepDir = L => { const a = L.a0 + Math.sin(patrolT * L.sp + L.ph) * L.sweep; return [Math.sin(a), 0, Math.cos(a)]; };
  const lightDir = L => L.aim || sweepDir(L);
  function grab(it){
    fac.kill(it);
    caches++;
    const ghost = exposure < 0.2;
    if(ghost) ghostRuns++;
    const pts = 40 + (ghost ? 25 : 0);
    score += pts; setLive(score);
    snd('pickup');
    fx.glowPop([it.p[0], 1.2, it.p[2]], '#39ff88', 2, 0.35);
    w.pop([it.p[0], 3, it.p[2]], '+' + pts + (ghost ? ' GHOST' : ''), ghost ? '#9dffc4' : '#7fe8ff', { size: 14 });
  }
  function spotted(){
    caught++;
    lives--;
    exposure = 0;
    me.inv = 2.5;
    snd('alarm'); w.kick(1.2);
    fx.sparks([me.p[0], 1, me.p[2]], 16, '#ff4a4a', 1.2, 12);
    if(lives <= 0){
      if(survivedFatal()){ lives = 1; say('SHIELD ABSORBED', 1.6); }
      else{ over = true; gLater(() => finish('caught'), 1200); return; }
    }
    say('🚨 SPOTTED — ' + lives + ' left · lie low', 2);
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('cutter', score, {
      '📡 Infiltration': why === 'clock' ? 'CLOCK EXPIRED' : 'CAUGHT',
      '💾 Caches Lifted': caches,
      '👻 Unseen Grabs': ghostRuns,
      '🚨 Times Spotted': caught,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, caches, lives, exposure: Math.round(exposure * 100), lit, walls: walls.length }),
    grab(){ let it = null; fac.each(o => { if(!it && o.t === 'cache') it = o; }); if(it) grab(it); return !!it; },
    expose(){ me.inv = 0; exposure = 1; spotted(); },
    lose(){ me.inv = 0; exposure = 1; spotted(); },
    specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use()
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    fac.update(me.p);
    walls.length = 0;
    fac.near(me.p, it => { if(it.t === 'wall') walls.push(it); });
    if(dt > 0 && !over){
      SP.tick(dt, I, score);
      spinT += dt * (SP.frozen() ? 0 : SP.warp());
      me.inv = Math.max(0, me.inv - dt);
      patrolT += dt * SP.warp();
      const dp = SP.decoy();
      fac.each(it => {
        if(it.t !== 'light') return;
        let want = sweepDir(it);
        if(dp && V.d2(dp, it.p) < (it.range + 24) ** 2 && V.d2(dp, it.p) > 0.01) want = V.norm([dp[0] - it.p[0], 0, dp[2] - it.p[2]]);
        it.aim = it.aim ? V.norm(V.lerp(it.aim, want, ease(dt, 0.12))) : want;
      });
      let mx = I.lx, mz = I.ly;
      if(I.device === 'mouse' && I.mDown && hud.cam){
        const g = screenToGround(hud, (I.mx + 1) / 2 * hud.W, (I.my + 1) / 2 * hud.H, 0);
        if(g){ const d = V.sub(g, me.p), l = Math.hypot(d[0], d[2]); if(l > 1){ mx = d[0] / l; mz = d[2] / l; } }
      }
      const ml = Math.hypot(mx, mz); if(ml > 1){ mx /= ml; mz /= ml; }
      const running = I.boost && ml > 0.1;
      const sp = running ? 15 : 8;
      me.v = V.lerp(me.v, [mx * sp, 0, mz * sp], ease(dt, 0.08));
      const np = V.madd(me.p, me.v, dt);
      let ok = true;
      for(const wl of walls) if(Math.abs(np[0] - wl.x) < wl.hw + 0.9 && Math.abs(np[2] - wl.z) < wl.hd + 0.9){ ok = false; break; }
      if(ok || SP.active('phase')) me.p = np;
      else{
        // Slide along the wall.
        const nx = [np[0], 0, me.p[2]], nz = [me.p[0], 0, np[2]];
        const free = q => !walls.some(wl => Math.abs(q[0] - wl.x) < wl.hw + 0.9 && Math.abs(q[2] - wl.z) < wl.hd + 0.9);
        if(free(nx)) me.p = nx; else if(free(nz)) me.p = nz;
      }
      // The light on you.
      let k = 0;
      fac.near(me.p, it => {
        if(it.t === 'light') k = Math.max(k, inCone(it.p, lightDir(it), it.range, it.half, me.p));
        else if(it.t === 'drone'){ const D = droneAt(it); k = Math.max(k, inCone(D.p, D.dir, it.range, it.half, me.p)); }
        else if(it.t === 'cache' && V.d2(it.p, me.p) < 2.4 * 2.4) grab(it);
      });
      if(SP.jammed() || SP.active('phase')) k = 0;
      lit = k > 0 && me.inv <= 0;
      if(lit) exposure += (0.55 + k * 0.6) * (running ? 1.7 : 1) * Math.min(1.4, diff) * dt;
      else exposure = Math.max(0, exposure - (Math.hypot(me.v[0], me.v[2]) < 1 ? 0.45 : 0.28) * dt);
      if(exposure >= 1) spotted();
      bar.style.width = clamp(exposure * 100, 0, 100) + '%';
      fac.each(it => {
        if(it.t !== 'drone' || SP.frozen()) return;
        // A drone staring at the decoy stands still.
        if(dp && V.d2(dp, droneAt(it).p) < 40 * 40) return;
        it.u += it.sp * it.dirn * dt * Math.min(1.3, diff) * SP.warp();
      });
    }
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    followCam(w, me.p, { height: 30, back: 18, look: 2, fov: 56, half: 0.12 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 4, radius: 110, color: '#0e2a4a', glow: 0.55, major: 7, floor: '#020408', rough: 0.35 });
    const eye = w.cam.eye;
    const fan = (o, dir, range, half, col, k) => {
      const m3 = [-dir[2], 0, dir[0], -dir[0], 0, -dir[2], 0, 1, 0];
      r.draw('cone', { pos: [o[0] + dir[0] * range / 2, 0.12, o[2] + dir[2] * range / 2], m3, scale: [2 * range * Math.tan(half), range, 0.15],
                       color: col, emissive: col, emissiveStrength: 1.2 * k, alpha: 0.16 * k, blend: true });
    };
    let nl = 0;
    fac.each(it => {
      if(it.t === 'wall'){
        if(V.d2([it.x, 0, it.z], eye) > 140 * 140) return;
        r.draw('cube', { pos: [it.x, 1.4, it.z], scale: [it.hw * 2, 2.8, it.hd * 2], color: '#141a26', metallic: 0.6, roughness: 0.45, rim: 0.5 });
        r.draw('box', { pos: [it.x, 2.85, it.z], scale: [it.hw * 2 + 0.02, 0.08, it.hd * 2 + 0.02], color: '#2a5a8a', emissive: '#2a6aaa', emissiveStrength: 1.2 });
      }else if(it.t === 'light'){
        if(V.d2(it.p, eye) > 150 * 150) return;
        const d = lightDir(it);
        r.draw('cylinder', { pos: [it.p[0], 1.6, it.p[2]], scale: [1, 3.2, 1], color: '#2a2a34', metallic: 0.8, roughness: 0.3 });
        const dark = SP.jammed();
        // ✨ v60 · A hostile like the others: painted bright, not a grey hull
        // with a lamp glow (its beam is the light it gives).
        r.draw('turret', { pos: [it.p[0], 3.4, it.p[2]], rot: [0, Math.atan2(-d[0], -d[2]), 0], scale: 1, ...P.kit.foeLook(dark ? '#8a7a3a' : '#ffc23a', false) });
        if(!dark){
          fan(it.p, d, it.range, it.half, '#ffd27a', 1);
          if(nl++ < 4) r.light({ pos: V.add(it.p, [d[0] * 8, 3, d[2] * 8]), color: '#ffe0a0', intensity: 70, range: 16 });
        }
      }else if(it.t === 'drone'){
        const D = droneAt(it);
        if(V.d2(D.p, eye) > 150 * 150) return;
        // ✨ v60 · PAINTED, NOT LIT (see ENEMY_PAINT): a red patrol drone, its
        // cone the only light it gives.
        const dyaw = Math.atan2(-D.dir[0], -D.dir[2]);
        const look = P.kit.foeLook('#ff5a5a', false);
        r.draw('drone', { pos: [D.p[0], 2, D.p[2]], rot: [0, dyaw, 0], scale: 1.6, ...look });
        P.kit.foeShadow(r, D.p[0], D.p[2], 1.4);
        P.kit.drawRotors(r, [D.p[0], 2, D.p[2]], [0, dyaw, 0], 1.6, spinT + it.c[0] * 0.1, look);
        if(!SP.jammed()) fan(D.p, D.dir, it.range, it.half, '#ff6a6a', 0.8);
      }else if(it.t === 'cache'){
        if(V.d2(it.p, eye) > 140 * 140) return;
        const y = 1 + Math.sin(w.t * 2 + it.ph) * 0.2;
        r.draw('cube', { pos: [it.p[0], y, it.p[2]], rot: [w.t, w.t * 0.7, 0], scale: 1, color: '#39ff88', emissive: '#39ff88', emissiveStrength: 1.6 });
        r.glow([it.p[0], y, it.p[2]], 1.6, '#39ff88', 0.6);
      }
    });
    if(!(me.inv > 0 && Math.sin(w.t * 20) > 0)){
      r.draw('mech', { pos: [me.p[0], 1.1, me.p[2]], rot: [0, Math.atan2(-me.v[0], -me.v[2] - 1e-6), 0], scale: 1.6, color: lit ? '#ffe8c0' : '#5a6a7a', metallic: 0.5, roughness: 0.4, rim: 0.6, emissive: colour, emissiveStrength: lit ? 0.6 : 0.2 });
    }
    groundRing(w, me.p, 1.3, lit ? '#ff4a4a' : colour, lit ? 1.6 : 0.5);
    r.light({ pos: [me.p[0], 6, me.p[2] + 2], color: '#7a9aca', intensity: 50, range: 18 });
    if(!over) SP.draw();
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    SP.hud();
    const rad = [];
    fac.each(it => {
      if(it.t === 'cache' && V.d2(it.p, me.p) < 90 * 90) rad.push({ p: it.p, c: '#39ff88', s: 2.2 });
      else if(it.t === 'light' && V.d2(it.p, me.p) < 90 * 90) rad.push({ p: it.p, c: '#ffd27a', s: 2.6, shape: 'diamond' });
      else if(it.t === 'drone'){ const D = droneAt(it); if(V.d2(D.p, me.p) < 90 * 90) rad.push({ p: D.p, c: '#ff6a6a', s: 2.6 }); }
    });
    hud.radar(70, Ht - 74, 54, me.p, [0, 0, -1], 70, rad);
    hud.bar(Wd / 2 - 90, 34, 180, 9, exposure, exposure > 0.7 ? '#ff2d6a' : '#ffd27a', 'EXPOSURE');
    hud.text(Wd / 2, 58, lit ? '👁 IN THE LIGHT' : SP.active('phase') ? '👻 PHASED' : SP.jammed() ? '⚡ BEAMS DOWN' : me.inv > 0 ? '…lie low…' : 'DARK', { size: 12, color: lit ? '#ff8a8a' : '#7fe8ff' });
    hud.text(Wd - 16, Ht - 40, '💾 ' + caches, { size: 14, align: 'right', color: '#9dffc4' });
    hud.text(Wd - 16, Ht - 20, '●'.repeat(Math.max(0, lives)) + '○'.repeat(Math.max(0, 3 - lives)), { size: 15, align: 'right', color: '#bff6ff' });
    if(msgT > 0) hud.text(Wd / 2, 80, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  🎵 RHYTHM · OPEN WORLD — BEAT GATES ON THE PLAIN
// ══════════════════════════════════════════════
// The classic is three lanes and one beat. Out here there are no lanes: you
// cruise an open plain and the gates are charted ahead of you on the beat of
// your Music Drive — left, right, wherever — each with a ring that closes on
// the exact moment it should be crossed. Steer through on the pulse; W and S
// nudge your speed to fix your timing. Perfects build the multiplier.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owDrive) return;
const { V, TAU, wrapAng, ease, drawFloor, owClock } = P.owKit;
const { groundBegin, chaseCam, groundRing, drawRover } = P.owGround;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const CRUISE = 26, GW = 7.5, LEAD = 6;     // gates are charted six beats out

P.ow.rhythm = function(){
  const G = groundBegin({ sky: 'violet', env: { horizon: '#7a1a8a' }, input: { mouseSteer: true, mouseGain: 1.2, touch: 'drive' } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  const bpm = (window.SFX && SFX.bpm) || 136;
  const beat = 60 / bpm;
  setControlHint('STICK: STEER THROUGH EACH GATE ON THE PULSE', 'A/D or THE MOUSE: STEER · W/S: NUDGE YOUR SPEED · CROSS EACH GATE AS ITS RING CLOSES');

  const me = { p: [0, 0, 0], yaw: 0, speed: CRUISE, bank: 0 };
  let t = 0, nextBeat = 2, score = 0, combo = 0, bestCombo = 0, mult = 1, perfect = 0, good = 0, ok = 0, missed = 0, over = false, finished = false;
  let msg = '', msgT = 0, judge = '', judgeT = 0, judgeCol = '#ffffff', lastBeatI = -1, pulse = 0;
  const gates = [];
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#ff2bd6,#a855f7,#00f5ff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, tt) => { msg = s; msgT = tt || 2; };

  // Chart a gate for beat number b: where you would be then if you held your
  // heading, swung left or right — further and more often as the run goes on.
  let side = 0;
  function chart(b){
    const at = b * beat;
    const ahead = CRUISE * (at - t);
    const f = [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], rt = [-f[2], 0, f[0]];
    const swing = Math.min(14, 5 + t * 0.06);
    side = clamp(side + rr(-1, 1) * swing, -swing * 1.6, swing * 1.6);
    const p = V.add(V.madd(me.p, f, ahead), V.mul(rt, side));
    gates.push({ p, n: f, at, b, done: false, res: null });
  }
  function judgeGate(g, dt0){
    g.done = true;
    const e = Math.abs(dt0);
    let pts, txt, col;
    if(e <= 0.07){ pts = 12; txt = 'PERFECT'; col = '#ffffff'; perfect++; }
    else if(e <= 0.15){ pts = 7; txt = 'GOOD'; col = '#9dffc4'; good++; }
    else if(e <= 0.26){ pts = 3; txt = 'OK'; col = '#7fe8ff'; ok++; }
    else{ pts = 1; txt = dt0 < 0 ? 'EARLY' : 'LATE'; col = '#ffd27a'; }
    if(e <= 0.15){ combo++; bestCombo = Math.max(bestCombo, combo); }
    else combo = 0;
    mult = 1 + Math.min(2, Math.floor(combo / 8));
    score += pts * mult; setLive(score);
    g.res = col;
    judge = txt + (mult > 1 ? ' ×' + mult : ''); judgeT = 0.6; judgeCol = col;
    snd(e <= 0.07 ? 'combo' : e <= 0.15 ? 'score' : 'click', { semi: Math.min(12, combo % 12) });
    fx.sparks([g.p[0], 3, g.p[2]], e <= 0.07 ? 16 : 8, col, 1, 12);
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    owFinish('rhythm', score, {
      '📡 Set': why === 'clock' ? 'CLOCK EXPIRED' : 'ENDED',
      '♪ Charted At': Math.round(bpm) + ' BPM',
      '✦ Perfect / Good / OK': perfect + ' / ' + good + ' / ' + ok,
      '✖ Missed Gates': missed,
      '⛓ Best Combo': bestCombo,
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, combo, mult, perfect, good, ok, missed, gates: gates.length, bpm: Math.round(bpm) }),
    hitPerfect(){ const g = gates.find(x => !x.done); if(g){ judgeGate(g, 0); return true; } return false; }
  };
  // The opening chart.
  while(nextBeat * beat < LEAD * beat){ chart(nextBeat); nextBeat += 2; }

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      t += dt;
      const steer = clamp(I.ax, -1, 1);
      me.yaw = wrapAng(me.yaw - steer * 1.6 * dt);
      me.bank += (clamp(steer * 0.5, -0.5, 0.5) - me.bank) * ease(dt, 0.1);
      const nudge = clamp(-I.ly, -1, 1);
      me.speed += (CRUISE * (1 + nudge * 0.28) - me.speed) * ease(dt, 0.2);
      const prev = V.copy(me.p);
      me.p = V.madd(me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], me.speed * dt);
      // Chart ahead: every second beat at first, every beat once you are in it.
      const step = t > 40 && diff >= 1 ? 1 : 2;
      while(nextBeat * beat < t + LEAD * beat){ chart(nextBeat); nextBeat += (t > 70 && Math.random() < 0.5) ? 1 : step; }
      // Crossing a gate's line, between its posts.
      for(const g of gates){
        if(g.done) continue;
        const da = V.dot(V.sub(prev, g.p), g.n), db = V.dot(V.sub(me.p, g.p), g.n);
        if(da < 0 && db >= 0){
          const q = V.lerp(prev, me.p, -da / Math.max(1e-6, db - da));
          const lat = Math.abs(V.dot(V.sub(q, g.p), [-g.n[2], 0, g.n[0]]));
          if(lat < GW / 2){ judgeGate(g, (t - dt * (db / Math.max(1e-6, db - da))) - g.at); }
        }
      }
      for(let i = gates.length - 1; i >= 0; i--){
        const g = gates[i];
        if(!g.done && t > g.at + 0.6){ g.done = true; g.res = '#ff4a6a'; missed++; combo = 0; mult = 1; judge = 'MISS'; judgeT = 0.6; judgeCol = '#ff6a8a'; snd('wrong'); }
        if(g.done && t > g.at + 1.5) gates.splice(i, 1);
      }
      const bi = Math.floor(t / beat);
      if(bi !== lastBeatI){ lastBeatI = bi; pulse = 1; }
    }
    pulse = Math.max(0, pulse - dt * 4);
    judgeT = Math.max(0, judgeT - dt);
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    chaseCam(w, me.p, me.yaw, { back: 10, up: 4.6, ahead: 20, fov: 64, half: 0.08 }, dt);
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 170, color: '#5a1a7a', glow: 0.7 + pulse * 0.9, major: 4, floor: '#07030e', rough: 0.2 });
    for(const g of gates){
      const lead = g.at - t;
      const col = g.res || (lead < 0.26 ? '#ffffff' : '#ff2bd6');
      const rt = [-g.n[2], 0, g.n[0]];
      for(const s of [-1, 1]){
        const pp = V.add(g.p, V.mul(rt, s * GW / 2));
        r.draw('cylinder', { pos: [pp[0], 2.5, pp[2]], scale: [0.6, 5, 0.6], color: '#1c1830', metallic: 0.8, roughness: 0.3, emissive: col, emissiveStrength: 0.6 });
      }
      r.beam(V.add(V.add(g.p, V.mul(rt, -GW / 2)), [0, 5, 0]), V.add(V.add(g.p, V.mul(rt, GW / 2)), [0, 5, 0]), 0.35, { color: col, emissive: col, emissiveStrength: 2.4 });
      if(!g.done){
        // The approach ring: it closes exactly on the beat.
        const k = clamp(lead / (LEAD * beat), 0, 1);
        const R = GW * 0.5 + k * 14;
        r.draw('thintorus', { pos: [g.p[0], 2.5, g.p[2]], m3: [rt[0], 0, rt[2], g.n[0], 0, g.n[2], 0, 1, 0], scale: [R / 0.45, 1, R / 0.45], color: col, emissive: col, emissiveStrength: 1.8 * (1 - k * 0.6) });
        groundRing(w, g.p, GW * 0.4, col, 0.6 + pulse);
      }
    }
    drawRover(w, me.p, me.yaw, colour, { bank: me.bank, boost: clamp((me.speed - CRUISE) / 10, 0, 1), scale: 1.6 });
    r.light({ pos: [me.p[0], 6, me.p[2]], color: '#ff9af0', intensity: 80 + pulse * 120, range: 24 });
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 120, gates.filter(g => !g.done).map(g => ({ p: g.p, c: '#ff2bd6', s: 2.6 })));
    for(const g of gates){ if(!g.done && !hud.proj([g.p[0], 3, g.p[2]]).on) hud.edgeArrow(g.p, '#ff2bd6', null); }
    if(judgeT > 0) hud.text(Wd / 2, Ht * 0.36, judge, { size: 22, color: judgeCol, alpha: clamp(judgeT / 0.3, 0, 1), blur: 14 });
    hud.text(Wd / 2, 26, '♪ ' + Math.round(bpm) + ' BPM' + (combo > 1 ? '  ·  COMBO ' + combo : ''), { size: 14, color: '#ffd8ff' });
    // The metronome: a dot that fills on every beat.
    for(let i = 0; i < 4; i++){
      const on = (lastBeatI % 4 + 4) % 4 === i;
      hud.text(Wd / 2 - 30 + i * 20, 46, on ? '●' : '○', { size: 12, color: on ? '#ffffff' : '#7a5a8a' });
    }
    hud.text(Wd - 16, Ht - 40, mult > 1 ? 'MULTIPLIER ×' + mult : '', { size: 13, align: 'right', color: '#ffffff' });
    hud.text(Wd - 16, Ht - 20, '✦ ' + perfect + '  ✓ ' + good, { size: 13, align: 'right', color: '#ffd8ff' });
    if(msgT > 0) hud.text(Wd / 2, 70, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();


// ══════════════════════════════════════════════
//  ⌨️ COMMAND LINE · OPEN WORLD — ROGUE PROCESSES
// ══════════════════════════════════════════════
// The classic types down viruses falling toward one shell. Out here the
// processes roam an open grid, each wearing its command, and you drive up to
// them: anything within range can be typed dead — the first letter locks on,
// a typo breaks the clean run, and one that reaches you costs integrity. The
// letters are all for typing, so you drive on the ARROWS (or hold the mouse
// where you want to go); a touch screen gets the classic's keypad.
(function(){
'use strict';
const P = window.PI3D;
if(!P || !P.owKit || !P.owGround || !P.owDrive) return;
const { V, TAU, ease, drawFloor, owClock } = P.owKit;
const { groundBegin, groundRing, makeCity } = P.owGround;
const { makeRover, driveStep, slideOut, roverCam, roverDraw, dotRing } = P.owDrive;
const { mine, clamp, runLoop } = P.kit;
const rr = (a, b) => a + Math.random() * (b - a);
const RANGE = 34, MAX_LIVE = 10;

P.ow.cmdline = function(){
  let onType = null;
  const G = groundBegin({ sky: 'toxic', input: { touch: 'drive', abilKey: 'Enter', onKey: e => { if(onType) onType(e); } } });
  const { w, r, hud, fx, inp } = G;
  const colour = mine();
  const diff = getDifficultyModifier();
  setControlHint('STICK: DRIVE · TAP THE KEYPAD: TYPE A PROCESS DEAD · ⚡ / LB: SPECIAL', 'ARROWS or HOLD THE MOUSE: DRIVE · TYPE A WORD IN RANGE TO KILL ITS PROCESS · BACKSPACE: LET GO · ENTER: SPECIAL');

  const me = makeRover({ max: 22 });
  let score = 0, kills = 0, letters = 0, keys = 0, typos = 0, combo = 0, bestCombo = 0, integrity = 3, elapsed = 0, spawnT = 1, bossT = 28;
  let over = false, finished = false, msg = '', msgT = 0, lock = null, zap = 0, typoT = 0;
  const procs = [];
  const city = makeCity({ seed: 5353, density: 0.14, cell: 100, clear: 70, hMin: 14, hMax: 60, radius: 640, towerColor: '#06120a' });
  const bar = document.getElementById('prog-fill');
  bar.style.width = '100%';
  bar.style.background = 'linear-gradient(90deg,#39ff88,#00f5ff)';
  const clock = owClock(120, () => end('clock'));
  const say = (s, t) => { msg = s; msgT = t || 2; };

  function spawn(boss){
    const taken = new Set(procs.map(p => p.word));
    const firsts = new Set(procs.map(p => p.word[0]));
    const word = (typeof cmdPickWord === 'function') ? cmdPickWord(elapsed, boss, taken, firsts) : ['ping', 'root', 'kill', 'grep', 'sudo'][(Math.random() * 5) | 0];
    const a = Math.random() * TAU, d = rr(50, 110);
    procs.push({ p: [me.p[0] + Math.cos(a) * d, 0, me.p[2] + Math.sin(a) * d], v: [0, 0, 0], word, typed: 0, boss: !!boss,
                 hunt: boss || Math.random() < 0.45, head: Math.random() * TAU, ph: Math.random() * TAU, flash: 0 });
  }
  for(let i = 0; i < 4; i++) spawn(false);

  const inRange = p => V.d2(p.p, me.p) < RANGE * RANGE;
  function press(ch){
    if(over) return;
    keys++;
    if(!lock){
      let best = null, bd = 1e12;
      for(const p of procs){ if(p.word[0] === ch && inRange(p)){ const d = V.d2(p.p, me.p); if(d < bd){ bd = d; best = p; } } }
      if(!best){ snd('ui'); return; }
      lock = best; lock.typed = 0;
    }
    if(lock.word[lock.typed] === ch){
      lock.typed++; letters++;
      score += 6; setLive(score);
      zap = 0.08; lock.flash = 0.08;
      snd('click', { semi: Math.min(12, lock.typed) });
      if(lock.typed >= lock.word.length) kill(lock);
    }else{
      typos++;
      combo = 0;
      typoT = 0.35;
      snd('error');
    }
  }
  function letGo(){ if(lock){ lock.typed = 0; lock = null; snd('uiBack'); } }
  onType = e => {
    if(e.ctrlKey || e.metaKey || e.altKey) return;
    if(e.key === 'Backspace' || e.key === 'Escape'){ e.preventDefault && e.preventDefault(); letGo(); return; }
    if(e.key && e.key.length === 1 && /[a-z]/i.test(e.key) && !e.repeat) press(e.key.toLowerCase());
  };
  if(typeof cmdShowKeys === 'function'){ cmdShowKeys(true); cmdKeysBind(press, letGo); }
  const prevStop = onStopGame;
  onStopGame = () => { try{ if(typeof cmdShowKeys === 'function') cmdShowKeys(false); }catch(e){} if(prevStop) prevStop(); };

  function kill(p){
    const i = procs.indexOf(p);
    if(i >= 0) procs.splice(i, 1);
    if(lock === p) lock = null;
    kills++;
    combo++; bestCombo = Math.max(bestCombo, combo);
    const pts = p.word.length * 8 + Math.min(40, combo * 4) + (p.boss ? 60 : 0);
    score += pts; setLive(score);
    snd(p.boss ? 'bigExplode' : 'explode');
    fx.explode([p.p[0], 2, p.p[2]], p.boss ? 3 : 1.6, { color: p.boss ? '#ffd700' : '#ff4df0', debris: 3, debrisGeo: 'slab', debrisColor: '#1a2a1a' });
    w.pop([p.p[0], 5, p.p[2]], '+' + pts + ' ' + p.word, p.boss ? '#ffd700' : '#9dffc4', { size: 15 });
  }
  // ⚡ Specials (ENTER, not V — every letter here is for typing): Time Freeze
  // and Time Warp stop or slow the processes, a Shield Burst throws back
  // whatever reaches the shell, and the Smart Missiles and the Nova kill
  // processes outright (each still pays its word).
  let spinT = 0;
  const SP = P.owKit.makeSpecials(G, {
    kinds: ['freeze', 'smart', 'shield', 'warp', 'nova'], every: 260, bubbleR: 3.4, novaR: 30, keyName: 'ENTER',
    player: () => [me.p[0], 1.6, me.p[2]],
    targets: () => procs.map(p => ({ p: [p.p[0], 2.2, p.p[2]], r: p.boss ? 3 : 1.8, obj: p })),
    hit: p => { if(procs.indexOf(p) >= 0) kill(p); }
  });
  function breach(p){
    if(SP.shielded()){
      // Thrown back out, not let in.
      const d = V.sub(p.p, me.p), l = Math.hypot(d[0], d[2]) || 1;
      p.p = V.add(me.p, [d[0] / l * 8, 0, d[2] / l * 8]);
      p.v = [d[0] / l * 10, 0, d[2] / l * 10];
      fx.sparks([p.p[0], 2, p.p[2]], 10, '#a855f7', 1, 12);
      return;
    }
    const i = procs.indexOf(p);
    if(i >= 0) procs.splice(i, 1);
    if(lock === p) lock = null;
    integrity--;
    combo = 0;
    snd('hurt'); w.kick(1);
    fx.explode([p.p[0], 1.5, p.p[2]], 1.8, { color: '#ff4a4a', debris: 0 });
    me.inv = 1.2; me.hit = 0.3;
    bar.style.width = (Math.max(0, integrity) / 3 * 100) + '%';
    if(integrity <= 0){
      if(survivedFatal()){ integrity = 1; bar.style.width = '33%'; say('SHIELD ABSORBED', 1.6); }
      else{ over = true; snd('gameOver'); gLater(() => finish('breached'), 1100); return; }
    }
    say('⚠ ' + p.word + ' GOT THROUGH — integrity ' + integrity, 1.8);
  }
  function end(why){ if(!over){ over = true; finish(why); } }
  function finish(why){
    if(finished) return;
    finished = true;
    const acc = keys ? letters / keys : 0;
    const survive = Math.max(0, integrity) * 30;
    score += survive;
    owFinish('cmdline', score, {
      '📡 Session': why === 'clock' ? 'CLOCK EXPIRED' : 'SHELL BREACHED',
      '💀 Processes Killed': kills,
      '⌨️ Accuracy': Math.round(acc * 100) + '% · ' + letters + ' of ' + keys + ' keys',
      '🔗 Best Clean Run': bestCombo + ' words',
      '🛡️ Integrity Left': Math.max(0, integrity) + ' (+' + survive + ')',
      '🏆 Score': score + ' PTS'
    });
  }
  P.owDebug = {
    state: () => ({ score, kills, typos, integrity, procs: procs.length, lock: lock && lock.word, inRange: procs.filter(inRange).length }),
    lose(){ me.inv = 0; if(!procs.length) spawn(false); breach(procs[0]); },
    typeNearest(){
      let best = null, bd = 1e12;
      for(const p of procs){ const d = V.d2(p.p, me.p); if(d < bd){ bd = d; best = p; } }
      if(!best) return false;
      best.p = V.add(me.p, [0, 0, -12]);
      for(const ch of best.word) press(ch);
      return true;
    },
    typo(){ const p = procs.find(inRange) || procs[0]; if(!p) return; p.p = V.add(me.p, [6, 0, -6]); press(p.word[0]); press('#'); },
    specials: () => SP.state(), grant: k => SP.grant(k), useSpecial: () => SP.use()
  };

  runLoop(dt => {
    if(finished) return false;
    const I = inp.poll();
    if(dt > 0 && !over){
      SP.tick(dt, I, score);
      spinT += dt * (SP.frozen() ? 0 : SP.warp());
      elapsed += dt;
      // Drive on the arrows, the stick, the pad or a held mouse — never the letters.
      const k = I.keys || {};
      let ax = (k.ArrowRight ? 1 : 0) - (k.ArrowLeft ? 1 : 0), ly = (k.ArrowDown ? 1 : 0) - (k.ArrowUp ? 1 : 0);
      if(I.stick){ ax += clamp((I.stick.x - I.stick.x0) / 0.26, -1, 1); ly += clamp((I.stick.y - I.stick.y0) / 0.26, -1, 1); }
      if(I.pad){ ax += I.pad.lx; ly += I.pad.ly; }
      driveStep(me, { ax: clamp(ax, -1, 1), ly: clamp(ly, -1, 1), boost: I.boost, device: I.device, mDown: I.mDown, mx: I.mx, my: I.my }, dt, hud);
      city.update(me.p);
      if(slideOut(me, city, 1.2)) me.hit = 0.15;
      spawnT -= dt;
      if(spawnT <= 0 && procs.length < MAX_LIVE){ spawn(false); spawnT = Math.max(1.2, 3.2 - elapsed * 0.018) / Math.min(1.4, diff); }
      bossT -= dt;
      if(bossT <= 0){ spawn(true); bossT = 30; say('☠ A BOSS PROCESS IS LOOSE', 2); snd('alarm'); }
      for(let i = procs.length - 1; i >= 0; i--){
        const p = procs[i];
        p.flash = Math.max(0, p.flash - dt);
        const d = V.sub(me.p, p.p), l = Math.hypot(d[0], d[2]) || 1;
        let want;
        if(p.hunt && l < 90) want = V.mul([d[0] / l, 0, d[2] / l], (p.boss ? 4 : 6.5) * Math.min(1.3, diff));
        else{ p.head += rr(-1, 1) * dt * 1.4; want = [Math.cos(p.head) * 4, 0, Math.sin(p.head) * 4]; }
        // The one being typed flinches.
        if(p === lock) want = V.mul(want, 0.4);
        if(SP.frozen()) want = [0, 0, 0];
        p.v = V.lerp(p.v, want, ease(dt, SP.frozen() ? 0.05 : 0.4));
        const np = V.madd(p.p, p.v, dt * SP.warp());
        if(!city.hit(np, 1.2)) p.p = np; else p.head += Math.PI * 0.7;
        if(l < 3 && me.inv <= 0) breach(p);
        else if(l > 200){ procs.splice(i, 1); if(lock === p) lock = null; }
      }
      if(lock && !inRange(lock) && V.d2(lock.p, me.p) > (RANGE * 1.4) ** 2){ say('OUT OF RANGE — ' + lock.word + ' let go', 1.4); letGo(); }
    }
    zap = Math.max(0, zap - dt);
    typoT = Math.max(0, typoT - dt);
    fx.step(dt);
    if(msgT > 0) msgT -= dt;

    roverCam(w, me, dt, { back: 15, up: 11, ahead: 14, fov: 60 });
    w.step(dt);

    w.begin();
    drawFloor(w, { step: 6, radius: 170, color: '#0f5a2a', glow: 0.85, major: 5, floor: '#020a04', rough: 0.25 });
    city.draw(w);
    dotRing(w, me.p, RANGE, typoT > 0 ? '#ff4a4a' : '#39ff88', 0.6);
    for(const p of procs){
      // ✨ v60 · PAINTED, NOT LIT (see ENEMY_PAINT): magenta processes, a yellow
      // boss, frost while a Time Freeze holds them — no glow, halo or lamp. The
      // one you are typing wears white livery stripes.
      const col = p.boss ? '#ffd700' : '#ff2d9a';
      const y = 2.2 + Math.sin(w.t * 3 + p.ph) * 0.3;
      const yaw = SP.frozen() ? p.ph : w.t * 0.8 + p.ph;
      const look = P.kit.foeLook(SP.frozen() ? '#9fe6ff' : col, p.flash > 0, p === lock ? { accent: 1 } : null);
      r.draw(p.boss ? 'core' : 'drone', { pos: [p.p[0], y, p.p[2]], rot: [0, yaw, 0], scale: p.boss ? 3 : 1.8, ...look });
      P.kit.foeShadow(r, p.p[0], p.p[2], p.boss ? 2.6 : 1.5);
      if(!p.boss) P.kit.drawRotors(r, [p.p[0], y, p.p[2]], [0, yaw, 0], 1.8, spinT + p.ph, look);
    }
    if(lock && zap > 0) r.streak([me.p[0], 2.4, me.p[2]], [lock.p[0], 2.2, lock.p[2]], 0.3, '#9dffc4', 3, 0);
    roverDraw(w, me, colour);
    if(!over) SP.draw();
    fx.draw();
    w.end();

    hud.begin();
    const Wd = hud.W, Ht = hud.H, ctx = hud.ctx;
    hud.avoid = [[0, Ht - 140, 150, Ht]];
    SP.hud();
    hud.radar(70, Ht - 74, 54, me.p, [-Math.sin(me.yaw), 0, -Math.cos(me.yaw)], 100, procs.map(p => ({ p: p.p, c: p.boss ? '#ffd700' : p.hunt ? '#ff4df0' : '#a87aa8', s: p.boss ? 3.4 : 2.4 })));
    // The words: typed part green, the rest white; dim when out of range.
    ctx.save();
    ctx.font = '700 13px "Orbitron", "Rajdhani", sans-serif';
    ctx.textBaseline = 'middle';
    for(const p of procs){
      if(V.d2(p.p, me.p) > 90 * 90) continue;
      const q = hud.proj([p.p[0], p.boss ? 6 : 4.4, p.p[2]]);
      if(!q.on) continue;
      const near = inRange(p);
      const a = p.word.slice(0, p.typed), b = p.word.slice(p.typed);
      const wa = ctx.measureText(a).width, wb = ctx.measureText(b).width, x0 = q.x - (wa + wb) / 2;
      ctx.globalAlpha = near ? 1 : 0.45;
      ctx.fillStyle = 'rgba(2,10,4,0.7)'; ctx.fillRect(x0 - 5, q.y - 10, wa + wb + 10, 20);
      ctx.shadowBlur = 6;
      ctx.fillStyle = '#39ff88'; ctx.shadowColor = '#39ff88'; ctx.textAlign = 'left'; ctx.fillText(a, x0, q.y);
      ctx.fillStyle = p === lock ? '#ffffff' : p.boss ? '#ffd700' : '#ffc8f4'; ctx.shadowColor = ctx.fillStyle; ctx.fillText(b, x0 + wa, q.y);
      ctx.shadowBlur = 0;
    }
    ctx.restore();
    if(lock && !hud.proj(lock.p).on) hud.edgeArrow(lock.p, '#ffffff', lock.word);
    hud.text(Wd / 2, 26, lock ? '> ' + lock.word.slice(0, lock.typed) + '_' : procs.some(inRange) ? '> type a word in range' : '> drive up to a process', { size: 14, color: typoT > 0 ? '#ff6a6a' : '#9dffc4', align: 'center' });
    hud.text(Wd - 16, Ht - 40, combo > 1 ? 'CLEAN RUN ' + combo : '', { size: 13, align: 'right', color: '#9dffc4' });
    hud.text(Wd - 16, Ht - 20, 'INTEGRITY ' + '▮'.repeat(Math.max(0, integrity)) + '▯'.repeat(Math.max(0, 3 - integrity)), { size: 13, align: 'right', color: integrity > 1 ? '#9dffc4' : '#ff8a8a' });
    if(msgT > 0) hud.text(Wd / 2, 50, msg, { size: 13, color: '#ffffff', alpha: clamp(msgT, 0, 1) });
    hud.touchPad(I);
  });
};

})();

// <<OW:END>>
